KB.add({"board":"03","title":"古典诗词曲赋","note":"交大近七届考得最密的板块：名解考过屈原、乐府双璧、苏辛、温庭筠，早年考过“词”；选择题考过《汉宫秋》、白朴、《倩女离魂》、司马相如、曹植、宋玉《九辩》、长吉体、《天净沙·秋思》、王维《使至塞上》、关汉卿“铜豌豆”。命题方式是“同一人物换作品、同一组合换成员”，所以要按组合整体掌握。","clusters":[{"cid":"03a","name":"先秦源头：《诗经》与楚辞","line":"北方《诗经》四言写实，以赋比兴和风雅颂为体例；南方屈原创楚辞，宋玉继之，《离骚》浪漫抒情；二者合称“风骚”，是中国诗歌现实主义与浪漫主义两大源头。"},{"cid":"03b","name":"两汉：辞赋、乐府与五言诗","line":"汉代文学有三条线：辞赋由贾谊骚体赋、枚乘《七发》发展到司马相如等汉赋四大家；乐府机构采诗，留下乐府双璧之一《孔雀东南飞》；文人五言诗至《古诗十九首》成熟；史传文学以司马迁、班固“班马”为高峰。"},{"cid":"03c","name":"魏晋南北朝：建安风骨到山水诗与骈文","line":"东汉末三曹、建安七子与蔡琰开“建安风骨”；魏晋之际竹林七贤代表正始文学；两晋太康诗风之后，陶渊明开田园诗，谢灵运开山水诗；南朝永明体讲声律，宫体诗与骈文趋于绮丽，庾信集南北之成。"},{"cid":"03d","name":"古代文论与诗文总集","line":"文论从曹丕《典论·论文》起步，南朝出现刘勰《文心雕龙》和钟嵘《诗品》两部专著，宋有严羽《沧浪诗话》，近代王国维《人间词话》提出境界说；总集按时代读：《诗经》、《楚辞》、萧统《文选》、徐陵《玉台新咏》、郭茂倩《乐府诗集》、清代《全唐诗》《唐诗三百首》《古文观止》。"},{"cid":"03e","name":"初盛唐诗：四杰、王孟高岑与李杜","line":"初唐四杰与陈子昂扫除齐梁余风，沈宋定型律诗；盛唐分两路，王维孟浩然写山水田园，高适岑参王昌龄写边塞；李白浪漫称诗仙，杜甫写实称诗圣，合称“李杜”。"},{"cid":"03f","name":"中晚唐：古文运动、新乐府与苦吟诗人","line":"安史之乱后，韩愈柳宗元倡古文运动，白居易元稹倡新乐府运动；韩孟诗派尚奇险，孟郊贾岛苦吟，李贺称诗鬼；晚唐李商隐杜牧合称“小李杜”，文学由盛转向感伤。"},{"cid":"03g","name":"词的兴起：花间、南唐到北宋婉约","line":"词起于隋唐燕乐，依词牌填写；晚唐温庭筠为花间鼻祖，后蜀赵崇祚编《花间集》；南唐李煜扩大词境；北宋柳永创慢词，晏殊晏几道、秦观、周邦彦延续婉约，至李清照“易安体”集大成。"},{"cid":"03h","name":"宋代诗文与豪放词","line":"北宋欧阳修领导诗文革新，唐宋八大家中宋占六家；苏轼开豪放词，与辛弃疾合称“苏辛”；诗坛有苏黄、江西诗派“一祖三宗”；南宋陆游等中兴四大诗人之后，永嘉四灵与江湖诗派继起，宋末文天祥以气节收束。"},{"cid":"03i","name":"元曲：杂剧与散曲","line":"金代诸宫调铺垫，元代形成元曲，含杂剧与散曲；杂剧一本四折加楔子，一人主唱，关汉卿、马致远、白朴、郑光祖为元曲四大家，王实甫《西厢记》、纪君祥《赵氏孤儿》为名作；散曲分小令与套数，马致远《天净沙·秋思》、张养浩《山坡羊·潼关怀古》最常考。"},{"cid":"03j","name":"明清：传奇戏曲与诗文流派","line":"南戏发展为明清传奇，汤显祖“临川四梦”、清初“南洪北孔”为高峰；明代诗文按流派更替：台阁体、前后七子复古、唐宋派、公安派“独抒性灵”、竟陵派；清代有清词中兴、四大诗说与桐城派古文。"}],"entries":[{"id":"b03-001","t":"《诗经》","cid":"03a","p":1,"kind":"作品","alias":["诗三百","诗","《诗》"],"one":"中国第一部诗歌总集，305篇，分风雅颂，用赋比兴，以四言为主。","ans":"《诗经》是**中国第一部诗歌总集**，收录西周初年至春秋中叶约五百年间的诗歌**305篇**，先秦称《诗》或“诗三百”，汉代儒家尊为经典，列入**五经**。内容按音乐分为**风、雅、颂**三部分，表现手法为**赋、比、兴**，以四言为主，多重章叠句。名篇有《关雎》《蒹葭》《硕鼠》《氓》《七月》。它开创了中国诗歌的**现实主义传统**，与楚辞并称**“风骚”**。","pts":["第一部诗歌总集，305篇","风雅颂，赋比兴，四言为主","现实主义源头，与楚辞并称风骚"],"mem":"数字口诀：三百零五，“诗三百”是约数。分类记“风雅颂”，手法记“赋比兴”，前者分体裁，后者分写法，合起来叫“六义”。画面：北方黄河边的采诗官，把民歌一首首收进竹简。","mix":"“风雅颂”是按音乐分类，“赋比兴”是表现手法，不要互换；《诗经》是北方现实主义，楚辞是南方浪漫主义；《九辩》《离骚》不在其中。","mcq":[{"q":"下列关于《诗经》的说法，正确的是","o":["是中国第一部诗歌总集","收诗约三千首","以七言为主","由刘向编集"],"a":0,"w":"《诗经》305篇，以四言为主，是第一部诗歌总集；刘向辑的是《楚辞》。"},{"q":"下列诗句出自《诗经》的是","o":["关关雎鸠，在河之洲","路漫漫其修远兮","采菊东篱下","大漠孤烟直"],"a":0,"w":"《周南·关雎》开篇；前者出自《离骚》，后两句分别出自陶渊明和王维。"}],"rel":[{"t":"《诗经》六义：风雅颂与赋比兴","n":"体制与手法详解"},{"t":"楚辞","n":"并称风骚"},{"t":"风骚","n":"《诗经》与楚辞合称"},{"t":"荷马史诗","n":"中西早期诗歌源头"}],"more":"名篇：《关雎》《蒹葭》《硕鼠》《氓》《七月》《采薇》\n关关雎鸠，在河之洲。窈窕淑女，君子好逑。｜《周南·关雎》\n昔我往矣，杨柳依依。今我来思，雨雪霏霏。｜《小雅·采薇》","exam":[]},{"id":"b03-002","t":"屈原","cid":"03a","p":1,"kind":"人物","exam":["2021名解"],"alias":["屈平","三闾大夫","屈子"],"one":"战国楚国爱国诗人，楚辞开创者，代表作《离骚》，投汨罗江而死。","ans":"屈原（约前340–前278），名平，字原，**战国时期楚国人，伟大的爱国诗人**，**楚辞的开创者**。他曾任三闾大夫，主张举贤修法、联齐抗秦，遭排挤流放，**秦军攻破楚都郢后投汨罗江而死**。代表作有**《离骚》《九歌》《天问》《九章》**，善用香草美人的比兴和神话想象，开创了**浪漫主义传统**，与《诗经》并称“风骚”。后世以**端午节**纪念他。","pts":["战国楚人，爱国诗人，楚辞开创者","三闾大夫，被放逐，投汨罗江","《离骚》等，浪漫主义，端午纪念"],"mem":"画面：端午节划龙舟、吃粽子，是为了不让鱼虾啃食投江的屈原。作品口诀“离九天九”：《离骚》《九歌》《天问》《九章》。《九辩》是宋玉的，不在其中。","mix":"《九辩》作者是宋玉（2024选择）；“楚辞”总集由西汉刘向辑成；《招魂》作者有屈原、宋玉两说；生卒年另有约前339–约前278等说法。","mcq":[{"q":"下列作品中，不属于屈原的是","o":["《天问》","《九辩》","《九歌》","《离骚》"],"a":1,"w":"《九辩》是宋玉所作，开悲秋主题。"},{"q":"屈原投江而死的河流是","o":["湘江","长江","汉水","汨罗江"],"a":3,"w":"秦破郢都后，屈原自沉汨罗江，端午节纪念他。"}],"rel":[{"t":"《离骚》","n":"代表作"},{"t":"楚辞","n":"开创者"},{"t":"宋玉","n":"并称屈宋"},{"t":"端午节","n":"纪念屈原"},{"t":"荷马史诗","n":"东西方早期诗人对照"}],"more":"路曼曼其修远兮，吾将上下而求索。｜《离骚》\n长太息以掩涕兮，哀民生之多艰。｜《离骚》\n作品：《九歌》含《国殇》《山鬼》《湘君》《湘夫人》；《九章》含《橘颂》《涉江》《哀郢》《怀沙》"},{"id":"b03-003","t":"楚辞","cid":"03a","p":1,"kind":"作品","alias":["楚词","骚体","楚骚"],"one":"战国楚地新诗体，屈原宋玉为代表；也指刘向所辑总集。","ans":"楚辞是**战国时期以屈原为代表的楚国诗人创作的新诗体**，也指**西汉刘向辑录的诗歌总集《楚辞》**。它运用楚地方言、声韵和神话，**句式参差灵活，多用“兮”字**，想象奇特、文采绚丽。代表作家有**屈原、宋玉**，代表作有《离骚》《九歌》《九辩》。楚辞是中国**浪漫主义文学的源头**，与《诗经》并称**“风骚”**，并直接影响汉赋的形成。","pts":["战国楚国新诗体，也是刘向所辑总集","楚地方言，多用“兮”，句式灵活","屈原宋玉，浪漫主义源头，影响汉赋"],"mem":"逻辑线：北方《诗经》四言整齐，南方楚辞长短参差、爱用“兮”，一北一南，一实一浪漫。口诀“兮兮楚辞”：见到满篇“兮”，先想楚辞。","mix":"《诗经》是现实主义，楚辞是浪漫主义；“楚辞”作为总集由刘向辑成，东汉王逸作注。","mcq":[{"q":"楚辞作为总集，最早由谁辑录成书","o":["王逸","萧统","郭茂倩","刘向"],"a":3,"w":"西汉刘向辑，东汉王逸作《楚辞章句》。"},{"q":"下列哪项最符合楚辞的特点","o":["多用“兮”字，句式参差","四言为主，重章叠句","严格平仄对仗","一人主唱，四折一楔子"],"a":0,"w":"楚辞用楚地方言，多“兮”字；四言重章是《诗经》。"}],"rel":[{"t":"《楚辞》的编集：刘向与王逸","n":"总集成书"},{"t":"屈原","n":"开创者"},{"t":"宋玉","n":"继承者"},{"t":"《诗经》","n":"北方源头对举"},{"t":"赋（文体）","n":"楚辞影响汉赋"}],"more":"“骚体”得名于《离骚》。","exam":[]},{"id":"b03-018","t":"宋玉《九辩》","cid":"03a","p":1,"kind":"作品","exam":["2024选择"],"alias":["九辩","宋玉","《九辩》"],"one":"战国楚人宋玉所作楚辞，开“悲秋”主题。","ans":"《九辩》是**战国末期楚国辞赋家宋玉**的代表作，属**楚辞**体，相传宋玉是**屈原弟子**。全篇借秋景抒发贫士失职的悲愤，“悲哉秋之为气也”一句**开创了中国文学的“悲秋”主题**，影响后世杜甫《登高》等诗。宋玉另有《神女赋》《高唐赋》，与屈原并称**“屈宋”**，是楚辞向汉赋过渡的重要作家。《九辩》不要误配给屈原。","pts":["宋玉作，楚辞，相传屈原弟子","开悲秋主题","与屈原并称屈宋，勿配给屈原"],"mem":"“九”字陷阱：屈原有《九歌》《九章》，宋玉有《九辩》，三个都带九。记法：辩（宋）、歌章（屈），“辩”配宋，“悲秋”也配宋。","mix":"《九歌》《九章》是屈原，《九辩》是宋玉，2024选择专考此点；《招魂》作者有屈原、宋玉两说。","mcq":[{"q":"开创“悲秋”主题的《九辩》，作者是","o":["屈原","宋玉","贾谊","司马相如"],"a":1,"w":"《九辩》为宋玉作，“悲哉秋之为气也”。"},{"q":"下列作品属于屈原的是","o":["《九辩》","《神女赋》","《天问》","《高唐赋》"],"a":2,"w":"前三者均属宋玉，《天问》是屈原所作。"}],"rel":[{"t":"宋玉","n":"作者"},{"t":"屈原","n":"同属楚辞，常混"},{"t":"屈原《九歌》《九章》《天问》","n":"屈原作品对照"},{"t":"屈宋","n":"二人合称"}],"more":"悲哉秋之为气也，萧瑟兮草木摇落而变衰。｜《九辩》"},{"id":"z10-003","t":"宋玉","cid":"03a","p":2,"kind":"人物","exam":["2024选择"],"alias":["宋玉《九辩》"],"one":"战国末楚国辞赋家，屈原弟子，《九辩》开悲秋传统，与屈原并称“屈宋”。","ans":"宋玉是**战国末期楚国辞赋家**，相传为**屈原的弟子**，继屈原之后成为**楚辞**的重要作家，与屈原并称**“屈宋”**。代表作有《九辩》《高唐赋》《神女赋》《风赋》《登徒子好色赋》。《九辩》以“悲哉，秋之为气也”起笔，借秋景写失意之悲，开启了**文人“悲秋”传统**。他的赋铺陈辞采、体物细腻，对后世汉赋影响很大。","pts":["战国末楚国辞赋家，相传屈原弟子","《九辩》《高唐赋》《神女赋》等","开文人悲秋传统；与屈原并称屈宋"],"mem":"画面记忆：屈原投江后，学生宋玉站在秋风里写“悲哉秋之为气也”。口诀“屈原《离骚》宋玉《九辩》”，离愁对悲秋。《高唐》《神女》两赋都写楚王梦遇神女，可串在一起记。","mix":"问《九辩》作者，屈原是最常见的干扰项；《九章》《九歌》才是屈原作品。","mcq":[{"q":"“悲哉，秋之为气也！萧瑟兮草木摇落而变衰”出自","o":["宋玉《九辩》","屈原《离骚》","贾谊《吊屈原赋》","曹操《短歌行》"],"a":0,"w":"这是宋玉《九辩》开篇，开文人悲秋传统，交大2024年选择题考过。"}],"rel":[{"t":"屈原","n":"相传的老师"},{"t":"屈宋","n":"并称"},{"t":"楚辞","n":"所属体裁"},{"t":"《诗学》","n":"中西早期文论源头对照"}],"more":"名句：悲哉，秋之为气也！萧瑟兮草木摇落而变衰。｜《九辩》\n作品：《九辩》《高唐赋》《神女赋》《风赋》《登徒子好色赋》\n《对楚王问》中有“下里巴人”“阳春白雪”的典故。"},{"id":"c-010","t":"风骚","cid":"03a","p":2,"kind":"合称","alias":["风骚"],"one":"《诗经》国风与《楚辞》离骚的合称，后泛指文学。","ans":"风骚是**《诗经》“国风”与《楚辞》“离骚”**的合称，是**中国古代诗歌两大源头**。“风”代表北方黄河流域的**四言写实诗歌**，“骚”代表南方楚地屈原开创的**浪漫抒情的楚辞**。前者奠定**现实主义**传统，后者开启**浪漫主义**传统。后来“风骚”引申为文学的代称，如“各领风骚”，也可指杰出的文人。","pts":["《诗经》国风与《楚辞》离骚","分别代表现实主义与浪漫主义源头","后泛指文学，引申为文坛"],"members":[["风","《诗经》国风，北方，现实主义，四言为主"],["骚","《楚辞》《离骚》，南方，浪漫主义，屈原开创"]],"mem":"一个字一个源头：风=北方民歌，写实；骚=南方屈原，浪漫。记“北风南骚”，两个字合起来就是整个先秦诗歌。","mix":"“风骚”不等于“风雅”：风雅是《诗经》的风与雅，常指诗歌或文雅之事。","mcq":[{"q":"“风骚”并称，其中“骚”指的是","o":["《诗经》大雅","《楚辞》《离骚》","汉乐府","建安诗歌"],"a":1,"w":"风指《诗经》国风，骚指屈原《离骚》，代表楚辞。"}],"rel":[{"t":"《诗经》","n":"“风”的来源"},{"t":"《离骚》","n":"“骚”的来源"},{"t":"屈宋","n":"楚辞代表作家并称"},{"t":"现实主义","n":"《诗经》开其传统"}],"more":"“风骚”也常写作“风”“骚”并提，如“独领风骚”。","exam":[]},{"id":"c-011","t":"屈宋","cid":"03a","p":2,"kind":"合称","alias":["屈宋"],"one":"屈原与宋玉的并称，楚辞两位代表作家。","ans":"屈宋是**战国楚国辞赋家屈原和宋玉**的并称，二人是**楚辞**的代表作家。屈原创立楚辞体，代表作**《离骚》**，以浪漫手法抒写忠贞与忧愤；宋玉相传是屈原弟子，继承其辞赋传统，作有**《九辩》**《高唐赋》《神女赋》等，其中《九辩》开**文人悲秋**之风。两人共同奠定了**南方浪漫文学**的传统，并影响了后来汉赋的形成。","pts":["屈原与宋玉并称","屈原《离骚》，宋玉《九辩》","共同代表楚辞，影响汉赋"],"members":[["屈原","《离骚》《九歌》《九章》《天问》，楚辞开创者"],["宋玉","《九辩》《高唐赋》《神女赋》，相传为屈原弟子"]],"mem":"“屈宋”像“李杜”一样是一个人加他的传人：屈原先写《离骚》，宋玉跟着写《九辩》。离=离别忧愤，辩=悲秋，各一个字对应各一篇。","mix":"屈宋是楚辞作家并称；“风骚”则是《诗经》与《楚辞》两部作品的并称。","mcq":[{"q":"下列属于楚辞作家并称的是","o":["李杜","班马","屈宋","嵇阮"],"a":2,"w":"屈宋指屈原、宋玉；李杜是唐代，班马是史家，嵇阮是魏晋人物。"}],"rel":[{"t":"屈原","n":"屈宋之首"},{"t":"宋玉","n":"屈宋之后"},{"t":"风骚","n":"另一组先秦并称"},{"t":"班马","n":"同为人名合称，易混"}],"exam":[]},{"id":"b03-004","t":"乐府与乐府双璧","cid":"03b","p":1,"kind":"合称","exam":["2024名解"],"alias":["乐府","汉乐府","乐府双璧"],"one":"乐府是汉代音乐官署及其诗歌；双璧指《孔雀东南飞》与《木兰诗》。","ans":"乐府原是**汉武帝时扩建的掌管音乐的官署**，负责采集民歌、配乐演唱，后来**这类配乐诗歌也称乐府**。汉乐府“感于哀乐，缘事而发”，以叙事见长。**“乐府双璧”指汉乐府《孔雀东南飞》和北朝民歌《木兰诗》**：前者原题《古诗为焦仲卿妻作》，见于**徐陵《玉台新咏》**，是**古代最长的叙事诗**；后者写木兰代父从军，收入**郭茂倩《乐府诗集》**。两诗代表了乐府叙事诗的最高成就。","pts":["乐府是汉代音乐机构及其诗歌","《孔雀东南飞》与《木兰诗》","乐府叙事诗最高成就"],"members":[["《孔雀东南飞》","汉乐府，焦仲卿刘兰芝悲剧，最长叙事诗"],["《木兰诗》","北朝民歌，木兰代父从军"]],"mem":"口诀：“汉孔北木”，汉乐府《孔雀》，北朝《木兰》。画面：一对璧玉，一块写爱情悲剧，一块写巾帼从军。","mix":"《木兰诗》是北朝民歌，不是汉乐府；《乐府诗集》编者郭茂倩是宋人，《玉台新咏》编者徐陵是南朝人。","mcq":[{"q":"“乐府双璧”指的是","o":["《孔雀东南飞》和《木兰诗》","《孔雀东南飞》和《陌上桑》","《木兰诗》和《长恨歌》","《陌上桑》和《木兰诗》"],"a":0,"w":"乐府双璧是汉乐府《孔雀东南飞》与北朝《木兰诗》。"},{"q":"《木兰诗》收录于","o":["《玉台新咏》","《昭明文选》","《全唐诗》","《乐府诗集》"],"a":3,"w":"宋代郭茂倩《乐府诗集》收录。"}],"rel":[{"t":"《孔雀东南飞》","n":"双璧之一"},{"t":"《木兰诗》","n":"双璧之一"},{"t":"《乐府诗集》","n":"乐府总集"},{"t":"《玉台新咏》","n":"最早载《孔雀》"},{"t":"《汉宫秋》与《梧桐雨》","n":"叙事与戏剧对照"}],"more":"《孔雀东南飞》又称《焦仲卿妻》，原题《古诗为焦仲卿妻作》。"},{"id":"b03-006","t":"汉赋与司马相如","cid":"03b","p":1,"kind":"概念","exam":["2023选择"],"alias":["汉赋","汉大赋"],"one":"汉赋是两汉铺陈辞藻的文体；司马相如以《子虚赋》《上林赋》称赋圣。","ans":"汉赋是**两汉时期盛行的文体，介于诗和散文之间，讲究铺陈排比、辞藻华丽**，多以“劝百讽一”的方式描写宫苑、都城和帝王活动。**西汉枚乘《七发》标志汉大赋形成**；**司马相如、扬雄、班固、张衡合称“汉赋四大家”**。司马相如字长卿，蜀郡成都人，代表作**《子虚赋》《上林赋》**，被誉为**“赋圣”**。东汉张衡《归田赋》开抒情小赋之风。","pts":["两汉文体，铺陈辞藻，劝百讽一","汉赋四大家：相如、扬雄、班固、张衡","司马相如《子虚赋》《上林赋》"],"members":[["司马相如","《子虚赋》《上林赋》，赋圣"],["扬雄","《甘泉赋》《长杨赋》"],["班固","《两都赋》"],["张衡","《二京赋》《归田赋》"]],"mem":"四大家口诀“马扬班张”，对应“子上、甘长、两都、二京”：马的《子虚》《上林》，扬的《甘泉》《长杨》，班的《两都》，张的《二京》。","mix":"贾谊《吊屈原赋》《鵩鸟赋》是骚体赋；《七发》作者枚乘；“班马”指班固与司马迁，不是司马相如。","mcq":[{"q":"下列作品中，属于司马相如的是","o":["《两都赋》","《上林赋》","《甘泉赋》","《归田赋》"],"a":1,"w":"《子虚赋》《上林赋》是司马相如代表作。"},{"q":"下列不属于“汉赋四大家”的是","o":["贾谊","扬雄","张衡","班固"],"a":0,"w":"四大家是司马相如、扬雄、班固、张衡，贾谊作骚体赋。"}],"rel":[{"t":"司马相如","n":"赋圣"},{"t":"汉赋四大家","n":"四家名单"},{"t":"枚乘《七发》","n":"汉大赋之始"},{"t":"赋（文体）","n":"文体源流"},{"t":"宋玉","n":"楚辞向汉赋过渡"}],"more":"扬雄《甘泉赋》《长杨赋》；班固《两都赋》；张衡《二京赋》《归田赋》；贾谊《吊屈原赋》《鵩鸟赋》。"},{"id":"b03-044","t":"《古诗十九首》","cid":"03b","p":2,"kind":"作品","alias":["古诗十九首"],"one":"东汉末无名文人五言诗，《文选》收录，刘勰称“五言之冠冕”。","ans":"《古诗十九首》是**东汉末年无名文人所作的五言诗**，由南朝**萧统编入《文选》**，因而得名。内容多写游子思妇的离别相思、人生短暂和仕途失意，如“行行重行行”“青青河畔草”“迢迢牵牛星”。它标志着**文人五言诗走向成熟**，语言质朴自然，抒情含蓄。**刘勰**称之为**“五言之冠冕”**，钟嵘称其“惊心动魄，一字千金”，对魏晋诗歌影响深远。","pts":["东汉末无名文人五言诗","萧统编入《文选》，题为古诗十九首","刘勰称五言之冠冕，文人五言诗成熟"],"mem":"“十九”就是一个数字，“五言之冠”记成五言诗的帽子(冠冕)戴在它头上。题材三个关键词：游子、思妇、人生苦短。《迢迢牵牛星》可联想七夕。","mix":"《古诗十九首》作者不详，不是枚乘或李陵等具名作家(旧题枚乘作，今不采信)；不属于汉乐府民歌。","mcq":[{"q":"被刘勰称为“五言之冠冕”的是","o":["《孔雀东南飞》","《古诗十九首》","《木兰诗》","《咏怀诗》"],"a":1,"w":"《文心雕龙·明诗》称《古诗十九首》为五言之冠冕。"}],"rel":[{"t":"《昭明文选》","n":"收录并命名"},{"t":"汉乐府名篇","n":"同时期，一民歌一文人"},{"t":"《文心雕龙》","n":"评价来源"},{"t":"钟嵘《诗品》","n":"评为一字千金"}],"more":"名句：行行重行行，与君生别离。\n青青河畔草，郁郁园中柳。\n生年不满百，常怀千岁忧。\n迢迢牵牛星，皎皎河汉女。","exam":[]},{"id":"b03-054","t":"蔡邕","cid":"03b","p":1,"kind":"人物","exam":["2014名解"],"alias":["蔡伯喈","蔡中郎"],"one":"东汉文学家、书法家，蔡文姬之父，创飞白书，主持刻《熹平石经》。","ans":"蔡邕（133–192），字伯喈，**东汉末年文学家、书法家、音乐家**，陈留圉人，**蔡文姬之父**。他精于辞章与音律，擅隶书，相传**创“飞白书”**；熹平年间奏请正定经书文字，并**书丹刊刻《熹平石经》**立于太学门外，成为士人校正经文的标准。他曾为董卓所用，卓死后被王允下狱而死。其女蔡琰有《悲愤诗》。蔡邕的碑文、书法和石经在东汉文化史上影响很大。","pts":["东汉文学家、书法家，蔡文姬之父","创飞白书，刻《熹平石经》","董卓死后下狱而死"],"mem":"画面：太学门外立起一排石碑，是蔡邕写的字（熹平石经）；他又因扫帚刷墙的痕迹，悟出笔画露白的“飞白书”。父女对记：蔡邕写字，蔡文姬写诗。","mix":"蔡邕是父，蔡琰（文姬）是女；《胡笳十八拍》《悲愤诗》是蔡琰的，不是蔡邕的。","mcq":[{"q":"主持刊刻《熹平石经》的人是","o":["蔡琰","蔡邕","曹操","王粲"],"a":1,"w":"蔡邕书丹，立于洛阳太学门外。"},{"q":"相传创“飞白书”的东汉书法家是","o":["张芝","蔡邕","钟繇","王羲之"],"a":1,"w":"飞白书相传为蔡邕所创。"}],"rel":[{"t":"蔡文姬","n":"其女"},{"t":"“飞白书”","n":"相传所创"},{"t":"建安文学与三曹","n":"时代背景"},{"t":"汉灵帝","n":"熹平石经立于其朝"}],"more":"《熹平石经》刻于汉灵帝熹平四年（175）前后。"},{"id":"b03-070","t":"枚乘《七发》","cid":"03b","p":3,"kind":"作品","alias":["七发"],"one":"西汉枚乘创作的骚体大赋，标志着汉代大赋体制正式形成。","ans":"《七发》是**西汉辞赋家枚乘**的代表作，**标志着汉代大赋体制正式形成**。作品假设吴客探视楚太子，以**音乐、饮食、车马、游宴、田猎、涛澜、要言妙道**七事启发劝诫，使太子出汗病愈。全篇以主客问答铺张扬厉，开创了汉魏六朝**“七体”**创作风尚。","pts":["西汉枚乘代表作，标志汉大赋正式形成","以七事设喻规劝楚太子，观涛最为精彩","确立主客问答铺张形式，开创后世“七体”"],"mem":"枚乘七发劝太子，广陵观涛治顽疾，汉大赋成开七体。","mix":"《七发》标志汉大赋‘正式形成’，司马相如《天子游猎赋》（《子虚赋》《上林赋》）标志汉大赋‘完全成熟’。","mcq":[{"q":"标志着汉代大赋体制正式形成的辞赋名篇是","o":["枚乘《七发》","司马相如《子虚赋》","贾谊《吊屈原赋》","扬雄《长杨赋》"],"a":0,"w":"枚乘《七发》标志着汉大赋体制的正式形成，开创了“七体”新文体。"}],"rel":[{"t":"枚乘","n":"赋作作者"},{"t":"司马相如","n":"汉赋大成者"},{"t":"汉赋四大家","n":"汉大赋代表作家群"}],"more":"代表段落：观广陵涛\n开创文体：七体（后世张衡《七辩》、陆机《七征》等）","exam":[]},{"id":"z10-004","t":"贾谊","cid":"03b","p":2,"kind":"人物","alias":["贾生","贾长沙"],"one":"西汉政论家、辞赋家，《过秦论》《吊屈原赋》作者，骚体赋代表。","ans":"贾谊（前200–前168）是**西汉初年的政论家、辞赋家**，世称贾生，曾任长沙王太傅，故称贾长沙。他的**政论文**以《过秦论》《论积贮疏》《陈政事疏》（又称《治安策》）为代表，《过秦论》总结秦亡教训，提出**“仁义不施而攻守之势异也”**。辞赋方面以**《吊屈原赋》《鵩鸟赋》**为代表，是**骚体赋**的典型。《史记》把他与屈原合传，鲁迅称其文“西汉鸿文”。","pts":["西汉初政论家、辞赋家，贾长沙","政论：过秦论、论积贮疏、陈政事疏","辞赋：吊屈原赋、鵩鸟赋，骚体赋代表"],"mem":"贾谊=“贾生”：李商隐写“可怜夜半虚前席，不问苍生问鬼神”，写的就是汉文帝召见他。《过秦论》记“仁义不施”，《吊屈原赋》记“吊”：他被贬长沙，路过湘江吊屈原，自比同样的遭遇。","mix":"《过秦论》是政论文，不是赋；贾谊与屈原被《史记》合传为《屈原贾生列传》。","mcq":[{"q":"《过秦论》和《吊屈原赋》的作者是","o":["晁错","司马相如","贾谊","枚乘"],"a":2,"w":"贾谊，西汉政论家、辞赋家。"}],"rel":[{"t":"贾谊《过秦论》与《吊屈原赋》","n":"代表作"},{"t":"屈原","n":"《吊屈原赋》所吊对象"},{"t":"司马相如","n":"汉赋另一代表"},{"t":"司马迁","n":"《史记》为其立传"}],"more":"名句：仁义不施而攻守之势异也。｜《过秦论》\n作品：《过秦论》《论积贮疏》《陈政事疏》（《治安策》）《吊屈原赋》《鵩鸟赋》\n李商隐《贾生》：可怜夜半虚前席，不问苍生问鬼神。","exam":[]},{"id":"z10-005","t":"枚乘","cid":"03b","p":3,"kind":"人物","alias":["枚叔"],"one":"西汉辞赋家，汉大赋奠基人，代表作《七发》。","ans":"枚乘（？—前140），字叔，淮阴人，**西汉辞赋家**。他曾谏吴王刘濞，武帝即位时以**“安车蒲轮”**征召，途中病卒。其代表作**《七发》**以主客问答铺叙讽谕，**标志汉大赋正式形成**。他开创了汉魏文人仿效的**“七体”**范式，其子枚皋亦以辞赋闻名。","pts":["西汉淮阴人，字叔，辞赋家","武帝以“安车蒲轮”礼聘，代表作《七发》","标志汉大赋正式形成，开创“七体”"],"mem":"淮阴枚乘作七发，安车蒲轮聘贤相；大赋形成开七体，父子辞赋振两汉。","mix":"枚乘与枚皋为父子，枚乘擅大赋（《七发》），枚皋擅敏捷短赋；汉武帝以‘安车蒲轮’征聘的是枚乘。","mcq":[{"q":"汉武帝即位后以‘安车蒲轮’特聘征召却在途中病卒的西汉辞赋家是","o":["贾谊","扬雄","司马相如","枚乘"],"a":3,"w":"汉武帝即位后以安车蒲轮礼聘枚乘，枚乘在赴长安途中病逝。"}],"rel":[{"t":"枚乘《七发》","n":"代表作"},{"t":"司马相如","n":"同时代辞赋大家"},{"t":"汉赋四大家","n":"汉赋后继高峰"}],"more":"代表作：《七发》\n谏书：《上书谏吴王》","exam":[]},{"id":"z10-006","t":"司马相如","cid":"03b","p":1,"kind":"人物","exam":["2023选择"],"alias":["司马长卿","相如","赋圣"],"one":"西汉辞赋家，字长卿，作《子虚赋》《上林赋》，被誉为赋圣。","ans":"司马相如（约前179–前118），字长卿，**蜀郡成都人，西汉辞赋家**，被誉为**“赋圣”**。他是**汉赋四大家之首**，作品铺陈宏丽，结尾寓讽谏。代表作有**《子虚赋》《上林赋》**，写诸侯游猎和天子苑囿，另有《大人赋》，《长门赋》归属有争议。他与**卓文君当垆卖酒**的故事流传甚广，琴曲《凤求凰》相传为其所作。他确立了汉大赋的体制，对后世赋体影响深远。","pts":["西汉辞赋家，字长卿，赋圣","《子虚赋》《上林赋》","汉赋四大家之首，与卓文君故事"],"mem":"口诀：相如写“子上”，即《子虚》《上林》；故事挂钩：琴挑卓文君，当垆卖酒，《凤求凰》。","mix":"《长门赋》作者归属有争议；扬雄写《甘泉赋》，班固写《两都赋》，张衡写《二京赋》，不要混配给司马相如。","mcq":[{"q":"《子虚赋》的作者是","o":["扬雄","班固","贾谊","司马相如"],"a":3,"w":"司马相如代表作为《子虚赋》《上林赋》。"},{"q":"与司马相如“当垆卖酒”故事相关的人物是","o":["蔡文姬","卓文君","班昭","李清照"],"a":1,"w":"卓文君与相如私奔，当垆卖酒。"}],"rel":[{"t":"汉赋与司马相如","n":"汉赋概说"},{"t":"汉赋四大家","n":"四大家之一"},{"t":"枚乘《七发》","n":"汉大赋先声"},{"t":"司马迁","n":"西汉并称“文宗”，不同人"}],"more":"《子虚赋》《上林赋》；《大人赋》；《长门赋》（有争议）"},{"id":"z10-007","t":"司马迁","cid":"03b","p":2,"kind":"人物","alias":["太史公","司马子长"],"one":"西汉史学家，字子长，撰《史记》，鲁迅称“史家之绝唱，无韵之离骚”。","ans":"司马迁（约前145–?），字子长，**西汉史学家、文学家**，曾任太史令，因替李陵辩护受宫刑，发愤著书。他撰成**《史记》**，共130篇，包括**十二本纪、十表、八书、三十世家、七十列传**，上起黄帝，下至汉武帝，是**中国第一部纪传体通史**。书信《报任安书》有“人固有一死，或重于泰山，或轻于鸿毛”。鲁迅称《史记》为**“史家之绝唱，无韵之离骚”**，与班固并称“班马”。","pts":["字子长，西汉史学家，受宫刑发愤著书","《史记》130篇，第一部纪传体通史","鲁迅评史家之绝唱，无韵之离骚；班马"],"mem":"数字口诀“十二本纪十表，八书三十世家，七十列传”，记成12、10、8、30、70，合起来是130。通史对断代：《史记》通史(司马迁)，《汉书》断代(班固)，一个“通”一个“断”。","mix":"《史记》是第一部纪传体通史，《汉书》是第一部纪传体断代史；司马迁与司马光(《资治通鉴》，编年体通史)易混。","mcq":[{"q":"“史家之绝唱，无韵之离骚”是鲁迅对哪部作品的评价","o":["《汉书》","《资治通鉴》","《左传》","《史记》"],"a":3,"w":"鲁迅《汉文学史纲要》评价《史记》。"}],"rel":[{"t":"纪传体与《史记》","n":"代表作与体例"},{"t":"班固","n":"并称班马"},{"t":"司马迁与司马光","n":"二司马易混"},{"t":"《春秋》与春秋三传","n":"编年体源头，对照纪传体"}],"more":"名句：人固有一死，或重于泰山，或轻于鸿毛。｜《报任安书》\n《史记》130篇：12本纪、10表、8书、30世家、70列传。","exam":[]},{"id":"z10-008","t":"班固","cid":"03b","p":2,"kind":"人物","alias":["班孟坚"],"one":"东汉史学家、辞赋家，撰《汉书》，《两都赋》作者。","ans":"班固（32–92），字孟坚，**东汉史学家、辞赋家**，出身史学世家，继父班彪之志编撰史书。所著**《汉书》**记西汉一代历史，是**中国第一部纪传体断代史**，后由妹**班昭**等续成未完的部分。辞赋以**《两都赋》**（《西都赋》《东都赋》）闻名，是汉代京都赋的代表，被列为**汉赋四大家**之一。他与司马迁并称“班马”，二人的著作奠定了纪传体史书的传统。","pts":["东汉史学家、辞赋家，字孟坚","《汉书》第一部纪传体断代史，班昭续成","《两都赋》；汉赋四大家；班马"],"mem":"“班”对“马”：班固写断代(汉书)，司马迁写通史(史记)。《两都赋》两个都城：西都长安、东都洛阳；张衡《二京赋》也是两京，配成对：“班两都，张二京”。","mix":"《汉书》前人说是“班氏父子”所作，班彪开其端，班昭、马续续成；《两都赋》(班固)与《二京赋》(张衡)易混。","mcq":[{"q":"《汉书》的作者是","o":["班固","司马迁","范晔","陈寿"],"a":0,"w":"班固撰《汉书》，范晔撰《后汉书》，陈寿撰《三国志》。"}],"rel":[{"t":"《汉书》","n":"代表作"},{"t":"班马","n":"与司马迁并称"},{"t":"汉赋四大家","n":"成员之一"},{"t":"张衡","n":"《二京赋》对举"}],"more":"作品：《汉书》《两都赋》《白虎通义》（整理）","exam":[]},{"id":"z10-009","t":"张衡","cid":"03b","p":2,"kind":"人物","alias":["张平子"],"one":"东汉科学家、文学家，《二京赋》《归田赋》作者，造浑天仪与地动仪。","ans":"张衡（78–139），字平子，**东汉杰出的科学家、文学家**，南阳西鄂人。科学上改进**浑天仪**，创制**候风地动仪**。文学上以**《二京赋》**（《西京赋》《东京赋》）模仿并超越班固《两都赋》，又作**《归田赋》**，抒写归隐田园的情怀，开**抒情小赋**之风；另有七言诗**《四愁诗》**。他位列**汉赋四大家**，两方面成就都在汉代首屈一指。","pts":["东汉科学家、文学家，字平子","《二京赋》《归田赋》《四愁诗》","归田赋开抒情小赋；汉赋四大家；浑天仪地动仪"],"mem":"一人两面：天上浑天仪，地下地动仪；文学上“二京”铺陈，“归田”抒情。《归田赋》的“田”和“归”记成：写累了大赋，回家种田。","mix":"《二京赋》(张衡)与《两都赋》(班固)；《归田赋》与陶渊明《归园田居》都写归隐，但前者是赋，后者是诗。","mcq":[{"q":"开抒情小赋之风的《归田赋》作者是","o":["班固","张衡","扬雄","司马相如"],"a":1,"w":"张衡《归田赋》，是汉赋由铺陈向抒情转变的标志。"}],"rel":[{"t":"汉赋四大家","n":"成员之一"},{"t":"班固","n":"《两都赋》对举"},{"t":"赋（文体）","n":"所作文体"},{"t":"陶渊明","n":"同写归田，后世诗人"}],"more":"作品：《二京赋》《归田赋》《四愁诗》\n科技：浑天仪、候风地动仪（132年）。","exam":[]},{"id":"z10-010","t":"扬雄","cid":"03b","p":3,"kind":"人物","alias":["杨雄","扬子云"],"one":"西汉辞赋家、哲学家、语言学家，“汉赋四大家”之一。","ans":"扬雄（前53–18），字子云，成都人，**西汉辞赋家、学者**。他与司马相如、班固、张衡合称**“汉赋四大家”**。其辞赋有**《甘泉赋》《长杨赋》**，后反思“劝百讽一”而弃赋；学术著有《法言》与我国首部方言专著**《方言》**，集辞赋与经哲之大成。","pts":["西汉成都人，字子云，汉赋四大家之一","辞赋代表作《甘泉赋》《长杨赋》，反思劝百讽一","著有《法言》《太玄》与首部方言专著《方言》"],"mem":"扬子云成都客，甘泉长杨成大赋；晚年反思劝百讽一，撰成法言与方言。","mix":"扬雄姓‘扬’（木易杨在古代通用但现代学术规范写‘扬’）；《方言》全称《輶轩使者绝代语释别国方言》，是我国第一部方言著作。","mcq":[{"q":"西汉学者扬雄撰写的中国第一部方言词汇研究专著是","o":["《尔雅》","《释名》","《方言》","《说文解字》"],"a":2,"w":"扬雄所撰《方言》是我国第一部方言学专著。"}],"rel":[{"t":"汉赋四大家","n":"所属合称"},{"t":"司马相如","n":"汉赋同侪先驱"},{"t":"班固","n":"汉赋四大家同列"}],"more":"辞赋：《甘泉赋》《羽猎赋》《长杨赋》《河东赋》\n著作：《法言》《太玄》《方言》","exam":[]},{"id":"c-012","t":"汉赋四大家","cid":"03b","p":2,"kind":"合称","alias":["汉赋四大家"],"one":"司马相如、扬雄、班固、张衡，汉赋四位代表作家。","ans":"汉赋四大家是指**汉代四位辞赋代表作家：司马相如、扬雄、班固、张衡**。司马相如作**《子虚赋》《上林赋》**，是汉大赋的奠基者；扬雄作《甘泉赋》《羽猎赋》，并著《方言》；班固作**《两都赋》**；张衡作**《二京赋》《归田赋》**，其中《归田赋》开抒情小赋之风。四人的作品铺陈华美，使**汉赋**成为**汉代文学的代表**，与唐诗、宋词、元曲并列。","pts":["司马相如、扬雄、班固、张衡","相如《子虚》《上林》，班固《两都》，张衡《二京》","汉赋是汉代文学代表"],"members":[["司马相如","《子虚赋》《上林赋》，汉大赋奠基者"],["扬雄","《甘泉赋》《羽猎赋》，著《方言》"],["班固","《两都赋》，撰《汉书》"],["张衡","《二京赋》《归田赋》，东汉科学家"]],"mem":"口诀“相扬班张”：相如，扬雄，班固，张衡。按时代顺序，前两位西汉，后两位东汉。配赋名：相如“子虚上林”，扬雄“甘泉羽猎”，班固“两都”，张衡“二京”。","mix":"另有“枚乘、司马相如、扬雄、班固/张衡”等说法，通行为本条四位；贾谊是骚体赋，不在四大家。","mcq":[{"q":"下列作家中，不属于“汉赋四大家”的是","o":["司马相如","班固","贾谊","张衡"],"a":2,"w":"四大家是司马相如、扬雄、班固、张衡；贾谊是西汉初的骚体赋作家。"}],"rel":[{"t":"司马相如","n":"四大家之首"},{"t":"扬雄","n":"成员之一"},{"t":"班固","n":"成员之一"},{"t":"张衡","n":"成员之一"},{"t":"元杂剧与元曲四大家","n":"同为“四大家”，常对举"}],"more":"汉赋发展：骚体赋(贾谊)→汉大赋(枚乘《七发》、司马相如)→抒情小赋(张衡《归田赋》)。","exam":[]},{"id":"c-013","t":"班马","cid":"03b","p":2,"kind":"合称","alias":["班马"],"one":"班固与司马迁的合称，西汉东汉两位史学大家。","ans":"班马是**班固与司马迁的合称**，指**汉代两位史学大家**。司马迁撰**《史记》**，是**第一部纪传体通史**，被鲁迅誉为“史家之绝唱，无韵之离骚”；班固撰**《汉书》**，是**第一部纪传体断代史**。二人开创并完善了**纪传体**，影响了此后“二十四史”的体例，也都具有很高的文学价值，后世常以“班马”并称，评价史家文章之优劣。","pts":["班固与司马迁并称","史记通史，汉书断代","共同奠定纪传体传统"],"members":[["司马迁","《史记》，第一部纪传体通史"],["班固","《汉书》，第一部纪传体断代史"]],"mem":"顺序是“班”在前，但时间上马在前：马(史记，西汉)，班(汉书，东汉)。记“班断马通”：班固断代，司马通史。","mix":"班马不是“班超”和“马融”；司马迁与司马光并称“二司马”，易混。","mcq":[{"q":"“班马”指的是","o":["班昭与马融","班固与马援","班超与司马相如","班固与司马迁"],"a":3,"w":"班固撰《汉书》，司马迁撰《史记》。"}],"rel":[{"t":"司马迁","n":"马"},{"t":"班固","n":"班"},{"t":"《汉书》","n":"班固所撰"},{"t":"纪传体与《史记》","n":"体例"}],"exam":[]},{"id":"b03-005","t":"建安文学与三曹","cid":"03c","p":1,"kind":"流派","exam":["2023选择"],"alias":["建安风骨","建安文学","三曹"],"one":"东汉末建安年间文学，三曹七子领衔，风格慷慨悲凉，称建安风骨。","ans":"建安文学指**东汉献帝建安年间（196–220）至魏初的文学**，代表作家为**“三曹”（曹操、曹丕、曹植）、“建安七子”和蔡琰**。作品反映战乱现实和建功立业的抱负，**风格慷慨悲凉，被称为“建安风骨”**。曹操有《观沧海》《短歌行》，曹丕有《燕歌行》和文论《典论·论文》，曹植有《白马篇》《赠白马王彪》《洛神赋》。建安文学**推动了五言诗的成熟**。","pts":["东汉末建安时期，三曹七子蔡琰","慷慨悲凉，建安风骨","五言诗成熟"],"members":[["曹操","《观沧海》《短歌行》"],["曹丕","《燕歌行》《典论·论文》"],["曹植","《白马篇》《洛神赋》《赠白马王彪》"]],"mem":"三曹口诀“操丕植”，父一子二：曹操是父，曹丕曹植是子。作品记“操歌海、丕燕论、植洛白”：操《短歌行》《观沧海》，丕《燕歌行》，植《洛神赋》《白马篇》。","mix":"曹丕《燕歌行》是现存最早完整的七言诗；“才高八斗”指曹植；蔡文姬即蔡琰，是蔡邕之女。","mcq":[{"q":"《赠白马王彪》的作者是","o":["曹操","曹植","曹丕","王粲"],"a":1,"w":"曹植写给异母弟曹彪，2023选择。"},{"q":"下列不属于“建安七子”的是","o":["孔融","陈琳","曹植","王粲"],"a":2,"w":"七子是孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢。"}],"rel":[{"t":"曹操","n":"三曹之首"},{"t":"曹丕","n":"三曹之一"},{"t":"曹植","n":"三曹之一"},{"t":"建安七子","n":"同时代文人"},{"t":"《诗经》","n":"现实主义传统远源"}],"more":"建安风骨亦称“汉魏风骨”。"},{"id":"b03-019","t":"曹植《赠白马王彪》","cid":"03c","p":1,"kind":"作品","exam":["2023选择"],"alias":["赠白马王彪"],"one":"曹植写给异母弟曹彪的七章离别诗，抒写兄弟被迫分离的悲愤。","ans":"《赠白马王彪》是**三国魏诗人曹植**创作的**五言赠答诗**，共七章。黄初四年，曹植与任城王曹彰、白马王曹彪入朝洛阳，曹彰暴卒，归国时又被迫与**异母弟白马王曹彪**分路而行。诗中抒写**骨肉被迫分离的悲愤**，揭露**曹丕集团的迫害**，感情沉郁，章法上每章首尾蝉联。此诗是**建安诗歌的代表作**，也是曹植后期诗风的典型，与《洛神赋》《白马篇》并列名篇。","pts":["曹植作，赠异母弟曹彪","七章，抒兄弟分离悲愤","建安诗歌代表作"],"mem":"画面：洛阳归途，兄弟三人上路，一人暴亡，两人被迫分道，诗人写“收泪即长路，援笔从此辞”。记“白马王”不是白马，是曹彪的封号。","mix":"曹植的诗另有《七哀诗》，《七步诗》作者有争议；《赠白马王彪》不是《洛神赋》。","mcq":[{"q":"《赠白马王彪》是曹植写给谁的","o":["曹彪","曹丕","曹彰","曹操"],"a":0,"w":"白马王即异母弟曹彪。"},{"q":"下列属于曹植作品的是","o":["《燕歌行》","《白马篇》","《短歌行》","《观沧海》"],"a":1,"w":"《白马篇》为曹植作，其余属曹丕、曹操。"}],"rel":[{"t":"曹植","n":"作者"},{"t":"曹植《洛神赋》","n":"另一名作"},{"t":"建安文学与三曹","n":"所属文学"},{"t":"曹丕","n":"诗中所指迫害者"}],"more":"收泪即长路，援笔从此辞。｜《赠白马王彪》"},{"id":"b03-028","t":"陶渊明","cid":"03c","p":1,"kind":"人物","alias":["陶潜","五柳先生","靖节先生","陶元亮","陶靖节"],"one":"东晋诗人，田园诗派之祖，《归园田居》《桃花源记》，不为五斗米折腰。","ans":"陶渊明（约365–427），名潜，字元亮，号五柳先生，私谥靖节，**东晋诗人、辞赋家**，**田园诗派之祖**。他曾任彭泽令，因**不愿“为五斗米折腰”**辞官归隐。代表作有**《归园田居》《饮酒》《桃花源记》《归去来兮辞》**，另有《五柳先生传》。诗风平淡自然，名句“采菊东篱下，悠然见南山”。钟嵘《诗品》称他为**“古今隐逸诗人之宗”**，对唐宋山水田园诗影响深远。","pts":["东晋诗人，田园诗派之祖","归园田居、饮酒、桃花源记、归去来兮辞","不为五斗米折腰，隐逸诗人之宗"],"mem":"口诀“田陶山谢”：田园陶渊明，山水谢灵运。作品记“归归饮桃”：《归园田居》《归去来兮辞》《饮酒》《桃花源记》。画面：东篱采菊，悠然见南山。","mix":"山水诗之祖是谢灵运，田园诗之祖是陶渊明；生卒年另有365–427、372或376–427等说。","mcq":[{"q":"“采菊东篱下，悠然见南山”的作者是","o":["谢灵运","陶渊明","王维","孟浩然"],"a":1,"w":"出自陶渊明《饮酒·其五》。"},{"q":"被视为山水诗之祖的是","o":["陶渊明","谢灵运","谢朓","王维"],"a":1,"w":"陶渊明是田园诗之祖，谢灵运开山水诗。"}],"rel":[{"t":"谢灵运","n":"山水诗对举"},{"t":"陶谢；大小谢","n":"并称"},{"t":"山水田园诗派","n":"后世继承"},{"t":"陶渊明作品：《归去来兮辞》《桃花源记》《饮酒》","n":"作品详解"},{"t":"孟浩然","n":"唐代田园继承者"}],"more":"采菊东篱下，悠然见南山。｜《饮酒·其五》\n少无适俗韵，性本爱丘山。｜《归园田居·其一》\n问今是何世，乃不知有汉，无论魏晋。｜《桃花源记》","exam":[]},{"id":"b03-053","t":"蔡文姬","cid":"03c","p":1,"kind":"人物","exam":["2014名解"],"alias":["蔡琰","文姬"],"one":"东汉末女诗人蔡琰，蔡邕之女，作《悲愤诗》，曹操赎归。","ans":"蔡文姬名琰，字文姬（一作昭姬），**东汉末年女诗人**，**蔡邕之女**。她在战乱中被匈奴所掳，嫁左贤王，生二子，在胡地十二年，后**曹操以重金将她赎回**，史称“文姬归汉”，再嫁董祀。代表作有五言长篇**《悲愤诗》**，叙述自己的离乱遭遇，被誉为**汉末的“史诗”式作品**，传为《胡笳十八拍》作者，但归属有争议。她是建安时期最重要的女作家。","pts":["蔡邕之女，东汉末女诗人","被掳匈奴，曹操赎归","《悲愤诗》，传《胡笳十八拍》"],"mem":"画面：曹操念蔡邕无后，用金璧从匈奴赎回其女，“文姬归汉”。作品记：悲愤诗是真，胡笳十八拍存疑。","mix":"《胡笳十八拍》作者有争议；蔡邕是父亲，书法家，不是诗人蔡文姬。","mcq":[{"q":"曹操以重金赎回的女诗人是","o":["李清照","班昭","卓文君","蔡文姬"],"a":3,"w":"蔡琰被曹操赎回，史称文姬归汉。"},{"q":"蔡文姬的代表作是","o":["《洛神赋》","《悲愤诗》","《白马篇》","《燕歌行》"],"a":1,"w":"《悲愤诗》是其五言长篇。"}],"rel":[{"t":"蔡邕","n":"其父"},{"t":"曹操","n":"赎其归汉"},{"t":"建安文学与三曹","n":"同时代文学"},{"t":"李清照","n":"后世女词人"}],"more":"《悲愤诗》五言与骚体各一首；《胡笳十八拍》有争议。"},{"id":"b03-055","t":"建安七子","cid":"03c","p":1,"kind":"合称","alias":["建安七子","七子"],"one":"孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢，建安时期七位文人。","ans":"建安七子是**东汉建安年间七位文人的合称**，由**曹丕《典论·论文》提出**，即**孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢**。他们大多依附曹氏，常聚邺下，与三曹唱和，作品反映战乱和个人抱负，风格慷慨，属**建安风骨**。其中**王粲成就最高，《登楼赋》最著名**，另有《七哀诗》；陈琳有《饮马长城窟行》，刘桢有《赠从弟》。七子推动了五言诗和抒情小赋的发展。","pts":["孔融陈琳王粲徐干阮瑀应玚刘桢","曹丕《典论·论文》提出","王粲《登楼赋》最著名"],"members":[["孔融","七子之首，《杂诗》，“孔融让梨”"],["陈琳","《饮马长城窟行》，檄文"],["王粲","《登楼赋》《七哀诗》，成就最高"],["徐干","《中论》"],["阮瑀","章表书记"],["应玚","《文质论》"],["刘桢","《赠从弟》“岁寒松柏”"]],"mem":"首字串联：孔陈王，徐阮应刘。顺口版“孔陈王徐，阮应刘”，通行排序即《典论·论文》所列。记忆点：王粲写《登楼赋》，孔融让梨，记住这两个就够抓大头。","mix":"“竹林七贤”是魏晋之际的另一七人（嵇康、阮籍等）；阮瑀与阮籍同姓不同人，阮瑀是建安七子。","mcq":[{"q":"《登楼赋》的作者是","o":["孔融","刘桢","陈琳","王粲"],"a":3,"w":"王粲，建安七子中成就最高者。"},{"q":"最早提出“建安七子”之名的是","o":["刘勰","钟嵘","萧统","曹丕"],"a":3,"w":"曹丕《典论·论文》。"}],"rel":[{"t":"曹丕《典论·论文》","n":"提出七子之名"},{"t":"建安文学与三曹","n":"同属建安"},{"t":"竹林七贤","n":"另一个“七”"},{"t":"曹丕","n":"首倡者"}],"more":"孔融《杂诗》；陈琳《饮马长城窟行》；王粲《登楼赋》《七哀诗》；刘桢《赠从弟》。","exam":[]},{"id":"b03-056","t":"竹林七贤与诗文","cid":"03c","p":1,"kind":"合称","alias":["竹林七贤","嵇阮"],"one":"嵇康、阮籍等七人，魏晋之际玄学名士，嵇康《与山巨源绝交书》，阮籍《咏怀诗》。","ans":"竹林七贤是**魏末晋初七位名士的合称**，即**嵇康、阮籍、山涛、向秀、刘伶、王戎、阮咸**，常聚于山阳竹林，崇尚老庄，反对虚伪礼教，是**正始文学**的代表。**嵇康作《与山巨源绝交书》**，表明不与司马氏合作，后遭杀害；**阮籍作五言《咏怀诗》八十二首**，曲折抒写苦闷，又有《大人先生传》；刘伶有《酒德颂》。其风度被称为**“魏晋风度”**。","pts":["嵇康阮籍山涛向秀刘伶王戎阮咸","嵇康《与山巨源绝交书》","阮籍《咏怀诗》，魏晋风度"],"members":[["嵇康","《与山巨源绝交书》，《广陵散》"],["阮籍","《咏怀诗》，青白眼"],["山涛","山巨源，后出仕"],["向秀","《思旧赋》"],["刘伶","《酒德颂》"],["王戎","善清谈"],["阮咸","善弹琵琶"]],"mem":"首字串联：嵇阮山向刘王阮。口诀“嵇阮山向，刘王阮咸”。文章记：嵇绝交，阮咏怀；一个写信一个写诗。画面：竹林里弹琴饮酒。","mix":"“建安七子”是东汉末，竹林七贤是魏晋之际；嵇康被杀前弹《广陵散》。","mcq":[{"q":"《咏怀诗》八十二首的作者是","o":["嵇康","刘伶","阮籍","山涛"],"a":2,"w":"阮籍的五言组诗。"},{"q":"作《与山巨源绝交书》的是","o":["嵇康","阮籍","向秀","王戎"],"a":0,"w":"嵇康写给山涛。"}],"rel":[{"t":"竹林七贤","n":"同一词条另一说法"},{"t":"嵇康","n":"代表之一"},{"t":"阮籍","n":"代表之一"},{"t":"正始文学与阮籍《咏怀诗》","n":"所属阶段"},{"t":"《广陵散》","n":"嵇康绝响"}],"more":"阮籍青白眼；刘伶《酒德颂》；向秀《思旧赋》。","exam":[]},{"id":"b03-057","t":"谢灵运","cid":"03c","p":2,"kind":"人物","alias":["谢康乐","大谢","谢客"],"one":"南朝宋诗人，山水诗派开创者，名句“池塘生春草”。","ans":"谢灵运（385–433）是**南朝宋诗人**，出身陈郡谢氏，袭封康乐公，世称**谢康乐**，因与谢朓并称“大小谢”而被称**大谢**。他长期任职外郡，纵情山水，把自然景物作为主要描写对象，是**山水诗派的开创者**。代表作有**《登池上楼》**，其中“池塘生春草，园柳变鸣禽”为千古名句，另有《山居赋》。他开启了**中国山水诗的传统**，与陶渊明并称“陶谢”，分别代表田园诗与山水诗。","pts":["南朝宋诗人，袭封康乐公","山水诗派开创者，《登池上楼》","与陶渊明并称陶谢，与谢朓并称大小谢"],"mem":"“谢”字有两个：大谢谢灵运，小谢谢朓。他写山水，陶渊明写田园，口诀“陶田谢山”。名句“池塘生春草”，画面就是池塘边春草初生。“才高八斗”也出自谢灵运的话，他说天下才共一石，曹植独占八斗。","mix":"陶渊明开田园诗，谢灵运开山水诗，不要互换；“池塘生春草”是谢灵运，“采菊东篱下”是陶渊明。","mcq":[{"q":"“池塘生春草，园柳变鸣禽”的作者是","o":["陶渊明","谢朓","谢灵运","鲍照"],"a":2,"w":"出自谢灵运《登池上楼》。"}],"rel":[{"t":"陶谢；大小谢","n":"并称"},{"t":"谢朓","n":"小谢"},{"t":"陶渊明","n":"田园诗对山水诗"},{"t":"山水田园诗派","n":"唐代继承者"}],"more":"名句：池塘生春草，园柳变鸣禽。｜《登池上楼》\n作品：《登池上楼》《山居赋》","exam":[]},{"id":"b03-058","t":"骈文","cid":"03c","p":2,"kind":"概念","alias":["骈体文","四六文","骈俪文"],"one":"讲究对偶、声律、用典、辞藻的文体，盛行于魏晋南北朝。","ans":"骈文是一种**以对偶为主要特征的文体**，又称骈体文、四六文，因句式多为四字、六字相间而得名。它形成于**汉魏**，**南北朝**时期最为盛行，讲究**对偶、声律、用典和辞藻**。代表作家有徐陵、庾信，合称“徐庾”，庾信的《哀江南赋》是集大成之作。唐代王勃的**《滕王阁序》**是骈文名篇，“落霞与孤鹜齐飞，秋水共长天一色”广为传诵。中唐韩愈倡导**古文运动**，针对的正是骈文的形式主义。","pts":["讲究对偶、声律、用典、辞藻","魏晋南北朝盛行，徐庾为代表","唐代王勃《滕王阁序》；古文运动反对"],"mem":"“骈”字本义是两马并驾，所以骈文就是句子“两两并排”(对偶)。再记四六：四字六字交错，所以叫“四六文”。古文运动就是对着它来的，一骈一散。","mix":"骈文与赋不同：赋是铺陈的文体，骈文强调对偶声律；《滕王阁序》是骈文，不是赋。","mcq":[{"q":"下列作品中属于骈文的是","o":["《过秦论》","《师说》","《岳阳楼记》","《滕王阁序》"],"a":3,"w":"王勃《滕王阁序》是唐代骈文名篇；《过秦论》《师说》是散文。"}],"rel":[{"t":"古文运动","n":"反对骈文"},{"t":"庾信","n":"集大成"},{"t":"徐庾","n":"骈文代表并称"},{"t":"王勃","n":"《滕王阁序》作者"},{"t":"《与朱元思书》与南朝骈体书信","n":"南朝骈体小品"}],"more":"名句：落霞与孤鹜齐飞，秋水共长天一色。｜王勃《滕王阁序》\n骈文别称：骈体文、骈俪文、四六文。","exam":[]},{"id":"b03-059","t":"永明体与宫体诗","cid":"03c","p":2,"kind":"流派","alias":["永明体","宫体诗","永明声律","四声八病"],"one":"永明体讲声律，是格律诗先声；宫体诗是梁陈宫廷艳情诗。","ans":"永明体与宫体诗都是**南朝诗歌的新体**。**永明体**产生于**南齐永明年间**，以**沈约、谢朓、王融**为代表，提出四声八病之说，讲究诗歌声律，是**唐代格律诗的先声**。**宫体诗**盛行于**梁陈**，因梁简文帝萧纲为太子时的东宫而得名，内容多写宫廷女性与艳情，形式绮丽，徐陵编的《玉台新咏》是其集中体现。两者分别在声律与题材上影响了后世。","pts":["永明体：南齐永明年间，沈约、谢朓、王融","讲声律，四声八病，格律诗先声","宫体诗：梁陈宫廷艳情诗，《玉台新咏》"],"mem":"“永”记“声”：永明体=讲究声律。“宫”记“宫廷”：宫体诗=宫廷艳情诗。一个管形式(音律)，一个管内容(艳情)。沈约“四声八病”，谢朓是永明体代表诗人，也是小谢。","mix":"永明体的声律说是格律诗的前身，不是已成熟的律诗；律诗定型要到初唐沈佺期、宋之问。","mcq":[{"q":"以下属于永明体代表人物的是","o":["沈约","徐陵","庾信","萧纲"],"a":0,"w":"永明体代表人物是沈约、谢朓、王融；徐陵、庾信、萧纲属宫体诗。"}],"rel":[{"t":"谢朓","n":"永明体代表诗人"},{"t":"《玉台新咏》","n":"宫体诗选集"},{"t":"徐庾","n":"宫体诗代表"},{"t":"“沈宋”与律诗定型","n":"永明体到律诗"}],"exam":[]},{"id":"z20-001","t":"曹操","cid":"03c","p":2,"kind":"人物","alias":["魏武帝","曹孟德","阿瞒","魏武"],"one":"建安文学开创者，《观沧海》《龟虽寿》《短歌行》作者，三曹之首。","ans":"曹操（155–220），字孟德，**东汉末政治家、军事家、诗人**，**建安文学的开创者**，追尊魏武帝。他的诗继承汉乐府传统，以**乐府旧题写时事**，风格**慷慨悲凉**，被称为**“建安风骨”**的代表。代表作有《观沧海》（出自《步出夏门行》）、《龟虽寿》、《短歌行》、《蒿里行》，名句如“老骥伏枥，志在千里”“对酒当歌，人生几何”。他与儿子曹丕、曹植并称**“三曹”**。","pts":["字孟德，东汉末政治家、诗人","观沧海、龟虽寿、短歌行、蒿里行","建安风骨开创者，三曹之首"],"mem":"名篇口诀“观龟短蒿”：观沧海、龟虽寿、短歌行、蒿里行。《观沧海》是《步出夏门行》的第一章，“东临碣石”是北征乌桓归来的场景。三曹按父子顺序：操、丕、植。","mix":"《观沧海》不是单独的诗，出自乐府组诗《步出夏门行》；《短歌行》有“周公吐哺”，是求贤之意。","mcq":[{"q":"《观沧海》出自曹操的乐府组诗","o":["《短歌行》","《步出夏门行》","《龟虽寿》","《蒿里行》"],"a":1,"w":"《观沧海》是《步出夏门行》第一章。"}],"rel":[{"t":"建安文学与三曹","n":"所属流派"},{"t":"曹丕","n":"长子"},{"t":"曹植","n":"三子"},{"t":"《三国演义》","n":"文学形象对照"}],"more":"名句：老骥伏枥，志在千里；烈士暮年，壮心不已。｜《龟虽寿》\n对酒当歌，人生几何！｜《短歌行》\n山不厌高，海不厌深。周公吐哺，天下归心。｜《短歌行》\n东临碣石，以观沧海。｜《观沧海》","exam":[]},{"id":"z20-002","t":"曹丕","cid":"03c","p":2,"kind":"人物","alias":["魏文帝","曹子桓"],"one":"魏文帝，《燕歌行》《典论·论文》作者，三曹之一。","ans":"曹丕（187–226），字子桓，**曹操之子，魏文帝**，建安文学代表人物，三曹之一。他的**《燕歌行》**是现存**最早的完整七言诗**，写思妇怀人。所著**《典论·论文》**是**中国第一篇文学批评专论**，提出**“文以气为主”**，称文章为“经国之大业，不朽之盛事”，并第一次提出**“建安七子”**。他把文学从经学附庸中独立出来，对魏晋文学自觉有开创之功。","pts":["曹操次子（嫡长子），魏文帝，三曹之一","《燕歌行》最早完整七言诗","《典论·论文》第一篇文学批评专论，提出建安七子"],"mem":"两个“第一”：燕歌行=第一首完整七言诗，典论论文=第一篇文论专文。名句“盖文章，经国之大业，不朽之盛事”，记成文章不朽。","mix":"唐代高适也有《燕歌行》，是边塞诗；曹丕的《燕歌行》写思妇之情；“文人相轻”也出自《典论·论文》。","mcq":[{"q":"现存最早的完整七言诗是","o":["曹操《短歌行》","曹植《白马篇》","曹丕《燕歌行》","高适《燕歌行》"],"a":2,"w":"曹丕《燕歌行》是现存最早的完整七言诗。"}],"rel":[{"t":"曹丕《典论·论文》","n":"文论代表作"},{"t":"曹丕《燕歌行》","n":"诗歌代表作"},{"t":"建安七子","n":"出自其文"},{"t":"曹操","n":"父亲"},{"t":"《文心雕龙》","n":"后来的文论专著"}],"more":"名句：盖文章，经国之大业，不朽之盛事。｜《典论·论文》\n文人相轻，自古而然。｜《典论·论文》","exam":[]},{"id":"z20-003","t":"曹植","cid":"03c","p":1,"kind":"人物","exam":["2023选择"],"alias":["曹子建","陈思王","子建"],"one":"建安诗人，字子建，号称“才高八斗”，作《洛神赋》《白马篇》。","ans":"曹植（192–232），字子建，**曹操之子，建安时期诗人**，封陈王，谥思，世称**陈思王**。早年受宠，后受曹丕猜忌，处境艰难。前期诗作有《白马篇》，名句“捐躯赴国难，视死忽如归”，后期有《赠白马王彪》《七哀诗》，另有名赋**《洛神赋》**。钟嵘《诗品》誉其**“建安之杰”**，谢灵运称其**“才高八斗”**。他使五言诗走向成熟，对后世诗歌影响很大。","pts":["字子建，陈思王，三曹之一","《洛神赋》《白马篇》《赠白马王彪》","建安之杰，才高八斗"],"mem":"画面：七步成诗，“煮豆燃豆萁”（作者有争议）；“才高八斗”中天下才一石，曹植独占八斗。作品记“洛白赠”：《洛神赋》《白马篇》《赠白马王彪》。","mix":"《七步诗》见《世说新语》，作者归属有争议；《燕歌行》是曹丕，《短歌行》是曹操。","mcq":[{"q":"“才高八斗”的典故用来称赞","o":["曹操","曹丕","王粲","曹植"],"a":3,"w":"谢灵运称天下才共一石，曹植独得八斗。"},{"q":"东晋顾恺之《洛神赋图》所据文学作品的作者是","o":["曹丕","曹操","蔡琰","曹植"],"a":3,"w":"据曹植《洛神赋》而画。"}],"rel":[{"t":"曹植《赠白马王彪》","n":"名作"},{"t":"曹植《洛神赋》","n":"代表赋"},{"t":"《洛神赋图》","n":"后世画作"},{"t":"曹丕","n":"兄"},{"t":"李白","n":"后世浪漫诗人"}],"more":"捐躯赴国难，视死忽如归。｜《白马篇》\n翩若惊鸿，婉若游龙。｜《洛神赋》"},{"id":"z20-004","t":"王粲","cid":"03c","p":2,"kind":"人物","alias":["王仲宣","七子之冠冕"],"one":"建安七子中成就最高者，《登楼赋》《七哀诗》作者。","ans":"王粲（177–217），字仲宣，**东汉末文学家，建安七子之一**，被认为是七子中**成就最高者**，刘勰称其为“七子之冠冕”。他早年避乱荆州，依附刘表，后归曹操。代表作为**《登楼赋》**，登楼远望，抒发怀乡与不得志之情，另有五言诗**《七哀诗》**，反映战乱中的民间苦难。他与曹植并称**“曹王”**，作品体现了**建安风骨**的悲凉慷慨。","pts":["建安七子中成就最高","《登楼赋》《七哀诗》","与曹植并称曹王"],"mem":"七子名单口诀“孔陈王徐阮应刘”：孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢，王粲排第三，也是最高者。《登楼赋》“登楼”记成他登城楼思乡。","mix":"建安七子不含曹氏父子；孔融排首，王粲成就最高；《七哀诗》“西京乱无象”写长安战乱。","mcq":[{"q":"《登楼赋》的作者是","o":["孔融","陈琳","刘桢","王粲"],"a":3,"w":"王粲，建安七子之一。"}],"rel":[{"t":"建安七子","n":"所属群体"},{"t":"曹植","n":"并称曹王"},{"t":"建安文学与三曹","n":"所属时代"},{"t":"赋（文体）","n":"抒情小赋代表"}],"more":"建安七子：孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢。\n作品：《登楼赋》《七哀诗》","exam":[]},{"id":"z20-005","t":"阮籍","cid":"03c","p":2,"kind":"人物","alias":["阮嗣宗","阮步兵"],"one":"竹林七贤之一，《咏怀诗》八十二首作者，“青白眼”典故。","ans":"阮籍（210–263），字嗣宗，**魏晋之际的诗人，竹林七贤之一**，曾任步兵校尉，世称阮步兵。他生活在司马氏与曹魏斗争的时期，为避祸常饮酒佯狂。代表作**《咏怀诗》八十二首**，用隐晦曲折的手法抒写苦闷，风格**沉郁**，开创了五言抒怀组诗；另有《大人先生传》。他与嵇康并称**“嵇阮”**，是**正始文学**的代表，**“青白眼”**典故出自他。","pts":["竹林七贤之一，正始文学代表","《咏怀诗》八十二首，隐晦抒愤","与嵇康并称嵇阮；青白眼"],"mem":"阮籍“青眼”看知己，“白眼”看俗人，一个动作记住一个人。“嵇阮”两人一个写文(《与山巨源绝交书》)，一个写诗(《咏怀》)。竹林七贤口诀见嵇康条。","mix":"阮籍写诗，嵇康长于论说文，且嵇康被杀、阮籍善终；“穷途之哭”也是阮籍典故。","mcq":[{"q":"“青白眼”的典故出自","o":["阮籍","嵇康","刘伶","山涛"],"a":0,"w":"阮籍能为青白眼，见礼俗之士以白眼对之。"}],"rel":[{"t":"竹林七贤","n":"所属群体"},{"t":"嵇康","n":"并称嵇阮"},{"t":"正始文学与阮籍《咏怀诗》","n":"代表作与时代"},{"t":"竹林七贤与诗文","n":"成员作品"}],"more":"作品：《咏怀诗》八十二首、《大人先生传》\n名句：昔日繁华子，安陵与龙阳。｜《咏怀诗》","exam":[]},{"id":"z20-006","t":"嵇康","cid":"03c","p":2,"kind":"人物","alias":["嵇叔夜","嵇中散"],"one":"竹林七贤领袖，《与山巨源绝交书》作者，临刑弹《广陵散》。","ans":"嵇康（223–262），字叔夜，**魏晋之际的文学家、思想家，竹林七贤的领袖**，曾任中散大夫，世称嵇中散。他主张**“越名教而任自然”**，反对司马氏提倡的虚伪礼教，因而被司马昭杀害，临刑弹**《广陵散》**。代表作有**《与山巨源绝交书》**《声无哀乐论》《养生论》，文风**峻切**。他与阮籍并称**“嵇阮”**，是**正始文学**的代表。","pts":["竹林七贤领袖，字叔夜","与山巨源绝交书、声无哀乐论、养生论","越名教而任自然；临刑弹广陵散"],"mem":"一个画面：刑场上，三千太学生请愿，嵇康索琴弹《广陵散》，叹“《广陵散》于今绝矣”。口诀“绝交书、无哀乐、养生论”三篇，配琴曲《广陵散》。","mix":"《广陵散》是琴曲，不是诗文；阮籍写诗，嵇康长于论说文，二人并称嵇阮；其生卒年学界另有224–263一说。","mcq":[{"q":"临刑前弹奏《广陵散》的是","o":["阮籍","嵇康","向秀","山涛"],"a":1,"w":"嵇康临刑索琴弹《广陵散》。"}],"rel":[{"t":"竹林七贤","n":"领袖"},{"t":"阮籍","n":"并称嵇阮"},{"t":"《广陵散》","n":"所弹琴曲"},{"t":"魏晋玄学","n":"思想背景"}],"more":"名句：越名教而任自然。｜《释私论》\n作品：《与山巨源绝交书》《声无哀乐论》《养生论》","exam":[]},{"id":"z20-007","t":"陆机","cid":"03c","p":3,"kind":"人物","alias":["陆士衡"],"one":"西晋文学家、书法家，作首篇系统创作论《文赋》与法帖《平复帖》。","ans":"陆机（261–303），字士衡，吴郡人，**西晋文学家、书法家**。他与弟陆云并称**“二陆”**，誉为太康之英。文论名篇**《文赋》**首次系统阐述艺术构思与创作过程；传世墨迹**《平复帖》**被称为**“法帖之祖”**，是现存最早的名家书法真迹。","pts":["西晋文学家，与弟陆云并称“二陆”","作《文赋》，系统论述文学构思与创作过程","作《平复帖》，现存最早名家法帖真迹"],"mem":"士衡二陆冠太康，文赋谈构思，平复传法帖祖。","mix":"《文赋》作者是陆机（西晋）；《文心雕龙》作者是刘勰（南朝）；书法《平复帖》为陆机真迹，王羲之《兰亭集序》仅存唐摹本。","mcq":[{"q":"西晋文学家陆机撰写的中国文学史上首篇系统论述创作心理过程的文论名篇是","o":["《典论·论文》","《诗品》","《文心雕龙》","《文赋》"],"a":3,"w":"陆机作《文赋》，首次系统论述了艺术构思和创作过程。"}],"rel":[{"t":"陆机《文赋》","n":"文论代表作"},{"t":"左思","n":"太康文学同列"},{"t":"太康文学：“三张二陆两潘一左”","n":"所属文学群体"}],"more":"代表作：《文赋》《猛虎行》《赴洛道中作》\n书法真迹：《平复帖》（藏于故宫博物院）","exam":[]},{"id":"z20-008","t":"左思","cid":"03c","p":3,"kind":"人物","alias":["左太冲"],"one":"西晋文学家，作《三都赋》致洛阳纸贵，诗作具“左思风力”。","ans":"左思（约250–约305），字太冲，齐国临淄人，**西晋文学家**。他出身寒门，十年构思撰成**《三都赋》**，豪贵争抄引发**“洛阳纸贵”**。其诗歌代表作**《咏史》**八首借古讽今，揭露门阀制度不公，骨力遒劲，被钟嵘《诗品》誉为具有**“左思风力”**。","pts":["西晋寒门作家，字太冲","作《三都赋》引发“洛阳纸贵”","作《咏史》八首，沉郁刚健，钟嵘称“左思风力”"],"mem":"太冲十年三都赋，洛阳纸贵动京师；咏史八首骨力健，钟嵘独重左思风。","mix":"成语‘洛阳纸贵’出自左思作《三都赋》；名句‘郁郁涧底松，离离山上苗’出自其《咏史·其二》。","mcq":[{"q":"成语‘洛阳纸贵’典故源自西晋哪位作家创作的辞赋名篇","o":["陆机《文赋》","潘岳《藉田赋》","左思《三都赋》","张衡《二京赋》"],"a":2,"w":"左思历时十年写成《三都赋》，洛阳豪贵争相传写，致使洛阳纸贵。"}],"rel":[{"t":"陆机","n":"太康文学同列"},{"t":"钟嵘《诗品》","n":"评其为“左思风力”"},{"t":"陶渊明","n":"晋代诗风演变"}],"more":"代表作：《三都赋》《咏史》八首、《悼亡诗》\n名句：郁郁涧底松，离离山上苗。世胄蹑高位，英俊沉下僚。｜《咏史·其二》","exam":[]},{"id":"z20-011","t":"谢朓","cid":"03c","p":3,"kind":"人物","alias":["小谢","谢玄晖","谢宣城"],"one":"南朝齐诗人，永明体代表作家，与谢灵运合称“大小谢”。","ans":"谢朓（464–499），字玄晖，阳夏人，**南朝齐诗人**。他与谢灵运合称**“大小谢”**，曾任宣城太守。他是**永明体**声律诗代表作家，名作**《晚登三山还望京邑》**有“余霞散成绮，澄江静如练”名句。其清丽诗风深为李白推崇，开盛唐律诗之先河。","pts":["南朝齐诗人，与谢灵运合称“大小谢”","永明体声律诗代表作家，人称“谢宣城”","名句“余霞散成绮，澄江静如练”，李白推重"],"mem":"小谢玄晖守宣城，余霞澄江如练白；永明新体开律绝，太白一生最倾心。","mix":"大谢是南朝宋谢灵运（开山水诗派），小谢是南朝齐谢朓（永明体代表）；李白‘中间小谢又清发’指谢朓。","mcq":[{"q":"李白诗句‘蓬莱文章建安骨，中间小谢又清发’中的‘小谢’指的是","o":["谢灵运","谢朓","谢惠连","谢庄"],"a":1,"w":"‘小谢’指南朝齐诗人谢朓，与南朝宋‘大谢’谢灵运相对。"}],"rel":[{"t":"谢灵运","n":"大小谢并称"},{"t":"竟陵八友","n":"所属文学集团"},{"t":"李白","n":"极度推崇小谢"}],"more":"代表作：《晚登三山还望京邑》《玉阶怨》\n名句：余霞散成绮，澄江静如练。｜《晚登三山还望京邑》","exam":[]},{"id":"z20-012","t":"鲍照","cid":"03c","p":3,"kind":"人物","alias":["鲍参军","鲍明远"],"one":"南朝宋文学家，“元嘉三大家”之一，大力发展七言歌行。","ans":"鲍照（约414–466），字明远，**南朝宋文学家**。他与谢灵运、颜延之并称**“元嘉三大家”**，世称鲍参军。代表作**《拟行路难》**十八首抒发寒士不平。他**大力拓展七言歌行**，辞采刚健，音节激越，对李白、高适等唐代歌行大家影响深远。","pts":["南朝宋文学家，元嘉三大家之一，人称鲍参军","代表作《拟行路难》十八首，抒发寒门志士不平","大力开拓七言歌行体，对盛唐歌行创作影响极深"],"mem":"明远参军行路难，元嘉三家展七言；泻水置平地安能行，盛唐歌行宗鲍照。","mix":"元嘉三大家为谢灵运、颜延之、鲍照；鲍照以七言乐府歌行见长，谢灵运以五言山水诗见长。","mcq":[{"q":"南朝宋时期大力开拓七言歌行、作有《拟行路难》十八首的诗人是","o":["鲍照","谢灵运","颜延之","江淹"],"a":0,"w":"鲍照大力发展七言歌行体，代表作为《拟行路难》十八首。"}],"rel":[{"t":"元嘉三大家","n":"所属文学并称"},{"t":"谢灵运","n":"元嘉三大家同列"},{"t":"李白","n":"受其歌行风格影响"}],"more":"代表作：《拟行路难》十八首、《芜城赋》\n名句：泻水置平地，各自东西南北流。人生亦有命，安能行叹复坐愁？｜《拟行路难·其四》","exam":[]},{"id":"z20-013","t":"庾信","cid":"03c","p":2,"kind":"人物","alias":["庾子山","庾开府"],"one":"由南入北的文学家，《哀江南赋》作者，集六朝骈文之大成。","ans":"庾信（513–581），字子山，**南朝梁入北周的文学家**。他早年在梁宫廷作绮艳的宫体诗，出使西魏时被扣留，后仕北周，作品风格转为**苍凉沉郁**。代表作有**《哀江南赋》**，追述梁朝兴亡与个人身世；另有《枯树赋》《拟咏怀》。他**集六朝骈文之大成**，与徐陵并称**“徐庾”**，杜甫赞他“庾信文章老更成，凌云健笔意纵横”。","pts":["南朝梁入北周，字子山","《哀江南赋》《枯树赋》《拟咏怀》","集六朝骈文之大成，与徐陵并称徐庾"],"mem":"一个人两段人生：南朝时绮艳(宫体)，被留北方后苍凉(哀江南)，“庾信文章老更成”就是这个转折。记“徐庾”：徐陵+庾信，两人都是梁代东宫文人。","mix":"徐陵与庾信都曾在东宫作宫体诗，徐陵入陈，庾信入北周；《哀江南赋》不是“江南”风景诗。","mcq":[{"q":"“庾信文章老更成，凌云健笔意纵横”出自","o":["李白","白居易","杜甫","韩愈"],"a":2,"w":"杜甫《戏为六绝句》。"}],"rel":[{"t":"徐庾","n":"并称"},{"t":"骈文","n":"集大成"},{"t":"徐陵","n":"并称者"},{"t":"杜甫","n":"称赞他"}],"more":"作品：《哀江南赋》《枯树赋》《拟咏怀》\n杜甫《戏为六绝句》：庾信文章老更成，凌云健笔意纵横。","exam":[]},{"id":"z20-018","t":"刘义庆","cid":"03c","p":2,"kind":"人物","alias":["临川王刘义庆"],"one":"南朝宋宗室，编撰志人小说代表《世说新语》。","ans":"刘义庆（403–444），**南朝宋宗室**，袭封临川王，**文学家**。他组织门客编撰**《世说新语》**，是**志人小说的代表作**，记述东汉末至东晋名士的言行与轶事，分德行、言语、政事、文学等**三十六门**。语言简约隽永，鲁迅评为“记言则玄远冷隽，记行则高简瑰奇”。书中**魏晋风度**的形象，对后世笔记小说影响深远。","pts":["南朝宋宗室，临川王","《世说新语》36门，志人小说代表","记魏晋名士言行，鲁迅评其语"],"mem":"“世说”记“世人的话”：记人=志人，对应干宝记鬼神的“志怪”。口诀“志人世说，志怪搜神”：刘义庆《世说》，干宝《搜神》。36门前四：德行、言语、政事、文学。","mix":"志人小说代表是《世说新语》，志怪小说代表是干宝《搜神记》；刘义庆另有志怪《幽明录》，但不是代表作。","mcq":[{"q":"志人小说的代表作是","o":["《搜神记》","《幽明录》","《列异传》","《世说新语》"],"a":3,"w":"《世说新语》是志人小说代表；《搜神记》是志怪小说代表。"}],"rel":[{"t":"《世说新语》","n":"代表作"},{"t":"志人小说","n":"所属类型"},{"t":"干宝","n":"志怪对举"},{"t":"魏晋玄学","n":"书中名士风度背景"}],"more":"作品：《世说新语》(36门)、《幽明录》","exam":[]},{"id":"z20-019","t":"干宝","cid":"03c","p":2,"kind":"人物","alias":["干令升"],"one":"东晋史学家，志怪小说代表《搜神记》作者。","ans":"干宝（?–336），字令升，**东晋史学家、文学家**，曾任著作郎，撰有《晋纪》。他所著**《搜神记》**是**志怪小说的代表作**，记录神异鬼怪与民间传说，其中**《干将莫邪》《韩凭夫妇》《董永》**等篇流传很广，如写复仇精神的《干将莫邪》、写爱情忠贞的《韩凭夫妇》。《搜神记》为后世志怪、传奇、戏曲提供了大量素材，也是**魏晋南北朝志怪小说**的高峰。","pts":["东晋史学家，撰《晋纪》","《搜神记》志怪小说代表","《干将莫邪》《韩凭夫妇》《董永》"],"mem":"“搜神”=搜集神怪故事。三篇各一个画面：干将莫邪(铸剑复仇，头颅煮于鼎中)，韩凭夫妇(相思树，鸳鸯)，董永(卖身葬父，仙女下凡)。","mix":"志怪是《搜神记》，志人是《世说新语》；《聊斋志异》是清代文言短篇小说，不属南北朝。","mcq":[{"q":"《干将莫邪》《韩凭夫妇》出自","o":["《搜神记》","《世说新语》","《幽明录》","《聊斋志异》"],"a":0,"w":"二篇均出自干宝《搜神记》。"}],"rel":[{"t":"《搜神记》","n":"代表作"},{"t":"志怪小说","n":"所属类型"},{"t":"刘义庆","n":"志人对举"},{"t":"《聊斋志异》与蒲松龄","n":"后世志怪高峰"}],"more":"作品：《搜神记》、史著《晋纪》\n名篇：《干将莫邪》《韩凭夫妇》《董永》《李寄斩蛇》","exam":[]},{"id":"z20-020","t":"郦道元","cid":"03c","p":3,"kind":"人物","alias":["郦善长"],"one":"北魏地理学家、散文家，撰地理兼文学巨著《水经注》。","ans":"郦道元（？—527），字善长，范阳人，**北魏地理学家、散文家**。他踏勘山川，为《水经》作注，撰成四十卷名著**《水经注》**。该书考录一千二百余条水道，更以优美纯熟的**骈俪写景散文**见长，名篇《三峡》开辟了中国古代山水游记散文之先河。","pts":["北魏地理学家、散文家，字善长","为《水经》作注，撰成四十卷《水经注》","考证千条水道，开创优美山水游记散文先河"],"mem":"善长北魏注水经，千条水道记分明；三峡奇绝传散文，地理文学两相成。","mix":"《水经注》作者是北魏郦道元，原《水经》相传为汉桑钦撰；《水经注》既是地理学名著，又是山水文学名篇。","mcq":[{"q":"初中文言经典《三峡》（‘自三峡七百里中’）节选自北魏郦道元的名作","o":["《洛阳伽蓝记》","《徐霞客游记》","《越绝书》","《水经注》"],"a":3,"w":"《三峡》节选自郦道元《水经注·江水》注。"}],"rel":[{"t":"《水经注》","n":"代表著作"},{"t":"《徐霞客游记》","n":"古代地理游记巨著对照"},{"t":"谢灵运","n":"中古山水文学映照"}],"more":"代表著作：《水经注》四十卷\n经典篇目：《水经注·江水》（课文《三峡》出自此篇）","exam":[]},{"id":"c-016","t":"陶谢；大小谢","cid":"03c","p":2,"kind":"合称","alias":["陶谢","大小谢","大谢小谢"],"one":"陶渊明与谢灵运合称陶谢；谢灵运与谢朓合称大小谢。","ans":"“陶谢”指**陶渊明与谢灵运**，前者开**田园诗**，后者开**山水诗**，是东晋南朝两大诗歌流派的代表。“大小谢”指**谢灵运（大谢）与谢朓（小谢）**，二人同族，都以山水诗著称。谢灵运有“池塘生春草”，谢朓有“余霞散成绮，澄江静如练”，李白赞“中间小谢又清发”。小谢的诗清丽流畅，兼具永明体声律，对唐代格律诗影响很大。","pts":["陶谢：陶渊明田园，谢灵运山水","大小谢：谢灵运（大谢）、谢朓（小谢）","山水诗派源头，谢朓清丽影响唐诗"],"members":[["陶渊明","田园诗开创者，《归园田居》《饮酒》"],["谢灵运","大谢，山水诗开创者，《登池上楼》"],["谢朓","小谢，永明体代表，《晚登三山还望京邑》"]],"mem":"陶谢=“田”和“山水”：陶渊明田园，谢灵运山水。大小谢=同姓“谢”按年龄分：大谢灵运385年出生，小谢朓464年。李白爱小谢，“中间小谢又清发”，记成“小谢清发”。","mix":"“陶谢”是田园与山水，“大小谢”是两个谢；“小李杜”(李商隐、杜牧)与“大李杜”(李白、杜甫)的“大小”是另一种用法。","mcq":[{"q":"“大小谢”指的是","o":["谢灵运与谢惠连","谢灵运与谢朓","谢朓与谢庄","谢安与谢灵运"],"a":1,"w":"大谢谢灵运，小谢谢朓。"}],"rel":[{"t":"谢灵运","n":"大谢"},{"t":"谢朓","n":"小谢"},{"t":"陶渊明","n":"陶谢之一"},{"t":"山水田园诗派","n":"后世合流"}],"more":"名句：余霞散成绮，澄江静如练。｜谢朓《晚登三山还望京邑》\n中间小谢又清发。｜李白《宣州谢朓楼饯别校书叔云》","exam":[]},{"id":"c-017","t":"元嘉三大家","cid":"03c","p":3,"kind":"合称","alias":["元嘉三诗人"],"one":"南朝宋元嘉年间三位代表诗人谢灵运、颜延之、鲍照的合称。","ans":"元嘉三大家指**南朝宋元嘉年间诗人谢灵运、颜延之与鲍照**。谢灵运开创**山水诗派**，颜延之讲究声辞俪丽，鲍照大力开拓**七言歌行**。三家创作一扫东晋玄言诗之平淡，标志着南朝诗歌转向注重**声色辞采与艺术形式**，在诗歌史上有承前启后之功。","pts":["南朝宋元嘉年间谢灵运、颜延之、鲍照合称","谢开山水，颜尚辞采，鲍创七言歌行","扫除东晋玄言平淡，开启南朝声色之风"],"members":[["谢灵运","开创山水诗派，代表作《登池上楼》"],["颜延之","讲究声辞俪偶，与谢合称“颜谢”，代表作《五君咏》"],["鲍照","开拓七言歌行，代表作《拟行路难》十八首"]],"mem":"口诀“谢颜鲍，元嘉傲”。大谢山水，延之辞彩，鲍照歌行。","mix":"元嘉三大家是谢灵运、颜延之、鲍照；齐代‘小谢’谢朓不属于元嘉三大家。","mcq":[{"q":"南朝宋时期合称为‘元嘉三大家’的三位诗人是","o":["谢灵运、谢朓、鲍照","沈约、谢朓、王融","谢灵运、颜延之、鲍照","陆机、陆云、潘岳"],"a":2,"w":"元嘉三大家是南朝宋的谢灵运、颜延之与鲍照。"}],"rel":[{"t":"谢灵运","n":"元嘉三大家之首"},{"t":"鲍照","n":"元嘉三大家之一"},{"t":"竟陵八友","n":"南朝文人群体承续"}],"more":"谢灵运：《登池上楼》《石壁精舍咽微月》\n颜延之：《五君咏》《秋胡行》\n鲍照：《拟行路难》十八首","exam":[]},{"id":"c-018","t":"徐庾","cid":"03c","p":3,"kind":"合称","alias":["徐庾体"],"one":"南朝梁陈之际文学家徐陵与庾信的并称，亦称其文风为徐庾体。","ans":"徐庾指**南朝梁陈文学家徐陵与庾信**的并称。二人仕梁时以工丽骈文齐名，文风被称为**“徐庾体”**，代表**南朝宫体与骈俪文学**的极盛。后庾信入北融南北诗风成文章大家，徐陵在南朝陈编选诗集**《玉台新咏》**，在六朝文学文献上贡献卓著。","pts":["南朝梁陈徐陵与庾信合称，文风称“徐庾体”","工丽绮艳，南朝宫体与骈体文代表","庾信入北融汇南北，徐陵编选《玉台新咏》"],"members":[["徐陵","仕陈官至尚书左仆射，编选《玉台新咏》，骈文大家"],["庾信","入北仕北周，融汇南北文风，代表作《哀江南赋》"]],"mem":"徐陵南选玉台咏，庾信北赋哀江南；徐庾体式夸绮丽，老成文章更流传。","mix":"徐庾体前期多宫体艳诗与骈文；但庾信后期入北后苍凉悲壮，杜甫‘庾信文章老更成，凌云健笔意纵横’评价的是其后期成就。","mcq":[{"q":"南朝时期以绮丽工巧的骈体文风著称、世称‘徐庾体’的作家是","o":["徐干、庾信","徐陵、庾信","徐陵、庾亮","徐彦伯、庾信"],"a":1,"w":"‘徐庾’指南朝徐陵与庾信，二人文风被称为‘徐庾体’。"}],"rel":[{"t":"徐陵","n":"合称成员之一"},{"t":"庾信","n":"合称成员之一"},{"t":"《玉台新咏》","n":"徐陵所编诗集"}],"more":"徐陵代表作：《玉台新咏序》《关山月》\n庾信代表作：《哀江南赋》《枯树赋》《拟咏怀》","exam":[]},{"id":"b03-045","t":"《昭明文选》","cid":"03d","p":1,"kind":"作品","alias":["文选","萧统文选","昭明太子文选"],"one":"南朝梁昭明太子萧统主编，现存最早的诗文总集。","ans":"《昭明文选》简称《文选》，是**南朝梁昭明太子萧统主持编选的诗文总集**，也是**现存最早的诗文总集**。全书共30卷（一说60卷），选录先秦至梁约七百多篇作品，按文体分为赋、诗、骚、论、序等30余类。选录标准是**“事出于沉思，义归乎翰藻”**，重视文辞之美，不选经、史、子书。它保存了大量汉魏六朝作品，唐代科举尤重其学，有**“文选烂，秀才半”**之说，李善作注。","pts":["萧统主编，现存最早诗文总集","事出沉思，义归翰藻，按文体分类","唐代影响大，李善注"],"mem":"逻辑线：诗经与楚辞各是一本诗集，《文选》是第一本“诗加文”的总集。标准记“沉思翰藻”四字；谚语“文选烂，秀才半”记它对科举的影响。","mix":"《玉台新咏》是诗歌总集（徐陵编，侧重艳诗）；《乐府诗集》是乐府专集（郭茂倩，宋）；《文选》诗文兼收。","mcq":[{"q":"现存最早的诗文总集是","o":["《玉台新咏》","《乐府诗集》","《全唐诗》","《昭明文选》"],"a":3,"w":"萧统主编，南朝梁。"},{"q":"《文选》的选录标准是","o":["事出于沉思，义归乎翰藻","文以载道","诗缘情而绮靡","温柔敦厚"],"a":0,"w":"重文辞之美，不选经史子。"}],"rel":[{"t":"《玉台新咏》","n":"同时期诗歌总集"},{"t":"《乐府诗集》","n":"乐府总集"},{"t":"《文心雕龙》","n":"同朝文论"},{"t":"《古文观止》","n":"清代散文选本"}],"more":"李善注《文选》；唐代有“文选学”。","exam":[]},{"id":"b03-046","t":"《文心雕龙》","cid":"03d","p":1,"kind":"作品","alias":["文心","刘勰《文心雕龙》"],"one":"南朝梁刘勰所著，中国第一部系统的文学理论专著。","ans":"《文心雕龙》是**南朝梁刘勰所著的文学理论专著**，是**中国第一部系统、体大思精的文学批评巨著**，共50篇。全书分总论（《原道》《征圣》《宗经》等）、文体论、创作论、批评论四部分，论述文体源流、创作构思与风格、鉴赏批评，提出**“神思”“风骨”“知音”**等范畴，主张“文以明道”。书名意为用心雕琢文章如雕龙。它与钟嵘《诗品》并称**南朝两部文论名著**，前者重综合，后者专论诗歌。","pts":["刘勰撰，第一部系统文论专著","50篇，文体论创作论批评论","与《诗品》并称，神思风骨知音"],"mem":"对照记：《文心雕龙》论“文”，包括各类文体，体大；《诗品》论“诗”，专论五言诗，专精。刘勰、钟嵘都是南朝梁人，一个“龙”一个“品”。","mix":"《诗品》是诗论专著，《文心雕龙》是综合文论；《典论·论文》是单篇论文。","mcq":[{"q":"中国第一部系统的文学理论专著是","o":["《诗品》","《典论·论文》","《沧浪诗话》","《文心雕龙》"],"a":3,"w":"刘勰《文心雕龙》。"},{"q":"下列书与作者对应正确的是","o":["《诗品》：刘勰","《文选》：钟嵘","《玉台新咏》：萧统","《文心雕龙》：刘勰"],"a":3,"w":"《诗品》钟嵘，《文选》萧统，《玉台新咏》徐陵。"}],"rel":[{"t":"刘勰","n":"作者"},{"t":"钟嵘《诗品》","n":"并称"},{"t":"曹丕《典论·论文》","n":"文论前驱"},{"t":"《诗学》","n":"中西文论对照"},{"t":"严羽","n":"后世诗论"}],"more":"全书50篇，《序志》为自序。","exam":[]},{"id":"b03-047","t":"《玉台新咏》","cid":"03d","p":2,"kind":"作品","alias":["玉台新咏"],"one":"南朝陈徐陵编的艳情诗总集，收《孔雀东南飞》。","ans":"《玉台新咏》是**南朝陈徐陵编的诗歌总集**，共十卷，收录**汉代至梁代的诗歌**，以**艳情诗**和宫体诗为主，是**宫体诗的选集**。它首次收录了汉乐府长篇叙事诗**《孔雀东南飞》**，使这篇名作得以保存。该书与萧统《文选》并称，反映南朝**绮靡的审美风气**，也保存了大量女性题材的诗作，对研究汉魏六朝诗歌有重要价值。","pts":["南朝陈徐陵编","汉至梁艳情诗、宫体诗选集","收《孔雀东南飞》"],"mem":"“玉台”是妇女的梳妆台，所以选的是闺阁艳情诗。与《文选》对举：《文选》萧统(梁)选文，《玉台新咏》徐陵选艳诗。","mix":"《玉台新咏》编者一说在梁代已编成，通行说法为南朝陈徐陵；《孔雀东南飞》也见于《乐府诗集》，但最早见《玉台新咏》。","mcq":[{"q":"最早收录《孔雀东南飞》的总集是","o":["《文选》","《乐府诗集》","《玉台新咏》","《古文观止》"],"a":2,"w":"《玉台新咏》，徐陵编。"}],"rel":[{"t":"徐陵","n":"编者"},{"t":"《孔雀东南飞》","n":"收录名篇"},{"t":"永明体与宫体诗","n":"宫体诗集中体现"},{"t":"《昭明文选》","n":"同期总集对举"}],"exam":[]},{"id":"b03-048","t":"《乐府诗集》","cid":"03d","p":2,"kind":"作品","alias":["乐府诗集","郭茂倩"],"one":"宋郭茂倩编，乐府诗最完备的总集，收《木兰诗》。","ans":"《乐府诗集》是**北宋郭茂倩编的乐府诗总集**，共一百卷，是**收集乐府诗最完备的总集**。全书上起**汉魏**，下及**唐五代**，共分十二类，包括郊庙歌辞、鼓吹曲辞、横吹曲辞、相和歌辞、清商曲辞、杂曲歌辞、新乐府辞等。北朝名篇**《木兰诗》**收在横吹曲辞，《孔雀东南飞》收在杂曲歌辞。它保存了大量民歌，是研究汉魏六朝乐府的基础材料。","pts":["宋郭茂倩编，一百卷","上起汉魏下至唐五代，分十二类","收《木兰诗》，乐府最完备总集"],"mem":"“乐府”配“郭”字，“玉台”配“徐”字：郭茂倩=乐府，徐陵=玉台，萧统=文选。《木兰诗》藏在“横吹”(鼓角声)里，对应北朝的鼓角横吹曲。","mix":"《乐府诗集》收乐府，《玉台新咏》收艳情诗，《文选》收诗文；三书编者分别是郭茂倩、徐陵、萧统。","mcq":[{"q":"《乐府诗集》的编者是","o":["萧统","徐陵","彭定求","郭茂倩"],"a":3,"w":"宋代郭茂倩编；彭定求参与编校《全唐诗》。"}],"rel":[{"t":"《木兰诗》","n":"所收名篇"},{"t":"乐府与乐府双璧","n":"乐府体裁"},{"t":"《玉台新咏》","n":"同类总集"},{"t":"南北朝民歌：吴歌西曲与《敕勒歌》","n":"收录对象"}],"more":"十二类：郊庙歌辞、燕射歌辞、鼓吹曲辞、横吹曲辞、相和歌辞、清商曲辞、舞曲歌辞、琴曲歌辞、杂曲歌辞、近代曲辞、杂歌谣辞、新乐府辞。","exam":[]},{"id":"b03-061","t":"《唐诗三百首》","cid":"03d","p":3,"kind":"作品","alias":["唐诗三百首"],"one":"清代蘅塘退士孙洙编选的唐诗选本，古代普及最广的诗歌读本。","ans":"《唐诗三百首》是**清代蘅塘退士孙洙**编选的唐诗选本。全书仿《诗经》之数，收七十七家共三百余首，按**古诗、律诗、绝句**编排。选篇雅正，俗称**“熟读唐诗三百首，不会作诗也会吟”**，是最著名的唐诗启蒙总集。","pts":["清乾隆年间蘅塘退士孙洙编选","按诗体分类，选篇雅正，普及最广","俗称“熟读唐诗三百首，不会作诗也会吟”"],"mem":"蘅塘退士选唐诗，三百十首分体式；熟读三百吟成句，童蒙学诗第一集。","mix":"《唐诗三百首》编选者是清代蘅塘退士（孙洙），而非官方编修的《全唐诗》（彭定求等编）或沈德潜的《唐诗别裁集》。","mcq":[{"q":"清乾隆年间以普及唐诗为宗旨、编选《唐诗三百首》的清代学者是","o":["沈德潜","金圣叹","蘅塘退士（孙洙）","严羽"],"a":2,"w":"《唐诗三百首》由清代学者蘅塘退士（原名孙洙）编选。"}],"rel":[{"t":"《千家诗》","n":"童蒙诗选同类对照"},{"t":"《全唐诗》","n":"唐代诗歌大型总集"},{"t":"严羽","n":"选诗受沧浪诗学影响"}],"more":"编选者：蘅塘退士（孙洙）\n成书年代：清乾隆二十八年（1763年）\n收录篇目：共收诗人77家，诗作311首","exam":[]},{"id":"z20-014","t":"刘勰","cid":"03d","p":2,"kind":"人物","alias":["刘彦和"],"one":"南朝梁文论家，《文心雕龙》作者，第一部系统的文学理论专著。","ans":"刘勰（约465–约520），字彦和，**南朝梁的文学理论家**，早年依沙门僧祐，晚年出家。他撰成**《文心雕龙》**，共**五十篇**，是**中国第一部系统的文学理论专著**，全书论文体、创作、批评，提出“文原于道”“风骨”“六观”等主张，体大思精。该书与钟嵘《诗品》并称**南朝文论双璧**，对后代文学批评影响深远。","pts":["南朝梁文论家，字彦和","《文心雕龙》五十篇","第一部系统文学理论专著"],"mem":"“雕龙”指文章精雕细琢，“文心”是文章之心。五十篇配“大衍之数”五十。口诀“刘勰文心，钟嵘诗品”，一个论文，一个论诗，南朝双璧。","mix":"《文心雕龙》是第一部系统的文学理论专著，《诗品》是第一部诗论专著，《文选》是现存最早的诗文总集；曹丕《典论·论文》是第一篇文学批评专论。","mcq":[{"q":"中国第一部系统的文学理论专著是","o":["《文心雕龙》","《诗品》","《典论·论文》","《文选》"],"a":0,"w":"刘勰《文心雕龙》，五十篇。"}],"rel":[{"t":"《文心雕龙》","n":"代表作"},{"t":"钟嵘","n":"双璧对举"},{"t":"曹丕《典论·论文》","n":"文论先声"},{"t":"《诗学》","n":"中西文论对照"}],"more":"作品：《文心雕龙》(50篇)\n评《古诗十九首》：五言之冠冕。","exam":[]},{"id":"z20-015","t":"钟嵘","cid":"03d","p":2,"kind":"人物","alias":["钟记室","钟参军"],"one":"南朝梁文论家，《诗品》作者，第一部诗论专著。","ans":"钟嵘（约468–约518），**南朝梁文学批评家**，曾任记室，世称钟记室。他撰成**《诗品》**，**品评汉至梁的五言诗人**，按**上、中、下三品**分类，是**中国第一部诗论专著**。书中推崇建安风骨，主张“滋味”说，评曹植“骨气奇高，词采华茂”，列陶渊明为中品，称其为“古今隐逸诗人之宗”。《诗品》与刘勰《文心雕龙》并称南朝文论双璧，后世“诗话”由此发端。","pts":["南朝梁，曾任记室","《诗品》评汉至梁五言诗人，分三品","第一部诗论专著；滋味说"],"mem":"“品”就是分等级：上、中、下三品。陶渊明在中品、曹植在上品是常见考点。口诀“文心论文，诗品论诗”。","mix":"《诗品》只评五言诗人，不评四言和乐府；与司空图《二十四诗品》不同：后者是唐代诗论，论诗歌风格。","mcq":[{"q":"《诗品》将诗人分为","o":["四等","三品","五品","九品"],"a":1,"w":"《诗品》分上、中、下三品。"}],"rel":[{"t":"钟嵘《诗品》","n":"代表作"},{"t":"刘勰","n":"双璧对举"},{"t":"《二十四诗品》","n":"书名相近易混"},{"t":"陶渊明","n":"中品，隐逸之宗"}],"more":"《诗品》品评122位诗人，列为上中下三品。\n评曹植：骨气奇高，词采华茂。\n评陶渊明：古今隐逸诗人之宗。","exam":[]},{"id":"z20-016","t":"萧统","cid":"03d","p":2,"kind":"人物","alias":["昭明太子","昭明"],"one":"梁武帝长子，主持编《文选》，现存最早的诗文总集。","ans":"萧统（501–531），**梁武帝长子**，立为太子，早逝，谥**昭明**，世称**昭明太子**。他组织文人编成**《文选》**（又称《昭明文选》），是**现存最早的诗文总集**，选录先秦至梁的诗文，不收经、史、子书。选文标准是**“事出于沉思，义归乎翰藻”**，重视文辞之美。《文选》对唐代科举与文学影响很大，唐代有“《文选》烂，秀才半”之谚，李善为之作注。","pts":["梁武帝长子，谥昭明","编《文选》，现存最早诗文总集","标准：事出于沉思，义归乎翰藻"],"mem":"“文选”=选文章，“昭明”=太子的谥号。徐陵编《玉台新咏》，同出梁代，一个选正统诗文，一个选艳情诗。标准八字：“沉思”“翰藻”，记成“思深，辞美”。","mix":"《文选》是现存最早的诗文总集，《诗经》是最早的诗歌总集，《玉台新咏》收艳情诗；《文选》不收经史子。","mcq":[{"q":"现存最早的诗文总集是","o":["《玉台新咏》","《乐府诗集》","《文选》","《文心雕龙》"],"a":2,"w":"萧统《文选》。"}],"rel":[{"t":"《昭明文选》","n":"主要成果"},{"t":"《玉台新咏》","n":"同代总集"},{"t":"《古诗十九首》","n":"因其编入而得名"},{"t":"《古文观止》","n":"清代散文选本对照"}],"more":"选文标准：事出于沉思，义归乎翰藻。\n唐代谚语：《文选》烂，秀才半。","exam":[]},{"id":"z20-017","t":"徐陵","cid":"03d","p":3,"kind":"人物","alias":["徐孝穆"],"one":"南朝陈文学家、骈文大家，与庾信合称“徐庾”，编《玉台新咏》。","ans":"徐陵（507–583），字孝穆，**南朝陈文学家**。他骈文工整绮丽，与庾信齐名并称**“徐庾”**。徐陵奉命编选十卷诗歌总集**《玉台新咏》**，多收闺阁艳体诗，但完整保存了汉乐府长诗**《孔雀东南飞》**，在诗歌文献保存与流传上具有不可替代的价值。","pts":["南朝陈文学家，字孝穆，与庾信合称“徐庾”","编选十卷诗歌总集《玉台新咏》","《玉台新咏》保存了《孔雀东南飞》等名作"],"mem":"孝穆编选玉台咏，徐庾骈文冠六朝；留得东南孔雀飞，艳体总集传后世。","mix":"《玉台新咏》由徐陵编选，以闺阁艳诗为主，收录了《孔雀东南飞》；《昭明文选》由南朝梁萧统编选，二者为南朝双璧总集。","mcq":[{"q":"奉命编选古代著名诗歌总集《玉台新咏》十卷的南朝文学家是","o":["萧统","徐陵","庾信","沈约"],"a":1,"w":"徐陵奉梁简文帝（萧纲）之命编选《玉台新咏》，完整收录了《孔雀东南飞》。"}],"rel":[{"t":"《玉台新咏》","n":"编选总集"},{"t":"徐庾","n":"所属文学并称"},{"t":"庾信","n":"徐庾齐名文友"}],"more":"代表作：《玉台新咏》（编选）、《玉台新咏序》《关山月》","exam":[]},{"id":"z40-027","t":"严羽","cid":"03d","p":3,"kind":"人物","alias":["严仪卿","沧浪客"],"one":"南宋诗论家，撰《沧浪诗话》，首倡以禅喻诗与“妙悟”说。","ans":"严羽（约1192–约1245），字仪卿，**南宋诗论家**。其名著**《沧浪诗话》**核心倡导**“以禅喻诗”**，主张作诗贵在**“妙悟”**，推崇盛唐诗“羚羊挂角，无迹可求”之境。其说反拨宋诗议论化风气，对明清神韵派影响深远。","pts":["南宋诗论家，字仪卿，自号沧浪逋客","著《沧浪诗话》，主张“以禅喻诗”与“妙悟”","崇盛唐神韵，批评宋诗议论化，影响深远"],"mem":"严羽号沧浪，以禅论盛唐；羚羊挂角无迹求，妙悟兴趣第一流。","mix":"严羽《沧浪诗话》倡‘以禅喻诗’与‘妙悟’，针对的是宋代‘以文字为诗，以议论为诗，以才学为诗’的江西诗派弊端；王国维《人间词话》倡‘境界说’。","mcq":[{"q":"在诗论名著中系统提出‘以禅喻诗’、主张‘诗之法度在盛唐’且贵在‘妙悟’的南宋学者是","o":["严羽","欧阳修","刘勰","司空图"],"a":0,"w":"南宋严羽在《沧浪诗话》中倡导‘以禅喻诗’和‘妙悟’说。"}],"rel":[{"t":"欧阳修《六一诗话》","n":"宋代诗话文论对照"},{"t":"钟嵘《诗品》","n":"古代诗论专著谱系"},{"t":"《文心雕龙》","n":"古代文论专著高峰"}],"more":"著作：《沧浪诗话》（五门：诗辨、诗体、诗法、诗评、考证）\n名论：不涉理路，不落言筌。羚羊挂角，无迹可求。","exam":[]},{"id":"b03-016","t":"李白","cid":"03e","p":1,"kind":"人物","alias":["太白","青莲居士","诗仙","谪仙人","李太白"],"one":"盛唐浪漫主义诗人，字太白，号青莲居士，称诗仙，与杜甫并称李杜。","ans":"李白（701–762），字太白，号青莲居士，**盛唐浪漫主义诗人，被称为“诗仙”**，贺知章称他“谪仙人”。他的诗**想象奇特、气势奔放、语言清新自然**，擅长乐府歌行和绝句。代表作有**《蜀道难》《将进酒》《梦游天姥吟留别》《行路难》《静夜思》**，名句“天生我材必有用”。他与杜甫并称**“李杜”**，是**中国浪漫主义诗歌的高峰**，对后世影响极大。","pts":["盛唐浪漫主义诗人，诗仙","想象奇特，豪放飘逸","蜀道难将进酒，与杜甫并称李杜"],"mem":"三篇名作口诀“蜀将天”：《蜀道难》《将进酒》《梦游天姥》。画面：醉酒斗诗，披发弄扁舟。区分记：李白仙、杜甫圣，仙是浪漫，圣是现实。","mix":"“小李杜”指晚唐李商隐、杜牧；“大李杜”才是李白、杜甫；“诗鬼”李贺不要与李白混。","mcq":[{"q":"“安能摧眉折腰事权贵，使我不得开心颜”出自","o":["《将进酒》","《行路难》","《梦游天姥吟留别》","《蜀道难》"],"a":2,"w":"出自《梦游天姥吟留别》结尾。"},{"q":"“长风破浪会有时，直挂云帆济沧海”的作者是","o":["杜甫","王维","白居易","李白"],"a":3,"w":"《行路难·其一》。"}],"rel":[{"t":"杜甫","n":"并称李杜"},{"t":"李杜；小李杜","n":"合称辨析"},{"t":"李白代表作","n":"作品详解"},{"t":"屈原","n":"浪漫主义源头"},{"t":"唐代诗人称号：诗仙、诗圣、诗佛、诗鬼、诗豪、诗魔","n":"称号对照"}],"more":"天生我材必有用，千金散尽还复来。｜《将进酒》\n长风破浪会有时，直挂云帆济沧海。｜《行路难·其一》\n两岸猿声啼不住，轻舟已过万重山。｜《早发白帝城》\n桃花潭水深千尺，不及汪伦送我情。｜《赠汪伦》","exam":[]},{"id":"b03-017","t":"杜甫","cid":"03e","p":1,"kind":"人物","alias":["子美","少陵野老","杜工部","诗圣","杜少陵"],"one":"唐代现实主义诗人，字子美，称诗圣，诗史，沉郁顿挫，有三吏三别。","ans":"杜甫（712–770），字子美，号少陵野老，**唐代现实主义诗人，被称为“诗圣”**。他亲历安史之乱，**诗歌深刻反映社会动荡和民生疾苦，被称为“诗史”**，风格**沉郁顿挫**。代表作有**“三吏”（《新安吏》《石壕吏》《潼关吏》）、“三别”（《新婚别》《垂老别》《无家别》）**，另有《春望》《登高》。曾任检校工部员外郎，世称**“杜工部”**。他与李白并称“李杜”。","pts":["唐代现实主义诗人，诗圣","诗史，沉郁顿挫","三吏三别，春望登高"],"members":[["三吏","《新安吏》《石壕吏》《潼关吏》"],["三别","《新婚别》《垂老别》《无家别》"]],"mem":"口诀：“新石潼”“新垂无”：三吏新安石壕潼关，三别新婚垂老无家。画面：茅屋被秋风吹破，仍想“大庇天下寒士”。","mix":"“大李杜”李白、杜甫；“小李杜”李商隐、杜牧；《登高》被胡应麟推为“古今七言律第一”。","mcq":[{"q":"下列不属于“三吏”的是","o":["《新安吏》","《石壕吏》","《新婚别》","《潼关吏》"],"a":2,"w":"《新婚别》属“三别”。"},{"q":"“国破山河在，城春草木深”出自","o":["《登高》","《蜀相》","《春望》","《望岳》"],"a":2,"w":"《春望》。"}],"rel":[{"t":"李白","n":"并称李杜"},{"t":"杜甫“三吏”“三别”","n":"作品详解"},{"t":"杜甫代表作与“沉郁顿挫”","n":"风格详解"},{"t":"《诗学》","n":"中西现实主义理论对照"},{"t":"白居易","n":"现实主义后继"}],"more":"国破山河在，城春草木深。｜《春望》\n无边落木萧萧下，不尽长江滚滚来。｜《登高》\n会当凌绝顶，一览众山小。｜《望岳》\n朱门酒肉臭，路有冻死骨。｜《自京赴奉先县咏怀五百字》\n安得广厦千万间，大庇天下寒士俱欢颜。｜《茅屋为秋风所破歌》","exam":[]},{"id":"b03-021","t":"王维《使至塞上》","cid":"03e","p":1,"kind":"作品","exam":["2025选择"],"alias":["使至塞上"],"one":"王维出使凉州途中所作的边塞诗，“大漠孤烟直，长河落日圆”。","ans":"《使至塞上》是**盛唐诗人王维的五言律诗**，作于**开元二十五年**奉命出使凉州慰问边军、赴河西节度副大使幕府途中。首联叙出使，颔联“**大漠孤烟直，长河落日圆**”写塞外壮阔景象，用线条与圆形构图，被王国维称为**“千古壮观”**。王维虽以山水田园诗著称，此诗却是**边塞诗名篇**，体现了他“诗中有画”的特色。","pts":["王维五律，出使凉州途中所作","大漠孤烟直，长河落日圆","山水田园诗人的边塞名篇"],"mem":"画面：一条直线（孤烟）配一个圆（落日），一句一幅画。“诗中有画”的最好例子。口诀：王维山水为主，这首是例外的边塞。","mix":"王维以山水田园著称，不是边塞诗人；边塞四大家是高适、岑参、王昌龄、王之涣。","mcq":[{"q":"“大漠孤烟直，长河落日圆”的作者是","o":["岑参","高适","王昌龄","王维"],"a":3,"w":"出自王维《使至塞上》。"},{"q":"《使至塞上》属于","o":["山水诗","边塞诗","田园诗","咏史诗"],"a":1,"w":"写出使塞外所见，属边塞诗。"}],"rel":[{"t":"王维","n":"作者"},{"t":"边塞诗派","n":"题材所属"},{"t":"盛唐边塞诗四大家","n":"边塞作者对照"},{"t":"王国维","n":"评其壮观"}],"more":"大漠孤烟直，长河落日圆。｜《使至塞上》"},{"id":"b03-030","t":"初唐四杰","cid":"03e","p":1,"kind":"合称","alias":["王杨卢骆","四杰"],"one":"初唐王勃、杨炯、卢照邻、骆宾王，革新宫体诗风。","ans":"初唐四杰指**初唐四位诗人王勃、杨炯、卢照邻、骆宾王**，简称**“王杨卢骆”**。他们出身较低，仕途坎坷，**反对齐梁以来柔靡的宫体诗风**，把诗歌从宫廷推向江山塞漠，扩大了题材。王勃有《滕王阁序》《送杜少府之任蜀州》，骆宾王有《咏鹅》《为徐敬业讨武曌檄》，卢照邻有《长安古意》，杨炯有《从军行》。四杰为**盛唐诗歌的繁荣开路**，与陈子昂一起扫除齐梁余风。","pts":["王勃杨炯卢照邻骆宾王","革新宫体诗风，扩大题材","滕王阁序，咏鹅，为徐敬业讨武曌檄"],"members":[["王勃","《滕王阁序》《送杜少府之任蜀州》"],["杨炯","《从军行》"],["卢照邻","《长安古意》"],["骆宾王","《咏鹅》《为徐敬业讨武曌檄》"]],"mem":"通行口诀“王杨卢骆”，排序按当时人评价。记作品：王勃送杜少府，骆宾王咏鹅（七岁作），杨炯从军，卢照邻古意。","mix":"“初唐四杰”不含陈子昂；“文章四友”是李峤、崔融、苏味道、杜审言；“沈宋”指沈佺期、宋之问。","mcq":[{"q":"下列不属于初唐四杰的是","o":["陈子昂","王勃","骆宾王","卢照邻"],"a":0,"w":"陈子昂不在四杰之列。"},{"q":"《咏鹅》的作者是","o":["骆宾王","王勃","杨炯","卢照邻"],"a":0,"w":"骆宾王七岁所作。"}],"rel":[{"t":"王勃","n":"四杰之首"},{"t":"骆宾王","n":"四杰之一"},{"t":"杨炯","n":"四杰之一"},{"t":"陈子昂","n":"同期革新者"},{"t":"“沈宋”与律诗定型","n":"同期诗人"}],"more":"海内存知己，天涯若比邻。｜王勃《送杜少府之任蜀州》\n鹅鹅鹅，曲项向天歌。｜骆宾王《咏鹅》","exam":[]},{"id":"b03-031","t":"边塞诗派","cid":"03e","p":1,"kind":"流派","alias":["边塞诗","高岑"],"one":"盛唐以边塞风光和征战生活为题材，代表高适、岑参、王昌龄、王之涣。","ans":"边塞诗派是**盛唐以边塞风光和征战生活为题材的诗歌流派**，代表诗人有**高适、岑参、王昌龄、王之涣**，其中**高适、岑参合称“高岑”**。高适诗风悲壮，有《燕歌行》；**岑参擅写西北奇异风光**，《白雪歌送武判官归京》中“忽如一夜春风来，千树万树梨花开”广为传诵；王昌龄以七绝著称，有《出塞》；王之涣有《凉州词》《登鹳雀楼》。边塞诗**风格雄浑豪迈**，是盛唐气象的重要体现。","pts":["盛唐边塞题材诗派","高适岑参王昌龄王之涣","雄浑豪迈，盛唐气象"],"members":[["高适","《燕歌行》，高岑并称"],["岑参","《白雪歌送武判官归京》"],["王昌龄","《出塞》，七绝圣手"],["王之涣","《凉州词》《登鹳雀楼》"]],"mem":"首字串联“高岑昌涣”：高适、岑参、王昌龄、王之涣。画面：大漠雪夜，一夜春风梨花开。口诀“高岑雄浑，昌龄七绝”。","mix":"王维《使至塞上》也写边塞，但王维属山水田园；李白、李益也写边塞，但不列入四大家。","mcq":[{"q":"“忽如一夜春风来，千树万树梨花开”的作者是","o":["高适","王昌龄","岑参","王之涣"],"a":2,"w":"岑参《白雪歌送武判官归京》。"},{"q":"“高岑”指的是","o":["高适、王昌龄","高适、岑参","岑参、王之涣","高适、王之涣"],"a":1,"w":"高适与岑参合称高岑。"}],"rel":[{"t":"盛唐边塞诗四大家","n":"四家详解"},{"t":"高适","n":"高岑之一"},{"t":"岑参","n":"高岑之一"},{"t":"山水田园诗派","n":"盛唐另一路"},{"t":"王孟；高岑","n":"并称对照"}],"more":"秦时明月汉时关，万里长征人未还。｜王昌龄《出塞》\n黄河远上白云间，一片孤城万仞山。｜王之涣《凉州词》","exam":[]},{"id":"b03-032","t":"山水田园诗派","cid":"03e","p":1,"kind":"流派","alias":["王孟","山水田园诗"],"one":"盛唐以山水田园、隐逸情趣为主的诗派，代表王维、孟浩然。","ans":"山水田园诗派是**盛唐以描写山水田园、表现隐逸情趣为主的诗歌流派**，代表诗人是**王维、孟浩然，合称“王孟”**。其渊源是**东晋陶渊明的田园诗和南朝谢灵运的山水诗**。王维有《山居秋暝》《鹿柴》，**诗中有画**，被称“诗佛”；孟浩然有《过故人庄》《春晓》，诗风清淡自然。此外储光羲、常建等也属此派。该诗派**与边塞诗派一起构成盛唐诗歌的两大潮流**。","pts":["盛唐山水田园题材诗派","王维孟浩然合称王孟","承陶渊明、谢灵运"],"members":[["王维","《山居秋暝》，诗佛"],["孟浩然","《过故人庄》《春晓》"]],"mem":"逻辑线：陶谢是祖，王孟是徒。口诀“田陶山谢”：田园陶渊明，山水谢灵运，到了盛唐合成王孟。","mix":"“王孟”是山水田园，“高岑”是边塞，二者是盛唐两大诗派，不要互换。","mcq":[{"q":"“王孟”指的是","o":["王勃、孟郊","王维、孟浩然","王昌龄、孟郊","王维、孟郊"],"a":1,"w":"盛唐山水田园诗派代表。"},{"q":"山水田园诗派远承的是","o":["陶渊明与谢灵运","曹植与曹操","李白与杜甫","庾信与徐陵"],"a":0,"w":"陶渊明田园、谢灵运山水。"}],"rel":[{"t":"王维","n":"代表"},{"t":"孟浩然","n":"代表"},{"t":"陶渊明","n":"田园源头"},{"t":"谢灵运","n":"山水源头"},{"t":"边塞诗派","n":"盛唐另一派"}],"more":"明月松间照，清泉石上流。｜王维《山居秋暝》\n春眠不觉晓，处处闻啼鸟。｜孟浩然《春晓》","exam":[]},{"id":"b03-033","t":"王维","cid":"03e","p":1,"kind":"人物","exam":["2025选择"],"alias":["摩诘","诗佛","王右丞","王摩诘"],"one":"盛唐山水田园诗派代表，字摩诘，称诗佛，诗中有画，画中有诗。","ans":"王维（701–761），字摩诘，**盛唐山水田园诗派代表诗人，被称为“诗佛”**，官至尚书右丞。他信佛，亦通音乐、绘画，**是南宗画之祖**。苏轼评其**“诗中有画，画中有诗”**。代表作有**《山居秋暝》《使至塞上》《送元二使安西》《相思》**，另有“独在异乡为异客，每逢佳节倍思亲”。他与孟浩然合称**“王孟”**，是盛唐山水田园诗的集大成者。","pts":["盛唐山水田园诗人，诗佛","诗中有画，画中有诗","山居秋暝，使至塞上，送元二使安西"],"mem":"口诀“摩诘诗佛画南宗”。作品对应：山居秋暝（明月松间照）、使至塞上（大漠孤烟）、送元二（西出阳关）、相思（红豆）、九月九日（每逢佳节）。","mix":"《使至塞上》是边塞诗，王维仍属山水田园；“诗佛”王维、“诗仙”李白、“诗圣”杜甫要分清。","mcq":[{"q":"苏轼评价王维“诗中有画，画中有诗”，王维的称号是","o":["诗仙","诗圣","诗佛","诗鬼"],"a":2,"w":"王维称诗佛。"},{"q":"“劝君更尽一杯酒，西出阳关无故人”出自","o":["《使至塞上》","《送元二使安西》","《山居秋暝》","《相思》"],"a":1,"w":"又名《渭城曲》。"}],"rel":[{"t":"王维《使至塞上》","n":"边塞名篇"},{"t":"孟浩然","n":"并称王孟"},{"t":"山水田园诗派","n":"所属诗派"},{"t":"《阳关三叠》","n":"《送元二使安西》谱曲"},{"t":"苏轼","n":"评其诗画"}],"more":"大漠孤烟直，长河落日圆。｜《使至塞上》\n劝君更尽一杯酒，西出阳关无故人。｜《送元二使安西》\n明月松间照，清泉石上流。｜《山居秋暝》\n红豆生南国，春来发几枝。｜《相思》"},{"id":"b03-071","t":"王昌龄《出塞》","cid":"03e","p":2,"kind":"作品","alias":["《出塞》","秦时明月汉时关"],"one":"王昌龄七绝边塞名篇，“秦时明月汉时关，万里长征人未还”。","ans":"《出塞》是**盛唐诗人王昌龄**的**七言绝句**，属**边塞诗**名篇，首句为“**秦时明月汉时关**，万里长征人未还”。首句秦汉互文，把自秦至汉绵延不断的边关战事收进一句，写出将士久戍不归；后两句“但使**龙城飞将**在，不教胡马度阴山”借汉代名将李广，寄托对良将的期盼。全诗气势雄浑，被明人李攀龙推为**唐人七绝压卷之作**，也是王昌龄“七绝圣手”称号的代表作。","pts":["盛唐王昌龄七绝，边塞诗名篇","秦时明月汉时关：秦汉互文","龙城飞将指李广，明人推为七绝压卷"],"mem":"画面记忆：一轮明月照着一座关，月是秦时的，关是汉时的，月和关一起守了千年，所以“秦汉互文”。后两句记“飞将”：只要李广在，胡马过不了阴山。题目《出塞》三个字，出的是关塞，写的是战争，与《从军行》同属一类题材。","mix":"王之涣《凉州词》又名《出塞》（“黄河远上白云间”）；“龙城飞将”通行解为李广，一说指卫青；唐人七绝压卷之作另有王翰、王之涣等说法。","mcq":[{"q":"“秦时明月汉时关，万里长征人未还”出自","o":["岑参《逢入京使》","高适《别董大》","王昌龄《出塞》","王之涣《凉州词》"],"a":2,"w":"此句为王昌龄《出塞》首句，用秦汉互文。"},{"q":"《出塞》“但使龙城飞将在”一句，“飞将”通行指","o":["霍去病","李广","卫青","班超"],"a":1,"w":"“飞将军”是匈奴对李广的称呼，通行解为李广，一说指卫青。"}],"rel":[{"t":"王昌龄","n":"作者，七绝圣手"},{"t":"边塞诗派","n":"所属流派"},{"t":"王之涣","n":"同有“出塞”名篇，常被混淆"},{"t":"盛唐边塞诗四大家","n":"同类题材作者群"}],"exam":[]},{"id":"b03-072","t":"王之涣","cid":"03e","p":2,"kind":"人物","alias":["王季凌"],"one":"盛唐边塞诗人，《登鹳雀楼》《凉州词》作者。","ans":"王之涣（688–742），**盛唐诗人**，擅写**边塞诗**，与王昌龄、高适齐名，流传下来的诗作不多。他的《**登鹳雀楼**》以“白日依山尽”写景，以“**欲穷千里目，更上一层楼**”说理，是唐代五绝的名篇；《**凉州词**》“黄河远上白云间”写边地苍凉，“羌笛何须怨杨柳，春风不度玉门关”意境深远。**“旗亭画壁”**的故事讲他与王昌龄、高适在酒楼听歌女唱诗，比较诗名高低，成为盛唐诗坛的著名佳话。","pts":["盛唐边塞诗人，存诗不多","《登鹳雀楼》《凉州词》","旗亭画壁：与王昌龄、高适"],"mem":"一人两首：登楼的诗记“更上一层楼”，边塞的诗记“春风不度玉门关”。“旗亭画壁”记三个人：王之涣、王昌龄、高适，歌女唱谁的诗多谁就更有名，最后一位歌女唱的是王之涣。","mix":"王翰也有一首《凉州词》（“葡萄美酒夜光杯”），不要与王之涣的“黄河远上白云间”混淆；“旗亭画壁”出自唐人笔记《集异记》，带有传说色彩。","mcq":[{"q":"“羌笛何须怨杨柳，春风不度玉门关”的作者是","o":["王翰","岑参","王之涣","高适"],"a":2,"w":"出自王之涣《凉州词》；王翰《凉州词》是“葡萄美酒夜光杯”。"}],"rel":[{"t":"王昌龄","n":"旗亭画壁同事者"},{"t":"高适","n":"旗亭画壁同事者"},{"t":"边塞诗派","n":"所属流派"},{"t":"盛唐边塞诗四大家","n":"同类诗人"}],"more":"名句：欲穷千里目，更上一层楼。｜《登鹳雀楼》\n羌笛何须怨杨柳，春风不度玉门关。｜《凉州词》\n作品：《登鹳雀楼》《凉州词》","exam":[]},{"id":"b03-073","t":"孟浩然","cid":"03e","p":2,"kind":"人物","alias":["孟襄阳","浩然"],"one":"盛唐山水田园诗人，与王维并称“王孟”，《春晓》作者。","ans":"孟浩然（689–740），**襄阳人**，世称“孟襄阳”，**盛唐山水田园诗人**，一生大半未仕，曾隐居鹿门山。他与**王维**并称“**王孟**”，同属山水田园诗派。诗风清淡自然，代表作有《**春晓**》《**过故人庄**》《宿建德江》，《望洞庭湖赠张丞相》中“气蒸云梦泽，波撼岳阳城”气象开阔。李白有《黄鹤楼送孟浩然之广陵》，称“故人西辞黄鹤楼，烟花三月下扬州”，可见两人交谊；他的诗以**平淡自然**见长，对后世田园诗影响很大。","pts":["襄阳人，盛唐山水田园诗人，布衣","与王维并称“王孟”","《春晓》《过故人庄》《宿建德江》"],"mem":"“王孟”记法：王维是“诗佛”，孟浩然是“布衣”，一个官场里的隐士，一个山林里的诗人。《春晓》首句“春眠不觉晓”，睡到天亮听鸟叫，诗风就是这种不费力的清淡。李白的“故人西辞黄鹤楼”送的就是他。","mix":"李白《黄鹤楼送孟浩然之广陵》《赠孟浩然》都是写给他的，作者仍是李白；“王孟”（山水田园）与“高岑”（边塞）不要混。","mcq":[{"q":"下列作品中，属于孟浩然的是","o":["《使至塞上》","《春晓》","《凉州词》","《别董大》"],"a":1,"w":"《春晓》为孟浩然作；《使至塞上》王维作，《凉州词》王之涣或王翰作，《别董大》高适作。"}],"rel":[{"t":"王维","n":"并称“王孟”"},{"t":"山水田园诗派","n":"所属流派"},{"t":"李白","n":"《黄鹤楼送孟浩然之广陵》"},{"t":"王孟；高岑","n":"盛唐两大诗派合称"}],"more":"名句：春眠不觉晓，处处闻啼鸟。｜《春晓》\n气蒸云梦泽，波撼岳阳城。｜《望洞庭湖赠张丞相》\n野旷天低树，江清月近人。｜《宿建德江》\n作品：《春晓》《过故人庄》《宿建德江》《望洞庭湖赠张丞相》","exam":[]},{"id":"z30-001","t":"王勃","cid":"03e","p":2,"kind":"人物","alias":["王子安"],"one":"初唐四杰之首，《滕王阁序》作者。","ans":"王勃（约650–676），字子安，**初唐诗人**，**“初唐四杰”之首**，与杨炯、卢照邻、骆宾王并称“王杨卢骆”。四杰的创作改变了齐梁宫体的绮靡诗风，把诗歌从宫廷引向江山和塞漠。王勃的名篇有骈文《**滕王阁序**》，其中“**落霞与孤鹜齐飞，秋水共长天一色**”流传最广；五律《送杜少府之任蜀州》“海内存知己，天涯若比邻”一改送别诗的悲伤。他二十多岁渡海探父时溺水而亡，才华早逝。","pts":["初唐四杰之首，王杨卢骆","《滕王阁序》（骈文）","《送杜少府之任蜀州》，早逝"],"mem":"四杰排序口诀“王杨卢骆”，王勃居首。两个名句各记一个场景：滕王阁上看落霞孤鹜，渡口送友说“天涯若比邻”。早逝可以记一句：二十多岁写出《滕王阁序》，也在二十多岁渡海溺亡。","mix":"杜甫《戏为六绝句》有“王杨卢骆当时体，轻薄为文哂未休”，是对四杰的评价；《滕王阁序》是骈文，不是诗。","mcq":[{"q":"“落霞与孤鹜齐飞，秋水共长天一色”出自","o":["王勃《滕王阁序》","杨炯《从军行》","骆宾王《咏鹅》","陈子昂《登幽州台歌》"],"a":0,"w":"该句出自王勃骈文《滕王阁序》。"}],"rel":[{"t":"初唐四杰","n":"四杰之首"},{"t":"杨炯","n":"四杰成员"},{"t":"陈子昂","n":"同为初唐革新诗风者"},{"t":"古体诗与近体诗（格律诗）","n":"四杰推动五律成熟"}],"more":"名句：落霞与孤鹜齐飞，秋水共长天一色。｜《滕王阁序》\n海内存知己，天涯若比邻。｜《送杜少府之任蜀州》\n作品：《滕王阁序》《送杜少府之任蜀州》","exam":[]},{"id":"z30-002","t":"杨炯","cid":"03e","p":3,"kind":"人物","alias":["杨盈川"],"one":"初唐诗人，“初唐四杰”之一，以豪迈边塞征战诗见长。","ans":"杨炯（650–约693），华阴人，**唐代诗人**。他才华早著，与王勃、卢照邻、骆宾王并称**“初唐四杰”**，世称杨盈川，自叹**“愧在卢前，耻居王后”**。其代表作**《从军行》**名句“宁为百夫长，胜作一书生”气势豪放，开拓了盛唐边塞诗风。","pts":["初唐四杰之一，华阴人，世称杨盈川","自叹“愧在卢前，耻居王后”","代表作《从军行》，名句“宁为百夫长，胜作一书生”"],"mem":"盈川杨炯从军行，百夫书生发壮声；初唐四杰扫柔靡，愧在卢前耻王后。","mix":"杨炯自称‘愧在卢前，耻居王后’；时人合称‘王杨卢骆’，杜甫《戏为六绝句》定论‘王杨卢骆当时体’。","mcq":[{"q":"初唐四杰中，写下边塞豪迈名句‘宁为百夫长，胜作一书生’的诗人是","o":["王勃","卢照邻","骆宾王","杨炯"],"a":3,"w":"杨炯作《从军行》，末句‘宁为百夫长，胜作一书生’抒发昂扬壮志。"}],"rel":[{"t":"初唐四杰","n":"所属文学群体"},{"t":"王勃","n":"四杰之首同列"},{"t":"骆宾王","n":"四杰同列"}],"more":"代表作：《从军行》《出塞》\n名句：烽火照西京，心中自不平。牙璋辞凤阙，铁骑绕龙城。雪暗凋旗画，风多杂鼓声。宁为百夫长，胜作一书生。｜《从军行》","exam":[]},{"id":"z30-003","t":"卢照邻","cid":"03e","p":3,"kind":"人物","alias":["卢升之","幽忧子"],"one":"初唐诗人，“初唐四杰”之一，以长篇七言歌行《长安古意》名世。","ans":"卢照邻（约635–约689），字升之，**唐代诗人**。他与王勃、杨炯、骆宾王合称**“初唐四杰”**。其诗以**七言长篇歌行**见长，代表作**《长安古意》**铺陈长安繁华与世态炎凉，名句**“愿作鸳鸯不羡仙”**传诵千古，拓宽了七言诗境界。","pts":["初唐四杰之一，字升之，号幽忧子","代表作七言长篇歌行《长安古意》","名句“得成比目何辞死，愿作鸳鸯不羡仙”"],"mem":"照邻幽忧病沉水，长安古意比目游；不羡神仙羡鸳鸯，七言歌行开盛唐。","mix":"‘得成比目何辞死，愿作鸳鸯不羡仙’出自卢照邻《长安古意》，常被误认为是李白或民间词曲作品；晚年因病自沉颖水。","mcq":[{"q":"名句‘得成比目何辞死，愿作鸳鸯不羡仙’出自初唐四杰卢照邻的长篇歌行","o":["《拟行路难》","《春江花月夜》","《长安古意》","《帝京篇》"],"a":2,"w":"出自卢照邻的长篇七言歌行《长安古意》。"}],"rel":[{"t":"初唐四杰","n":"所属文学群体"},{"t":"王勃","n":"四杰并称"},{"t":"杨炯","n":"四杰同列"}],"more":"代表作：《长安古意》《结客少年场行》《病梨树赋》\n名句：得成比目何辞死，愿作鸳鸯不羡仙。｜《长安古意》","exam":[]},{"id":"z30-004","t":"骆宾王","cid":"03e","p":3,"kind":"人物","alias":["骆临海","骆宾客"],"one":"初唐诗人，“初唐四杰”之一，起草《为徐敬业讨武曌檄》。","ans":"骆宾王（约619–约687），**唐代诗人**。他少年作《咏鹅》，与王勃、杨炯、卢照邻合称**“初唐四杰”**，世称骆临海。他随徐敬业起兵，起草**《为徐敬业讨武曌檄》**，武后叹惜失才；在狱中作**《在狱咏蝉》**。其文辞气沛，风格慷慨悲凉。","pts":["初唐四杰之一，婺州义乌人，世称骆临海","少作《咏鹅》，后起草《为徐敬业讨武曌檄》","作《在狱咏蝉》，骈文辞意激昂悲壮"],"mem":"七岁咏鹅骆宾王，临海起兵讨武曌；一抔土未干惊朝野，武后叹惜失俊才。","mix":"《为徐敬业讨武曌檄》（又名《代李敬业传檄天下文》）是骆宾王所作；唐代‘咏蝉三绝’为虞世南《蝉》、骆宾王《在狱咏蝉》、李商隐《蝉》。","mcq":[{"q":"武则天读到‘一抔之土未干，六尺之孤何托’而叹惜‘宰相安得失此人’的名篇檄文是","o":["《讨周檄》","《为徐敬业讨武曌檄》","《讨曹操檄》","《移檄州郡》"],"a":1,"w":"骆宾王随徐敬业起兵，起草《为徐敬业讨武曌檄》，气势磅礴震撼朝野。"}],"rel":[{"t":"初唐四杰","n":"所属文学群体"},{"t":"王勃","n":"四杰并称"},{"t":"杨炯","n":"四杰同列"}],"more":"代表作：《咏鹅》《在狱咏蝉》《帝京篇》《为徐敬业讨武曌檄》\n名句：\n一抔之土未干，六尺之孤何托？｜《为徐敬业讨武曌檄》\n露重飞难进，风多响易沉。无人信高洁，谁为表予心。｜《在狱咏蝉》","exam":[]},{"id":"z30-005","t":"陈子昂","cid":"03e","p":2,"kind":"人物","alias":["陈拾遗","陈伯玉"],"one":"初唐诗歌革新先驱，倡“汉魏风骨”，《登幽州台歌》作者。","ans":"陈子昂（659–700），字伯玉，梓州射洪人，曾任右拾遗，世称“**陈拾遗**”，是**初唐诗歌革新的先驱**。他在理论上倡导“**汉魏风骨**”和“**兴寄**”，反对齐梁以来**绮靡的诗风**；创作上有组诗《**感遇**》三十八首，格调苍劲。《**登幽州台歌**》“前不见古人，后不见来者。念天地之悠悠，独怆然而涕下”，抒写怀才不遇的孤独与宇宙苍茫之感。他为盛唐诗歌的兴盛扫清了道路。","pts":["初唐诗歌革新先驱，陈拾遗","倡汉魏风骨、兴寄，反齐梁绮靡","《登幽州台歌》《感遇》三十八首"],"mem":"逻辑线：齐梁诗绮靡，陈子昂要“汉魏风骨”，所以他是唐诗革新第一人，后面才有盛唐。《登幽州台歌》记四句话：前无古人，后无来者，天地悠悠，涕下独怆，每句都在讲孤独。官名“拾遗”和杜甫“杜拾遗”同类，别混。","mix":"杜甫曾任左拾遗，世称“杜拾遗”；陈子昂任右拾遗，世称“陈拾遗”。陈子昂的“风骨”指汉魏建安风骨，与唐代“盛唐气象”不同；其生卒年学界另有661–702一说。","mcq":[{"q":"提出“汉魏风骨”“兴寄”，倡导唐诗革新的初唐诗人是","o":["沈佺期","王勃","宋之问","陈子昂"],"a":3,"w":"陈子昂反对齐梁绮靡诗风，是唐诗革新先驱。"},{"q":"《登幽州台歌》的作者是","o":["陈子昂","张若虚","卢照邻","骆宾王"],"a":0,"w":"“前不见古人，后不见来者”是陈子昂名篇。"}],"rel":[{"t":"初唐四杰","n":"同为初唐革新力量"},{"t":"建安七子","n":"他所推崇的汉魏风骨来源"},{"t":"杜甫","n":"同有“拾遗”之称"},{"t":"“沈宋”与律诗定型","n":"同时代，路径不同"}],"more":"名句：前不见古人，后不见来者。念天地之悠悠，独怆然而涕下。｜《登幽州台歌》\n作品：《登幽州台歌》《感遇》三十八首","exam":[]},{"id":"z30-006","t":"张若虚","cid":"03e","p":2,"kind":"人物","alias":["《春江花月夜》"],"one":"初唐诗人，以一首《春江花月夜》名垂后世。","ans":"张若虚（约660–约720），**扬州人**，与贺知章、张旭、包融并称“**吴中四士**”，是**初唐诗人**。他在《全唐诗》中仅存二首，凭《**春江花月夜**》一首奠定地位。该诗沿用**乐府旧题**，写春江、明月、花林、夜色，由景入情，发出“江畔何人初见月？江月何年初照人？”的宇宙之问。闻一多称其为“**诗中的诗，顶峰上的顶峰**”，清人王闿运评为“**孤篇横绝，竟为大家**”。","pts":["初唐扬州人，吴中四士之一","一首《春江花月夜》，乐府旧题","闻一多“诗中的诗”，孤篇横绝"],"mem":"关键词“孤篇”：全唐诗只留下他两首，一首就压倒一片，所以叫“孤篇横绝”。诗名五个意象“春、江、花、月、夜”，开头“江畔何人初见月”问的是月，提问方式像屈原《天问》。","mix":"同名琵琶曲《春江花月夜》由古曲《夕阳箫鼓》改编，与张若虚的诗不是一回事；《春江花月夜》本是陈后主所创的乐府旧题。","mcq":[{"q":"被闻一多誉为“诗中的诗，顶峰上的顶峰”的作品是","o":["《长恨歌》","《琵琶行》","《登幽州台歌》","《春江花月夜》"],"a":3,"w":"闻一多对张若虚《春江花月夜》的评价。"}],"rel":[{"t":"《乐府诗集》","n":"该诗题收入乐府诗集"},{"t":"陈子昂","n":"同为初唐诗人"},{"t":"白居易《长恨歌》《琵琶行》","n":"同为长篇歌行名作"},{"t":"屈原","n":"“天问”式发问的源头"}],"more":"名句：江畔何人初见月？江月何年初照人？｜《春江花月夜》\n作品：《春江花月夜》《代答闺梦还》","exam":[]},{"id":"z30-007","t":"贺知章","cid":"03e","p":3,"kind":"人物","alias":["贺季真","四明狂客","秘书监"],"one":"盛唐诗人、书法家，号四明狂客，代表作《回乡偶书》《咏柳》。","ans":"贺知章（659–744），字季真，**盛唐诗人、书法家**。他自号**“四明狂客”**，为吴中四士之一。他初见李白便叹为**“谪仙人”**并解金龟换酒。其诗纯真质朴，代表作**《回乡偶书》**与**《咏柳》**（“二月春风似剪刀”）皆为脍炙人口的绝唱。","pts":["盛唐诗人、书法家，号四明狂客，吴中四士之一","赏识李白并称其为“谪仙人”，引为知交","代表作绝句《回乡偶书》《咏柳》，自然纯真"],"mem":"四明狂客贺季真，金龟换酒谪仙人；少小离家老大回，春风剪刀咏柳青。","mix":"初遇李白并赞其为‘谪仙人’、解金龟换酒的是贺知章，并非汪伦或杜甫；贺知章与张若虚、张旭、包融并称‘吴中四士’。","mcq":[{"q":"读李白诗大加赞赏并呼其为‘谪仙人’、引为‘金龟换酒’挚友的盛唐诗人是","o":["贺知章","孟浩然","高适","王维"],"a":0,"w":"贺知章读李白《蜀道难》等篇，叹为‘谪仙人’，解金龟换酒与李白共饮。"}],"rel":[{"t":"李白","n":"赞其为谪仙人"},{"t":"张若虚","n":"吴中四士同列"},{"t":"王维","n":"盛唐诗坛同代"}],"more":"代表作：《回乡偶书》二首、《咏柳》\n名句：\n少小离家老大回，乡音无改鬓毛衰。儿童相见不相识，笑问客从何处来。｜《回乡偶书·其一》\n碧玉妆成一树高，万条垂下绿丝绦。不知细叶谁裁出，二月春风似剪刀。｜《咏柳》","exam":[]},{"id":"z30-011","t":"王昌龄","cid":"03e","p":2,"kind":"人物","alias":["王少伯","王龙标","诗家天子","七绝圣手"],"one":"盛唐边塞诗人，“七绝圣手”，《出塞》《从军行》作者。","ans":"王昌龄（约698–约757），字少伯，**盛唐诗人**，曾任江宁丞、龙标尉，故称“**王龙标**”，被誉为“**七绝圣手**”“诗家天子”。他是**边塞诗派**代表，七绝成就最高。代表作《**出塞**》“秦时明月汉时关”、《**从军行**》七首“黄沙百战穿金甲，不破楼兰终不还”写戍边将士；《**芙蓉楼送辛渐**》“洛阳亲友如相问，一片冰心在玉壶”抒写高洁志趣；《闺怨》写闺中情思。他的七绝语言精练、意境深远，影响很大。","pts":["盛唐边塞诗人，七绝圣手","《出塞》《从军行》七首","《芙蓉楼送辛渐》“一片冰心在玉壶”"],"mem":"三个称号对三类诗：边塞（出塞、从军行），送别（芙蓉楼），闺怨（闺怨）。记“龙标”：他最后被贬龙标尉，李白有名句“我寄愁心与明月，随风直到夜郎西”专写这件事（《闻王昌龄左迁龙标遥有此寄》）。","mix":"“七绝圣手”属王昌龄，“诗仙”“诗圣”“诗佛”分属李白、杜甫、王维；《出塞》另有王之涣《凉州词》别名《出塞》。","mcq":[{"q":"被后世称为“七绝圣手”的诗人是","o":["李白","王昌龄","王维","高适"],"a":1,"w":"王昌龄七绝成就最高，号“七绝圣手”。"},{"q":"“洛阳亲友如相问，一片冰心在玉壶”出自","o":["《芙蓉楼送辛渐》","《别董大》","《送杜少府之任蜀州》","《逢入京使》"],"a":0,"w":"此为王昌龄《芙蓉楼送辛渐》名句。"}],"rel":[{"t":"王昌龄《出塞》","n":"代表作"},{"t":"边塞诗派","n":"所属流派"},{"t":"李白","n":"作诗《闻王昌龄左迁龙标》"},{"t":"盛唐边塞诗四大家","n":"其中之一"}],"more":"名句：秦时明月汉时关，万里长征人未还。｜《出塞》\n黄沙百战穿金甲，不破楼兰终不还。｜《从军行·其四》\n洛阳亲友如相问，一片冰心在玉壶。｜《芙蓉楼送辛渐》\n作品：《出塞》《从军行》七首《芙蓉楼送辛渐》《闺怨》","exam":[]},{"id":"z30-012","t":"高适","cid":"03e","p":2,"kind":"人物","alias":["高达夫","高常侍"],"one":"盛唐边塞诗人，与岑参并称“高岑”，《燕歌行》《别董大》作者。","ans":"高适（约704–765），字达夫，**盛唐边塞诗人**，与**岑参**并称“**高岑**”，曾任刑部侍郎、散骑常侍，是唐代诗人中仕途较显达者。他早年漫游，后入哥舒翰幕府，熟悉边塞生活，诗风**悲壮沉郁**。代表作《**燕歌行**》“战士军前半死生，美人帐下犹歌舞”，批判将帅骄逸、士卒苦战；《**别董大**》“莫愁前路无知己，天下谁人不识君”豪迈开阔。他是**盛唐边塞诗派**的重要代表。","pts":["盛唐边塞诗人，与岑参并称“高岑”","《燕歌行》批判将帅骄逸","《别董大》“莫愁前路无知己”"],"mem":"“高岑”配对记：高适写“燕歌”和“别董大”，岑参写“白雪”和“梨花”。高适的诗沉郁，岑参的诗奇丽，一个重写实，一个重浪漫。","mix":"曹丕《燕歌行》是现存最早的完整七言诗，高适《燕歌行》是唐代边塞名篇，两者同题不同时；《别董大》第一首即“千里黄云白日曛”。","mcq":[{"q":"“莫愁前路无知己，天下谁人不识君”的作者是","o":["岑参","王昌龄","王之涣","高适"],"a":3,"w":"出自高适《别董大》。"}],"rel":[{"t":"岑参","n":"并称“高岑”"},{"t":"边塞诗派","n":"所属流派"},{"t":"曹丕《燕歌行》","n":"同题，常被混淆"},{"t":"王孟；高岑","n":"合称"}],"more":"名句：莫愁前路无知己，天下谁人不识君。｜《别董大》\n战士军前半死生，美人帐下犹歌舞。｜《燕歌行》\n作品：《燕歌行》《别董大》","exam":[]},{"id":"z30-013","t":"岑参","cid":"03e","p":2,"kind":"人物","alias":["岑嘉州"],"one":"盛唐边塞诗人，两度出塞，《白雪歌送武判官归京》作者。","ans":"岑参（约715–770），**盛唐边塞诗人**，曾**两度出塞**，到过安西、北庭，对西域风光和军旅生活有亲身体验，晚年任嘉州刺史，故称“岑嘉州”。他与**高适**并称“**高岑**”，诗风**奇丽雄壮**，想象丰富。代表作《**白雪歌送武判官归京**》以“忽如一夜春风来，千树万树梨花开”形容雪景，《走马川行奉送封大夫出师西征》写大漠行军，《**逢入京使**》“马上相逢无纸笔，凭君传语报平安”写思乡之情。他的诗代表了**盛唐边塞诗的最高成就**之一。","pts":["盛唐边塞诗人，两度出塞","《白雪歌送武判官归京》，“千树万树梨花开”","《逢入京使》，与高适并称“高岑”"],"mem":"一句话分辨高岑：岑参=奇（雪像梨花，想象奇丽），高适=悲（半死生，美人帐下歌舞）。“两度出塞”记两个数字，两次，一次安西，一次北庭。","mix":"高适与岑参并称“高岑”，别与“李杜”“王孟”混；“忽如一夜春风来”写的是雪，不是真正的春天。","mcq":[{"q":"“忽如一夜春风来，千树万树梨花开”出自","o":["岑参《白雪歌送武判官归京》","李白《行路难》","王维《使至塞上》","高适《燕歌行》"],"a":0,"w":"该句以梨花比雪景，出自岑参《白雪歌送武判官归京》。"}],"rel":[{"t":"高适","n":"并称“高岑”"},{"t":"边塞诗派","n":"所属流派"},{"t":"王维《使至塞上》","n":"同写塞外风光"},{"t":"盛唐边塞诗四大家","n":"其中之一"}],"more":"名句：忽如一夜春风来，千树万树梨花开。｜《白雪歌送武判官归京》\n马上相逢无纸笔，凭君传语报平安。｜《逢入京使》\n作品：《白雪歌送武判官归京》《走马川行奉送封大夫出师西征》《逢入京使》","exam":[]},{"id":"z30-016","t":"崔颢","cid":"03e","p":3,"kind":"人物","one":"盛唐诗人，以千古七言律诗《黄鹤楼》名重诗坛。","ans":"崔颢（？—754），汴州人，**盛唐诗人**。他游历边塞，诗风转向慷慨雄阔。其名作七律**《黄鹤楼》**（“昔人已乘黄鹤去”）气象雄奇，严羽《沧浪诗话》推为**“唐人七言律诗第一”**。相传李白登楼亦叹**“眼前有景道不得，崔颢题诗在上头”**。","pts":["盛唐诗人，边塞历练后诗风转雄健","代表作七律《黄鹤楼》，严羽推为唐人七律第一","李白登楼留“眼前有景道不得，崔颢题诗在上头”"],"mem":"崔颢题诗黄鹤楼，沧浪推为七律首；李白眼前景难道，盛唐气象冠古今。","mix":"严羽《沧浪诗话》推崔颢《黄鹤楼》为‘唐人七言律诗第一’；沈德潜《唐诗别裁》则推杜甫《登高》为古今七律之冠；李白因此在金陵写《登金陵凤凰台》以拟之。","mcq":[{"q":"严羽在《沧浪诗话》中推崇为‘唐人七言律诗第一’的诗篇是","o":["杜甫《登高》","王维《积雨辋川庄作》","李商隐《锦瑟》","崔颢《黄鹤楼》"],"a":3,"w":"严羽《沧浪诗话》推崔颢《黄鹤楼》为‘唐人七言律诗第一’。"}],"rel":[{"t":"李白","n":"黄鹤楼搁笔典故"},{"t":"严羽","n":"推其为唐人七律第一"},{"t":"杜甫","n":"盛唐七律双峰对照"}],"more":"代表作：《黄鹤楼》《长干行》四首\n名句：\n昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不复返，白云千载空悠悠。\n晴川历历汉阳树，芳草萋萋鹦鹉洲。日暮乡关何处是？烟波江上使人愁。｜《黄鹤楼》\n君家何处住，妾住在横塘。停舟暂借问，或恐是同乡。｜《长干行·其一》","exam":[],"alias":[]},{"id":"c-019","t":"吴中四士","cid":"03e","p":3,"kind":"合称","alias":["吴中四友"],"one":"贺知章、张旭、包融、张若虚，初盛唐之交江浙四位文士名家。","ans":"吴中四士指**初盛唐之交江浙文士贺知章、张旭、包融、张若虚**，首见于《新唐书》。四人诗风带有**吴越清丽爽朗的地域特色**。张若虚以《春江花月夜》称“**孤篇盖全唐**”，张旭工草书，贺知章号“**四明狂客**”，共同**开启盛唐诗歌新风**。","pts":["贺知章、张旭、包融、张若虚四人","诗风具吴越清丽爽朗特色","张若虚《春江花月夜》，开启盛唐诗风"],"members":[["贺知章","《咏柳》《回乡偶书》；号“四明狂客”"],["张旭","“草圣”，与李白、裴旻合称“大唐三绝”"],["包融","善五言诗，与包佶、包何并称“二包”"],["张若虚","代表作《春江花月夜》被誉为“孤篇盖全唐”"]],"mem":"口诀“**贺张包张**”（贺知章、张旭、包融、张若虚）。记住两位狂客书法家（贺知章、草圣张旭）加两位江南才子（孤篇横绝的张若虚与包融）。","mix":"注意区别于“初唐四杰”（王杨卢骆）；吴中四士活跃于初盛唐之交，带有鲜明的江浙吴越地域特色。","mcq":[{"q":"下列唐代文人中，不属于“吴中四士”的是","o":["贺知章","张旭","包融","骆宾王"],"a":3,"w":"吴中四士为贺知章、张旭、包融、张若虚；骆宾王属于“初唐四杰”。"}],"rel":[{"t":"张若虚","n":"四士之一"},{"t":"贺知章","n":"四士之一"},{"t":"初唐四杰","n":"初唐文人合称对照"}],"exam":[]},{"id":"c-020","t":"王孟；高岑","cid":"03e","p":2,"kind":"合称","alias":["王孟","高岑"],"one":"王维、孟浩然（山水田园）；高适、岑参（边塞）。","ans":"“**王孟**”指**盛唐山水田园诗人王维与孟浩然**，“**高岑**”指**盛唐边塞诗人高适与岑参**，是盛唐诗歌两大流派的合称。王孟诗风清淡、意境幽远，王维有《山居秋暝》，孟浩然有《春晓》《过故人庄》；高岑诗风悲壮，高适有《燕歌行》《别董大》，岑参有《白雪歌送武判官归京》。两个合称与“李杜”共同构成了**盛唐诗坛的主要格局**，分别代表田园山水与边塞两类题材。","pts":["王孟：王维、孟浩然，山水田园","高岑：高适、岑参，边塞","盛唐两大诗派，与李杜并立"],"members":[["王维","山水田园，诗佛，《山居秋暝》"],["孟浩然","山水田园，《春晓》《过故人庄》"],["高适","边塞，《燕歌行》《别董大》"],["岑参","边塞，《白雪歌送武判官归京》"]],"mem":"按“山水田园”和“边塞”两组记：王孟的诗里有山有水（《山居秋暝》《春晓》），高岑的诗里有关有雪（《燕歌行》《白雪歌》）。顺序固定为王在孟前、高在岑前，各自与两人的通行排序一致。","mix":"“王孟”不能写成“王杜”；边塞诗四大家通行是高适、岑参、王昌龄、王之涣，王昌龄不属于“高岑”；王孟与李杜、小李杜、郊寒岛瘦、元白并为唐诗常考合称。","mcq":[{"q":"“高岑”是指","o":["高适、岑参","高适、王昌龄","李白、岑参","王维、高适"],"a":0,"w":"高岑指盛唐边塞诗人高适与岑参。"},{"q":"下列诗人属于“王孟”一派的是","o":["高适","岑参","孟浩然","王昌龄"],"a":2,"w":"王孟指王维、孟浩然，山水田园诗派。"}],"rel":[{"t":"山水田园诗派","n":"王孟所属"},{"t":"边塞诗派","n":"高岑所属"},{"t":"李杜；小李杜","n":"盛唐另一合称"},{"t":"王维","n":"王孟之一"}],"exam":[]},{"id":"c-021","t":"李杜；小李杜","cid":"03e","p":1,"kind":"合称","alias":["李杜","小李杜","大李杜"],"one":"李杜指李白、杜甫；小李杜指晚唐李商隐、杜牧。","ans":"“李杜”指**盛唐李白、杜甫**，二人是唐诗双峰，李白是**浪漫主义“诗仙”**，杜甫是**现实主义“诗圣”**。“小李杜”指**晚唐李商隐、杜牧**，为区别于前者而称“小”。李商隐诗风深情缠绵，善写无题诗，有《锦瑟》；杜牧诗风俊爽，有《阿房宫赋》《清明》，七绝尤佳。另有“温李”指温庭筠、李商隐。“李杜”与“小李杜”分属盛唐与晚唐，是**唐诗的两个高峰**。","pts":["李杜：李白、杜甫（盛唐）","小李杜：李商隐、杜牧（晚唐）","浪漫与现实；无题诗与七绝"],"members":[["李白","诗仙，浪漫主义"],["杜甫","诗圣，现实主义"],["李商隐","《锦瑟》，无题诗"],["杜牧","《阿房宫赋》《清明》"]],"mem":"“大小”记年代：大李杜在前（盛唐），小李杜在后（晚唐）。小李杜里李商隐在前，杜牧在后，都是晚唐，“商牧”。","mix":"“温李”是温庭筠与李商隐；“李杜”也有称“大李杜”；李贺是中唐诗鬼，不属于二者。","mcq":[{"q":"“小李杜”指的是","o":["李商隐、杜牧","李白、杜甫","李贺、杜牧","李白、杜牧"],"a":0,"w":"晚唐李商隐、杜牧。"},{"q":"《阿房宫赋》的作者是","o":["杜牧","杜甫","李商隐","李白"],"a":0,"w":"杜牧作。"}],"rel":[{"t":"李白","n":"李杜之一"},{"t":"杜甫","n":"李杜之一"},{"t":"李商隐","n":"小李杜之一"},{"t":"杜牧","n":"小李杜之一"},{"t":"温李；温韦","n":"另一并称"}],"more":"李商隐：“相见时难别亦难”“春蚕到死丝方尽”。\n杜牧：“停车坐爱枫林晚，霜叶红于二月花”。","exam":[]},{"id":"b03-020","t":"李贺“长吉体”","cid":"03f","p":1,"kind":"概念","exam":["2024选择"],"alias":["长吉体","李长吉"],"one":"李贺诗风，奇诡冷艳，想象怪异，人称“诗鬼”。","ans":"“长吉体”指**中唐诗人李贺的诗歌风格**，李贺字长吉，故称。其诗**想象奇特、辞采瑰丽、意象幽冷诡异**，善用“鬼”“泣”“血”“死”等字，色彩浓烈，又称“**诗鬼**”。代表作有**《雁门太守行》《李凭箜篌引》《金铜仙人辞汉歌》**。名句如“黑云压城城欲摧”“天若有情天亦老”。长吉体对晚唐李商隐、温庭筠影响很大，是**韩孟诗派**中奇险一路的代表。","pts":["李贺字长吉，诗风称长吉体","奇诡冷艳，诗鬼","雁门太守行，李凭箜篌引"],"mem":"画面：骑驴背锦囊，写诗投囊（“呕心”典故）。字串：长吉-诗鬼-冷艳，别配给李白（诗仙）或李商隐（朦胧）。","mix":"2024年考“长吉体”，干扰项多为李白、李商隐；李贺生卒年790–816，只活27岁。","mcq":[{"q":"“长吉体”的创立者是","o":["李贺","李白","李商隐","李煜"],"a":0,"w":"李贺字长吉。"},{"q":"“天若有情天亦老”的作者是","o":["李白","李贺","杜牧","李商隐"],"a":1,"w":"《金铜仙人辞汉歌》。"}],"rel":[{"t":"李贺","n":"人物词条"},{"t":"韩孟诗派","n":"所属诗派"},{"t":"唐代诗人称号：诗仙、诗圣、诗佛、诗鬼、诗豪、诗魔","n":"称号对照"},{"t":"李商隐","n":"易混李姓诗人"}],"more":"黑云压城城欲摧，甲光向日金鳞开。｜《雁门太守行》"},{"id":"b03-027","t":"古文运动","cid":"03f","p":1,"kind":"事件","alias":["唐代古文运动","文以明道"],"one":"中唐韩愈、柳宗元倡导，学习先秦两汉散文，反对骈文，主张“文以明道”。","ans":"古文运动是**中唐时期以韩愈、柳宗元为首倡导的文体改革运动**。**主张学习先秦两汉的散体文，反对六朝以来的骈文**，强调**“文以明道”**，要求文章内容充实、语言自创（“惟陈言之务去”）。韩愈有《师说》《原道》，柳宗元有《永州八记》《捕蛇者说》。**北宋欧阳修继承并领导诗文革新运动**，使古文成为文坛正宗。运动涌现了**“唐宋八大家”**中的韩柳，影响了其后千年的散文写作。","pts":["中唐韩愈柳宗元倡导","反骈文，学先秦两汉，文以明道","宋欧阳修继承，唐宋八大家"],"mem":"逻辑线：骈文华丽空洞，所以韩柳要回到先秦两汉的“古文”。口诀“韩柳明道反骈文”。苏轼称韩愈“文起八代之衰”，八代指东汉至隋。","mix":"“古文”指散体文，与骈文对立；宋代是北宋诗文革新运动，主将欧阳修。","mcq":[{"q":"唐代古文运动的倡导者是","o":["李白、杜甫","白居易、元稹","欧阳修、苏轼","韩愈、柳宗元"],"a":3,"w":"韩柳。"},{"q":"古文运动反对的是","o":["散文","诗歌","小说","骈文"],"a":3,"w":"反对六朝以来的骈文。"}],"rel":[{"t":"韩愈","n":"倡导者"},{"t":"柳宗元","n":"倡导者"},{"t":"北宋诗文革新运动","n":"后继"},{"t":"唐宋八大家","n":"成果"},{"t":"韩柳；刘柳；元白；刘白","n":"并称"}],"more":"苏轼称韩愈：文起八代之衰，道济天下之溺。","exam":[]},{"id":"b03-029","t":"白居易与新乐府运动","cid":"03f","p":1,"kind":"事件","alias":["新乐府运动","元白","新乐府"],"one":"中唐白居易、元稹倡导，主张“文章合为时而著，歌诗合为事而作”。","ans":"新乐府运动是**中唐白居易、元稹倡导的诗歌革新运动**，兴起于元和年间，李绅等参与。主张**“文章合为时而著，歌诗合为事而作”**，要求诗歌反映现实、讽喻时政，用乐府旧题之外的新题写时事，语言通俗。白居易作**《新乐府》五十首**和《秦中吟》十首，代表作有**《卖炭翁》《长恨歌》《琵琶行》**。两人并称**“元白”**，是现实主义诗歌传统的继承与发展。","pts":["中唐白居易、元稹倡导，元白并称","文章合为时而著，歌诗合为事而作","新乐府五十首，卖炭翁等"],"mem":"口诀“为时为事”：文章为时，歌诗为事。画面：白居易写完诗念给老妪听，老妪听懂才定稿，所以诗风通俗。","mix":"古文运动是韩柳（文），新乐府运动是元白（诗）；“元白”是元稹白居易，不是元好问。","mcq":[{"q":"“文章合为时而著，歌诗合为事而作”出自","o":["白居易《与元九书》","韩愈《师说》","杜甫《春望》","柳宗元《封建论》"],"a":0,"w":"白居易《与元九书》。"},{"q":"新乐府运动的倡导者是","o":["韩愈、柳宗元","李白、杜甫","刘禹锡、柳宗元","白居易、元稹"],"a":3,"w":"元白。"}],"rel":[{"t":"白居易","n":"主将"},{"t":"元稹","n":"并称元白"},{"t":"古文运动","n":"同期文体革新"},{"t":"杜甫","n":"现实主义传统来源"},{"t":"白居易《长恨歌》《琵琶行》","n":"代表作"}],"more":"新乐府五十首、《秦中吟》十首；《卖炭翁》是《新乐府》之一。","exam":[]},{"id":"b03-034","t":"李商隐","cid":"03f","p":2,"kind":"人物","alias":["李义山","玉谿生","义山"],"one":"晚唐诗人，无题诗朦胧深婉，与杜牧并称“小李杜”。","ans":"李商隐（约813–约858），字义山，号玉谿生，**晚唐诗人**，与**杜牧**并称“**小李杜**”，与温庭筠并称“**温李**”。他一生受**牛李党争**牵连，仕途坎坷。诗风**深情绵邈，朦胧婉曲**，擅长**无题诗**和咏史诗，代表作有《**锦瑟**》《**夜雨寄北**》《无题》“春蚕到死丝方尽，蜡炬成灰泪始干”，《登乐游原》“夕阳无限好，只是近黄昏”。他的诗**用典精深、意象幽美**，对宋初西昆体及后世诗歌影响很深。","pts":["晚唐，与杜牧“小李杜”，与温庭筠“温李”","无题诗，朦胧深婉，《锦瑟》《夜雨寄北》","夹在牛李党争，仕途坎坷"],"mem":"记“小李杜”用“大小”对照：大李杜是盛唐李白杜甫，小李杜是晚唐李商隐杜牧，一对一对应。名句记两个情绪：爱情用“春蚕到死丝方尽”，怀人用“何当共剪西窗烛”，伤时用“夕阳无限好，只是近黄昏”。","mix":"“温李”（温庭筠、李商隐）与“温韦”（温庭筠、韦庄）不同，前者指诗，后者指词；“小李杜”是李商隐、杜牧，不要写成李贺、杜牧。","mcq":[{"q":"“何当共剪西窗烛，却话巴山夜雨时”出自","o":["杜牧《泊秦淮》","李商隐《夜雨寄北》","白居易《琵琶行》","李贺《雁门太守行》"],"a":1,"w":"出自李商隐《夜雨寄北》。"},{"q":"“春蚕到死丝方尽，蜡炬成灰泪始干”的作者是","o":["杜牧","温庭筠","李商隐","李贺"],"a":2,"w":"出自李商隐《无题》。"}],"rel":[{"t":"杜牧","n":"并称“小李杜”"},{"t":"温庭筠","n":"并称“温李”"},{"t":"李杜；小李杜","n":"合称"},{"t":"李贺","n":"同为晚唐前后奇险诗人"}],"more":"名句：春蚕到死丝方尽，蜡炬成灰泪始干。｜《无题》\n何当共剪西窗烛，却话巴山夜雨时。｜《夜雨寄北》\n夕阳无限好，只是近黄昏。｜《登乐游原》\n此情可待成追忆，只是当时已惘然。｜《锦瑟》\n作品：《锦瑟》《无题》《夜雨寄北》《登乐游原》《贾生》","exam":[]},{"id":"b03-035","t":"杜牧","cid":"03f","p":2,"kind":"人物","alias":["杜樊川","樊川居士","小杜"],"one":"晚唐诗人，《阿房宫赋》作者，与李商隐并称“小李杜”。","ans":"杜牧（803–约852），字牧之，号樊川居士，**晚唐诗人**，与**李商隐**并称“**小李杜**”，因与杜甫相对，也称“**小杜**”。他的诗以**七言绝句**见长，风格清丽俊爽，兼有咏史和写景之作，如《**泊秦淮**》“商女不知亡国恨，隔江犹唱后庭花”，《**江南春**》“南朝四百八十寺，多少楼台烟雨中”，《**山行**》“停车坐爱枫林晚，霜叶红于二月花”。他还写有著名的赋体散文《**阿房宫赋**》，借秦亡讽喻唐朝统治者。","pts":["晚唐，号樊川居士，与李商隐“小李杜”","七绝见长：《泊秦淮》《江南春》《山行》","《阿房宫赋》借秦亡讽喻时政"],"mem":"“小李杜”的分工：李商隐写情（无题），杜牧写景和史（咏史、江南）。三首七绝各一个意象：泊秦淮是“后庭花”，江南春是“四百八十寺”，山行是“霜叶红”。《阿房宫赋》第一句“六王毕，四海一”，赋名放前面。","mix":"《清明》“清明时节雨纷纷”通行归杜牧，但作者有争议；杜甫称“老杜”，杜牧称“小杜”；《阿房宫赋》是赋，不是诗。","mcq":[{"q":"“商女不知亡国恨，隔江犹唱后庭花”出自","o":["李商隐《锦瑟》","杜牧《泊秦淮》","刘禹锡《乌衣巷》","白居易《琵琶行》"],"a":1,"w":"出自杜牧《泊秦淮》，借陈后主《玉树后庭花》讽刺晚唐沉迷享乐。"},{"q":"下列作品中，作者为杜牧的是","o":["《阿房宫赋》","《锦瑟》","《师说》","《岳阳楼记》"],"a":0,"w":"《阿房宫赋》为杜牧所作。"}],"rel":[{"t":"李商隐","n":"并称“小李杜”"},{"t":"杜甫","n":"“小杜”对“老杜”"},{"t":"李杜；小李杜","n":"合称"},{"t":"刘禹锡","n":"同写金陵怀古"}],"more":"名句：商女不知亡国恨，隔江犹唱后庭花。｜《泊秦淮》\n停车坐爱枫林晚，霜叶红于二月花。｜《山行》\n南朝四百八十寺，多少楼台烟雨中。｜《江南春》\n一骑红尘妃子笑，无人知是荔枝来。｜《过华清宫》\n作品：《阿房宫赋》《泊秦淮》《江南春》《山行》《赤壁》《过华清宫》","exam":[]},{"id":"z30-017","t":"张继","cid":"03f","p":3,"kind":"人物","alias":["张懿孙"],"one":"中唐诗人，代表作《枫桥夜泊》使苏州寒山寺闻名天下。","ans":"张继（约715–约779），字懿孙，襄州人，**中唐诗人**。其诗风格清远平淡。代表作**七绝《枫桥夜泊》**抒发羁旅孤愁，“**姑苏城外寒山寺，夜半钟声到客船**”将音画意境完美交融，使寒山寺名闻中外，成为**唐代纪行诗的千古绝唱**。","pts":["中唐诗人，字懿孙","代表作七绝《枫桥夜泊》","“夜半钟声到客船”使苏州寒山寺闻名"],"mem":"景点与诗歌绑定：**张继《枫桥夜泊》＝苏州寒山寺**。抓住“月落乌啼霜满天，江枫渔火对愁眠”的羁旅名句。","mix":"注意区分中唐诗人张继与张籍（字文昌，作《节妇吟》）；寒山寺因唐初诗僧寒山曾结庐而得名，因张继此诗而广为人知。","mcq":[{"q":"名句“姑苏城外寒山寺，夜半钟声到客船”出自中唐诗人张继的","o":["《滁州西涧》","《山行》","《江雪》","《枫桥夜泊》"],"a":3,"w":"张继代表作《枫桥夜泊》，写于途经苏州寒山寺之时。"}],"rel":[{"t":"《唐诗三百首》","n":"收录《枫桥夜泊》"},{"t":"唐诗分期：初唐、盛唐、中唐、晚唐","n":"所属诗歌分期"},{"t":"寒山与寒山诗","n":"寒山寺得名源头"}],"more":"名句：月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。｜《枫桥夜泊》","exam":[]},{"id":"z30-018","t":"韦应物","cid":"03f","p":3,"kind":"人物","alias":["韦苏州"],"one":"中唐山水田园诗人，世称“韦苏州”，与柳宗元并称“韦柳”。","ans":"韦应物（约737–约792），长安人，**中唐山水田园诗人**。曾任苏州刺史，**世称韦苏州**。诗风高雅闲淡，与柳宗元并称“**韦柳**”，上承陶渊明传统。代表作**七绝《滁州西涧》**以“**野渡无人舟自横**”传诵千古，寄托了淡远冲和的隐逸情怀。","pts":["中唐山水田园诗人，世称韦苏州","与柳宗元合称“韦柳”","代表作《滁州西涧》“野渡无人舟自横”"],"mem":"官职与合称绑定：**韦应物＝韦苏州＝韦柳之一**。名作《滁州西涧》牢记“春潮带雨晚来急，野渡无人舟自横”。","mix":"“韦柳”并称是指中唐韦应物与柳宗元，继承陶谢山水田园传统；白居易、刘禹锡也曾任苏州刺史，勿混淆官职称谓。","mcq":[{"q":"传诵千古的名句“春潮带雨晚来急，野渡无人舟自横”的作者是","o":["韦应物","柳宗元","王维","孟浩然"],"a":0,"w":"韦应物代表作《滁州西涧》名句；韦应物世称“韦苏州”。"}],"rel":[{"t":"柳宗元","n":"并称“韦柳”"},{"t":"山水田园诗派","n":"所属诗歌流派"},{"t":"王维","n":"盛唐山水诗前贤"}],"more":"名句：独怜幽草涧边生，上有黄鹂深树鸣。春潮带雨晚来急，野渡无人舟自横。｜《滁州西涧》","exam":[]},{"id":"z30-019","t":"孟郊","cid":"03f","p":2,"kind":"人物","alias":["孟东野","东野"],"one":"中唐苦吟诗人，《游子吟》作者，“郊寒岛瘦”之“寒”。","ans":"孟郊（751–814），字东野，**中唐诗人**，**韩孟诗派**代表之一，以**苦吟**著称，与贾岛并称“**郊寒岛瘦**”（苏轼语）。他早年屡试不第，46岁中进士，作《**登科后**》“春风得意马蹄疾，一日看尽长安花”。诗风**险僻苦涩**，多写贫寒与人情冷暖，但**《游子吟》**“谁言寸草心，报得三春晖”以平易语言写母爱，是流传最广的名篇。他与韩愈为忘年交，对韩孟诗派有重要影响。","pts":["中唐，苦吟诗人，韩孟诗派","《游子吟》《登科后》","与贾岛并称“郊寒岛瘦”"],"mem":"孟郊的诗两面：苦的一面“寒”（郊寒），暖的一面是《游子吟》（寸草心、三春晖）。《登科后》的喜悦很有名，但他46岁才中进士，所以写得特别得意。","mix":"“郊寒岛瘦”的“郊”是孟郊，“岛”是贾岛；与“元轻白俗”同出苏轼《祭柳子玉文》。","mcq":[{"q":"“谁言寸草心，报得三春晖”的作者是","o":["贾岛","韩愈","白居易","孟郊"],"a":3,"w":"出自孟郊《游子吟》。"}],"rel":[{"t":"贾岛","n":"并称“郊寒岛瘦”"},{"t":"韩孟诗派","n":"所属流派"},{"t":"郊寒岛瘦","n":"合称"},{"t":"韩愈","n":"忘年交，韩孟诗派领袖"}],"more":"名句：谁言寸草心，报得三春晖。｜《游子吟》\n春风得意马蹄疾，一日看尽长安花。｜《登科后》\n作品：《游子吟》《登科后》","exam":[]},{"id":"z30-020","t":"贾岛","cid":"03f","p":2,"kind":"人物","alias":["贾浪仙","浪仙"],"one":"中唐苦吟诗人，曾为僧，“推敲”典故的主角。","ans":"贾岛（779–843），字浪仙，**中唐诗人**，早年**曾为僧**，后受**韩愈**赏识还俗，属**韩孟诗派**，是**苦吟诗人**的代表，与孟郊并称“**郊寒岛瘦**”。他作诗讲究炼字，**“推敲”**的典故即出自他的《**题李凝幽居**》“鸟宿池边树，僧敲月下门”：他为用“推”还是“敲”犹豫不决，冲撞了韩愈的车驾，韩愈为他定为“敲”。《**寻隐者不遇**》“只在此山中，云深不知处”（一说为孙革所作）也很有名。","pts":["中唐苦吟诗人，曾为僧","“推敲”典故，《题李凝幽居》","“郊寒岛瘦”，受韩愈赏识"],"mem":"一个故事记全：僧人贾岛骑驴想“僧推月下门”还是“僧敲月下门”，撞上韩愈的仪仗，韩愈说“敲”字好。成语“推敲”就来自这里。“岛瘦”：诗境清冷瘦硬。","mix":"《寻隐者不遇》作者一说孙革，题为《访羊尊师》；“推敲”的故事见于唐人笔记，带有传说色彩。","mcq":[{"q":"成语“推敲”的典故与哪位诗人有关","o":["孟郊","李贺","贾岛","李商隐"],"a":2,"w":"贾岛作《题李凝幽居》时反复斟酌“推”“敲”二字。"}],"rel":[{"t":"孟郊","n":"并称“郊寒岛瘦”"},{"t":"韩愈","n":"为他定“敲”字"},{"t":"韩孟诗派","n":"所属流派"},{"t":"郊寒岛瘦","n":"合称"}],"more":"名句：鸟宿池边树，僧敲月下门。｜《题李凝幽居》\n只在此山中，云深不知处。｜《寻隐者不遇》\n作品：《题李凝幽居》《寻隐者不遇》（一说孙革作）","exam":[]},{"id":"z30-021","t":"韩愈","cid":"03f","p":1,"kind":"人物","alias":["韩昌黎","退之","韩文公","昌黎先生"],"one":"中唐文学家，唐宋八大家之首，倡导古文运动，作《师说》《马说》。","ans":"韩愈（768–824），字退之，郡望昌黎，世称**韩昌黎**，谥文，**中唐文学家、思想家**，**唐宋八大家之首**。他与柳宗元**倡导古文运动**，反对骈文，主张“文以明道”，苏轼称其**“文起八代之衰”**。代表作有**《师说》《马说》《进学解》《祭十二郎文》《原道》**。其诗尚奇险，是**韩孟诗派**领袖。他提出**道统说**，是宋代理学的先导。","pts":["字退之，唐宋八大家之首","古文运动，文起八代之衰","师说马说进学解，祭十二郎文"],"mem":"口诀“师马进祭原”：《师说》《马说》《进学解》《祭十二郎文》《原道》。名句各配一篇：“业精于勤”进学解，“世有伯乐”马说，“师者传道授业解惑”师说。","mix":"《祭十二郎文》被誉为“祭文中千年绝调”；“韩柳”是韩愈柳宗元，“韩孟”是韩愈孟郊。","mcq":[{"q":"“世有伯乐，然后有千里马”出自","o":["《马说》","《师说》","《进学解》","《原道》"],"a":0,"w":"韩愈《马说》。"},{"q":"苏轼称赞“文起八代之衰”的是","o":["柳宗元","欧阳修","白居易","韩愈"],"a":3,"w":"指韩愈倡古文。"}],"rel":[{"t":"古文运动","n":"倡导者"},{"t":"柳宗元","n":"并称韩柳"},{"t":"韩愈与道统说","n":"思想主张"},{"t":"韩孟诗派","n":"诗歌流派"},{"t":"唐宋八大家","n":"八家之首"}],"more":"师者，所以传道受业解惑也。｜《师说》\n世有伯乐，然后有千里马。｜《马说》\n业精于勤，荒于嬉；行成于思，毁于随。｜《进学解》\n天街小雨润如酥，草色遥看近却无。｜《早春呈水部张十八员外》","exam":[]},{"id":"z30-022","t":"柳宗元","cid":"03f","p":1,"kind":"人物","alias":["柳河东","柳柳州","子厚","柳子厚"],"one":"中唐文学家，字子厚，唐宋八大家之一，《永州八记》《捕蛇者说》《江雪》。","ans":"柳宗元（773–819），字子厚，河东人，世称**柳河东、柳柳州**，**中唐文学家，唐宋八大家之一**。他参加**永贞革新**失败后被贬永州，后任柳州刺史，在贬谪中写下大量作品。代表作有**《永州八记》**（含《小石潭记》）、**《捕蛇者说》**、**《江雪》**，另有寓言《三戒》（含《黔之驴》）和政论《封建论》。他与韩愈并称**“韩柳”**，同倡古文运动，山水游记成就最高。","pts":["字子厚，柳河东，唐宋八大家之一","永州八记，捕蛇者说，江雪","与韩愈并称韩柳，永贞革新被贬"],"mem":"画面：被贬永州，独钓寒江雪。口诀“永捕江”：《永州八记》《捕蛇者说》《江雪》。寓言记“黔驴技穷”出自《三戒》。","mix":"“刘柳”指刘禹锡柳宗元，二人同参加永贞革新；《小石潭记》是《永州八记》之一。","mcq":[{"q":"《小石潭记》出自柳宗元的","o":["《三戒》","《封建论》","《永州八记》","《捕蛇者说》"],"a":2,"w":"《永州八记》之四。"},{"q":"“孤舟蓑笠翁，独钓寒江雪”的作者是","o":["柳宗元","刘禹锡","王维","孟浩然"],"a":0,"w":"《江雪》。"}],"rel":[{"t":"韩愈","n":"并称韩柳"},{"t":"古文运动","n":"共同倡导"},{"t":"柳宗元《永州八记》","n":"代表游记"},{"t":"刘禹锡","n":"并称刘柳"},{"t":"唐宋八大家","n":"八家之一"}],"more":"千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。｜《江雪》\n孰知赋敛之毒有甚是蛇者乎！｜《捕蛇者说》","exam":[]},{"id":"z30-023","t":"刘禹锡","cid":"03f","p":2,"kind":"人物","alias":["刘梦得","诗豪"],"one":"中唐“诗豪”，《陋室铭》《乌衣巷》作者。","ans":"刘禹锡（772–842），字梦得，**中唐诗人**，被白居易称为“**诗豪**”，曾参加**永贞革新**，失败后长期被贬朗州、连州等地。他的诗风**豪迈乐观**，如《**酬乐天扬州初逢席上见赠**》“沉舟侧畔千帆过，病树前头万木春”；《**乌衣巷**》“旧时王谢堂前燕，飞入寻常百姓家”为咏史名篇；《**竹枝词**》“东边日出西边雨，道是无晴却有晴”学习民歌；文章《**陋室铭**》“山不在高，有仙则名”广为传诵。他与白居易并称“**刘白**”，与柳宗元并称“**刘柳**”。","pts":["中唐诗豪，永贞革新参与者","《乌衣巷》《竹枝词》《酬乐天扬州初逢席上见赠》","与白居易“刘白”，与柳宗元“刘柳”"],"mem":"“诗豪”对应“豪”：别人被贬写悲，他写“沉舟侧畔千帆过”“我言秋日胜春朝”，全是乐观。三个合称：刘白（唱和），刘柳（同被贬），一个写诗，一个写文。","mix":"《陋室铭》是铭文，作者刘禹锡，不在唐宋八大家之列；范仲淹《岳阳楼记》、周敦颐《爱莲说》同样不在八大家之列。","mcq":[{"q":"“沉舟侧畔千帆过，病树前头万木春”的作者是","o":["柳宗元","白居易","刘禹锡","元稹"],"a":2,"w":"出自刘禹锡《酬乐天扬州初逢席上见赠》。"},{"q":"下列属于唐宋八大家的是","o":["刘禹锡","范仲淹","周敦颐","柳宗元"],"a":3,"w":"柳宗元属于八大家；刘禹锡、范仲淹、周敦颐均不在其列。"}],"rel":[{"t":"白居易","n":"并称“刘白”"},{"t":"柳宗元","n":"并称“刘柳”"},{"t":"韩柳；刘柳；元白；刘白","n":"合称"},{"t":"唐宋八大家","n":"常把《陋室铭》作者错放进来"}],"more":"名句：沉舟侧畔千帆过，病树前头万木春。｜《酬乐天扬州初逢席上见赠》\n旧时王谢堂前燕，飞入寻常百姓家。｜《乌衣巷》\n山不在高，有仙则名。｜《陋室铭》\n东边日出西边雨，道是无晴却有晴。｜《竹枝词》\n自古逢秋悲寂寥，我言秋日胜春朝。｜《秋词》\n作品：《陋室铭》《乌衣巷》《竹枝词》《石头城》《秋词》《浪淘沙》","exam":[]},{"id":"z30-024","t":"白居易","cid":"03f","p":1,"kind":"人物","alias":["乐天","香山居士","白乐天","诗魔"],"one":"中唐诗人，字乐天，号香山居士，诗魔，倡新乐府运动，作《长恨歌》《琵琶行》。","ans":"白居易（772–846），字乐天，号香山居士，**中唐现实主义诗人**，被称为**“诗魔”**。他与元稹**倡导新乐府运动**，主张“**文章合为时而著，歌诗合为事而作**”，诗风通俗平易。代表作有**《长恨歌》《琵琶行》《卖炭翁》**，另有《秦中吟》十首、《新乐府》五十首，文论有《与元九书》。他与元稹并称**“元白”**，与刘禹锡并称“刘白”。其诗在当时及日本、朝鲜流传很广。","pts":["字乐天，香山居士，诗魔","倡导新乐府运动，元白并称","长恨歌，琵琶行，卖炭翁"],"mem":"口诀“长琵卖”：《长恨歌》《琵琶行》《卖炭翁》。名句各配：“同是天涯沦落人”琵琶行，“在天愿作比翼鸟”长恨歌。","mix":"同写唐明皇杨贵妃，《长恨歌》是白居易，《梧桐雨》是白朴，《长生殿》是洪昇；诗魔白居易，诗鬼李贺。","mcq":[{"q":"“同是天涯沦落人，相逢何必曾相识”出自","o":["《琵琶行》","《长恨歌》","《卖炭翁》","《赋得古原草送别》"],"a":0,"w":"《琵琶行》。"},{"q":"“元白”指的是","o":["元好问、白朴","元稹、白居易","元结、白居易","元稹、白朴"],"a":1,"w":"元稹与白居易。"}],"rel":[{"t":"白居易与新乐府运动","n":"倡导运动"},{"t":"元稹","n":"并称元白"},{"t":"刘禹锡","n":"并称刘白"},{"t":"白居易《长恨歌》《琵琶行》","n":"代表作"},{"t":"《汉宫秋》与《梧桐雨》","n":"同写唐明皇与杨贵妃"}],"more":"同是天涯沦落人，相逢何必曾相识。｜《琵琶行》\n在天愿作比翼鸟，在地愿为连理枝。｜《长恨歌》\n野火烧不尽，春风吹又生。｜《赋得古原草送别》","exam":[]},{"id":"z30-025","t":"元稹","cid":"03f","p":2,"kind":"人物","alias":["元微之","微之"],"one":"中唐诗人，与白居易并称“元白”，《莺莺传》作者。","ans":"元稹（779–831），字微之，**中唐诗人**，与**白居易**同倡**新乐府运动**，并称“**元白**”，二人诗风平易，后人称为“元和体”。他的**悼亡诗**《**遣悲怀**》三首情深语淡，《离思》“曾经沧海难为水，除却巫山不是云”成为爱情名句。他写的唐传奇《**莺莺传**》（又名《会真记》），讲张生与崔莺莺的爱情，是**后世《西厢记》**故事的源头：由此发展出金董解元《西厢记诸宫调》和元王实甫《西厢记》。","pts":["中唐，与白居易“元白”，新乐府运动","悼亡诗《遣悲怀》，《离思》","唐传奇《莺莺传》，西厢故事源头"],"mem":"一条链：元稹《莺莺传》→董解元《西厢记诸宫调》→王实甫《西厢记》。“元白”分工：元稹重写情（离思、遣悲怀），白居易重写时事（秦中吟、新乐府）。","mix":"“元白”是元稹、白居易；“元轻白俗”是苏轼对二人诗风的评价；“刘白”不是“元白”。","mcq":[{"q":"“曾经沧海难为水，除却巫山不是云”的作者是","o":["白居易","元稹","李商隐","杜牧"],"a":1,"w":"出自元稹《离思》。"}],"rel":[{"t":"白居易","n":"并称“元白”"},{"t":"白居易与新乐府运动","n":"共同倡导"},{"t":"唐传奇名篇：《莺莺传》《李娃传》《柳毅传》","n":"《莺莺传》作者"},{"t":"《西厢记》","n":"故事源头"}],"more":"名句：曾经沧海难为水，除却巫山不是云。｜《离思·其四》\n作品：《莺莺传》（又名《会真记》）《离思》五首《遣悲怀》三首","exam":[]},{"id":"z30-026","t":"李贺","cid":"03f","p":1,"kind":"人物","exam":["2024选择"],"alias":["李长吉","诗鬼","长吉"],"one":"中唐诗人，字长吉，诗风奇诡冷艳，称诗鬼，“长吉体”。","ans":"李贺（790–816），字长吉，**中唐浪漫主义诗人**，唐宗室后裔，仕途失意，仅活27岁，被称为**“诗鬼”**，诗风称**“长吉体”**。其诗**想象奇特、辞采幽冷诡丽**，属**韩孟诗派**。代表作有**《雁门太守行》《李凭箜篌引》《金铜仙人辞汉歌》《马诗》二十三首**。名句“黑云压城城欲摧”“天若有情天亦老”。他对晚唐李商隐等人的诗风影响明显。","pts":["中唐诗人，字长吉，诗鬼","诗风奇诡冷艳，长吉体","雁门太守行，李凭箜篌引"],"mem":"画面：骑驴背锦囊的少年写诗，早逝。三篇口诀“雁凭金”：《雁门太守行》《李凭箜篌引》《金铜仙人辞汉歌》。区分“三李”：李白仙，李贺鬼，李商隐朦胧。","mix":"2024年考“长吉体”，干扰项多为李白、李商隐；李贺不是“小李杜”。","mcq":[{"q":"李贺的称号是","o":["诗仙","诗豪","诗鬼","诗魔"],"a":2,"w":"李贺称诗鬼。"},{"q":"“女娲炼石补天处，石破天惊逗秋雨”出自","o":["《雁门太守行》","《金铜仙人辞汉歌》","《李凭箜篌引》","《马诗》"],"a":2,"w":"描写箜篌声。"}],"rel":[{"t":"李贺“长吉体”","n":"诗风概念"},{"t":"韩孟诗派","n":"所属诗派"},{"t":"李商隐","n":"后继者"},{"t":"李白","n":"浪漫主义前辈"}],"more":"黑云压城城欲摧，甲光向日金鳞开。｜《雁门太守行》\n衰兰送客咸阳道，天若有情天亦老。｜《金铜仙人辞汉歌》"},{"id":"z30-030","t":"段成式","cid":"03f","p":1,"kind":"人物","exam":["2025名解"],"alias":["段柯古"],"one":"晚唐笔记小说家，著《酉阳杂俎》，书中《叶限》为早期灰姑娘型故事。","ans":"段成式（？–863），字柯古，**晚唐文学家**，与李商隐、温庭筠诗名相近，三人都排行十六，**合称“三十六体”**。他撰**《酉阳杂俎》**，是**唐代笔记小说集**，内容广博，涉及仙佛鬼怪、异闻物产、风俗医药。书中**《叶限》**一则记南方女子叶限得鱼骨相助、遗鞋而嫁王的故事，被认为是**世界上最早的灰姑娘型故事之一**。该书对后世志怪笔记影响很大。","pts":["晚唐，字柯古，三十六体","《酉阳杂俎》笔记小说集","《叶限》灰姑娘型故事"],"mem":"三人（李商隐、温庭筠、段成式）都排行十六，故合称“三十六体”。关键词“酉阳杂俎+叶限”：叶限是中国版灰姑娘，一只金鞋是线索。","mix":"《酉阳杂俎》（唐）与《阅微草堂笔记》（清纪昀）同为笔记，朝代不同；“三十六体”来自三人排行。","mcq":[{"q":"《酉阳杂俎》的作者是","o":["李商隐","温庭筠","沈既济","段成式"],"a":3,"w":"晚唐段成式。"},{"q":"被认为是最早灰姑娘型故事之一的《叶限》出自","o":["《太平广记》","《酉阳杂俎》","《聊斋志异》","《搜神记》"],"a":1,"w":"载于《酉阳杂俎》续集。"}],"rel":[{"t":"《酉阳杂俎》","n":"代表作"},{"t":"《叶限》","n":"书中故事"},{"t":"李商隐","n":"三十六体"},{"t":"《阅微草堂笔记》","n":"清代笔记对照"}],"more":"《叶限》载《酉阳杂俎·续集》。"},{"id":"c-022","t":"韩柳；刘柳；元白；刘白","cid":"03f","p":2,"kind":"合称","alias":["韩柳","刘柳","元白","刘白"],"one":"中唐四个并称：韩愈柳宗元、刘禹锡柳宗元、元稹白居易、刘禹锡白居易。","ans":"这组是**中唐四个常考合称**。“**韩柳**”指**韩愈与柳宗元**，二人倡导古文运动，同为唐宋八大家；“**刘柳**”指**刘禹锡与柳宗元**，同参与永贞革新，同遭贬谪；“**元白**”指**元稹与白居易**，同倡新乐府运动，诗风平易；“**刘白**”指**刘禹锡与白居易**，晚年唱和频繁，留有《刘白唱和集》。四个合称覆盖了中唐文学两条主线：古文运动与新乐府运动。","pts":["韩柳：古文运动；元白：新乐府运动","刘柳：永贞革新同被贬","刘白：晚年唱和"],"members":[["韩柳","韩愈、柳宗元，古文运动"],["刘柳","刘禹锡、柳宗元，永贞革新同被贬"],["元白","元稹、白居易，新乐府运动"],["刘白","刘禹锡、白居易，晚年唱和"]],"mem":"抓住“柳”和“白”各出现两次：柳宗元与韩愈（文）、刘禹锡（遭遇）搭档；白居易与元稹（诗）、刘禹锡（唱和）搭档。刘禹锡出现两次，也是两个合称里的“连接点”。口诀：韩柳写文，元白写诗，刘柳同遭贬，刘白唱和多。","mix":"韩柳指古文运动，“韩孟”（韩愈、孟郊）指诗派，两者不同；“元白”指元稹与白居易，苏轼称“元轻白俗”；“小李杜”属晚唐，与这四个中唐合称无关。","mcq":[{"q":"倡导古文运动的“韩柳”指","o":["韩愈、柳宗元","韩愈、刘禹锡","韩愈、孟郊","韩愈、白居易"],"a":0,"w":"韩柳为韩愈与柳宗元。"}],"rel":[{"t":"古文运动","n":"韩柳倡导"},{"t":"白居易与新乐府运动","n":"元白倡导"},{"t":"刘禹锡","n":"两个合称的交点"},{"t":"韩孟诗派","n":"另一个“韩”字组合"}],"exam":[]},{"id":"c-023","t":"郊寒岛瘦","cid":"03f","p":2,"kind":"合称","alias":["郊寒岛瘦"],"one":"孟郊、贾岛，中唐苦吟诗人，诗境清寒瘦硬。","ans":"“**郊寒岛瘦**”出自**苏轼**《祭柳子玉文》，指**中唐诗人孟郊与贾岛**。两人同属**韩孟诗派**，以**苦吟**著称，作诗力求锤炼字句。“寒”指孟郊诗境穷愁苦涩，“瘦”指贾岛诗境清冷瘦硬。孟郊代表作有《**游子吟**》《登科后》，贾岛有《题李凝幽居》，“推敲”的典故出于此。这一合称概括了**中唐苦吟一派的风格**，与“元轻白俗”（元稹、白居易）形成对比。","pts":["孟郊、贾岛，苏轼评语","苦吟诗人，韩孟诗派","寒：孟郊；瘦：贾岛"],"members":[["孟郊","寒，《游子吟》《登科后》"],["贾岛","瘦，“推敲”，《题李凝幽居》"]],"mem":"字序对应：郊=孟郊=寒，岛=贾岛=瘦，口诀“郊寒岛瘦，推敲苦吟”。与“元轻白俗”一起记：苏轼把中唐四个诗人评了四个字，一边苦，一边俗。","mix":"“元轻白俗”也是苏轼语，指元稹、白居易；“郊寒岛瘦”不指李贺。","mcq":[{"q":"“郊寒岛瘦”评价的两位中唐苦吟诗人是","o":["孟郊、贾岛","韩愈、孟郊","元稹、白居易","李商隐、杜牧"],"a":0,"w":"孟郊（寒）、贾岛（瘦），语出苏轼；元稹白居易对应“元轻白俗”。"}],"rel":[{"t":"孟郊","n":"“郊”"},{"t":"贾岛","n":"“岛”"},{"t":"韩孟诗派","n":"所属流派"},{"t":"苏轼","n":"评语出自苏轼"}],"exam":[]},{"id":"b03-007","t":"词","cid":"03g","p":1,"kind":"概念","exam":["2013名解"],"alias":["曲子词","长短句","诗余","词体"],"one":"起源于隋唐、兴盛于宋的配乐歌唱诗体，依词牌填写，句式长短不齐。","ans":"词是**起源于隋唐燕乐、兴盛于宋代的配乐歌唱诗体**，又称曲子词、长短句、诗余。它**依词牌填写，句式长短不齐**，讲究平仄与押韵，多分上下阕，按字数分**小令、中调、长调**。民间词见于敦煌曲子词，中唐文人开始仿作，**晚唐五代温庭筠、韦庄、李煜使词走向成熟，宋代达到鼎盛**，形成**婉约、豪放两大风格**，代表词人有柳永、苏轼、李清照、辛弃疾。词与唐诗、元曲并称，宋词是宋代文学的代表样式，使诗歌能够更细腻地抒写个人情感。","pts":["隋唐起源、宋代鼎盛的配乐诗体","依词牌填，长短句，分上下阕","小令中调长调；婉约豪放两派"],"mem":"三个别名各说一个特点：曲子词（配乐的曲子）、长短句（句子长短不齐）、诗余（诗之余，词的地位低于诗时的叫法）。时间线只记四站：温庭筠（晚唐）→李煜（五代）→柳永（慢词）→苏辛（豪放），“唐起宋盛”。","mix":"词牌（如《念奴娇》）与题目（如“赤壁怀古”）不同；“诗余”指词，“曲”指元曲；词属宋，散曲属元，二者都可配乐但体制不同。","mcq":[{"q":"下列不属于词的别称的是","o":["曲子词","长短句","诗余","乐府"],"a":3,"w":"乐府原指汉代音乐机关及其采集的诗歌，不是词的别称。"},{"q":"词在句式上最突出的特点是","o":["每句字数相等","句式长短不齐","四句为一首","必须通篇押同一个韵"],"a":1,"w":"词依词牌填写，句子长短错落，故称“长短句”。"}],"rel":[{"t":"词牌","n":"词的格式名称"},{"t":"婉约派与豪放派","n":"词的两大风格"},{"t":"小令、中调、长调与慢词","n":"词的分类"},{"t":"词的起源：敦煌曲子词与李白《菩萨蛮》《忆秦娥》","n":"词的起源"},{"t":"散曲","n":"元代的曲，与词对照"}],"more":"词集名：柳永《乐章集》，李清照《漱玉词》，晏殊《珠玉词》，辛弃疾《稼轩长短句》。\n词的分段：一段称“阕”，两段称上阕、下阕（上片、下片）。"},{"id":"b03-009","t":"温庭筠","cid":"03g","p":1,"kind":"人物","exam":["2026名解"],"alias":["温飞卿","飞卿","温岐","温八叉"],"one":"晚唐诗人词人，花间派鼻祖，诗与李商隐并称“温李”，词与韦庄并称“温韦”。","ans":"温庭筠（约812–约866），**本名岐，字飞卿，太原祁县人，晚唐诗人、词人**。他精通音律，**大量填词，被尊为“花间派鼻祖”**，词风秾艳精巧，多写闺情，代表作有**《菩萨蛮·小山重叠金明灭》《望江南·梳洗罢》**。他的诗与李商隐齐名，并称**“温李”**；词与韦庄并称**“温韦”**。后蜀赵崇祚编《花间集》，以他居首。他推动词由民间曲子走向文人创作，使词体趋于定型，对五代宋初婉约词影响很大。","pts":["晚唐诗人、词人，字飞卿","花间派鼻祖，词风秾艳","诗称“温李”，词称“温韦”"],"mem":"一个口诀分清两个并称：诗找李商隐（“温李”），词找韦庄（“温韦”），诗看“李”，词看“韦”。《菩萨蛮》开头“小山重叠金明灭”画面：屏风上的小山重重叠叠，晨光里金色明灭闪动，女子刚醒来梳妆，全是闺阁里的物件，由此记住“秾艳闺情”。","mix":"《花间集》的编者是后蜀赵崇祚，不是温庭筠；温庭筠与韦庄同为花间代表，温词秾艳，韦词清疏；“温李”论诗，“温韦”论词。","mcq":[{"q":"“温韦”并称指的是","o":["温庭筠与韦庄","温庭筠与李商隐","温庭筠与李煜","温庭筠与冯延巳"],"a":0,"w":"温庭筠与韦庄并称“温韦”，二人是花间词派代表。"},{"q":"《花间集》的编者是","o":["温庭筠","韦庄","赵崇祚","欧阳炯"],"a":2,"w":"《花间集》由后蜀赵崇祚编成于940年，欧阳炯为之作序。"}],"rel":[{"t":"花间词派","n":"鼻祖所属流派"},{"t":"《花间集》","n":"收其词居首"},{"t":"温李；温韦","n":"两个并称"},{"t":"韦庄","n":"并称“温韦”"},{"t":"李商隐","n":"并称“温李”"}],"more":"《菩萨蛮·小山重叠金明灭》\n《望江南·梳洗罢》：过尽千帆皆不是，斜晖脉脉水悠悠。\n《商山早行》：鸡声茅店月，人迹板桥霜。"},{"id":"b03-010","t":"花间词派","cid":"03g","p":1,"kind":"流派","alias":["花间派","花间词人","花间词"],"one":"晚唐五代以闺情艳情为主的词派，得名于《花间集》，温庭筠为鼻祖。","ans":"花间词派是**晚唐五代以写男女情爱、闺阁生活为主的词派**，得名于**后蜀赵崇祚编的《花间集》（940年成书，收晚唐五代18家词500首）**。**温庭筠被尊为鼻祖，韦庄与之并称“温韦”**，其余词人多为西蜀文人，如牛峤、欧阳炯等。词风**秾丽婉约、注重辞藻**，奠定了词“诗庄词媚”的基本格调，影响宋代婉约词。《花间集》是**现存最早的文人词总集**。","pts":["晚唐五代词派，得名《花间集》","温庭筠鼻祖，温韦并称","秾丽婉约，写闺情，西蜀文人为主"],"mem":"“花间”就是花丛之间，题材也是花前月下的闺阁情事。地点记“蜀”：花间在西蜀（后蜀），南唐在江东，花间写闺情，南唐（李煜）后期写家国。年份记 940，编者记赵崇祚（“赵”编，“温”只是鼻祖）。","mix":"编者是赵崇祚，不是温庭筠；南唐词（李璟、李煜、冯延巳）另成一路，李煜后期词转向家国之痛，不属花间；韦庄词清疏，与温庭筠的秾艳有别。","mcq":[{"q":"现存最早的文人词总集是","o":["《花间集》","《乐府诗集》","《玉台新咏》","《草堂诗余》"],"a":0,"w":"《花间集》成书于后蜀940年，收晚唐五代词。"},{"q":"关于花间词派，下列说法正确的是","o":["以苏轼为鼻祖","编者是温庭筠","主要写闺情艳情，词风秾丽","属于豪放词的先声"],"a":2,"w":"花间词以闺情为主，风格秾丽婉约，鼻祖是温庭筠，编者是赵崇祚。"}],"rel":[{"t":"温庭筠","n":"花间鼻祖"},{"t":"韦庄","n":"与温并称“温韦”"},{"t":"赵崇祚","n":"《花间集》编者"},{"t":"《花间集》","n":"词派得名之书"},{"t":"南唐二主","n":"另一路词风对照"}],"exam":[]},{"id":"b03-011","t":"李清照","cid":"03g","p":1,"kind":"人物","alias":["易安居士","易安","李易安","易安体"],"one":"两宋之际女词人，号易安居士，婉约派代表，词集《漱玉词》，主张词“别是一家”。","ans":"李清照（1084–约1155），**号易安居士，济南人，两宋之际女词人**，**婉约派代表**，词风称“易安体”。她前期词写闺中生活与离情，如**《如梦令》“绿肥红瘦”《醉花阴》**；靖康之变、南渡及丈夫赵明诚去世后，词转为国破家亡、身世飘零之感，如**《声声慢》《武陵春》**。她在《词论》中提出词**“别是一家”**，主张词与诗有别。有词集《漱玉词》，与赵明诚编纂《金石录》并作《金石录后序》。她以白描口语入词，被誉为“千古第一才女”。","pts":["两宋之际女词人，婉约派，易安体","前期闺情，南渡后家国身世之痛","《词论》“别是一家”；《漱玉词》"],"mem":"分期记两个字：前期“花”（绿肥红瘦、人比黄花瘦），后期“愁”（寻寻觅觅、载不动许多愁）。词集名对作者：柳永《乐章集》，李清照《漱玉词》，晏殊《珠玉词》，辛弃疾《稼轩长短句》，可串成“乐章柳，漱玉李，珠玉晏，稼轩辛”。","mix":"《漱玉词》是李清照，《乐章集》是柳永，《珠玉词》是晏殊；“生当作人杰，死亦为鬼雄”是李清照《夏日绝句》；她与辛弃疾同为济南人，合称“济南二安”。","mcq":[{"q":"下列词集与作者对应正确的是","o":["《乐章集》，李清照","《珠玉词》，柳永","《漱玉词》，李清照","《稼轩长短句》，苏轼"],"a":2,"w":"《漱玉词》是李清照的词集；《乐章集》是柳永，《珠玉词》是晏殊，《稼轩长短句》是辛弃疾。"},{"q":"“莫道不销魂，帘卷西风，人比黄花瘦”出自","o":["《如梦令》","《声声慢》","《武陵春》","《醉花阴》"],"a":3,"w":"出自李清照《醉花阴》，写重阳思念丈夫。"}],"rel":[{"t":"李清照代表作与“词别是一家”","n":"代表作与词论"},{"t":"济南二安","n":"与辛弃疾并称"},{"t":"柳永","n":"同属婉约，集名易混"},{"t":"婉约派与豪放派","n":"所属流派"},{"t":"岳飞","n":"同处靖康南渡之世"}],"more":"知否，知否？应是绿肥红瘦。｜《如梦令》\n莫道不销魂，帘卷西风，人比黄花瘦。｜《醉花阴》\n寻寻觅觅，冷冷清清，凄凄惨惨戚戚。｜《声声慢》\n此情无计可消除，才下眉头，却上心头。｜《一剪梅》\n只恐双溪舴艋舟，载不动许多愁。｜《武陵春》\n生当作人杰，死亦为鬼雄。｜《夏日绝句》","exam":[]},{"id":"b03-026","t":"《花间集》","cid":"03g","p":2,"kind":"作品","alias":["花间集","花间"],"one":"五代后蜀赵崇祚编，现存最早的文人词总集。","ans":"《花间集》是**五代后蜀赵崇祚所编的词集**，成书于**940年**，是现存**最早的文人词总集**。全书收温庭筠、韦庄等18位词人的约500首词，以温庭筠为首，由欧阳炯作序。所收词作多写闺情离愁，风格**浓艳绮丽**，形成了**花间词派**，温庭筠被尊为“**花间鼻祖**”。该书确立了**婉约词风的传统**，对宋词发展影响深远。","pts":["后蜀赵崇祚编，940年成书","现存最早的文人词总集，收18家约500首","花间词派，温庭筠花间鼻祖"],"mem":"数字记“940”，18家500首；“花间”两个字对应环境：花前月下、闺阁愁绪，所以风格浓艳。编者名“崇祚”，记“赵（后蜀）+欧阳炯作序”。","mix":"编者是赵崇祚，欧阳炯只作序；敦煌曲子词是民间词，早于《花间集》，但《花间集》是现存最早的文人词总集。","mcq":[{"q":"现存最早的文人词总集是","o":["《花间集》","《全唐诗》","《乐府诗集》","《玉台新咏》"],"a":0,"w":"《花间集》，后蜀赵崇祚编，940年成书。"},{"q":"《花间集》的编者是","o":["欧阳炯","李煜","赵崇祚","韦庄"],"a":2,"w":"编者赵崇祚，欧阳炯作序。"}],"rel":[{"t":"赵崇祚","n":"编者"},{"t":"温庭筠","n":"花间鼻祖"},{"t":"花间词派","n":"所属流派"},{"t":"《玉台新咏》","n":"同为早期总集"}],"more":"重要年份：940年成书（后蜀广政三年）。\n词人：温庭筠、韦庄、牛峤、薛昭蕴等18家。","exam":[]},{"id":"b03-036","t":"李煜","cid":"03g","p":1,"kind":"人物","alias":["李后主","南唐后主","李重光","千古词帝"],"one":"南唐亡国之君，亡国后词风沉痛深婉，号“千古词帝”，《虞美人》最著。","ans":"李煜（937–978），**字重光，南唐最后一位国君，史称南唐后主**，**与其父李璟合称“南唐二主”**。他前期词多写宫廷享乐与男女之情；975年南唐被北宋所灭，他被俘至汴京，**后期词转写亡国之痛与故国之思**，代表作**《虞美人》“春花秋月何时了”《浪淘沙》《相见欢》**。他以白描和直抒胸臆扩大了词的境界，王国维评其**“眼界始大，感慨遂深”**，后人称他“千古词帝”。978年他死于汴京。","pts":["南唐后主，与李璟合称南唐二主","前期宫廷享乐，后期亡国之痛","《虞美人》《浪淘沙》《相见欢》；千古词帝"],"mem":"画面：前期是“皇帝写艳词”，后期是“囚徒写哀词”。三首后期名作各抓一句：一江春水（《虞美人》），帘外雨潺潺（《浪淘沙》），无言独上西楼（《相见欢》）。年份：975 灭国，978 去世（“七五亡，七八死”）。","mix":"“南唐二主”是李璟、李煜父子；冯延巳是南唐词人，词风近花间；“问君能有几多愁”出自《虞美人》，“剪不断，理还乱”出自《相见欢》。","mcq":[{"q":"“问君能有几多愁？恰似一江春水向东流”出自","o":["《相见欢》","《浪淘沙》","《虞美人》","《蝶恋花》"],"a":2,"w":"出自李煜《虞美人》。"},{"q":"下列称号与词人对应正确的是","o":["词中之龙：李清照","千古词帝：李煜","花间鼻祖：韦庄","婉约词宗：辛弃疾"],"a":1,"w":"李煜称“千古词帝”；词中之龙是辛弃疾，花间鼻祖是温庭筠，婉约词宗是李清照。"}],"rel":[{"t":"南唐二主","n":"与李璟合称"},{"t":"李煜《虞美人》与“千古词帝”","n":"代表作与称号"},{"t":"花间词派","n":"同时期另一词风"},{"t":"王国维《人间词话》","n":"评其“眼界始大”"},{"t":"宋徽宗赵佶","n":"同为亡国君主兼艺术家"}],"more":"问君能有几多愁？恰似一江春水向东流。｜《虞美人》\n剪不断，理还乱，是离愁。｜《相见欢》\n流水落花春去也，天上人间。｜《浪淘沙令》\n独自莫凭栏，无限江山，别时容易见时难。｜《浪淘沙令》","exam":[]},{"id":"b03-042","t":"秦观、周邦彦","cid":"03g","p":2,"kind":"人物","alias":["秦少游","淮海居士","周美成","清真居士","周清真"],"one":"北宋婉约词人，秦观《鹊桥仙》，周邦彦集婉约词大成。","ans":"秦观（1049–1100），字少游，**苏门四学士**之一，北宋**婉约派**词人，词风婉约凄婉，代表作《**鹊桥仙**》“两情若是久长时，又岂在朝朝暮暮”。周邦彦（1056–1121），字美成，号清真居士，曾提举**大晟府**，精通音律，他的词格律严整，铺叙精致，被誉为**集婉约词之大成**，是**格律派**的开创者，词集《清真集》。两人代表北宋婉约词的两种面貌，秦观重情韵，周邦彦重格律技巧。","pts":["秦观：苏门四学士，《鹊桥仙》","周邦彦：大晟府，格律派，集婉约大成","北宋婉约词代表"],"mem":"一个重情一个重律：秦观“情”，周邦彦“律”。秦观名句记七夕，“金风玉露一相逢”，周邦彦记《兰陵王·柳》和《苏幕遮》“风荷举”。“苏门四学士”顺口：黄秦晁张。","mix":"苏门四学士是黄庭坚、秦观、晁补之、张耒；加陈师道、李廌为苏门六君子；周邦彦不属于苏门。","mcq":[{"q":"“两情若是久长时，又岂在朝朝暮暮”的作者是","o":["柳永","晏几道","周邦彦","秦观"],"a":3,"w":"出自秦观《鹊桥仙》。"}],"rel":[{"t":"秦观","n":"单独词条"},{"t":"周邦彦","n":"单独词条"},{"t":"苏门四学士","n":"秦观所属"},{"t":"婉约派与豪放派","n":"所属风格"}],"exam":[]},{"id":"z30-031","t":"韦庄","cid":"03g","p":2,"kind":"人物","alias":["韦端己","韦相"],"one":"晚唐五代词人，花间派代表，与温庭筠并称“温韦”。","ans":"韦庄（约836–910），字端己，**晚唐五代词人**，曾在**前蜀**任宰相。他是**花间派**重要词人，与**温庭筠**并称“**温韦**”。温词浓艳，韦词**清丽疏淡**，多写自身经历与江南情怀，如《**菩萨蛮**》“人人尽说江南好，游人只合江南老”。他还有长篇叙事诗《**秦妇吟**》，写黄巢之乱中妇人的见闻，被称“秦妇吟秀才”。韦庄使花间词由闺阁走向个人抒情，影响了后来的南唐词。","pts":["晚唐五代，前蜀宰相","与温庭筠“温韦”，花间派，词风清丽","《菩萨蛮》“人人尽说江南好”，《秦妇吟》"],"mem":"温韦对比：温浓韦淡，温写物，韦写己。《菩萨蛮》“江南好”是怀乡之作，不是真的夸江南：游人“只合江南老”，说明回不去北方。","mix":"“温韦”指词，“温李”指诗；《秦妇吟》是长篇叙事诗，不是词。","mcq":[{"q":"“人人尽说江南好，游人只合江南老”的作者是","o":["温庭筠","韦庄","李煜","冯延巳"],"a":1,"w":"出自韦庄《菩萨蛮》。"}],"rel":[{"t":"温庭筠","n":"并称“温韦”"},{"t":"花间词派","n":"所属流派"},{"t":"温李；温韦","n":"合称"},{"t":"《花间集》","n":"收录其词"}],"more":"名句：人人尽说江南好，游人只合江南老。｜《菩萨蛮》\n作品：《菩萨蛮》《秦妇吟》","exam":[]},{"id":"z30-033","t":"冯延巳","cid":"03g","p":3,"kind":"人物","alias":["冯正中"],"one":"五代南唐词人、宰相，“开北宋一代词风”的领军人物。","ans":"冯延巳（903–960），字正中，广陵人，**五代南唐词人、宰相**。词风清丽深幽，多写离情闲愁。代表作**《谒金门》**中“**风乍起，吹皱一池春水**”传为名话。王国维《人间词话》赞其“堂庑特大”，认为其词**开北宋晏殊、欧阳修一代词风**。","pts":["五代南唐词人、宰相，字正中","名句“风乍起，吹皱一池春水”","王国维赞其堂庑特大，开北宋一代词风"],"mem":"名君名臣问答典故：南唐中主李璟戏问“吹皱一池春水，干卿何事”，冯延巳答“未若陛下小楼吹彻玉笙寒”。**冯延巳开北宋晏欧词风**。","mix":"冯延巳词风开阔未被收入蜀派的《花间集》（王国维指出其堂庑特大在花间范围之外）；常与南唐后主李煜并提。","mcq":[{"q":"王国维在《人间词话》中评价“堂庑特大，开北宋一代词风”的五代南唐词人是","o":["韦庄","温庭筠","冯延巳","李煜"],"a":2,"w":"王国维称赞南唐词人冯延巳（字正中）词境深大，开北宋晏欧词风。"}],"rel":[{"t":"南唐二主","n":"南唐同时代词人"},{"t":"晏殊","n":"受冯延巳词风影响"},{"t":"《花间集》","n":"未收录冯词的总集"}],"more":"名句：风乍起，吹皱一池春水。｜《谒金门》","exam":[]},{"id":"z30-034","t":"赵崇祚","cid":"03g","p":3,"kind":"人物","alias":["赵弘基"],"one":"五代后蜀文学家，编纂我国现存最早文人词总集《花间集》。","ans":"赵崇祚，字弘基，南阳人，**五代后蜀文学家**。于940年编纂成**《花间集》**十卷，欧阳炯作序，辑录温庭筠、韦庄等十八位词人五百首词作。该书是**我国现存最早的文人词总集**，确立了“**花间词派**”流派，标志着词体在文人创作中正式成熟确立。","pts":["五代后蜀文学家，字弘基","编纂我国现存最早文人词总集《花间集》","确立花间词派，奠定文人词基础"],"mem":"总集编选对应：**赵崇祚编《花间集》**，**欧阳炯作序**。收录18位词人500首词，温庭筠居首、韦庄次之。","mix":"《花间集》是文人词总集，敦煌曲子词是民间词；赵崇祚是编纂者，序言作者是欧阳炯，选择题常调换二者出题。","mcq":[{"q":"我国文学史上现存最早的文人词总集《花间集》的编纂者是","o":["欧阳炯","温庭筠","韦庄","赵崇祚"],"a":3,"w":"后蜀赵崇祚编纂《花间集》，欧阳炯为其作序。"}],"rel":[{"t":"《花间集》","n":"其编纂代表作"},{"t":"花间词派","n":"《花间集》确立流派"},{"t":"温庭筠","n":"《花间集》收录首位"},{"t":"韦庄","n":"《花间集》重要作者"}],"exam":[]},{"id":"z40-001","t":"柳永","cid":"03g","p":1,"kind":"人物","alias":["柳三变","柳七","柳屯田","耆卿","柳耆卿"],"one":"北宋婉约派词人，大量创作慢词，词集《乐章集》，《雨霖铃》最著。","ans":"柳永（约984–约1053），**原名三变，字耆卿，崇安（今福建）人，北宋词人**，官至屯田员外郎，世称柳七、柳屯田。他是**婉约派代表**，**大量创作慢词（长调）**，发展了铺叙手法，并多用俚语口语，描写都市风光与羁旅离情，代表作有**《雨霖铃》“寒蝉凄切”《望海潮》《八声甘州》《蝶恋花》**，词集**《乐章集》**。传说“凡有井水饮处，即能歌柳词”。他使慢词成为词体主流，为苏轼、周邦彦等人开路。","pts":["北宋婉约派，原名三变，字耆卿","大量创作慢词，铺叙，用俚语","《雨霖铃》《望海潮》；《乐章集》"],"mem":"姓“柳”，名句也是“杨柳岸，晓风残月”，一个“柳”字串起人与词。集名口诀：柳永乐章，李清照漱玉，晏殊珠玉，辛弃疾稼轩。画面：街头井台边，人人都在哼柳七的词，就是“有井水处皆歌柳”。","mix":"《乐章集》柳永，《漱玉词》李清照，《珠玉词》晏殊。《吹剑录》载苏轼问幕士自己的词与柳永比如何，答：柳词宜十七八岁女郎执红牙板唱“杨柳岸，晓风残月”，苏词须关西大汉执铁板唱“大江东去”，常被用来对比婉约与豪放。","mcq":[{"q":"“今宵酒醒何处？杨柳岸，晓风残月”出自","o":["《八声甘州》","《望海潮》","《雨霖铃》","《蝶恋花》"],"a":2,"w":"出自柳永《雨霖铃》。"},{"q":"北宋大量创作慢词的婉约词人是","o":["晏殊","柳永","欧阳修","晏几道"],"a":1,"w":"柳永大量创作慢词（长调），词集《乐章集》。"}],"rel":[{"t":"小令、中调、长调与慢词","n":"柳永擅长慢词"},{"t":"婉约派与豪放派","n":"所属流派"},{"t":"秦观、周邦彦","n":"同属婉约，继承铺叙"},{"t":"苏轼","n":"与其词风对举"},{"t":"张先“张三影”","n":"同时期词人"}],"more":"今宵酒醒何处？杨柳岸，晓风残月。｜《雨霖铃》\n衣带渐宽终不悔，为伊消得人憔悴。｜《蝶恋花》\n三秋桂子，十里荷花。｜《望海潮》\n《八声甘州》：渐霜风凄紧，关河冷落，残照当楼。","exam":[]},{"id":"z40-002","t":"晏殊","cid":"03g","p":2,"kind":"人物","alias":["晏同叔","晏元献","大晏"],"one":"北宋婉约词人，北宋宰相，与子晏几道并称“二晏”。","ans":"晏殊（991–1055），字同叔，**北宋词人**，官至**宰相**，与其子**晏几道**并称“**二晏**”。他提携过范仲淹、欧阳修等人。词风**温润圆融**，用语雅致，富于闲雅情致，词集《**珠玉词**》。代表作《**浣溪沙**》“**无可奈何花落去，似曾相识燕归来**”；《**蝶恋花**》中“昨夜西风凋碧树，独上高楼，望尽天涯路”被**王国维**用作做学问“**三境界**”的第一境。","pts":["北宋宰相，婉约词人，《珠玉词》","《浣溪沙》“无可奈何花落去”","王国维三境界第一境，二晏"],"mem":"三境界口诀：“晏柳辛”，第一境晏殊“昨夜西风”，第二境柳永“衣带渐宽”，第三境辛弃疾“众里寻他”，顺序对应：望路、苦求、顿悟。","mix":"“二晏”：晏殊（大晏）、晏几道（小晏）；三境界第二句出自柳永《蝶恋花》（衣带渐宽终不悔），第三境出自辛弃疾《青玉案》。","mcq":[{"q":"王国维“三境界”说中，第一境“昨夜西风凋碧树”出自","o":["晏殊","柳永","辛弃疾","晏几道"],"a":0,"w":"第一境晏殊《蝶恋花》，第二境柳永，第三境辛弃疾。"}],"rel":[{"t":"晏几道","n":"其子，并称二晏"},{"t":"二晏","n":"合称"},{"t":"王国维《人间词话》","n":"三境界出处"},{"t":"柳永","n":"三境界第二境"}],"more":"名句：无可奈何花落去，似曾相识燕归来。｜《浣溪沙》\n昨夜西风凋碧树，独上高楼，望尽天涯路。｜《蝶恋花》\n作品：《浣溪沙》《蝶恋花》《珠玉词》","exam":[]},{"id":"z40-003","t":"晏几道","cid":"03g","p":3,"kind":"人物","alias":["晏小山","叔原"],"one":"北宋婉约派词人，晏殊第七子，与父并称“二晏”，词集《小山词》。","ans":"晏几道（1038–1110），字叔原，**号小山**，**北宋婉约派词人**。宰相晏殊幼子，父子并称“**二晏**”。词风纯真深婉、感伤凄艳，著有《小山词》。名篇**《临江仙》**留有名句“**落花人独立，微雨燕双飞**”，为**北宋文人小令的高峰与尾声**。","pts":["北宋婉约派词人，号小山，晏殊幼子","与父并称“二晏”，词集《小山词》","名句“落花人独立，微雨燕双飞”"],"mem":"父子词人对比：大晏晏殊富贵从容（昨夜西风凋碧树），**小晏晏几道凄艳深情**（落花人独立，微雨燕双飞），号**小山**。","mix":"晏几道与晏殊并称“二晏”，大晏官居宰相词风典丽，小晏生平偃蹇词风凄婉；“落花人独立”化用自五代翁宏诗句。","mcq":[{"q":"词集名为《小山词》，留有名句“落花人独立，微雨燕双飞”的北宋婉约派词人是","o":["晏几道","晏殊","秦观","周邦彦"],"a":0,"w":"晏几道号小山，著有《小山词》，与父晏殊并称“二晏”。"}],"rel":[{"t":"晏殊","n":"其父，并称“二晏”"},{"t":"婉约派与豪放派","n":"婉约词代表人物"},{"t":"秦观","n":"同代婉约派词人"}],"more":"名句：落花人独立，微雨燕双飞。｜《临江仙》\n舞低杨柳楼心月，歌尽桃花扇底风。｜《鹧鸪天》","exam":[]},{"id":"z40-013","t":"秦观","cid":"03g","p":2,"kind":"人物","alias":["秦少游","淮海居士","少游"],"one":"北宋婉约词人，苏门四学士之一，《鹊桥仙》作者。","ans":"秦观（1049–1100），字少游，号淮海居士，**北宋婉约词人**，**苏门四学士**之一（另三人为黄庭坚、晁补之、张耒）。他的词多写离情别绪与身世之感，词风**凄婉清丽**，被视为婉约正宗。代表作《**鹊桥仙·纤云弄巧**》“**两情若是久长时，又岂在朝朝暮暮**”，歌咏牛郎织女，立意高远；《**踏莎行·郴州旅舍**》写贬谪的孤寂。他受苏轼赏识，但词风与苏轼的豪放有别，是婉约词的重要代表。","pts":["苏门四学士之一，号淮海居士","《鹊桥仙》“两情若是久长时”","《踏莎行·郴州旅舍》，婉约词代表"],"mem":"苏门四学士口诀“黄秦晁张”：黄庭坚、秦观、晁补之、张耒。秦观的《鹊桥仙》在七夕必背：“金风玉露一相逢，便胜却人间无数”。","mix":"苏门四学士与“苏门六君子”不同，后者加陈师道、李廌；秦观是苏轼学生，词风却不似苏轼。","mcq":[{"q":"下列不属于“苏门四学士”的是","o":["黄庭坚","秦观","晁补之","柳永"],"a":3,"w":"苏门四学士为黄庭坚、秦观、晁补之、张耒。"}],"rel":[{"t":"苏门四学士","n":"所属"},{"t":"苏轼","n":"老师"},{"t":"黄庭坚","n":"同为苏门四学士"},{"t":"婉约派与豪放派","n":"所属风格"}],"more":"名句：两情若是久长时，又岂在朝朝暮暮。｜《鹊桥仙》\n金风玉露一相逢，便胜却人间无数。｜《鹊桥仙》\n作品：《鹊桥仙》《踏莎行·郴州旅舍》","exam":[]},{"id":"z40-014","t":"周邦彦","cid":"03g","p":2,"kind":"人物","alias":["周美成","清真居士","周清真"],"one":"北宋词人，格律派开创者，集婉约词之大成。","ans":"周邦彦（1056–1121），字美成，号清真居士，**北宋词人**，曾提举**大晟府**，精通音律，创制不少新词调。他的词**格律严整**、**铺叙精致**，被视为**格律派的开创者**，**集婉约词之大成**，对南宋姜夔、吴文英等人影响很大。代表作有《**兰陵王·柳**》《**苏幕遮**》，其中“叶上初阳干宿雨，水面清圆，一一风荷举”写荷风，细腻传神。词集称《**清真集**》，又名《**片玉词**》。","pts":["提举大晟府，精通音律","格律派开创者，集婉约词之大成","《兰陵王·柳》《苏幕遮》，《清真集》"],"mem":"“周”与“集大成”绑定：柳永创慢词，周邦彦集大成，李清照继之。“大晟府”是官方音乐机构，所以周词格律最严。","mix":"“集婉约词之大成”常指周邦彦，而婉约词宗常指李清照；周词重格律，苏轼重意境。","mcq":[{"q":"提举大晟府、被视为格律派开创者的北宋词人是","o":["周邦彦","晏几道","秦观","柳永"],"a":0,"w":"周邦彦曾提举大晟府，是格律派开创者。"}],"rel":[{"t":"柳永","n":"慢词前驱"},{"t":"婉约派与豪放派","n":"所属风格"},{"t":"吴文英与南宋格律词派","n":"受其影响"},{"t":"李清照","n":"婉约另一高峰"}],"more":"名句：叶上初阳干宿雨，水面清圆，一一风荷举。｜《苏幕遮》\n作品：《兰陵王·柳》《苏幕遮》《清真集》（又名《片玉词》）","exam":[]},{"id":"z40-015","t":"贺铸","cid":"03g","p":3,"kind":"人物","alias":["贺方回","贺梅子","庆湖遗老"],"one":"北宋词人，兼具豪放与婉约，因《青玉案》名句得名“贺梅子”。","ans":"贺铸（1052–1125），字方回，号庆湖遗老，**北宋词人**。词风**兼擅豪放与婉约**。代表作**《青玉案》**以“梅子黄时雨”博喻闲愁，得名“**贺梅子**”；其《六州歌头》慷慨悲壮，深具爱国气概，**开南宋辛派爱国词先声**。","pts":["北宋词人，字方回，兼擅豪放与婉约","《青玉案》博喻闲愁，得名“贺梅子”","《六州歌头》开创南宋爱国词派先声"],"mem":"词人绰号绑定：贺铸写江南梅雨闲愁→**贺梅子**。记住其一身兼二任：婉约写情愁（《青玉案》），豪放写侠气（《六州歌头》）。","mix":"辛弃疾也写有名作《青玉案·元夕》（东风夜放花千树），贺铸作的是《青玉案·凌波不过横塘路》；贺铸与“张三影”张先同为以佳句得雅号词人。","mcq":[{"q":"北宋词人贺铸因在《青玉案》中写出“一川烟草，满城风絮，梅子黄时雨”的名句，在词坛被美称为","o":["贺鬼才","贺梅子","贺狂客","贺三影"],"a":1,"w":"贺铸因《青玉案》名句化闲愁为江南梅雨，人称“贺梅子”。"}],"rel":[{"t":"辛弃疾","n":"受贺铸豪放词风影响"},{"t":"张先“张三影”","n":"同以雅号传世词人"},{"t":"婉约派与豪放派","n":"兼跨两派之代表"}],"more":"名句：试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨。｜《青玉案》\n少年侠气，交结五都雄。｜《六州歌头》","exam":[]},{"id":"c-024","t":"温李；温韦","cid":"03g","p":2,"kind":"合称","alias":["温李","温韦"],"one":"温庭筠与李商隐（晚唐诗）；温庭筠与韦庄（花间词）。","ans":"“**温李**”指**晚唐诗人温庭筠与李商隐**，二人诗风都绮丽深婉，与同时的杜牧不同；“**温韦**”指**温庭筠与韦庄**，二人均为**花间词派**代表。温庭筠词浓艳密丽，开创花间词风，被尊为**花间鼻祖**；韦庄词清丽疏淡，更重抒写个人经历。区分口径：**温李论诗，温韦论词**，温庭筠是两个合称共同的核心人物，说明他诗词兼擅。","pts":["温李：温庭筠、李商隐（诗）","温韦：温庭筠、韦庄（词）","温庭筠诗词兼擅"],"members":[["温李","温庭筠、李商隐，晚唐诗"],["温韦","温庭筠、韦庄，花间词"]],"mem":"看字：“温李”后面的李是李商隐，诗人；“温韦”后面是韦庄，词人。温庭筠在中间两头占：既是诗，又是词。","mix":"“小李杜”（李商隐、杜牧）与“温李”不同；“温韦”是词，不要说成诗。","mcq":[{"q":"“温韦”是指","o":["温庭筠、韦庄","温庭筠、李商隐","李煜、韦庄","温庭筠、杜牧"],"a":0,"w":"温韦指温庭筠与韦庄，花间词。"}],"rel":[{"t":"温庭筠","n":"共同核心"},{"t":"李商隐","n":"“温李”之一"},{"t":"韦庄","n":"“温韦”之一"},{"t":"花间词派","n":"“温韦”所属"}],"exam":[]},{"id":"c-025","t":"南唐二主","cid":"03g","p":2,"kind":"合称","alias":["二主","南唐二主词"],"one":"李璟、李煜，南唐中主与后主，词作后合编为《南唐二主词》。","ans":"“**南唐二主**”指**五代南唐的李璟与李煜**，李璟称**中主**，李煜称**后主**，二人均为**词人**。李璟词留存不多，有《**摊破浣溪沙**》“菡萏香销翠叶残”“小楼吹彻玉笙寒”，意境清冷。李煜前期写宫廷享乐，亡国后作《**虞美人**》“春花秋月何时了”、《**浪淘沙**》等，**由伶工之词变为士大夫之词**。两人的词合编为**《南唐二主词》**，使词的境界从花间的闺情转向身世之慨。","pts":["李璟（中主）、李煜（后主）","词后合编为《南唐二主词》","李煜成就最高，眼界始大"],"members":[["李璟","中主，《摊破浣溪沙》“小楼吹彻玉笙寒”"],["李煜","后主，《虞美人》《浪淘沙》"]],"mem":"父子顺序：李璟（中主，父）→李煜（后主，子）。成就一父一子：中主词少而清，后主词多而深。","mix":"南唐二主指父子，不要与“二晏”（晏殊、晏几道父子）混；李煜成就远高于李璟。","mcq":[{"q":"“南唐二主”指","o":["李璟、李煜","李煜、冯延巳","李璟、冯延巳","李煜、李清照"],"a":0,"w":"南唐中主李璟与后主李煜。"}],"rel":[{"t":"李煜","n":"后主"},{"t":"李煜《虞美人》与“千古词帝”","n":"代表作"},{"t":"二晏","n":"同为父子词人"},{"t":"《花间集》","n":"前代词风"}],"exam":[]},{"id":"c-027","t":"二晏","cid":"03g","p":2,"kind":"合称","alias":["大晏小晏","晏氏父子"],"one":"晏殊、晏几道父子，北宋婉约词人。","ans":"“**二晏**”指**北宋晏殊与其子晏几道**，**父子**均为**婉约词人**，晏殊称“大晏”，晏几道称“小晏”。晏殊官至宰相，词风**温润圆融**，有《珠玉词》，《浣溪沙》“无可奈何花落去，似曾相识燕归来”著名；晏几道字叔原，号小山，词风**哀感缠绵**，多写恋情与身世，有《小山词》，《鹧鸪天》“彩袖殷勤捧玉钟”为代表作。二晏继承了**南唐、花间以来的小令传统**，是北宋小令的高峰。","pts":["晏殊（大晏）、晏几道（小晏），父子","晏殊《珠玉词》，晏几道《小山词》","北宋小令高峰"],"members":[["晏殊","大晏，字同叔，《珠玉词》"],["晏几道","小晏，字叔原，号小山，《小山词》"]],"mem":"大晏富贵（宰相），小晏落魄（公子沦落），所以一个词温润，一个词哀感。“珠玉”对应大晏，“小山”对应小晏。","mix":"二晏是父子；南唐二主也是父子；王国维三境界第一境是晏殊，不是晏几道。","mcq":[{"q":"“二晏”的关系是","o":["兄弟","师生","父子","叔侄"],"a":2,"w":"晏殊与其子晏几道。"}],"rel":[{"t":"晏殊","n":"大晏"},{"t":"晏几道","n":"小晏"},{"t":"南唐二主","n":"同为父子词人"},{"t":"婉约派与豪放派","n":"所属风格"}],"exam":[]},{"id":"b03-008","t":"苏辛","cid":"03h","p":1,"kind":"合称","exam":["2026名解"],"alias":["苏辛"],"one":"北宋苏轼与南宋辛弃疾的并称，宋词豪放派代表。","ans":"苏辛是**北宋苏轼与南宋辛弃疾的并称，二人是宋词豪放派的代表**。**苏轼（号东坡居士）“以诗为词”，扩大词的题材和境界**，代表作《念奴娇·赤壁怀古》《水调歌头·明月几时有》。**辛弃疾（号稼轩）“以文为词”，词中多抒抗金收复之志**，代表作《永遇乐·京口北固亭怀古》《破阵子·为陈同甫赋壮词以寄之》，有《稼轩长短句》。二人开拓了词的表现领域，使豪放词与婉约词并立，也使词摆脱“艳科”的局限。","pts":["苏轼与辛弃疾并称，豪放派代表","苏轼北宋，以诗为词","辛弃疾南宋，以文为词，抗金"],"members":[["苏轼","北宋，号东坡居士，“以诗为词”，《念奴娇·赤壁怀古》《水调歌头》"],["辛弃疾","南宋，号稼轩，“以文为词”，《永遇乐》《破阵子》，词集《稼轩长短句》"]],"mem":"一人一句：苏轼“大江东去”，辛弃疾“气吞万里如虎”。顺序记“苏诗辛文”：苏轼“以诗为词”在前，辛弃疾“以文为词”在后，苏开路，辛集大成。","mix":"“苏黄”指苏轼、黄庭坚（诗）；“济南二安”指李清照、辛弃疾；追随辛弃疾的陈亮、刘过等称“辛派词人”。","mcq":[{"q":"“以文为词”常用来概括的词人是","o":["苏轼","辛弃疾","李清照","周邦彦"],"a":1,"w":"辛弃疾以文为词，苏轼则是以诗为词。"},{"q":"“苏辛”中“辛”所指人物的词集名称是","o":["《乐章集》","《漱玉词》","《稼轩长短句》","《东坡乐府》"],"a":2,"w":"辛弃疾词集为《稼轩长短句》。"}],"rel":[{"t":"苏轼","n":"“苏”"},{"t":"辛弃疾","n":"“辛”"},{"t":"婉约派与豪放派","n":"所属流派"},{"t":"苏黄","n":"同以苏轼并称，指诗"},{"t":"济南二安","n":"辛弃疾的另一并称"}]},{"id":"b03-012","t":"唐宋八大家","cid":"03h","p":1,"kind":"合称","alias":["八大家"],"one":"唐宋两代八位散文家：韩愈、柳宗元、欧阳修、三苏、王安石、曾巩。","ans":"唐宋八大家是**唐宋两代八位散文家的合称**：**唐代韩愈、柳宗元，宋代欧阳修、苏洵、苏轼、苏辙、王安石、曾巩**，即“唐二宋六”。**韩愈、柳宗元倡导古文运动，反对六朝以来的骈文，主张“文以明道”**；北宋欧阳修领导诗文革新运动，继承其主张。**明代茅坤编《唐宋八大家文钞》，“八大家”之名由此流行**。八家散文文从字顺、说理明晰，奠定古代散文的正统，明代唐宋派和清代桐城派都奉为典范。","pts":["唐二宋六的八位散文家","韩柳倡古文运动，反骈文","茅坤《唐宋八大家文钞》"],"members":[["韩愈","唐，《师说》《马说》《进学解》"],["柳宗元","唐，《永州八记》《捕蛇者说》"],["欧阳修","北宋，《醉翁亭记》《秋声赋》"],["苏洵","北宋，《六国论》"],["苏轼","北宋，《赤壁赋》《石钟山记》"],["苏辙","北宋，《黄州快哉亭记》"],["王安石","北宋，《游褒禅山记》《答司马谏议书》"],["曾巩","北宋，《墨池记》"]],"mem":"口诀“韩柳欧苏王曾”（三苏合为一个“苏”字，实有三人）。画面：先是唐代的“韩柳”两位开路，宋代欧阳修带着三苏父子、再加王安石、曾巩，一共“唐二宋六”。","mix":"范仲淹《岳阳楼记》、刘禹锡《陋室铭》、周敦颐《爱莲说》、司马光的作者都不在八大家之列；“三苏”三人全在八大家之内。","mcq":[{"q":"下列人物中，不属于“唐宋八大家”的是","o":["曾巩","苏辙","范仲淹","王安石"],"a":2,"w":"范仲淹不在八大家之列。"},{"q":"编选《唐宋八大家文钞》，使“八大家”之名流行的是","o":["归有光","唐顺之","方苞","茅坤"],"a":3,"w":"明代茅坤编《唐宋八大家文钞》。"}],"rel":[{"t":"古文运动","n":"韩柳所倡"},{"t":"北宋诗文革新运动","n":"欧阳修所倡"},{"t":"三苏","n":"八家中的父子三人"},{"t":"唐宋派","n":"明代尊奉八家"},{"t":"桐城派","n":"清代继承八家"}],"exam":[]},{"id":"b03-022","t":"苏轼《饮湖上初晴后雨》","cid":"03h","p":1,"kind":"作品","exam":["2010选择"],"alias":["饮湖上初晴后雨","欲把西湖比西子"],"one":"苏轼咏西湖的七绝，以西子比西湖，“淡妆浓抹总相宜”。","ans":"《饮湖上初晴后雨》是**北宋苏轼所作七言绝句，共两首，传诵的是其二**，写于**任杭州通判期间**，记在西湖宴饮时所见晴雨景色。诗中“水光潋滟晴方好，山色空蒙雨亦奇”写西湖晴雨皆美，结句**“欲把西湖比西子，淡妆浓抹总相宜”**以**春秋美人西施比西湖**，构思新奇，比喻贴切。后人因此称西湖为“西子湖”，此诗成为咏西湖诗中最著名的一首。","pts":["苏轼七绝，咏杭州西湖","水光潋滟晴方好，山色空蒙雨亦奇","以西子喻西湖，西湖别称西子湖"],"mem":"画面：晴天阳光下湖水闪亮，像西施的“浓抹”；雨天山色朦胧，像“淡妆”，晴雨都美，所以“总相宜”。西湖诗对号入座：苏轼“淡妆浓抹”，杨万里“接天莲叶”，白居易“最爱湖东”，林升“西湖歌舞几时休”。","mix":"西湖诗易混：杨万里《晓出净慈寺送林子方》“接天莲叶无穷碧”，白居易《钱塘湖春行》“最爱湖东行不足”，林升《题临安邸》“西湖歌舞几时休”；“淡妆浓抹总相宜”属苏轼。","mcq":[{"q":"“欲把西湖比西子，淡妆浓抹总相宜”的作者是","o":["杨万里","苏轼","白居易","陆游"],"a":1,"w":"出自苏轼《饮湖上初晴后雨》。"},{"q":"苏轼诗中以“西子”比喻的是","o":["洞庭湖","太湖","西湖","鄱阳湖"],"a":2,"w":"“西子”指西施，诗以其比西湖。"}],"rel":[{"t":"苏轼","n":"作者"},{"t":"苏轼代表作","n":"同属苏轼名篇"},{"t":"杨万里","n":"同写西湖"},{"t":"白居易","n":"同写西湖"}],"more":"水光潋滟晴方好，山色空蒙雨亦奇。\n欲把西湖比西子，淡妆浓抹总相宜。"},{"id":"b03-037","t":"陆游","cid":"03h","p":2,"kind":"人物","alias":["陆放翁","放翁","陆务观"],"one":"南宋爱国诗人，现存诗九千余首，《示儿》作者。","ans":"陆游（1125–1210），字务观，号放翁，**南宋爱国诗人**，与尤袤、杨万里、范成大并称“**南宋中兴四大诗人**”。他现存诗**九千余首**，诗集《**剑南诗稿**》，多抒发收复中原的抱负，代表作《**示儿**》“王师北定中原日，家祭无忘告乃翁”是临终绝笔；《**游山西村**》“山重水复疑无路，柳暗花明又一村”、《十一月四日风雨大作》“铁马冰河入梦来”也流传很广。他的词《**钗头凤**》写与唐琬的爱情悲剧。","pts":["南宋爱国诗人，中兴四大诗人之一","存诗九千余首，《示儿》《游山西村》","《钗头凤》写与唐琬"],"mem":"一个“爱国”主线：《示儿》（临终）、《书愤》、《十一月四日风雨大作》都是收复中原的愿望。口诀“尤杨范陆”：南宋中兴四大诗人。","mix":"毛泽东《卜算子·咏梅》注明“反其意而用之”，反的是陆游的《卜算子·咏梅》；中兴四大诗人里尤袤存诗最少，辛弃疾是词人，常作干扰项。","mcq":[{"q":"“山重水复疑无路，柳暗花明又一村”出自陆游的","o":["《示儿》","《钗头凤》","《书愤》","《游山西村》"],"a":3,"w":"出自陆游《游山西村》。"},{"q":"下列不属于南宋“中兴四大诗人”的是","o":["陆游","杨万里","范成大","辛弃疾"],"a":3,"w":"南宋中兴四大诗人为尤袤、杨万里、范成大、陆游。"}],"rel":[{"t":"中兴四大诗人","n":"所属合称"},{"t":"陆游代表作","n":"代表作条目"},{"t":"辛弃疾","n":"同为南宋爱国词人"},{"t":"杨万里","n":"同为中兴四大诗人"}],"more":"名句：王师北定中原日，家祭无忘告乃翁。｜《示儿》\n山重水复疑无路，柳暗花明又一村。｜《游山西村》\n夜阑卧听风吹雨，铁马冰河入梦来。｜《十一月四日风雨大作》\n零落成泥碾作尘，只有香如故。｜《卜算子·咏梅》\n纸上得来终觉浅，绝知此事要躬行。｜《冬夜读书示子聿》\n作品：《示儿》《钗头凤》《游山西村》《书愤》《剑南诗稿》","exam":[]},{"id":"b03-038","t":"范仲淹","cid":"03h","p":2,"kind":"人物","alias":["范文正公","范希文","范文正"],"one":"北宋政治家、文学家，主持庆历新政，作《岳阳楼记》，不在八大家之列。","ans":"范仲淹（989–1052），字希文，谥文正，**北宋政治家、文学家**，苏州吴县人。他在仁宗时主持**庆历新政**，提出整顿吏治、改革科举等十项主张，后因保守派反对而失败。文学上以《岳阳楼记》最有名，文中“**先天下之忧而忧，后天下之乐而乐**”成为士大夫精神的写照；戍守西北时所作《渔家傲·秋思》以边塞入词，被视为**豪放词先声**。他**不在唐宋八大家之列**。","pts":["北宋政治家，主持庆历新政","《岳阳楼记》：先天下之忧而忧","《渔家傲·秋思》开豪放词先声；非八大家"],"mem":"八大家口诀“韩柳欧三苏曾王”，里面没有范。记一句分工：范仲淹是政治家兼文章家，八大家是以文章立身。《岳阳楼记》两组对子：“不以物喜，不以己悲”写心态，“先忧后乐”写抱负。","mix":"《苏幕遮·碧云天》是范仲淹词，周邦彦另有同调《苏幕遮》；刘禹锡《陋室铭》、周敦颐《爱莲说》同样常作八大家干扰项。","mcq":[{"q":"下列作家中，不属于“唐宋八大家”的是","o":["范仲淹","曾巩","苏辙","王安石"],"a":0,"w":"范仲淹作《岳阳楼记》，是政治家，不在八大家之列。"}],"rel":[{"t":"庆历新政","n":"他主持的改革"},{"t":"范仲淹《岳阳楼记》与“易混作者”","n":"名篇与干扰项"},{"t":"唐宋八大家","n":"不在其列"},{"t":"欧阳修","n":"同时代，推动诗文革新"}],"more":"生平：989–1052，字希文，谥文正。\n作品：《岳阳楼记》《渔家傲·秋思》（“塞下秋来风景异”）《苏幕遮》（“碧云天，黄叶地”）\n先天下之忧而忧，后天下之乐而乐。｜《岳阳楼记》\n不以物喜，不以己悲。｜《岳阳楼记》\n浊酒一杯家万里，燕然未勒归无计。｜《渔家傲·秋思》","exam":[]},{"id":"b03-039","t":"王安石","cid":"03h","p":2,"kind":"人物","alias":["王荆公","王介甫","半山","荆国公"],"one":"北宋政治家、唐宋八大家之一，主持熙宁变法，诗称“王荆公体”。","ans":"王安石（1021–1086），字介甫，号半山，封荆国公，**抚州临川人**，北宋政治家、文学家。他在神宗支持下主持**熙宁变法**，推行青苗法、免役法、方田均税法等新法，因保守派反对而受挫。他是**唐宋八大家之一**，散文说理严密，有《答司马谏议书》《游褒禅山记》；诗风晚年转为含蓄精工，称“**王荆公体**”，《泊船瓜洲》中“春风又绿江南岸”的“绿”字是炼字名例。","pts":["北宋政治家，主持熙宁变法","唐宋八大家之一，诗称王荆公体","《泊船瓜洲》“绿”字；《登飞来峰》"],"mem":"作品配句子记：《泊船瓜洲》“春风又绿江南岸”（炼字），《登飞来峰》“不畏浮云遮望眼”（改革者的气魄，浮云可比守旧势力），《元日》“爆竹声中一岁除”，《梅花》“墙角数枝梅”。“半山”是他晚年居江宁半山园的号。","mix":"变法的对头是司马光，两人是同时代的政敌；曾巩与王安石是好友，同列八大家；《桂枝香·金陵怀古》是他的词，不要与苏轼的豪放词混。","mcq":[{"q":"“春风又绿江南岸，明月何时照我还”出自","o":["苏轼《水调歌头》","王安石《泊船瓜洲》","欧阳修《醉翁亭记》","陆游《示儿》"],"a":1,"w":"该句出自王安石《泊船瓜洲》，“绿”字为炼字名例。"}],"rel":[{"t":"王安石变法","n":"他主持的改革"},{"t":"唐宋八大家","n":"八大家之一"},{"t":"曾巩","n":"好友，同列八大家"},{"t":"庆历新政","n":"前一次北宋改革"}],"more":"生平：1021–1086，字介甫，号半山，封荆国公。\n作品：《泊船瓜洲》《登飞来峰》《元日》《梅花》《游褒禅山记》《答司马谏议书》《桂枝香·金陵怀古》\n春风又绿江南岸，明月何时照我还。｜《泊船瓜洲》\n不畏浮云遮望眼，自缘身在最高层。｜《登飞来峰》\n爆竹声中一岁除，春风送暖入屠苏。｜《元日》\n墙角数枝梅，凌寒独自开。｜《梅花》","exam":[]},{"id":"b03-040","t":"欧阳修","cid":"03h","p":1,"kind":"人物","alias":["欧公","醉翁","六一居士","欧阳永叔","永叔"],"one":"北宋文坛领袖，唐宋八大家之一，领导诗文革新，作《醉翁亭记》。","ans":"欧阳修（1007–1072），**字永叔，号醉翁、六一居士，吉州庐陵人，北宋政治家、文学家、史学家**，谥文忠。他**领导北宋诗文革新运动**，继承韩愈古文主张，反对西昆体和太学体，嘉祐二年知贡举时录取苏轼、苏辙、曾巩，为**唐宋八大家之一**。散文代表作有**《醉翁亭记》《秋声赋》《朋党论》《伶官传序》**；所著《六一诗话》开“诗话”体；史学上**独撰《新五代史》**，并与宋祁合修《新唐书》。他奖掖后进，是北宋中期的文坛领袖。","pts":["字永叔，号醉翁、六一居士，文坛领袖","领导诗文革新，知贡举取苏轼等","《醉翁亭记》；《新五代史》；《六一诗话》"],"mem":"“六一”的画面：书一万卷、金石一千卷、琴一张、棋一局、酒一壶，再加上他这一个老翁，凑成六个“一”。作品四体各一篇：记（《醉翁亭记》）、赋（《秋声赋》）、论（《朋党论》）、序（《伶官传序》）。","mix":"“醉翁之意不在酒”是欧阳修《醉翁亭记》，《岳阳楼记》是范仲淹；《新五代史》欧阳修独撰，《旧五代史》是薛居正等，《新唐书》是欧阳修与宋祁合修。","mcq":[{"q":"欧阳修独撰的史书是","o":["《新唐书》","《新五代史》","《旧五代史》","《资治通鉴》"],"a":1,"w":"《新五代史》为欧阳修独撰；《新唐书》由他与宋祁合修。"},{"q":"“六一居士”的“六一”不包括","o":["宝剑一口","藏书一万卷","金石遗文一千卷","酒一壶"],"a":0,"w":"六一指藏书一万卷、金石遗文一千卷、琴一张、棋一局、酒一壶和一老翁。"}],"rel":[{"t":"北宋诗文革新运动","n":"他所领导"},{"t":"唐宋八大家","n":"所属合称"},{"t":"欧阳修《六一诗话》","n":"开诗话体"},{"t":"苏轼","n":"门生与继承者"},{"t":"韩愈","n":"古文传统的先驱"}],"more":"醉翁之意不在酒，在乎山水之间也。｜《醉翁亭记》\n忧劳可以兴国，逸豫可以亡身。｜《伶官传序》\n作品：《醉翁亭记》《秋声赋》《朋党论》《新五代史》《六一诗话》。","exam":[]},{"id":"b03-041","t":"黄庭坚与江西诗派","cid":"03h","p":1,"kind":"流派","alias":["黄庭坚","黄山谷","山谷道人","黄鲁直","江西诗派"],"one":"黄庭坚开创江西诗派，与苏轼并称“苏黄”，主张“点铁成金”“夺胎换骨”。","ans":"黄庭坚（1045–1105），**字鲁直，号山谷道人，洪州分宁（今江西修水）人，北宋诗人、书法家**，为**“苏门四学士”之一**，与苏轼并称**“苏黄”**。他**开创江西诗派**，主张作诗“无一字无来处”，以**“点铁成金”“夺胎换骨”**化用前人诗句，诗风奇崛瘦硬。南宋吕本中作《江西诗社宗派图》，列二十五人，江西诗派因此得名，后人又有“一祖三宗”之说。黄庭坚书法与苏轼、米芾、蔡襄并称“宋四家”。他深刻影响了南宋诗坛，也带来堆砌典故、模拟的流弊。","pts":["苏门四学士，与苏轼并称“苏黄”","开创江西诗派，点铁成金、夺胎换骨","吕本中《宗派图》；一祖三宗"],"mem":"点铁成金：把前人的旧句（铁）点化成自己的好诗（金）；夺胎换骨：借旧诗的意思，换一副新的形式。“苏黄”记诗与书法，“苏辛”记词，别互相串。书法“宋四家”口诀“苏黄米蔡”。","mix":"“苏黄”指苏轼、黄庭坚（诗与书法），“苏辛”指苏轼、辛弃疾（词）；江西诗派因黄庭坚籍贯得名，诗人并不都是江西人；“一祖三宗”是元代方回的追认。","mcq":[{"q":"提出“点铁成金”“夺胎换骨”的诗派是","o":["西昆体","永嘉四灵","江西诗派","江湖诗派"],"a":2,"w":"点铁成金、夺胎换骨是黄庭坚及江西诗派的作诗主张。"},{"q":"下列人物中，属于“苏门四学士”的是","o":["陆游","黄庭坚","范成大","陈师道"],"a":1,"w":"苏门四学士是黄庭坚、秦观、晁补之、张耒；陈师道属“苏门六君子”。"}],"rel":[{"t":"江西诗派“一祖三宗”","n":"江西诗派的宗祖说"},{"t":"苏黄","n":"与苏轼并称"},{"t":"苏门四学士","n":"所属群体"},{"t":"苏轼","n":"师友"},{"t":"宋诗特点：以文字为诗、以议论为诗、以才学为诗","n":"宋诗风气代表"}],"exam":[]},{"id":"b03-043","t":"姜夔","cid":"03h","p":2,"kind":"人物","alias":["白石道人","姜白石","姜尧章"],"one":"南宋格律派词人，精通音律，善自度曲，《扬州慢》《暗香》《疏影》。","ans":"姜夔（约1155–约1221），字尧章，号白石道人，**南宋词人、音乐家**，终身未仕，以清客身份游走江湖。他是**格律派（骚雅派）**代表，词风清空峭拔，又**精通音律、能自度曲**。代表作有《扬州慢·淮左名都》，其中“二十四桥仍在，波心荡，冷月无声”写战乱后扬州的萧条；《暗香》《疏影》是咏梅二首。其《白石道人歌曲》**保存了十余首词的旁谱**，是研究宋词音乐的珍贵资料。","pts":["南宋格律派词人，号白石道人","自度曲，《扬州慢》《暗香》《疏影》","《白石道人歌曲》保存旁谱"],"mem":"一个画面：白石道人一手执笔，一手拨弦，自己写词又自己谱曲，所以“自度曲”配“旁谱”。咏梅二首记“暗香疏影”，出自林逋“疏影横斜水清浅，暗香浮动月黄昏”，两个词牌名都是他从林逋诗里取的。","mix":"辛弃疾也有《扬州慢》之外的怀古词，但风格豪放；姜夔属婉约一路的格律派，与吴文英、张炎同属南宋格律词派；“旁谱”只有姜夔的词集保存得最完整。","mcq":[{"q":"南宋词人中，以自度曲著称并留下词乐旁谱的是","o":["辛弃疾","姜夔","陆游","刘过"],"a":1,"w":"姜夔精通音律，《白石道人歌曲》保存旁谱。"}],"rel":[{"t":"吴文英与南宋格律词派","n":"同属格律派"},{"t":"婉约派与豪放派","n":"风格归属"},{"t":"辛弃疾","n":"南宋词坛对举对象"},{"t":"范成大","n":"姜夔曾在其家作《暗香》《疏影》"}],"more":"作品：《扬州慢·淮左名都》《暗香》《疏影》；词集《白石道人歌曲》\n二十四桥仍在，波心荡，冷月无声。｜《扬州慢》","exam":[]},{"id":"z40-007","t":"苏洵","cid":"03h","p":2,"kind":"人物","alias":["苏老泉","老泉","苏明允"],"one":"北宋散文家，三苏之父，唐宋八大家之一，《六国论》作者。","ans":"苏洵（1009–1066），字明允，号老泉，**眉州眉山人**，北宋散文家，苏轼、苏辙之父。他二十七岁才发愤读书，经欧阳修推荐而知名，与二子并称“**三苏**”，同列**唐宋八大家**。他长于政论，文风雄健，代表作《六国论》提出“六国破灭，非兵不利，战不善，弊在赂秦”，借古讽今，针对的是宋对辽、西夏的纳币求和。","pts":["北宋散文家，三苏之父","唐宋八大家之一，欧阳修推荐","《六国论》：弊在赂秦"],"mem":"《三字经》有“苏老泉，二十七，始发愤，读书籍”，“老泉”就是他的号，二十七岁就是晚学的年龄。《六国论》论点记三个字“赂秦弊”。","mix":"苏辙也写过一篇《六国论》，观点是六国不能团结、忽视韩魏的屏障作用，与苏洵“赂秦”说不同。","mcq":[{"q":"“六国破灭，非兵不利，战不善，弊在赂秦”出自","o":["苏辙《黄州快哉亭记》","苏轼《赤壁赋》","苏洵《六国论》","贾谊《过秦论》"],"a":2,"w":"该句是苏洵《六国论》的中心论点。"}],"rel":[{"t":"三苏","n":"三苏之父"},{"t":"苏辙","n":"也作《六国论》"},{"t":"唐宋八大家","n":"八大家之一"},{"t":"欧阳修","n":"推荐其文章"}],"more":"生平：1009–1066，字明允，号老泉。\n作品：《六国论》《权书》《衡论》，文集《嘉祐集》\n六国破灭，非兵不利，战不善，弊在赂秦。｜《六国论》","exam":[]},{"id":"z40-008","t":"苏轼","cid":"03h","p":1,"kind":"人物","exam":["2010选择","2026名解"],"alias":["东坡","苏东坡","东坡居士","苏子瞻","子瞻","苏文忠"],"one":"北宋文坛全才，唐宋八大家之一，豪放词开创者，号东坡居士。","ans":"苏轼（1037–1101），**字子瞻，号东坡居士，眉州眉山人，北宋文学家、书画家**，谥文忠，为**“唐宋八大家”之一**，与父苏洵、弟苏辙合称“三苏”。他**开豪放词一派，“以诗为词”**，扩大词的题材，代表作**《念奴娇·赤壁怀古》《水调歌头·明月几时有》**，与辛弃疾并称“苏辛”；散文有**《赤壁赋》《石钟山记》**，诗有《题西林壁》；书法列“宋四家”，有《黄州寒食诗帖》。乌台诗案后他被贬黄州，其后又贬惠州、儋州，这一经历深刻影响了他旷达的风格。他诗、词、文、书、画兼擅，是宋代文学艺术的代表。","pts":["字子瞻，号东坡居士，唐宋八大家，三苏","豪放词开创者，以诗为词，苏辛","《赤壁赋》《念奴娇》；书法宋四家"],"mem":"贬谪三地口诀“黄惠儋”：黄州（写出《赤壁赋》《念奴娇》）→惠州（日啖荔枝三百颗）→儋州（海南）。名句按体裁归类：词（大江东去，但愿人长久）、诗（不识庐山真面目，淡妆浓抹总相宜）、文（《赤壁赋》）。","mix":"《念奴娇》是词牌，“赤壁怀古”是词题；苏轼游的黄州赤壁（赤鼻矶）并非三国赤壁之战旧址，词中“人道是”即带存疑；“苏黄”指诗，“苏辛”指词，“宋四家”指书法（苏黄米蔡）。","mcq":[{"q":"下列作品中，不是苏轼所作的是","o":["《赤壁赋》","《石钟山记》","《醉翁亭记》","《记承天寺夜游》"],"a":2,"w":"《醉翁亭记》是欧阳修的作品。"},{"q":"“竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生”出自","o":["《卜算子》","《定风波》","《江城子》","《临江仙》"],"a":1,"w":"出自苏轼《定风波·莫听穿林打叶声》。"}],"rel":[{"t":"苏辛","n":"与辛弃疾并称"},{"t":"苏轼代表作","n":"代表作汇总"},{"t":"三苏","n":"与父弟并称"},{"t":"唐宋八大家","n":"所属合称"},{"t":"黄庭坚与江西诗派","n":"诗坛“苏黄”"}],"more":"欲把西湖比西子，淡妆浓抹总相宜。｜《饮湖上初晴后雨》\n但愿人长久，千里共婵娟。｜《水调歌头》\n大江东去，浪淘尽，千古风流人物。｜《念奴娇·赤壁怀古》\n不识庐山真面目，只缘身在此山中。｜《题西林壁》\n十年生死两茫茫，不思量，自难忘。｜《江城子·记梦》\n竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。｜《定风波》\n竹外桃花三两枝，春江水暖鸭先知。｜《惠崇春江晚景》"},{"id":"z40-009","t":"苏辙","cid":"03h","p":2,"kind":"人物","alias":["苏子由","子由","颍滨遗老","苏颍滨"],"one":"苏轼之弟，唐宋八大家之一，文风汪洋澹泊，《黄州快哉亭记》。","ans":"苏辙（1039–1112），字子由，号颍滨遗老，**眉州眉山人**，北宋散文家，苏轼之弟。他与父苏洵、兄苏轼合称“**三苏**”，同列**唐宋八大家**。其文汪洋澹泊，条理清晰，代表作《黄州快哉亭记》为兄长苏轼贬谪黄州时的朋友张梦得所筑快哉亭而作，借景抒怀，说明“士生于世，使其中不自得，将何往而非病”的道理；另有《六国论》《上枢密韩太尉书》。","pts":["北宋散文家，苏轼之弟，三苏之一","唐宋八大家之一","《黄州快哉亭记》《六国论》"],"mem":"苏轼字子瞻，苏辙字子由，“瞻”望前方、“由”随其后，哥哥走在前头；苏轼写“但愿人长久”正是怀念子由。作品记《黄州快哉亭记》，“快哉”二字由苏轼命名。","mix":"《六国论》苏洵、苏辙都写过，苏辙一篇论六国忽视韩魏；《赤壁赋》《记承天寺夜游》是苏轼，不是苏辙。","mcq":[{"q":"《黄州快哉亭记》的作者是","o":["苏洵","苏轼","曾巩","苏辙"],"a":3,"w":"《黄州快哉亭记》为苏辙所作。"}],"rel":[{"t":"三苏","n":"三苏之一"},{"t":"苏轼","n":"兄长"},{"t":"苏洵","n":"父亲，也作《六国论》"},{"t":"唐宋八大家","n":"八大家之一"}],"more":"生平：1039–1112，字子由，号颍滨遗老。\n作品：《黄州快哉亭记》《六国论》《上枢密韩太尉书》，文集《栾城集》","exam":[]},{"id":"z40-010","t":"曾巩","cid":"03h","p":2,"kind":"人物","alias":["曾子固","南丰先生","曾南丰"],"one":"北宋散文家，唐宋八大家之一，欧阳修门人，《墨池记》。","ans":"曾巩（1019–1083），字子固，建昌军南丰人，世称**南丰先生**，北宋散文家，**唐宋八大家之一**。他是欧阳修的门生，与王安石为好友，文章以儒家经学为根底，风格古雅平正，长于议论与记叙。代表作有《墨池记》，借王羲之墨池的旧迹，说明学问要靠勤学苦练；另有《越州赵公救灾记》，详记赵抃赈灾的措施。有文集《元丰类稿》。","pts":["北宋散文家，号南丰先生","欧阳修门人，唐宋八大家之一","《墨池记》《越州赵公救灾记》"],"mem":"八大家宋六家顺序“欧三苏，曾王”：欧阳修、苏洵、苏轼、苏辙、曾巩、王安石。曾巩在其中最不出名，抓两个标记：南丰（出生地，也是他的称号）和《墨池记》（王羲之洗笔的池子）。","mix":"王安石是曾巩的好友，同列八大家；《醉翁亭记》是欧阳修所作，《墨池记》不要张冠李戴。","mcq":[{"q":"下列作品中，作者是曾巩的是","o":["《醉翁亭记》","《墨池记》","《石钟山记》","《游褒禅山记》"],"a":1,"w":"《墨池记》为曾巩所作；《游褒禅山记》是王安石。"}],"rel":[{"t":"唐宋八大家","n":"八大家之一"},{"t":"欧阳修","n":"老师"},{"t":"王安石","n":"同乡好友，同列八大家"},{"t":"三苏","n":"同列八大家"}],"more":"生平：1019–1083，字子固，世称南丰先生。\n作品：《墨池记》《越州赵公救灾记》，文集《元丰类稿》","exam":[]},{"id":"z40-012","t":"黄庭坚","cid":"03h","p":2,"kind":"人物","alias":["黄山谷","山谷道人","黄鲁直","涪翁"],"one":"北宋诗人书法家，江西诗派开创者，“苏黄”之一，苏门四学士之首。","ans":"黄庭坚（1045–1105），字鲁直，号山谷道人，**洪州分宁（今江西修水）人**，北宋诗人、书法家。他是**苏门四学士之首**，与苏轼并称“**苏黄**”，是**江西诗派的开创者**，该派尊杜甫为“一祖”，黄庭坚、陈师道、陈与义为“三宗”。他提倡“**点铁成金**”“**夺胎换骨**”，主张学古而有变化；诗作如《登快阁》；书法列“**宋四家**”，有《松风阁诗帖》。","pts":["江西诗派开创者，苏门四学士之首","诗论：点铁成金、夺胎换骨","与苏轼并称“苏黄”；书法宋四家"],"mem":"“一祖三宗”记“杜甫领头，黄庭坚、陈师道、陈与义三人跟上”。诗论两个动作词：点铁成金像炼金，夺胎换骨像换魂，都是“用旧换新”。《登快阁》“落木千山天远大”是他诗中的名句。","mix":"“苏黄”指诗坛的苏轼、黄庭坚；书法“宋四家”是苏黄米蔡（苏轼、黄庭坚、米芾、蔡襄，另有蔡京一说）；“苏辛”则是苏轼与辛弃疾。","mcq":[{"q":"江西诗派“一祖三宗”中，“三宗”不包括","o":["黄庭坚","陈师道","陈与义","杜甫"],"a":3,"w":"杜甫是“一祖”，三宗为黄庭坚、陈师道、陈与义。"}],"rel":[{"t":"江西诗派“一祖三宗”","n":"他是开创者"},{"t":"苏黄","n":"与苏轼并称"},{"t":"苏门四学士","n":"四学士之首"},{"t":"黄庭坚与江西诗派","n":"诗论与流派"}],"more":"生平：1045–1105，字鲁直，号山谷道人。\n作品：《登快阁》，书法《松风阁诗帖》\n落木千山天远大，澄江一道月分明。｜《登快阁》","exam":[]},{"id":"z40-017","t":"岳飞","cid":"03h","p":2,"kind":"人物","alias":["岳武穆","岳鹏举","岳鄂王"],"one":"南宋抗金名将，相传《满江红·怒发冲冠》作者（有争议）。","ans":"岳飞（1103–1142），字鹏举，**相州汤阴人**，**南宋抗金名将**。他领导的岳家军屡败金兵，主张收复中原，后被宋高宗、秦桧以“莫须有”罪名杀害，孝宗时平反，谥武穆。他也能诗词，《**满江红·写怀**》中“三十功名尘与土，八千里路云和月”抒发壮志，是爱国词的名篇，但**作者归属学界有争议**；另有《小重山》。","pts":["南宋抗金名将，岳家军","被秦桧以“莫须有”害死","《满江红》作者有争议；《小重山》"],"mem":"一个画面：背上刺着“尽忠报国”的岳母故事，对应他的志向，再配“怒发冲冠，凭栏处”的《满江红》开头。数字：三十功名、八千里路，一个写年龄，一个写征程。","mix":"《满江红·怒发冲冠》作者有争议，有人认为是后人托名；辛弃疾、陆游也写抗金，但不是将领；“中兴四将”岳飞、韩世忠、张俊、刘光世。","mcq":[{"q":"“三十功名尘与土，八千里路云和月”出自《满江红》，传统上认为其作者是","o":["辛弃疾","陆游","文天祥","岳飞"],"a":3,"w":"该词传为岳飞所作，作者归属有争议。"}],"rel":[{"t":"靖康之变","n":"南宋建立的背景"},{"t":"辛弃疾","n":"同写抗金壮志"},{"t":"陆游","n":"同写收复中原"},{"t":"文天祥","n":"同为南宋忠烈"}],"more":"生平：1103–1142，字鹏举，抗金名将。\n作品：《满江红·写怀》（“怒发冲冠”，作者有争议）《小重山》\n三十功名尘与土，八千里路云和月。｜《满江红》","exam":[]},{"id":"z40-019","t":"辛弃疾","cid":"03h","p":1,"kind":"人物","exam":["2026名解"],"alias":["稼轩","辛稼轩","辛幼安","幼安"],"one":"南宋豪放派词人，号稼轩，爱国词人，与苏轼并称“苏辛”。","ans":"辛弃疾（1140–1207），**字幼安，号稼轩，济南历城人，南宋词人**。他出生时北方已沦于金，二十余岁起义，率众投奔耿京，后南归。他是**豪放派集大成者**，**“以文为词”**，大量用典、入议论，词多抒**抗金收复之志与壮志难酬之愤**，代表作**《永遇乐·京口北固亭怀古》《破阵子·为陈同甫赋壮词以寄之》《青玉案·元夕》《西江月·夜行黄沙道中》**，词集《稼轩长短句》。他与苏轼并称**“苏辛”**，与李清照并称“济南二安”，被誉为“词中之龙”。","pts":["字幼安，号稼轩，济南人，抗金南归","豪放派集大成，以文为词","永遇乐、破阵子、青玉案；稼轩长短句"],"mem":"题材三字诀“战、情、田”：战（《破阵子》醉里挑灯看剑）、情（《青玉案·元夕》众里寻他千百度）、田（《西江月》稻花香里说丰年），再加怀古（《永遇乐》）。“稼轩”得名于他在带湖建的住所，“稼”是庄稼，号里就带着田园气。","mix":"辛弃疾与李清照同为济南人，合称“济南二安”（幼安、易安）；京口北固亭有两首名作：《永遇乐》（“英雄无觅孙仲谋处”“廉颇老矣”）和《南乡子》（“生子当如孙仲谋”），别混。","mcq":[{"q":"“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”出自","o":["《永遇乐·京口北固亭怀古》","《破阵子》","《青玉案·元夕》","《西江月·夜行黄沙道中》"],"a":2,"w":"出自辛弃疾《青玉案·元夕》。"},{"q":"“济南二安”指","o":["柳永与李清照","苏轼与辛弃疾","辛弃疾与陆游","李清照与辛弃疾"],"a":3,"w":"易安居士李清照与稼轩（字幼安）辛弃疾，同为济南人。"}],"rel":[{"t":"苏辛","n":"与苏轼并称"},{"t":"辛弃疾代表作","n":"代表作汇总"},{"t":"济南二安","n":"与李清照并称"},{"t":"辛派词人","n":"追随者"},{"t":"岳飞","n":"同为抗金志士"}],"more":"众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。｜《青玉案·元夕》\n想当年，金戈铁马，气吞万里如虎。｜《永遇乐》\n醉里挑灯看剑，梦回吹角连营。｜《破阵子》\n稻花香里说丰年，听取蛙声一片。｜《西江月》\n少年不识愁滋味，爱上层楼。｜《丑奴儿》\n天下英雄谁敌手？曹刘。生子当如孙仲谋。｜《南乡子》"},{"id":"z40-020","t":"杨万里","cid":"03h","p":2,"kind":"人物","alias":["杨诚斋","诚斋","杨廷秀"],"one":"南宋诗人，中兴四大诗人之一，创“诚斋体”，《小池》作者。","ans":"杨万里（1127–1206），字廷秀，号诚斋，**吉州吉水人**，南宋诗人，与陆游、范成大、尤袤合称“**中兴四大诗人**”。他的诗善于描写自然景物，语言口语化，富于幽默和情趣，世称“**诚斋体**”，又称“活法”。代表作有《小池》“小荷才露尖尖角，早有蜻蜓立上头”，《晓出净慈寺送林子方》“接天莲叶无穷碧，映日荷花别样红”，都是**七言绝句**中描绘荷花的名篇。","pts":["南宋诗人，号诚斋，创诚斋体","中兴四大诗人之一","《小池》《晓出净慈寺送林子方》"],"mem":"两首都写荷：《小池》是“小荷”刚露角，蜻蜓来立；《晓出净慈寺》是“莲叶”铺满、荷花映红。一首写初夏，一首写盛夏。“诚斋体”记“活”：看到什么写什么，像说话一样。","mix":"“中兴四大诗人”通行为陆游、杨万里、范成大、尤袤，另有以萧德藻代尤袤之说；范成大写田园，陆游写爱国，杨万里写自然小景。","mcq":[{"q":"“接天莲叶无穷碧，映日荷花别样红”的作者是","o":["范成大","陆游","杨万里","姜夔"],"a":2,"w":"出自杨万里《晓出净慈寺送林子方》。"}],"rel":[{"t":"中兴四大诗人","n":"四人之一"},{"t":"陆游","n":"同属中兴四大诗人"},{"t":"范成大","n":"同属中兴四大诗人"},{"t":"宋诗特点：以文字为诗、以议论为诗、以才学为诗","n":"宋诗的风格对照"}],"more":"生平：1127–1206，字廷秀，号诚斋。\n作品：《小池》《晓出净慈寺送林子方》，诗集《诚斋集》\n小荷才露尖尖角，早有蜻蜓立上头。｜《小池》\n接天莲叶无穷碧，映日荷花别样红。｜《晓出净慈寺送林子方》","exam":[]},{"id":"z40-021","t":"范成大","cid":"03h","p":2,"kind":"人物","alias":["范石湖","石湖居士","范至能"],"one":"南宋诗人，中兴四大诗人之一，《四时田园杂兴》集古代田园诗大成。","ans":"范成大（1126–1193），字至能，号石湖居士，**平江吴县人**，南宋诗人，与陆游、杨万里、尤袤合称“**中兴四大诗人**”。他晚年退居石湖，写成**《四时田园杂兴》六十首**，分春日、晚春、夏日、秋日、冬日五组，既写农村风光，也写农民受赋税压迫的辛苦，被誉为**古代田园诗的集大成之作**。名句如“昼出耘田夜绩麻，村庄儿女各当家”。他还出使金国，有使金纪行诗。","pts":["南宋诗人，号石湖居士","《四时田园杂兴》六十首","古代田园诗集大成；中兴四大诗人"],"mem":"六十首＝五组×十二首（春、晚春、夏、秋、冬），可记“五季各十二”。陶渊明开田园诗，王维孟浩然写山水田园，到范成大把农家劳动与赋税之苦写进来，是“集大成”。","mix":"陶渊明是田园诗的开创者，范成大是集大成者；杨万里重自然小景，陆游重爱国，三人不要混。","mcq":[{"q":"《四时田园杂兴》六十首的作者是","o":["杨万里","范成大","陆游","陶渊明"],"a":1,"w":"范成大作，被誉为古代田园诗集大成。"}],"rel":[{"t":"中兴四大诗人","n":"四人之一"},{"t":"杨万里","n":"同属四大诗人"},{"t":"陆游","n":"同属四大诗人"},{"t":"山水田园诗派","n":"田园诗传统对照"}],"more":"生平：1126–1193，字至能，号石湖居士。\n作品：《四时田园杂兴》六十首，《石湖居士诗集》\n昼出耘田夜绩麻，村庄儿女各当家。｜《四时田园杂兴》","exam":[]},{"id":"z40-024","t":"文天祥","cid":"03h","p":2,"kind":"人物","alias":["文山","文宋瑞","文丞相"],"one":"南宋末抗元名臣，《过零丁洋》《正气歌》作者，以气节收束宋诗。","ans":"文天祥（1236–1283），字宋瑞，号文山，**吉州庐陵人**，宝祐四年状元，**南宋末抗元名臣**。他组织义军抗击元军，兵败被俘，**拒不投降**，最终在大都就义。《过零丁洋》“人生自古谁无死？留取丹心照汗青”表明心志，《**正气歌**》“天地有正气，杂然赋流形”歌颂浩然正气，二者是以**气节**著称的宋末诗歌代表。另有《指南录后序》。","pts":["南宋末状元，抗元被俘不降","《过零丁洋》：留取丹心照汗青","《正气歌》：天地有正气"],"mem":"两首诗两句话：《过零丁洋》“留取丹心照汗青”是回答劝降，《正气歌》“天地有正气”是狱中自勉。宋末“三杰”：文天祥、陆秀夫、张世杰。","mix":"辛弃疾、陆游、岳飞也写抗金，文天祥抗的是元；《过零丁洋》“惶恐滩头说惶恐，零丁洋里叹零丁”的地名是双关。","mcq":[{"q":"“人生自古谁无死？留取丹心照汗青”的作者是","o":["岳飞","陆游","辛弃疾","文天祥"],"a":3,"w":"出自文天祥《过零丁洋》。"}],"rel":[{"t":"岳飞","n":"同为南宋忠烈"},{"t":"陆游","n":"同写家国之志"},{"t":"辛弃疾","n":"同写抗敌壮志"},{"t":"于谦《石灰吟》","n":"明代同类气节诗"}],"more":"生平：1236–1283，字宋瑞，号文山。\n作品：《过零丁洋》《正气歌》《指南录后序》\n人生自古谁无死？留取丹心照汗青。｜《过零丁洋》\n天地有正气，杂然赋流形。｜《正气歌》","exam":[]},{"id":"z40-025","t":"叶绍翁","cid":"03h","p":3,"kind":"人物","alias":["叶嗣宗","靖逸"],"one":"南宋江湖诗派诗人，代表作《游园不值》传诵千古。","ans":"叶绍翁，字嗣宗，建安人，**南宋江湖派诗人**。长期隐居钱塘，诗多写西湖风物与闲适幽趣。代表作为**七绝名篇《游园不值》**，诗中“**春色满园关不住，一枝红杏出墙来**”蕴含深刻理趣与勃勃生机，千古传诵，为**宋诗咏春景物的经典代表**。","pts":["南宋江湖诗派诗人，字嗣宗","代表作七绝《游园不值》","名句“春色满园关不住，一枝红杏出墙来”"],"mem":"名句挂钩：**叶绍翁＝《游园不值》＝红杏出墙**。注意其所属诗派为**南宋江湖诗派**。","mix":"常有人将《游园不值》误记为唐诗，实为南宋江湖派诗人叶绍翁所作；诗题“不值”意为未遇到主人。","mcq":[{"q":"传诵千古的名句“春色满园关不住，一枝红杏出墙来”出自南宋诗人叶绍翁的","o":["《游园不值》","《钱塘湖春行》","《春日》","《绝句》"],"a":0,"w":"叶绍翁代表作为七言绝句《游园不值》，诗题意为游园未遇到主人。"}],"rel":[{"t":"江湖诗派","n":"所属诗歌流派"},{"t":"陆游","n":"同时代南宋诗人"},{"t":"林逋","n":"西湖隐逸诗人前后对照"}],"more":"名句：应怜屐齿印苍苔，小扣柴扉久不开。春色满园关不住，一枝红杏出墙来。｜《游园不值》","exam":[]},{"id":"z40-026","t":"林逋","cid":"03h","p":3,"kind":"人物","alias":["林和靖","和靖先生"],"one":"北宋隐逸诗人，隐居西湖孤山，人称“梅妻鹤子”，谥和靖先生。","ans":"林逋（967–1028），字君复，钱塘人，**北宋隐逸诗人**，谥和靖先生。他终身不娶不仕，隐居西湖孤山，世称“**梅妻鹤子**”。诗风淡泊超逸，代表作**律诗《山园小梅》**留有名句“**疏影横斜水清浅，暗香浮动月黄昏**”，成为**古今咏梅绝唱**。","pts":["北宋隐逸诗人，谥和靖先生","隐居西湖孤山，人称“梅妻鹤子”","《山园小梅》“疏影横斜水清浅，暗香浮动月黄昏”"],"mem":"名胜意象联想：**孤山＋梅花＋白鹤＝林逋（林和靖）**。千古名句“**疏影横斜水清浅，暗香浮动月黄昏**”。","mix":"林逋是北宋初年人，并非南宋人；南宋姜夔自度词牌《暗香》《疏影》即化用林逋此诗句。","mcq":[{"q":"隐居杭州西湖孤山、人称“梅妻鹤子”并写下“疏影横斜水清浅，暗香浮动月黄昏”的北宋诗人是","o":["苏轼","林逋","王安石","黄庭坚"],"a":1,"w":"林逋（林和靖）以“梅妻鹤子”著称，《山园小梅》为咏梅名作。"}],"rel":[{"t":"姜夔","n":"受其诗启发创《暗香》"},{"t":"苏轼","n":"西湖文人后贤"},{"t":"北宋诗文革新运动","n":"北宋前期文坛背景"}],"more":"名句：疏影横斜水清浅，暗香浮动月黄昏。｜《山园小梅》","exam":[]},{"id":"c-026","t":"三苏","cid":"03h","p":2,"kind":"合称","alias":["三苏","苏氏父子"],"one":"苏洵、苏轼、苏辙父子三人，同列唐宋八大家，眉州眉山人。","ans":"三苏指**北宋眉州眉山人苏洵、苏轼、苏辙父子三人**。父苏洵长于政论，代表作《六国论》；次子苏轼（长兄景先早夭）诗文书画词俱佳，是**宋代文学最高成就的代表**，有《赤壁赋》《水调歌头》；三子苏辙文风汪洋澹泊，有《黄州快哉亭记》。三人同列**唐宋八大家**，在八大家中占三席，是宋代文坛上罕见的**一门三家**，其中苏轼影响最大。","pts":["苏洵、苏轼、苏辙，眉州眉山人","同列唐宋八大家，占三席","各自代表作：六国论、赤壁赋、快哉亭记"],"members":[["苏洵","《六国论》；号老泉"],["苏轼","《赤壁赋》《水调歌头》；字子瞻"],["苏辙","《黄州快哉亭记》；字子由"]],"mem":"“老苏”苏洵、“大苏”苏轼、“小苏”苏辙。八大家口诀“韩柳欧三苏曾王”，中间“三苏”就是这三位。字：子瞻、子由两兄弟，洵字明允。","mix":"“三苏”是父子，不要与“苏黄”（苏轼与黄庭坚）、“苏辛”（苏轼与辛弃疾）混；苏小妹是后世传说，不是史实。","mcq":[{"q":"下列关于“三苏”的说法，正确的是","o":["指苏轼、苏辙、苏舜钦","指苏洵、苏轼、苏辙","指苏轼、黄庭坚、秦观","指苏洵、苏轼、苏小妹"],"a":1,"w":"三苏为北宋苏洵及其二子苏轼、苏辙。"}],"rel":[{"t":"苏轼","n":"长子，成就最高"},{"t":"苏洵","n":"父亲"},{"t":"苏辙","n":"次子"},{"t":"唐宋八大家","n":"三人同列其中"}],"more":"“三苏祠”位于四川眉山。","exam":[]},{"id":"c-028","t":"苏门四学士","cid":"03h","p":2,"kind":"合称","alias":["苏门四学士","苏门学士"],"one":"黄庭坚、秦观、晁补之、张耒，受苏轼奖掖的四位文人。","ans":"苏门四学士指**受苏轼赏识提携的四位北宋文人：黄庭坚、秦观、晁补之、张耒**。四人早年均出入苏轼门下，在文学上各有所长：黄庭坚长于诗，开**江西诗派**；秦观长于词，是**婉约词的代表**；晁补之、张耒擅长诗文。在四学士之外加上陈师道、李廌，则称“**苏门六君子**”。四人的成就体现了苏轼对北宋文坛的影响。","pts":["黄庭坚、秦观、晁补之、张耒","黄诗、秦词各成一派","加陈师道、李廌为苏门六君子"],"members":[["黄庭坚","江西诗派开创者，四学士之首"],["秦观","婉约词人，《鹊桥仙》"],["晁补之","诗文兼擅"],["张耒","诗文兼擅"]],"mem":"首字串联“黄秦晁张”，谐音“黄琴朝张”，黄庭坚领头。六君子再加“陈李”：陈师道、李廌，“四学士+陈李＝六君子”。","mix":"“苏门四学士”是苏轼的学生与追随者，“苏黄”是苏轼与黄庭坚，两个概念不同；秦观、周邦彦的“秦周”则是婉约词的对举。","mcq":[{"q":"下列人物中，不属于“苏门四学士”的是","o":["黄庭坚","秦观","陈师道","张耒"],"a":2,"w":"陈师道属“苏门六君子”，不在四学士之列。"}],"rel":[{"t":"苏门六君子","n":"加两人即六君子"},{"t":"黄庭坚","n":"四学士之首"},{"t":"秦观","n":"婉约词代表"},{"t":"苏轼","n":"他们的老师"}],"more":"苏门六君子：四学士加陈师道、李廌。","exam":[]},{"id":"c-029","t":"苏黄","cid":"03h","p":2,"kind":"合称","alias":["苏黄"],"one":"苏轼与黄庭坚，北宋诗坛的两位代表，黄为江西诗派开创者。","ans":"苏黄指**北宋诗人苏轼与黄庭坚**，是北宋诗坛的两位代表。苏轼诗清新豪健，善用比喻与议论，如《饮湖上初晴后雨》《题西林壁》；黄庭坚是苏门四学士之首，**开创江西诗派**，主张“点铁成金”“夺胎换骨”，诗风**瘦硬生新**。二人相互推重，在书法上又与米芾、蔡襄合称“宋四家”。“苏黄”体现了宋诗在苏轼之后由自然流畅转向锤炼字句的发展。","pts":["苏轼、黄庭坚，北宋诗坛代表","黄庭坚开创江西诗派","书法同列宋四家"],"members":[["苏轼","诗风清新豪健，主盟北宋文坛"],["黄庭坚","江西诗派开创者，诗风瘦硬生新"]],"mem":"对比记“苏流黄瘦”：苏轼的诗像流水，自然奔放；黄庭坚的诗像瘦骨，硬朗生新，字句都经过锤炼。“苏黄”写诗，“苏辛”写词，“苏米黄蔡”写字，三个“苏”的搭档不同。","mix":"“苏辛”是苏轼与辛弃疾，指豪放词；“三苏”是苏洵、苏轼、苏辙；书法“宋四家”的通行顺序是苏黄米蔡。","mcq":[{"q":"“苏黄”中的“黄”指","o":["黄庭坚","黄遵宪","黄仲则","黄宗羲"],"a":0,"w":"“苏黄”指北宋诗人苏轼与黄庭坚。"}],"rel":[{"t":"苏轼","n":"苏黄之一"},{"t":"黄庭坚","n":"苏黄之一，江西诗派开创者"},{"t":"苏辛","n":"苏轼与辛弃疾，写词"},{"t":"江西诗派“一祖三宗”","n":"黄庭坚所开诗派"}],"more":"书法“宋四家”：苏轼、黄庭坚、米芾、蔡襄。","exam":[]},{"id":"c-030","t":"济南二安","cid":"03h","p":2,"kind":"合称","alias":["济南二安","二安"],"one":"李清照（号易安）与辛弃疾（字幼安），同为济南人的两大词人。","ans":"济南二安指**李清照与辛弃疾**，两人都是**济南人**，李清照号易安居士，辛弃疾字幼安，各有一个“安”字，故名。李清照是**婉约派**代表，早期词清丽，南渡后转为凄婉，《声声慢》《如梦令》最有名，她还提出“词别是一家”；辛弃疾是**豪放派**代表，与苏轼并称“苏辛”，《破阵子》《永遇乐·京口北固亭怀古》抒写抗金壮志。二人代表了**宋词婉约与豪放两路的最高成就**。","pts":["李清照（号易安）与辛弃疾（字幼安）","同为济南人，各取一“安”","婉约与豪放两派的代表"],"members":[["李清照","号易安居士，婉约派，《声声慢》"],["辛弃疾","字幼安，号稼轩，豪放派，《破阵子》"]],"mem":"“二安”＝易安＋幼安。一句话分工：易安写“寻寻觅觅”，幼安写“醉里挑灯看剑”，一个婉约一个豪放，却同出济南。","mix":"“苏辛”是苏轼与辛弃疾；“二晏”是晏殊、晏几道；“济南二安”不要和“南唐二主”这类帝王合称混淆。","mcq":[{"q":"“济南二安”指的是","o":["晏殊与晏几道","苏轼与辛弃疾","李清照与辛弃疾","李煜与李璟"],"a":2,"w":"李清照号易安，辛弃疾字幼安，均为济南人。"}],"rel":[{"t":"李清照","n":"二安之一，婉约"},{"t":"辛弃疾","n":"二安之一，豪放"},{"t":"苏辛","n":"豪放词对举"},{"t":"婉约派与豪放派","n":"两派代表"}],"more":"李清照出生于济南章丘，辛弃疾出生于济南历城。","exam":[]},{"id":"c-031","t":"中兴四大诗人","cid":"03h","p":1,"kind":"合称","alias":["南宋四大诗人","尤杨范陆","南宋中兴四大诗人"],"one":"南宋孝宗时期四位诗人：尤袤、杨万里、范成大、陆游。","ans":"中兴四大诗人指**南宋孝宗时期的四位诗人尤袤、杨万里、范成大、陆游**，也称“南宋四大诗人”“尤杨范陆”。**陆游**存诗近万首，以爱国诗最著，有《剑南诗稿》；**杨万里**自创活泼口语的**“诚斋体”**；**范成大**以《四时田园杂兴》六十首著称，是田园诗集大成者；**尤袤**存诗不多。四人上承北宋，不满江西诗派的掉书袋，转向写现实与自然，代表南宋诗歌的成就，其中陆游成就最高。","pts":["尤袤、杨万里、范成大、陆游","陆游爱国诗，杨万里诚斋体，范成大田园诗","矫江西诗派之弊，陆游最高"],"members":[["尤袤","存诗不多"],["杨万里","“诚斋体”，活泼口语，《晓出净慈寺送林子方》"],["范成大","《四时田园杂兴》六十首"],["陆游","近万首，爱国诗，《剑南诗稿》"]],"mem":"口诀“尤杨范陆”，一人一个标签：尤（存诗最少）、杨（诚斋体）、范（《四时田园杂兴》）、陆（近万首、爱国）。顺序按通行说法，不代表成就高低，成就最高的陆游排在最后。","mix":"也有以萧德藻代替尤袤之说，以尤杨范陆为通行；与“元曲四大家”“唐宋八大家”等数目合称区分；“诚斋体”属杨万里，“放翁”是陆游的号。","mcq":[{"q":"下列诗人中，不属于“中兴四大诗人”的是","o":["辛弃疾","陆游","范成大","杨万里"],"a":0,"w":"辛弃疾是词人，中兴四大诗人是尤袤、杨万里、范成大、陆游。"},{"q":"“诚斋体”的创立者是","o":["范成大","尤袤","陆游","杨万里"],"a":3,"w":"杨万里号诚斋，其诗称“诚斋体”。"}],"rel":[{"t":"陆游","n":"四人之一"},{"t":"杨万里","n":"四人之一"},{"t":"范成大","n":"四人之一"},{"t":"江西诗派“一祖三宗”","n":"他们所矫正的诗风"},{"t":"永嘉四灵","n":"南宋另一诗人群"}],"exam":[]},{"id":"b03-013","t":"元杂剧与元曲四大家","cid":"03i","p":1,"kind":"合称","exam":["2020选择","2021选择","2022选择","2024选择","2026选择"],"alias":["元杂剧","元曲四大家","关马郑白"],"one":"元杂剧一本四折，一人主唱；元曲四大家为关汉卿、马致远、郑光祖、白朴。","ans":"元杂剧是**元代成熟的戏曲形式**，与散曲合称“元曲”。体制上**一般一本四折，可加楔子，用北曲演唱，一人主唱（旦本或末本）**，由唱、科（动作）、白（宾白）组成。**元曲四大家指关汉卿、马致远、郑光祖、白朴**，简称“关马郑白”，代表作分别是《窦娥冤》《汉宫秋》《倩女离魂》《梧桐雨》。王实甫《西厢记》、纪君祥《赵氏孤儿》也是名作，但不在四大家之列。元杂剧**标志中国戏曲的成熟**，与唐诗、宋词并称一代文学之胜。","pts":["元代戏曲，一本四折，北曲，唱科白","关马郑白及其代表作","戏曲成熟的标志"],"members":[["关汉卿","《窦娥冤》《救风尘》《单刀会》《拜月亭》；自称“铜豌豆”"],["马致远","《汉宫秋》；散曲《天净沙·秋思》"],["郑光祖","《倩女离魂》"],["白朴","《梧桐雨》《墙头马上》"]],"mem":"通行口诀“关马郑白”，剧名接力：关家窦娥喊冤，马家汉宫望秋，郑家倩女离魂，白家梧桐听雨。体制口诀“四折一人唱，北曲唱科白”，对比明清传奇“数十出，众人唱”。","mix":"元代周德清原文作“关郑白马”，通行说法是“关马郑白”；王实甫《西厢记》五本二十一折，突破四折与一人主唱的体例，不在四大家之列；纪君祥《赵氏孤儿》也不在其中。","mcq":[{"q":"下列作家中，不属于“元曲四大家”的是","o":["关汉卿","白朴","纪君祥","郑光祖"],"a":2,"w":"四大家是关汉卿、马致远、郑光祖、白朴，纪君祥作《赵氏孤儿》，不在其列。"},{"q":"元杂剧一本通常的折数是","o":["两折","三折","五折","四折"],"a":3,"w":"元杂剧一般一本四折，可加楔子。"}],"rel":[{"t":"关汉卿","n":"四大家之首"},{"t":"王实甫","n":"常作干扰项"},{"t":"散曲","n":"与杂剧合称元曲"},{"t":"元杂剧四大悲剧","n":"代表剧目"},{"t":"世界三大古老戏剧","n":"中外戏剧对照"}],"more":"周德清《中原音韵》：关郑白马，一新制作。"},{"id":"b03-014","t":"《西厢记》","cid":"03i","p":1,"kind":"作品","alias":["西厢记","崔莺莺待月西厢记","王西厢"],"one":"王实甫的元杂剧，写张生与崔莺莺，五本二十一折，“愿普天下有情的都成了眷属”。","ans":"《西厢记》全称《崔莺莺待月西厢记》，是**元代王实甫创作的杂剧**。故事**源于唐代元稹的传奇《莺莺传》**，经金代董解元《西厢记诸宫调》改编，写书生**张生与相国千金崔莺莺在红娘帮助下冲破礼教阻挠自由相爱**的故事。全剧**五本二十一折**，突破元杂剧一本四折的体例，曲词华美，结尾点明主题**“愿普天下有情的都成了眷属”**。它是中国古典爱情戏的代表，被誉为“天下夺魁”，对明清戏曲和小说中的爱情描写影响很大。","pts":["元代王实甫杂剧","源于元稹《莺莺传》，张生与崔莺莺","五本二十一折，反对礼教"],"mem":"故事接力三个人：元稹《莺莺传》（唐，负心结局）→董解元《西厢记诸宫调》（金，改团圆）→王实甫《西厢记》（元）。画面：普救寺，张生跳墙，红娘传书。","mix":"《莺莺传》是唐传奇（元稹），《西厢记》是元杂剧（王实甫），《牡丹亭》是明传奇（汤显祖）；王实甫不在元曲四大家之列；《西厢记》突破一本四折和一人主唱的体制。","mcq":[{"q":"《西厢记》故事最早的源头是唐代的","o":["《李娃传》","《霍小玉传》","《柳毅传》","《莺莺传》"],"a":3,"w":"《西厢记》源于元稹《莺莺传》。"},{"q":"关于《西厢记》，下列说法正确的是","o":["作者是关汉卿","共五本二十一折","属于明代传奇","主人公是柳梦梅"],"a":1,"w":"《西厢记》为王实甫所作，五本二十一折。"}],"rel":[{"t":"王实甫","n":"作者"},{"t":"董解元《西厢记诸宫调》","n":"直接前身"},{"t":"唐传奇名篇：《莺莺传》《李娃传》《柳毅传》","n":"故事源头"},{"t":"元杂剧四大爱情剧","n":"所属合称"},{"t":"《罗密欧与朱丽叶》","n":"中西爱情剧对照"}],"more":"愿普天下有情的都成了眷属。｜《西厢记》\n碧云天，黄花地，西风紧，北雁南飞。晓来谁染霜林醉？总是离人泪。｜《西厢记·长亭送别》","exam":[]},{"id":"b03-015","t":"散曲","cid":"03i","p":1,"kind":"概念","alias":["散曲"],"one":"元代兴起的配乐清唱新诗体，无科白，分小令与套数，与杂剧合称元曲。","ans":"散曲是**元代兴起的可配乐清唱的新诗体**，与杂剧合称“元曲”。它**没有科白和故事情节，只用于抒情、写景或叙事**，体式分**小令（单支曲子）和套数（同一宫调的若干支曲子连成一套）**。语言通俗活泼，多用衬字，贴近口语。代表作家有关汉卿、马致远、张养浩，名作有**马致远《天净沙·秋思》、张养浩《山坡羊·潼关怀古》**，关汉卿有套数《不伏老》。散曲继词之后成为新兴诗体，语言更贴近民间，后期乔吉、张可久走向清丽典雅。","pts":["元代配乐清唱诗体，与杂剧合称元曲","小令与套数，无科白","马致远、张养浩、关汉卿"],"mem":"杂剧=“散曲＋故事（科白）”，散曲就是“只唱不演”的那部分。小令像单曲，套数像一张专辑（一串同宫调的曲子）。名作配人：秋思配马致远，潼关怀古配张养浩，不伏老配关汉卿。","mix":"散曲无科白，杂剧有；曲牌（如“天净沙”）和题目（“秋思”）要分开；“小令”在词中指短调，在曲中指单支曲子，含义不同。","mcq":[{"q":"关于散曲，下列说法正确的是","o":["含有科白和故事情节","盛行于宋代","只能用于叙事","分为小令与套数"],"a":3,"w":"散曲没有科白，分小令与套数，兴起于元代。"},{"q":"“兴，百姓苦；亡，百姓苦”出自","o":["马致远《天净沙·秋思》","张养浩《山坡羊·潼关怀古》","关汉卿《不伏老》","白朴《沉醉东风·渔夫》"],"a":1,"w":"出自张养浩《山坡羊·潼关怀古》。"}],"rel":[{"t":"小令、中调、长调与慢词","n":"词里的小令不同"},{"t":"张养浩","n":"散曲名家"},{"t":"马致远《天净沙·秋思》","n":"散曲名篇"},{"t":"曲牌与宫调","n":"散曲格式"},{"t":"“乔张”：乔吉与张可久","n":"清丽派散曲家"}],"more":"峰峦如聚，波涛如怒，山河表里潼关路。……兴，百姓苦；亡，百姓苦。｜张养浩《山坡羊·潼关怀古》\n枯藤老树昏鸦，小桥流水人家，古道西风瘦马。｜马致远《天净沙·秋思》","exam":[]},{"id":"b03-023","t":"马致远《天净沙·秋思》","cid":"03i","p":1,"kind":"作品","exam":["2024选择"],"alias":["天净沙·秋思","秋思之祖","天净沙秋思"],"one":"马致远的散曲小令，“枯藤老树昏鸦”，被誉为“秋思之祖”。","ans":"《天净沙·秋思》是**元代马致远所作散曲小令**，**天净沙为曲牌，秋思为题目**。全曲仅28字，前三句由九个名词意象并置而成，几乎不用动词，**末以“夕阳西下，断肠人在天涯”点出游子的羁旅愁思**，以景起，以情结。周德清《中原音韵》誉之为**“秋思之祖”**，是元曲小令的代表作，也是**意象并置**写法的典范。它属散曲，不是杂剧。","pts":["元代马致远散曲小令，天净沙为曲牌","28字，意象并置，景起情结","秋思之祖；不是杂剧"],"mem":"口诀“三三三一人”：三句各三个物象（枯藤老树昏鸦；小桥流水人家；古道西风瘦马），一个夕阳，一个断肠人。前三句全是名词，没有动词，最后才点出人。","mix":"天净沙是曲牌，秋思是题目；马致远的杂剧代表作是《汉宫秋》，《天净沙·秋思》是散曲小令；同曲牌还有白朴《天净沙·秋》。","mcq":[{"q":"《天净沙·秋思》的体裁是","o":["杂剧","词","散曲小令","传奇"],"a":2,"w":"属元代散曲中的小令。"},{"q":"“枯藤老树昏鸦”的作者是","o":["关汉卿","白朴","郑光祖","马致远"],"a":3,"w":"出自马致远《天净沙·秋思》。"}],"rel":[{"t":"马致远","n":"作者"},{"t":"散曲","n":"所属文体"},{"t":"曲牌与宫调","n":"天净沙为曲牌"},{"t":"元杂剧与元曲四大家","n":"马致远为四大家之一"},{"t":"周德清《中原音韵》与钟嗣成《录鬼簿》","n":"“秋思之祖”出处"}],"more":"枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯。"},{"id":"b03-024","t":"关汉卿“铜豌豆”","cid":"03i","p":1,"kind":"作品","exam":["2026选择"],"alias":["铜豌豆","不伏老","一枝花·不伏老","南吕·一枝花·不伏老"],"one":"关汉卿散曲套数《南吕·一枝花·不伏老》，自比“一粒铜豌豆”。","ans":"“铜豌豆”出自**关汉卿的散曲套数《南吕·一枝花·不伏老》**，**南吕为宫调，一枝花为曲牌，不伏老为题目**。作者在曲中自称**“我是个蒸不烂煮不熟捶不匾炒不爆响珰珰一粒铜豌豆”**，以铜豌豆比喻自己坚韧倔强、不受世俗束缚的性格，并宣称**至死不离风月场、不向衰老屈服**。这是关汉卿**自我写照**的名篇，语言泼辣豪放，通俗尖新，体现元代书会才人的生活与反抗精神。它是散曲套数，不是杂剧剧名。","pts":["关汉卿散曲套数《南吕·一枝花·不伏老》","自比蒸不烂煮不熟的铜豌豆","自我写照，倔强不屈；非杂剧"],"mem":"口诀“蒸煮捶炒”：蒸不烂，煮不熟，捶不扁，炒不爆，四个动作都拿它没办法，最后“响珰珰”一声，铜豌豆敲在锅上。结论：铜豌豆是关汉卿本人，不是哪一部杂剧。","mix":"“铜豌豆”不是杂剧名，《窦娥冤》《救风尘》《单刀会》《拜月亭》才是关汉卿的杂剧；《一枝花》是曲牌，南吕是宫调，《不伏老》是题目；它是套数，不是小令。","mcq":[{"q":"关汉卿以“铜豌豆”自喻，出自","o":["《救风尘》","《窦娥冤》","《单刀会》","《南吕·一枝花·不伏老》"],"a":3,"w":"出自散曲套数《南吕·一枝花·不伏老》。"},{"q":"《不伏老》的体裁是","o":["杂剧","散曲套数","散曲小令","诸宫调"],"a":1,"w":"《南吕·一枝花·不伏老》是散曲套数。"}],"rel":[{"t":"关汉卿","n":"作者"},{"t":"散曲","n":"所属文体"},{"t":"曲牌与宫调","n":"南吕、一枝花"},{"t":"《窦娥冤》","n":"关汉卿杂剧代表作"},{"t":"元杂剧与元曲四大家","n":"四大家之首"}],"more":"我是个蒸不烂煮不熟捶不匾炒不爆响珰珰一粒铜豌豆。｜《南吕·一枝花·不伏老》"},{"id":"b03-052","t":"张养浩","cid":"03i","p":2,"kind":"人物","alias":["张云庄","张希孟","云庄"],"one":"元代散曲家，《山坡羊·潼关怀古》作者，“兴，百姓苦；亡，百姓苦”。","ans":"张养浩（1270–1329），字希孟，号云庄，**济南人**，**元代散曲家**。官至礼部尚书，晚年辞官归隐，天历二年（1329）关中大旱，被起用为陕西行台中丞，赴任赈灾，积劳病逝。**《山坡羊·潼关怀古》**是赴陕途经潼关时所作，结句“**兴，百姓苦；亡，百姓苦**”指出无论朝代兴亡，受苦的始终是百姓，是**元散曲怀古咏史的名篇**。有散曲集《云庄休居自适小乐府》。","pts":["元代散曲家，号云庄，济南人","《山坡羊·潼关怀古》","兴，百姓苦；亡，百姓苦"],"mem":"一句话记结论：兴也苦，亡也苦，“百姓”是主语。对照马致远《天净沙·秋思》：马写游子的愁，张写百姓的苦，一个是个人，一个是天下。","mix":"《山坡羊·潼关怀古》是张养浩的作品，不是马致远的；全曲写秦汉兴亡的怀古，主旨落在百姓之苦。","mcq":[{"q":"“兴，百姓苦；亡，百姓苦”出自","o":["张养浩《山坡羊·潼关怀古》","马致远《天净沙·秋思》","关汉卿《不伏老》","白朴《天净沙·秋》"],"a":0,"w":"该句是张养浩《山坡羊·潼关怀古》的结句。"}],"rel":[{"t":"散曲","n":"所属文体"},{"t":"马致远","n":"另一散曲名家"},{"t":"《汉宫秋》与《梧桐雨》","n":"同属元曲"},{"t":"“乔张”：乔吉与张可久","n":"散曲家合称，注意区分"}],"more":"《山坡羊·潼关怀古》：峰峦如聚，波涛如怒，山河表里潼关路。望西都，意踌躇。伤心秦汉经行处，宫阙万间都做了土。兴，百姓苦；亡，百姓苦。","exam":[]},{"id":"b03-062","t":"元好问","cid":"03i","p":3,"kind":"人物","alias":["元遗山","元裕之"],"one":"金元之际著名文学家，世称遗山先生，词作《雁丘词》传诵千古。","ans":"元好问（1190–1257），字裕之，**号遗山**，**金代文学集大成者**。其诗文沉郁悲壮，以诗记金亡历史被称为“**诗史**”；《论诗三十首》开绝句论诗先河。代表词作**《摸鱼儿·雁丘词》**以“**问世间，情是何物，直教生死相许**”传诵千古。","pts":["金代文学集大成者，号遗山","词作《雁丘词》“问世间，情是何物”","以诗记金亡历史称诗史，《论诗三十首》"],"mem":"金句挂钩：**“问世间，情是何物，直教生死相许”＝元好问《摸鱼儿·雁丘词》**。记住他是金代文宗（遗山先生）。","mix":"元好问虽姓“元”，但主要成名与生活在金代，是金代文学集大成者；其绝句体诗论接续杜甫《戏为六绝句》而大盛。","mcq":[{"q":"名句“问世间，情是何物，直教生死相许”出自金代文学家元好问的","o":["《念奴娇》","《江城子》","《摸鱼儿·雁丘词》","《青玉案》"],"a":2,"w":"出自元好问《摸鱼儿·雁丘词》，词前有小序讲述猎人捕双雁的故事。"}],"rel":[{"t":"董解元《西厢记诸宫调》","n":"同属金代文学代表"},{"t":"辛弃疾","n":"词风慷慨悲壮对照"},{"t":"杜甫","n":"同具“诗史”精神"}],"more":"名句：问世间，情是何物，直教生死相许？天南地北双飞客，老翅几回寒暑。｜《摸鱼儿·雁丘词》","exam":[]},{"id":"b03-066","t":"楔子与折","cid":"03i","p":2,"kind":"概念","alias":["四折一楔子","楔子","折"],"one":"元杂剧结构单位：折相当于一幕，楔子是开场或过场的短戏。","ans":"楔子与折是**元杂剧的结构单位**。一本杂剧通常为**四折一楔子**。**折**既是音乐单位，一折用同一宫调的一套曲子，一韵到底，又是情节单位，**相当于一幕**。**楔子**篇幅短小，只唱一两支曲子，多放在全剧开头交代背景，也可放在折间起过渡作用，名称借自木工填缝的木片。每本由**正末或正旦一人主唱**。例外有王实甫《西厢记》五本二十一折。","pts":["一本通常四折一楔子","折相当于一幕，一套曲、一韵到底","楔子短，开场或过场"],"mem":"画面：楔子像木匠敲进榫缝里的小木片，补空隙；四折像起承转合四幕。顺口记“一本四折外加楔，一人主唱末或旦”。","mix":"《西厢记》五本二十一折、《赵氏孤儿》五折，都是对四折体制的突破；“一人主唱”指正末或正旦，不是全体演员都唱。","mcq":[{"q":"元杂剧一本通常的体制是","o":["四折一楔子","三折一序","五折两楔子","六折一尾声"],"a":0,"w":"元杂剧一本通常四折，有时加楔子。"}],"rel":[{"t":"元杂剧与元曲四大家","n":"体制所属文体"},{"t":"旦本与末本","n":"主唱角色"},{"t":"《西厢记》","n":"突破四折体制"},{"t":"《窦娥冤》","n":"四折一楔子的例子"}],"more":"《窦娥冤》四折一楔子；《赵氏孤儿》五折一楔子；《西厢记》五本二十一折。","exam":[]},{"id":"b03-067","t":"旦本与末本","cid":"03i","p":3,"kind":"概念","alias":["末本与旦本"],"one":"元杂剧根据一人主唱的主角行当划分的两种基本剧本体制。","ans":"旦本与末本是**元杂剧按主唱行当划分的剧本体制**。元杂剧遵循“**一人主唱到底**”通例。全剧由正旦（女主角）主唱的称为**旦本**（如《窦娥冤》）；由正末（男主角）主唱的称为**末本**（如《汉宫秋》）。二者构成了**元杂剧剧本体制的核心规范**。","pts":["元杂剧按主唱行当划分的剧本体制","女角正旦主唱称旦本（如《窦娥冤》）","男角正末主唱称末本（如《汉宫秋》）"],"mem":"角色对应记忆：**旦本＝女主角正旦唱到底**（窦娥、崔莺莺）；**末本＝男主角正末唱到底**（汉元帝）。一人主唱是元杂剧体制规范。","mix":"元杂剧严格一人主唱（非旦即末），而南戏和明清传奇则是生旦等各角色分唱、轮唱；《西厢记》以崔莺莺主唱，属于旦本。","mcq":[{"q":"在元杂剧中，全剧四折一律由女主角（正旦）一人主唱的剧本类型称为","o":["生本","末本","净本","旦本"],"a":3,"w":"元杂剧遵循一人主唱制，女角唱到底称旦本，男角唱到底称末本。"}],"rel":[{"t":"元杂剧与元曲四大家","n":"元杂剧基本体制"},{"t":"关汉卿","n":"作著名旦本《窦娥冤》"},{"t":"马致远","n":"作著名末本《汉宫秋》"}],"exam":[]},{"id":"b03-068","t":"宾白与科","cid":"03i","p":3,"kind":"概念","alias":["科白"],"one":"中国古代戏曲剧本中人物台词说白与表演动作提示的术语。","ans":"宾白与科是中国古代戏曲（尤指元杂剧）**与曲词并列的两大结构要素**。**宾白**指剧中人物的说白对话与独白，所谓“曲为主、白为宾”；**科**（科介）指**表演动作、表情及上下场的舞台提示**。曲、白、科相互配合，**共同承担展开情节与刻画人物的职能**。","pts":["元杂剧结构要素，与曲词三足鼎立","宾白指剧中人物台词说白与独白","科指演员动作、表情及舞台效果提示"],"mem":"戏曲构成公式：**曲词（唱）＋ 宾白（说）＋ 科介（演/动作指示）**。白为台词，科为舞台动作提示。","mix":"元杂剧称“科”或“科介”，明清传奇南戏中多称“介”；“宾白”包含主角与配角的所有念白，非仅次要配角说话。","mcq":[{"q":"中国古代戏曲剧本中，指示演员动作、表情、舞台效果及出入场的专门术语是","o":["科","折","白","楔"],"a":0,"w":"“科”又称“科介”，是古代戏曲剧本中表演动作与舞台提示的专门术语。"}],"rel":[{"t":"元杂剧与元曲四大家","n":"元杂剧组成要素"},{"t":"戏曲美学特征：综合性、虚拟性、程式性","n":"戏曲舞台表演体制"},{"t":"南戏与《琵琶记》","n":"南戏表演术语对照"}],"exam":[]},{"id":"b03-069","t":"诸宫调","cid":"03i","p":2,"kind":"概念","alias":["诸宫调","董西厢"],"one":"宋金说唱艺术，多宫调联套演唱，代表作董解元《西厢记诸宫调》。","ans":"诸宫调是**宋金时期的说唱艺术**，用多个宫调的曲子联套演唱，间以说白，故名“诸宫调”。北宋艺人**孔三传**创始，金代**董解元**的**《西厢记诸宫调》**（俗称《董西厢》）是现存最完整的作品，据唐代元稹《莺莺传》改编，并把悲剧结局改为团圆，是**王实甫《西厢记》的直接蓝本**。诸宫调的联套方式对元杂剧的曲牌联套体制有直接影响。","pts":["宋金说唱，多宫调联套，说唱相间","董解元《西厢记诸宫调》","影响元杂剧联套体制"],"mem":"“诸”＝多：多个宫调＝诸宫调。西厢故事的接力：元稹《莺莺传》→董解元《西厢记诸宫调》→王实甫《西厢记》，一路从小说、说唱到杂剧。","mix":"《董西厢》是说唱，不是杂剧；王实甫《西厢记》是杂剧，人物结局都是团圆，与《莺莺传》的悲剧不同。","mcq":[{"q":"金代董解元的《西厢记诸宫调》属于","o":["说唱艺术","元杂剧","南戏","明传奇"],"a":0,"w":"诸宫调是宋金说唱艺术，《董西厢》是其代表。"}],"rel":[{"t":"董解元《西厢记诸宫调》","n":"代表作"},{"t":"董解元","n":"代表作者"},{"t":"《西厢记》","n":"据此改编的杂剧"},{"t":"元杂剧与元曲四大家","n":"后起的杂剧"}],"more":"北宋孔三传首创诸宫调；现存作品还有《刘知远诸宫调》（残）。","exam":[]},{"id":"b03-049","t":"南戏与《琵琶记》","cid":"03j","p":1,"kind":"作品","alias":["南戏","琵琶记","永嘉杂剧","温州杂剧","戏文"],"one":"南戏是宋元流行于南方的戏曲；元末高明《琵琶记》为其最高成就，称“曲祖”。","ans":"南戏是**宋元时期流行于南方的戏曲**，起源于浙江温州（永嘉），又称温州杂剧、永嘉杂剧、戏文，用南曲演唱，**不限折数，各脚色都可歌唱**，与元杂剧的一本四折、一人主唱不同。现存早期作品有《张协状元》，后有**“荆刘拜杀”四大南戏**。**元末高明的《琵琶记》写蔡伯喈与赵五娘的故事，代表南戏的最高成就**，被明人推为“曲祖”“南曲之祖”，标志南戏进入文人创作阶段。南戏后经改造，发展为明清传奇。","pts":["宋元南方戏曲，起于温州，南曲，不限折数","高明《琵琶记》最高成就，曲祖","后发展为明清传奇"],"mem":"对比记：元杂剧是北方、北曲、四折、一人主唱；南戏是南方、南曲、不限折数、众人皆可唱。名单口诀“荆刘拜杀琵琶祖”：荆钗记、刘知远白兔记、拜月亭记、杀狗记，《琵琶记》是“曲祖”。","mix":"《琵琶记》是南戏（元末高明），《西厢记》是元杂剧，《牡丹亭》是明传奇；“荆刘拜杀”不含《琵琶记》；南戏《拜月亭记》与关汉卿杂剧《拜月亭》题材相近，注意区分。","mcq":[{"q":"被明人誉为“曲祖”“南曲之祖”的作品是","o":["《西厢记》","《牡丹亭》","《琵琶记》","《桃花扇》"],"a":2,"w":"高明《琵琶记》被称“曲祖”。"},{"q":"关于南戏，下列说法正确的是","o":["起源于北方，一人主唱","用北曲演唱","起源于温州一带，不限折数","由关汉卿创立"],"a":2,"w":"南戏起源于温州一带，用南曲演唱，不限折数。"}],"rel":[{"t":"高明","n":"《琵琶记》作者"},{"t":"四大南戏","n":"“荆刘拜杀”"},{"t":"南戏四大声腔","n":"南戏的声腔发展"},{"t":"明清传奇","n":"南戏的发展"},{"t":"世界三大古老戏剧","n":"戏曲史对照"}],"more":"荆刘拜杀：《荆钗记》《刘知远白兔记》《拜月亭记》《杀狗记》。\n《琵琶记》：蔡伯喈与赵五娘，高明作，元末。","exam":[]},{"id":"b03-050","t":"汤显祖与“临川四梦”","cid":"03j","p":1,"kind":"作品","alias":["临川四梦","玉茗堂四梦","玉茗堂"],"one":"汤显祖明代戏曲家，“临川四梦”作者，《牡丹亭》最著，与莎士比亚同年去世。","ans":"汤显祖（1550–1616），**字义仍，号若士，江西临川人，明代戏曲家**，临川派代表。他的**“临川四梦”（玉茗堂四梦）**包括**《牡丹亭》《紫钗记》《南柯记》《邯郸记》**，四剧都写梦，因他居玉茗堂而得名。《牡丹亭》写杜丽娘与柳梦梅因梦生情、死而复生，以**“情”**对抗礼教，是明传奇的高峰；《南柯记》《邯郸记》借梦写人生虚幻，典出“南柯一梦”“黄粱一梦”。他与重格律的沈璟形成“汤沈之争”。**1616年与莎士比亚同年去世**，被称“东方的莎士比亚”。","pts":["明代戏曲家，临川派，主“情”","临川四梦：牡丹亭、紫钗记、南柯记、邯郸记","与莎士比亚同年（1616）去世"],"mem":"四梦的来路：《紫钗记》取自唐传奇《霍小玉传》，《南柯记》取自《南柯太守传》，《邯郸记》取自《枕中记》，《牡丹亭》取自明话本《杜丽娘慕色还魂》，“三部取唐传奇，一部取话本”。年份挂钩：1616 年汤显祖、莎士比亚同年去世，2026 年是 410 周年。","mix":"《牡丹亭》又名《还魂记》；《西厢记》（王实甫）、《长生殿》（洪昇）、《桃花扇》（孔尚任）都不属四梦；同在1616年去世的还有塞万提斯。","mcq":[{"q":"下列作品中，不属于“临川四梦”的是","o":["《长生殿》","《南柯记》","《牡丹亭》","《紫钗记》"],"a":0,"w":"《长生殿》是清代洪昇的作品。"},{"q":"与汤显祖同在1616年去世的西方作家是","o":["但丁","歌德","莎士比亚","雨果"],"a":2,"w":"莎士比亚与汤显祖同年去世。"}],"rel":[{"t":"《牡丹亭》","n":"四梦中最著名"},{"t":"吴江派与临川派（汤沈之争）","n":"与沈璟之争"},{"t":"汤显祖与莎士比亚同年逝世","n":"同年逝世"},{"t":"《枕中记》与《南柯太守传》","n":"两梦的取材"},{"t":"明清传奇","n":"所属体裁"}],"more":"情不知所起，一往而深。｜《牡丹亭》题词\n原来姹紫嫣红开遍，似这般都付与断井颓垣。｜《牡丹亭·惊梦》","exam":[]},{"id":"b03-051","t":"“南洪北孔”","cid":"03j","p":1,"kind":"合称","alias":["南洪北孔","洪孔"],"one":"清初传奇双璧：洪昇《长生殿》与孔尚任《桃花扇》。","ans":"“南洪北孔”指**清初两位传奇作家洪昇与孔尚任**，洪昇为钱塘（今杭州）人，居南，孔尚任为山东曲阜人，居北，故称。洪昇的**《长生殿》**写**唐明皇与杨贵妃的爱情故事**，约成于康熙二十七年（1688）；孔尚任的**《桃花扇》**以**侯方域与李香君的离合之情**，写南明弘光王朝的覆亡，成于康熙三十八年（1699）。二人作品被视为**清代传奇的两大高峰**，标志着明清传奇创作的尾声。","pts":["清初传奇作家洪昇、孔尚任","洪昇《长生殿》写唐明皇杨贵妃","孔尚任《桃花扇》写侯方域李香君"],"members":[["洪昇","《长生殿》，写唐明皇与杨贵妃，约1688年"],["孔尚任","《桃花扇》，写侯方域与李香君，1699年"]],"mem":"方位对人：南（钱塘）对洪，北（曲阜）对孔。作品对题材：洪→长生殿→唐朝（七夕盟誓），孔→桃花扇→南明（一把染血的扇子）。年份：1688 与 1699，相隔十一年。","mix":"白朴《梧桐雨》也写唐明皇与杨贵妃，是元杂剧；白居易《长恨歌》是诗；汤显祖是明代，不在“南洪北孔”之列；孔尚任是孔子第六十四代孙。","mcq":[{"q":"《桃花扇》的作者是","o":["洪昇","孔尚任","汤显祖","李渔"],"a":1,"w":"《桃花扇》为孔尚任所作。"},{"q":"洪昇《长生殿》所写的故事是","o":["张生与崔莺莺","侯方域与李香君","杜丽娘与柳梦梅","唐明皇与杨贵妃"],"a":3,"w":"《长生殿》写唐明皇与杨贵妃。"}],"rel":[{"t":"《长生殿》","n":"洪昇代表作"},{"t":"《桃花扇》","n":"孔尚任代表作"},{"t":"洪昇","n":"“南洪”"},{"t":"孔尚任","n":"“北孔”"},{"t":"《汉宫秋》与《梧桐雨》","n":"同写唐明皇杨贵妃的《梧桐雨》"}],"exam":[]},{"id":"b03-063","t":"纳兰性德","cid":"03j","p":2,"kind":"人物","alias":["纳兰容若","纳兰成德","容若","饮水词"],"one":"清代词人，字容若，《饮水词》，清词三大家之一，“北宋以来一人而已”。","ans":"纳兰性德（1655–1685），原名成德，字容若，**满洲正黄旗人**，大学士明珠之子，**清代词人**。他曾任一等侍卫，三十一岁早逝。词集**《饮水词》**（与《侧帽词》合称《纳兰词》）多写爱情悼亡和塞外羁旅，感情真挚，语言自然，《长相思》“山一程，水一程”、《木兰花令》“人生若只如初见”流传最广。王国维《人间词话》称他“**北宋以来，一人而已**”，他是**清词三大家**之一。","pts":["清代满族词人，字容若","词集《饮水词》，《长相思》","王国维称“北宋以来一人而已”"],"mem":"“饮水”取自“如人饮水，冷暖自知”，词里写的都是自己的真情。名句配词牌：“山一程，水一程”＝《长相思》（塞外），“人生若只如初见”＝《木兰花令》（拟古决绝词）。","mix":"“人生若只如初见”出自纳兰性德《木兰花令·拟古决绝词柬友》，不是李煜；清词三大家通行说法为纳兰性德、陈维崧、朱彝尊，另有以王士禛代之的说法。","mcq":[{"q":"“人生若只如初见，何事秋风悲画扇”出自","o":["李煜《虞美人》","李清照《如梦令》","纳兰性德《木兰花令》","晏几道《鹧鸪天》"],"a":2,"w":"出自纳兰性德《木兰花令·拟古决绝词柬友》。"}],"rel":[{"t":"清词三大家与清代词派","n":"三大家之一"},{"t":"王国维《人间词话》","n":"对他评价极高"},{"t":"李清照","n":"同以真情见长的词人"},{"t":"清代四大诗说：神韵、格调、性灵、肌理","n":"清代诗论对照"}],"more":"人生若只如初见，何事秋风悲画扇。｜《木兰花令·拟古决绝词柬友》\n山一程，水一程，身向榆关那畔行，夜深千帐灯。｜《长相思》","exam":[]},{"id":"b03-064","t":"桐城派","cid":"03j","p":1,"kind":"流派","alias":["桐城文派","桐城古文"],"one":"清代散文流派，方苞、刘大櫆、姚鼐为桐城三祖，主张义理、考据、辞章。","ans":"桐城派是**清代影响最大的散文流派**，因主要作家方苞、刘大櫆、姚鼐都是**安徽桐城人**而得名，三人称**“桐城三祖”**。该派尊奉唐宋八大家与明代归有光，方苞提出**“义法”**（言有物、言有序），姚鼐总结为**“义理、考据、辞章”**三者并重，文风清通雅正、简洁。姚鼐编《古文辞类纂》作为范本。桐城派前后延续近二百年，主导清代中后期文坛，晚清曾国藩等“湘乡派”继承并变通，五四新文化运动时遭到批评，被钱玄同斥为“桐城谬种”。","pts":["清代散文流派，桐城人方苞、刘大櫆、姚鼐","义法；义理、考据、辞章","宗唐宋八大家与归有光"],"mem":"三祖顺序“方刘姚”，师承链：方苞→刘大櫆→姚鼐。三要素：义理（思想）、考据（学问凭据）、辞章（文笔），也就是“想得对、查得准、写得好”。","mix":"“义法”是方苞，“义理、考据、辞章”是姚鼐；桐城派是散文流派，不是诗派；清代四大诗说（神韵、格调、性灵、肌理）讲诗，别混；“桐城”是地名，不是人名。","mcq":[{"q":"下列人物中，不属于“桐城三祖”的是","o":["曾国藩","方苞","刘大櫆","姚鼐"],"a":0,"w":"桐城三祖是方苞、刘大櫆、姚鼐，曾国藩属湘乡派。"},{"q":"提出“义理、考据、辞章”三者合一的桐城派作家是","o":["方苞","刘大櫆","姚鼐","归有光"],"a":2,"w":"“义理、考据、辞章”由姚鼐总结。"}],"rel":[{"t":"桐城三祖","n":"三位代表"},{"t":"桐城派“义法”与“义理、考据、辞章”","n":"文论主张"},{"t":"方苞","n":"奠基者"},{"t":"姚鼐","n":"集大成者"},{"t":"唐宋八大家","n":"所尊范本"}],"more":"代表选本：姚鼐《古文辞类纂》。","exam":[]},{"id":"b03-065","t":"公安派与竟陵派","cid":"03j","p":1,"kind":"流派","alias":["公安派","竟陵派","三袁","独抒性灵"],"one":"明代晚期两个反复古流派：公安三袁“独抒性灵”，竟陵钟惺、谭元春“幽深孤峭”。","ans":"公安派与竟陵派是**晚明两个反对复古的文学流派**。**公安派**以湖北公安人袁宗道、袁宏道、袁中道“三袁”为代表，以袁宏道为首，主张**“独抒性灵，不拘格套”**，反对前后七子“文必秦汉，诗必盛唐”的拟古，作品清新自然，多山水小品与游记。**竟陵派**以湖北竟陵人钟惺、谭元春为代表，同样讲性灵，却倡导**“幽深孤峭”**，意在矫公安派的浅率，后流于艰涩。两派推动晚明小品文兴盛，对清代性灵说也有影响。","pts":["公安派：三袁，独抒性灵","竟陵派：钟惺、谭元春，幽深孤峭","反对前后七子复古"],"mem":"口诀“公安三袁讲性灵，竟陵钟谭求幽峭”。画面：公安派像“明信片式的山水小品”，清新直白；竟陵派像“深山小径”，幽深冷僻。","mix":"公安派袁宏道不是清代性灵说的袁枚；前后七子主复古，公安派反复古；竟陵派继承性灵说，又求幽深以矫公安之浅。","mcq":[{"q":"“独抒性灵，不拘格套”是哪一流派的主张","o":["前七子","唐宋派","公安派","竟陵派"],"a":2,"w":"公安派袁宏道主张独抒性灵。"},{"q":"竟陵派的代表人物是","o":["袁宏道、袁中道","李梦阳、何景明","归有光、茅坤","钟惺、谭元春"],"a":3,"w":"竟陵派以钟惺、谭元春为代表。"}],"rel":[{"t":"袁宏道","n":"公安派领袖"},{"t":"晚明小品文","n":"主要成就"},{"t":"后七子","n":"所反对的复古派"},{"t":"清代四大诗说：神韵、格调、性灵、肌理","n":"性灵说后续"},{"t":"英国浪漫主义两代诗人","n":"重个性情感的对照"}],"more":"公安派：三袁（袁宗道、袁宏道、袁中道），主张“独抒性灵，不拘格套”。\n竟陵派：钟惺、谭元春，主张“幽深孤峭”，编《诗归》。","exam":[]},{"id":"c-033","t":"四大南戏","cid":"03j","p":2,"kind":"合称","alias":["荆刘拜杀","四大南戏"],"one":"《荆钗记》《白兔记》《拜月亭记》《杀狗记》，合称“荆刘拜杀”。","ans":"四大南戏指**宋元南戏中的四部代表作：《荆钗记》《白兔记》《拜月亭记》《杀狗记》**，合称“**荆刘拜杀**”（《白兔记》全称《刘知远白兔记》）。南戏起源于温州（永嘉），又称温州杂剧，用南曲演唱，是**中国最早成熟的戏曲形式之一**。《荆钗记》写王十朋与钱玉莲，《白兔记》写刘知远与李三娘，《拜月亭记》写蒋世隆与王瑞兰，《杀狗记》写孙华之妻杀狗劝夫、使兄弟和好。元末高明的《琵琶记》是南戏走向成熟的标志。","pts":["荆钗记、白兔记、拜月亭记、杀狗记","合称“荆刘拜杀”","南戏起源于温州，用南曲"],"members":[["《荆钗记》","王十朋与钱玉莲"],["《白兔记》","刘知远与李三娘（全称《刘知远白兔记》）"],["《拜月亭记》","蒋世隆与王瑞兰"],["《杀狗记》","孙华之妻杀狗劝夫，兄弟和好"]],"mem":"通行口诀“荆刘拜杀”，每个字对应一部：荆（荆钗）、刘（刘知远白兔）、拜（拜月亭）、杀（杀狗）。《琵琶记》不在四大南戏里，要单独记为“南戏之祖”一类的高明之作。","mix":"《琵琶记》（高明）常被当成第五部，实际不在“荆刘拜杀”之内；《拜月亭记》（南戏）与关汉卿杂剧《拜月亭》是两部不同的戏，后者属元杂剧。","mcq":[{"q":"下列作品中，不属于“四大南戏”的是","o":["《荆钗记》","《白兔记》","《琵琶记》","《杀狗记》"],"a":2,"w":"四大南戏是荆刘拜杀，《琵琶记》是高明之作，不在其列。"}],"rel":[{"t":"南戏与《琵琶记》","n":"南戏的成熟之作"},{"t":"明清传奇","n":"南戏的发展"},{"t":"元杂剧与元曲四大家","n":"同时期北方戏曲"},{"t":"世界三大古老戏剧","n":"中西戏剧对照"}],"more":"南戏又称温州杂剧、永嘉杂剧。","exam":[]},{"id":"c-035","t":"公安三袁","cid":"03j","p":2,"kind":"合称","alias":["三袁","公安派三袁"],"one":"袁宗道、袁宏道、袁中道三兄弟，公安派代表，主张“独抒性灵”。","ans":"公安三袁指**明代公安派的三位代表人物：袁宗道、袁宏道、袁中道**三兄弟，湖北公安人，字分别为伯修、中郎、小修，活动于万历年间。他们反对前后七子的复古模拟，主张“**独抒性灵，不拘格套**”，认为文学随时代而变，崇尚真情与自然。其中**袁宏道**成就最高，是公安派领袖，有《徐文长传》《满井游记》；袁宗道推崇白居易、苏轼，袁中道有《游居柿录》。","pts":["袁宗道、袁宏道、袁中道，湖北公安人","主张独抒性灵，不拘格套","反对前后七子复古；袁宏道为领袖"],"members":[["袁宗道","字伯修，长兄，推崇白居易、苏轼"],["袁宏道","字中郎，公安派领袖，《徐文长传》"],["袁中道","字小修，《游居柿录》"]],"mem":"字的顺序“伯中小”对应排行：宗道伯修（大）、宏道中郎（中）、中道小修（小）。主张记“独抒性灵”，对象是前后七子的“文必秦汉”。","mix":"公安派之后是竟陵派（钟惺、谭元春），“幽深孤峭”，是对公安派浅俗的纠偏；三袁都出自公安，与“三苏”“三曹”不要混。","mcq":[{"q":"明代公安派主张“独抒性灵，不拘格套”，其核心人物是","o":["李梦阳、何景明","袁宗道、袁宏道、袁中道","钟惺、谭元春","王慎中、唐顺之"],"a":1,"w":"公安三袁是公安派代表，竟陵派是钟惺、谭元春。"}],"rel":[{"t":"公安派与竟陵派","n":"同簇流派"},{"t":"袁宏道","n":"三袁中成就最高"},{"t":"前七子","n":"他们反对的复古派"},{"t":"后七子","n":"他们反对的复古派"}],"more":"袁宏道：《徐文长传》《满井游记》《虎丘记》。","exam":[]},{"id":"c-036","t":"桐城三祖","cid":"03j","p":2,"kind":"合称","alias":["桐城三祖","桐城派三祖"],"one":"方苞、刘大櫆、姚鼐，清代桐城派的三位代表。","ans":"桐城三祖指**清代桐城派的三位代表人物方苞、刘大櫆、姚鼐**，都是安徽桐城人。方苞提出“**义法**”，有《狱中杂记》《左忠毅公逸事》；刘大櫆重文章的“神气音节”，著《论文偶记》；姚鼐是**集大成者**，主张**义理、考据、辞章**三者统一，编《古文辞类纂》，有《登泰山记》。桐城派是**清代影响最大的散文流派**，提倡学习唐宋八大家，文风雅洁，影响延续到清末民初。","pts":["方苞、刘大櫆、姚鼐，安徽桐城人","方苞义法，姚鼐义理考据辞章","桐城派是清代影响最大的散文流派"],"members":[["方苞","提出“义法”；《狱中杂记》"],["刘大櫆","重神气音节；《论文偶记》"],["姚鼐","集大成；《古文辞类纂》《登泰山记》"]],"mem":"首字顺序“方—刘—姚”，一路从“法”到“气”到“集成”：方苞定义法，刘大櫆补神气，姚鼐三合一，再编《古文辞类纂》做范本。","mix":"桐城派是散文流派，不是诗派；清代诗说（神韵、格调、性灵、肌理）与桐城文论属于不同领域。","mcq":[{"q":"桐城派的“三祖”是","o":["方苞、刘大櫆、姚鼐","曾国藩、梅曾亮、管同","钱谦益、吴伟业、龚鼎孳","朱彝尊、陈维崧、纳兰性德"],"a":0,"w":"桐城三祖为方苞、刘大櫆、姚鼐。"}],"rel":[{"t":"桐城派","n":"所属流派"},{"t":"方苞","n":"三祖之首"},{"t":"姚鼐","n":"集大成者"},{"t":"桐城派“义法”与“义理、考据、辞章”","n":"核心主张"}],"more":"姚鼐《登泰山记》；方苞《左忠毅公逸事》。","exam":[]},{"id":"a03-001","t":"《诗经》六义：风雅颂与赋比兴","cid":"03a","p":1,"kind":"概念","alias":["六义","风雅颂","赋比兴"],"one":"风雅颂是体制，赋比兴是手法，合称《诗经》“六义”。","ans":"“六义”是**《毛诗序》提出的《诗经》六种分类与表现方法**。其中**风、雅、颂是按音乐划分的体制**：风是各地民歌，含十五国风160篇；雅是朝廷正乐，分大雅小雅共105篇；颂是宗庙祭祀乐歌，含周颂、鲁颂、商颂共40篇。**赋、比、兴是表现手法**：赋是直陈其事，比是打比方，兴是先言他物以引起所咏之词。全书共**305篇**，又称“诗三百”。六义是理解《诗经》的基本框架。","pts":["风雅颂为体制，赋比兴为手法","风160、雅105、颂40，共305篇","赋直陈，比比喻，兴起兴"],"mem":"数字拆解：160+105+40=305。顺口溜“风百六、雅百五、颂四十”。手法记“赋直比喻兴起头”：赋直说，比比方，兴先说别的再引出正题。","mix":"风雅颂分体裁，赋比兴分手法，不能混为一类；《毛诗序》称“六义”，实际一类是体、一类是用。","mcq":[{"q":"《诗经》中“风”的含义是","o":["宗庙祭祀乐歌","朝廷宴饮乐歌","各地民歌","直陈其事的手法"],"a":2,"w":"风即国风，是各地民歌，共160篇。"},{"q":"“先言他物以引起所咏之词”属于哪种手法","o":["兴","赋","比","颂"],"a":0,"w":"兴是起兴，如“关关雎鸠”引出君子好逑。"}],"rel":[{"t":"《诗经》","n":"六义所属"},{"t":"《诗经》名篇","n":"各体名篇"},{"t":"诗言志与兴观群怨","n":"《诗经》批评传统"}],"more":"风：十五国风；雅：大雅、小雅；颂：周颂、鲁颂、商颂。","exam":[]},{"id":"a03-002","t":"《诗经》名篇","cid":"03a","p":2,"kind":"作品","alias":["《关雎》","《蒹葭》","《氓》","《硕鼠》","《伐檀》","《七月》","《采薇》"],"one":"《诗经》常考篇目：关雎、蒹葭、氓、硕鼠、伐檀、七月、采薇。","ans":"《诗经》是**中国最早的诗歌总集**，常考篇目各有出处。**《关雎》**是首篇，属周南，写君子追求淑女；**《蒹葭》**属秦风，以“蒹葭苍苍”写追寻伊人；**《氓》**属卫风，是弃妇诗；**《硕鼠》《伐檀》**属魏风，讽刺剥削者；**《七月》**属豳风，写农夫一年劳作；**《采薇》**属小雅，有“昔我往矣，杨柳依依”之句，写戍边士兵的归思。这些篇目集中体现了《诗经》**写实**的风格。","pts":["《关雎》首篇；《蒹葭》秦风；《氓》卫风弃妇","《硕鼠》《伐檀》魏风；《七月》豳风","《采薇》小雅，昔我往矣杨柳依依"],"mem":"按篇名配地区记：关雎(周南)，蒹葭(秦风)，氓(卫风)，硕鼠、伐檀(魏风)，七月(豳风)。记“关氓兼七”：关雎、氓、蒹葭、七月。《采薇》是小雅，唯一的雅，对应戍边士兵的“杨柳依依”。","mix":"《诗经》名句常张冠李戴：“关关雎鸠”是《关雎》，“所谓伊人，在水一方”是《蒹葭》，“昔我往矣”是《采薇》。《硕鼠》和《伐檀》都出魏风。","mcq":[{"q":"“昔我往矣，杨柳依依；今我来思，雨雪霏霏”出自《诗经》的","o":["《蒹葭》","《氓》","《七月》","《采薇》"],"a":3,"w":"出自《小雅·采薇》，写戍边士兵归途。"}],"rel":[{"t":"《诗经》","n":"总集"},{"t":"《诗经》六义：风雅颂与赋比兴","n":"篇目所属体例"},{"t":"风骚","n":"风即国风"},{"t":"荷马史诗","n":"同为早期诗歌，中西对照"}],"more":"《关雎》：关关雎鸠，在河之洲。窈窕淑女，君子好逑。\n《蒹葭》：蒹葭苍苍，白露为霜。所谓伊人，在水一方。\n《硕鼠》：硕鼠硕鼠，无食我黍。\n《氓》：氓之蚩蚩，抱布贸丝。","exam":[]},{"id":"a03-003","t":"《离骚》","cid":"03a","p":1,"kind":"作品","alias":["离骚","骚体"],"one":"屈原代表作，古代最长的政治抒情诗，香草美人比兴。","ans":"《离骚》是**战国时期楚国诗人屈原的代表作**，是**中国古代最长的政治抒情诗**，约370余句。全诗抒写诗人遭谗被疏、坚持理想而不肯同流的悲愤，大量运用**“香草美人”的比兴**，并借神话游仙构造奇幻境界。名句“**路漫漫其修远兮，吾将上下而求索**”。它是**楚辞的代表作，开创浪漫主义传统**，“骚体”因此得名，后世以“风骚”并称《诗经》与楚辞。","pts":["屈原作，最长的政治抒情诗","香草美人比兴，神话想象","骚体得名，浪漫主义源头"],"mem":"画面：屈原披香草佩兰芷，乘龙驾凤上天入地求索，美人比君王，香草比君子。“离骚”一说为“遭忧”之意，一说为“离别的忧愁”。","mix":"《离骚》是屈原作品，《九辩》是宋玉作品；“风骚”的“骚”指《离骚》。","mcq":[{"q":"“路漫漫其修远兮，吾将上下而求索”出自","o":["《离骚》","《九歌》","《天问》","《九辩》"],"a":0,"w":"出自屈原《离骚》。"},{"q":"“骚体”这一名称源于","o":["《九歌》","《诗经》","《离骚》","《天问》"],"a":2,"w":"因屈原《离骚》得名。"}],"rel":[{"t":"屈原","n":"作者"},{"t":"楚辞","n":"代表作"},{"t":"风骚","n":"“骚”指本篇"},{"t":"屈原《九歌》《九章》《天问》","n":"屈原其他作品"}],"more":"路曼曼其修远兮，吾将上下而求索。\n长太息以掩涕兮，哀民生之多艰。","exam":[]},{"id":"a03-004","t":"屈原《九歌》《九章》《天问》","cid":"03a","p":2,"kind":"作品","alias":["《九歌》","《九章》","《天问》","《国殇》","《湘夫人》","《山鬼》","《橘颂》","《涉江》","《哀郢》"],"one":"屈原三组作品：《九歌》祭歌，《九章》抒愤，《天问》连发170余问。","ans":"《九歌》《九章》《天问》都是**战国楚国屈原**的作品，收入《楚辞》。**《九歌》**据楚地祭神乐歌加工而成，含《国殇》《湘夫人》《山鬼》等；**《九章》**是屈原抒写个人遭遇的九篇，含《涉江》《橘颂》《哀郢》；**《天问》**以问句成篇，连发**一百七十多个问题**，涉及天地、神话与历史。它们与《离骚》一起体现了楚辞**浪漫抒情**的风格，其中《国殇》祭奠阵亡将士。","pts":["九歌：祭歌改作，含国殇、湘夫人、山鬼","九章：涉江、橘颂、哀郢等抒愤之作","天问：连发170多问"],"mem":"数字挂钩：九歌里其实有十一篇，九只是虚数；九章九篇；天问170多问。口诀“歌祭章抒问天地”：歌=祭神，章=抒怀，问=天地神话。《橘颂》写橘树，是屈原的“自画像”。","mix":"《九歌》《九章》《天问》都不是《离骚》；《九歌》中“国殇”写战死者，不是屈原自己的遭遇。","mcq":[{"q":"下列作品中，以连续发问的形式写成、共一百七十多问的是","o":["《天问》","《九歌》","《九章》","《九辩》"],"a":0,"w":"《天问》是屈原所作，连发170多问；《九辩》是宋玉所作。"}],"rel":[{"t":"屈原","n":"作者"},{"t":"《离骚》","n":"屈原代表作"},{"t":"楚辞","n":"收录作品的总集"},{"t":"端午节","n":"纪念屈原的节日"}],"more":"《九歌》含：东皇太一、云中君、湘君、湘夫人、大司命、少司命、东君、河伯、山鬼、国殇、礼魂。\n《九章》含：惜诵、涉江、哀郢、抽思、怀沙、思美人、惜往日、橘颂、悲回风。","exam":[]},{"id":"a03-005","t":"《楚辞》的编集：刘向与王逸","cid":"03a","p":3,"kind":"常识","alias":["楚辞编集","楚辞成书"],"one":"西汉刘向辑录成书，东汉王逸作现存最早注本《楚辞章句》。","ans":"《楚辞》的编集指**西汉刘向**辑录屈原、宋玉及汉代仿作而成诗歌总集。东汉**王逸**作**《楚辞章句》**，是现存最早的《楚辞》完整注本。南宋**朱熹**作**《楚辞集注》**，成为后世通行注本。两汉学者的整理与训诂确立了骚体文学在文坛的经典地位。","pts":["西汉刘向最早辑录屈宋作品成书","东汉王逸作现存最早注本《楚辞章句》","南宋朱熹作后世通行本《楚辞集注》"],"mem":"汉代向辑逸注，宋代朱熹集注。口诀记法：向辑、逸章、熹注。","mix":"刘向是辑录编订者而非注者；现存最早完整注本作者是东汉王逸，朱熹《楚辞集注》为宋代注本。","mcq":[{"q":"现存最早的《楚辞》完整注本是","o":["刘向《楚辞》","王逸《楚辞章句》","朱熹《楚辞集注》","洪兴祖《楚辞补注》"],"a":1,"w":"东汉王逸的《楚辞章句》是现存最早的《楚辞》完整注本。"}],"rel":[{"t":"楚辞","n":"楚辞作品总集"},{"t":"屈原","n":"楚辞主要作者"},{"t":"宋玉《九辩》","n":"楚辞重要篇目"}],"more":"编选注本脉络：\n西汉刘向《楚辞》辑录成书\n东汉王逸《楚辞章句》（现存最早完整注本）\n宋代洪兴祖《楚辞补注》\n南宋朱熹《楚辞集注》（后世通行读本）","exam":[]},{"id":"a03-006","t":"许穆夫人","cid":"03a","p":3,"kind":"人物","one":"春秋卫国女子，中国文学史上有诗作传世的第一位女诗人。","ans":"许穆夫人是**春秋时期卫国**女子、许穆公夫人，**中国文学史上第一位有名可考的女诗人**。卫国遭狄人攻伐后，她作**《载驰》**表达急救宗邦之志，诗作收入《诗经·鄘风》。相传《泉水》《竹竿》亦为其作。其作开创了中国诗歌史上的忧国爱国传统。","pts":["春秋卫国人，中国第一位留名女诗人","代表作《载驰》收录于《诗经·鄘风》","抒发急救宗邦之志，开创忧国诗传统"],"mem":"许穆夫人乘车疾驰救卫国，代表作《载驰》，名列中国第一位留名女诗人。","mix":"中国第一位女诗人是春秋许穆夫人；汉代班婕妤、蔡文姬年代均晚于她。","mcq":[{"q":"中国文学史上第一位有名可考、有诗作传世的女诗人是","o":["蔡文姬","李清照","许穆夫人","班婕妤"],"a":2,"w":"春秋时期的许穆夫人是我国第一位有名可考的女诗人，代表作为《载驰》。"}],"rel":[{"t":"《诗经》","n":"收录其代表作"},{"t":"《诗经》名篇","n":"《载驰》所在篇目"},{"t":"蔡文姬","n":"汉魏女性文学对照"}],"more":"代表作：《载驰》（收于《诗经·鄘风》）\n名句：跋涉趟涉，唯寄其疾。驱马悠悠，言至于漕。","exam":[],"alias":[]},{"id":"a03-007","t":"赋（文体）","cid":"03b","p":1,"kind":"概念","alias":["赋体","辞赋"],"one":"铺采摛文、体物写志的文体，历骚体赋、汉大赋至文赋。","ans":"赋是**介于诗与文之间的文体**，刘勰称其**“铺采摛文，体物写志”**，班固称“不歌而诵谓之赋”。其演变依次为：**战国楚辞骚体赋**，**汉大赋**（主客问答、铺陈、劝百讽一，代表司马相如），东汉**抒情小赋**（张衡《归田赋》），魏晋南北朝**骈赋**，唐宋**律赋**，以及宋代**文赋**（欧阳修《秋声赋》、苏轼《赤壁赋》）。赋与诗、词、曲共同构成古代韵文的主要体式。","pts":["铺采摛文，体物写志；不歌而诵","骚体赋、汉大赋、抒情小赋、骈赋、律赋、文赋","文赋代表《秋声赋》《赤壁赋》"],"mem":"逻辑线口诀“骚大小骈律文”：骚体赋、汉大赋、小赋、骈赋、律赋、文赋，六个字就是时间顺序。","mix":"苏轼《赤壁赋》是文赋，不是骈赋；贾谊《吊屈原赋》是骚体赋，司马相如《子虚赋》是汉大赋。","mcq":[{"q":"欧阳修《秋声赋》属于","o":["骚体赋","汉大赋","文赋","骈赋"],"a":2,"w":"宋代文赋，打破骈偶，近于散文。"},{"q":"开抒情小赋之风的是东汉张衡的","o":["《二京赋》","《归田赋》","《两都赋》","《上林赋》"],"a":1,"w":"《归田赋》是抒情小赋开端。"}],"rel":[{"t":"汉赋与司马相如","n":"汉赋代表"},{"t":"楚辞","n":"骚体赋源头"},{"t":"枚乘《七发》","n":"汉大赋形成"},{"t":"苏轼","n":"《赤壁赋》文赋"}],"more":"刘勰《文心雕龙·诠赋》：赋者，铺也，铺采摛文，体物写志也。","exam":[]},{"id":"a03-008","t":"《孔雀东南飞》","cid":"03b","p":2,"kind":"作品","alias":["《古诗为焦仲卿妻作》","孔雀东南飞","焦仲卿妻"],"one":"汉乐府最长的叙事诗，写刘兰芝与焦仲卿的爱情悲剧，乐府双璧之一。","ans":"《孔雀东南飞》原题**《古诗为焦仲卿妻作》**，是**东汉末年的乐府叙事诗**，最早见于南朝徐陵编的**《玉台新咏》**。诗写庐江府小吏焦仲卿与妻子**刘兰芝**被焦母逼迫离异，兰芝不肯再嫁，二人双双殉情。全诗三百五十余句，是**中国古代最长的叙事诗**，与北朝民歌**《木兰诗》**合称**“乐府双璧”**，成功塑造了刘兰芝的形象，反映了封建家长制对爱情的摧残。","pts":["原题《古诗为焦仲卿妻作》，见《玉台新咏》","写刘兰芝、焦仲卿的爱情悲剧","古代最长叙事诗；与《木兰诗》为乐府双璧"],"mem":"开头“孔雀东南飞，五里一徘徊”，孔雀一飞一回头，比喻夫妻不忍分离。双璧口诀“汉孔北木”：汉代孔雀，北朝木兰。最长叙事诗配最长篇幅，记“双璧一长一短”。","mix":"《孔雀东南飞》是汉乐府(文人整理)；《木兰诗》是北朝民歌；二者合称“乐府双璧”，注意与唐代《长恨歌》《琵琶行》区分。","mcq":[{"q":"《孔雀东南飞》最早收录于","o":["《玉台新咏》","《文选》","《乐府诗集》","《诗经》"],"a":0,"w":"《玉台新咏》收录，原题《古诗为焦仲卿妻作》，另见《乐府诗集》。"}],"rel":[{"t":"乐府与乐府双璧","n":"并称"},{"t":"《木兰诗》","n":"另一璧"},{"t":"《玉台新咏》","n":"最早收录"},{"t":"《罗密欧与朱丽叶》","n":"中西爱情悲剧对照"}],"more":"名句：孔雀东南飞，五里一徘徊。\n“十三能织素，十四学裁衣，十五弹箜篌，十六诵诗书。”","exam":[]},{"id":"a03-009","t":"《木兰诗》","cid":"03b","p":2,"kind":"作品","alias":["木兰辞","花木兰","《木兰辞》"],"one":"北朝民歌，木兰代父从军，乐府双璧之一。","ans":"《木兰诗》是**北朝民歌**，收于宋代郭茂倩《乐府诗集》的**“梁鼓角横吹曲”**，又称《木兰辞》。诗写**木兰女扮男装、代父从军**，征战十余年，立功后辞官还乡、恢复女装的故事，开篇“唧唧复唧唧，木兰当户织”。全诗质朴刚健，叙事详略得当，塑造了巾帼英雄木兰的形象，与汉乐府《孔雀东南飞》合称**“乐府双璧”**，是**北朝民歌的代表作**。","pts":["北朝民歌，《乐府诗集》梁鼓角横吹曲","木兰代父从军的故事","与《孔雀东南飞》为乐府双璧"],"mem":"对照《孔雀东南飞》：它写爱情悲剧，《木兰诗》写英雄凯旋；一个是悲，一个是喜。开头“唧唧复唧唧”是织布声，结尾“雄兔脚扑朔，雌兔眼迷离”点出男女难辨。","mix":"《木兰诗》是北朝民歌，不是汉乐府；它与《敕勒歌》同属北朝民歌，风格刚健，南朝民歌多为缠绵情歌。","mcq":[{"q":"“乐府双璧”指的是","o":["《长恨歌》和《琵琶行》","《孔雀东南飞》和《木兰诗》","《陌上桑》和《木兰诗》","《孔雀东南飞》和《陌上桑》"],"a":1,"w":"乐府双璧是汉乐府《孔雀东南飞》与北朝民歌《木兰诗》。"}],"rel":[{"t":"乐府与乐府双璧","n":"并称"},{"t":"《孔雀东南飞》","n":"另一璧"},{"t":"《乐府诗集》","n":"收录总集"},{"t":"南北朝民歌：吴歌西曲与《敕勒歌》","n":"同属北朝民歌"}],"more":"名句：唧唧复唧唧，木兰当户织。\n万里赴戎机，关山度若飞。\n雄兔脚扑朔，雌兔眼迷离；双兔傍地走，安能辨我是雄雌？","exam":[]},{"id":"a03-010","t":"汉乐府名篇","cid":"03b","p":3,"kind":"作品","alias":["两汉乐府名篇","汉乐府"],"one":"两汉乐府机关采集保存的民间歌辞与文人诗歌代表作群。","ans":"汉乐府名篇指**两汉乐府官署采集的民歌与诗作**，以**“感于哀乐，缘事而发”**为特征。叙事名作有**《陌上桑》**、**《孔雀东南飞》**，抒情名篇有**《长歌行》**（“少壮不努力，老大徒伤悲”）与《上邪》。其创作极大推动了五言叙事诗的成熟。","pts":["两汉乐府官署采集民歌，“感于哀乐，缘事而发”","叙事名作《陌上桑》《孔雀东南飞》","抒情名作《长歌行》《上邪》，推动五言诗成熟"],"mem":"陌上秦罗敷，东南孔雀飞；长歌惜少壮，上邪誓不移。","mix":"《汉书·艺文志》论乐府‘感于哀乐，缘事而发’；《乐府诗集》是北宋郭茂倩编订的总集，并非汉代成书。","mcq":[{"q":"劝勉世人珍惜韶华的名句‘少壮不努力，老大徒伤悲’出自汉乐府名篇","o":["《短歌行》","《长歌行》","《陌上桑》","《东门行》"],"a":1,"w":"‘少壮不努力，老大徒伤悲’出自汉乐府诗《长歌行》。"}],"rel":[{"t":"乐府与乐府双璧","n":"汉乐府最高成就"},{"t":"《乐府诗集》","n":"乐府收录总集"},{"t":"《古诗十九首》","n":"五言诗发展同阶段"}],"more":"名篇与名句：\n《长歌行》：百川东到海，何时复西归？少壮不努力，老大徒伤悲。\n《上邪》：山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝！\n《陌上桑》：秦氏有好女，自名为罗敷。\n《十五从军征》：十五从军征，八十始得归。","exam":[]},{"id":"a03-011","t":"贾谊《过秦论》与《吊屈原赋》","cid":"03b","p":3,"kind":"作品","alias":["过秦论","吊屈原赋"],"one":"西汉贾谊的两大传世名篇，分属政论散文与骚体赋代表作。","ans":"《过秦论》与《吊屈原赋》是**西汉贾谊**的传世名篇。《过秦论》分析秦亡教训，得出**“仁义不施而攻守之势异也”**的名论，为汉代政论散文典范；**《吊屈原赋》**为骚体赋，借吊屈原抒发逐臣之悲。两作展现了贾谊在**政论散文与骚体辞赋**上的卓越成就。","pts":["贾谊代表作，分属史论散文与骚体赋","《过秦论》核心论断“仁义不施而攻守之势异也”","《吊屈原赋》借吊屈子抒不平，屈贾并称"],"mem":"过秦政论斥仁义不施，吊屈骚赋叹逐臣同悲；贾生才调屈贾传。","mix":"《过秦论》是史论散文，分为上中下三篇；《吊屈原赋》《鵩鸟赋》是骚体赋，两者体裁不同；司马迁合立《屈原贾生列传》。","mcq":[{"q":"贾谊在政论散文名篇《过秦论》中得出的核心论断是","o":["仁义不施而攻守之势异也","六国互丧，率赂秦耶","灭六国者六国也，非秦也","水则载舟，水则覆舟"],"a":0,"w":"贾谊《过秦论》总结秦朝灭亡的教训是‘仁义不施而攻守之势异也’。"}],"rel":[{"t":"贾谊","n":"作品作者"},{"t":"屈原","n":"《吊屈原赋》悼念对象"},{"t":"司马迁","n":"《史记》合立屈贾列传"}],"more":"政论：《过秦论》《论积贮疏》《治安策》\n辞赋：《吊屈原赋》《鵩鸟赋》","exam":[]},{"id":"a03-012","t":"曹丕《典论·论文》","cid":"03c","p":1,"kind":"作品","alias":["典论论文","《典论》","论文"],"one":"曹丕所作，中国第一篇文学批评专论，提出“文以气为主”。","ans":"《典论·论文》是**三国魏文帝曹丕所作的文学批评专论**，是**中国现存最早的文学批评专论**。文中提出**“文章经国之大业，不朽之盛事”**，抬高文学的地位；提出**“文以气为主”**，强调作者个性与才气；分文体为**四科八体**（奏议宜雅、书论宜理、铭诔尚实、诗赋欲丽）；并最早评论**“建安七子”**，批评“文人相轻”。此文开启了魏晋文学自觉的风气。","pts":["曹丕作，第一篇文学批评专论","文章经国大业，文以气为主","四科八体，评建安七子"],"mem":"三句话：一句价值“经国大业”，一句主体“文以气为主”，一句分类“四科八体”。四科口诀“奏书铭诗”：奏议、书论、铭诔、诗赋，分别雅、理、实、丽。","mix":"《文心雕龙》是第一部系统文论专著，《诗品》是第一部诗论专著，《典论·论文》是第一篇文论专文。","mcq":[{"q":"“文章经国之大业，不朽之盛事”出自","o":["《文心雕龙》","《诗品》","《典论·论文》","《人间词话》"],"a":2,"w":"曹丕《典论·论文》。"},{"q":"最早提出“建安七子”之名的文献是","o":["《典论·论文》","《文选》","《文赋》","《诗品》"],"a":0,"w":"曹丕在此文中列孔融等七人。"}],"rel":[{"t":"曹丕","n":"作者"},{"t":"建安七子","n":"首次提出"},{"t":"《文心雕龙》","n":"后出系统文论"},{"t":"陆机《文赋》","n":"同时期文论"},{"t":"《诗学》","n":"中西文论对照"}],"more":"文章经国之大业，不朽之盛事。\n文以气为主。\n文人相轻，自古而然。","exam":[]},{"id":"a03-013","t":"曹丕《燕歌行》","cid":"03c","p":3,"kind":"作品","alias":["燕歌行"],"one":"魏文帝曹丕所作乐府诗，文学史上现存最早的成熟文人七言诗。","ans":"《燕歌行》是**三国魏文帝曹丕**所作乐府诗，是**现存最早完整的文人七言诗**。作品以思妇口吻述秋夜怀人，名句**“秋风萧瑟天气凉，草木摇落露为霜”**委婉凄清。全诗句句用韵，音节柔美，情韵悱恻，彻底确立了**七言诗体制**在诗坛的独立正统地位。","pts":["魏文帝曹丕所作乐府诗，现存最早文人七言诗","名句“秋风萧瑟天气凉，草木摇落露为霜”","句句押韵，声韵清丽，确立七言诗体制地位"],"mem":"秋风萧瑟天气凉，曹丕燕歌最先尝；最早完整七言作，思妇长夜盼归郎。","mix":"曹丕《燕歌行》是现存最早完整文人七言歌行（古体诗，非七律）；盛唐高适亦有边塞名篇《燕歌行》（‘战士军前半死生’），同名不同作。","mcq":[{"q":"文学史上一般被认为是现存最早的完整文人七言诗的是","o":["曹丕《燕歌行》","曹操《短歌行》","高适《燕歌行》","鲍照《拟行路难》"],"a":0,"w":"曹丕《燕歌行》（‘秋风萧瑟天气凉’）是现存最早的完整文人七言诗。"}],"rel":[{"t":"曹丕","n":"诗作作者"},{"t":"曹丕《典论·论文》","n":"曹丕文论名作"},{"t":"建安文学与三曹","n":"所属文学时代"}],"more":"名句：秋风萧瑟天气凉，草木摇落露为霜，群燕辞归雁南翔。\n念君客游思断肠，慊慊思归恋故乡，君何淹留寄他方？","exam":[]},{"id":"a03-014","t":"曹植《洛神赋》","cid":"03c","p":2,"kind":"作品","alias":["洛神赋","《感甄赋》"],"one":"曹植辞赋代表作，写洛水女神宓妃，后世绘成《洛神赋图》。","ans":"《洛神赋》是**三国魏曹植的辞赋代表作**，约作于黄初年间，属**抒情小赋**。赋中假托作者途经洛水，邂逅**洛水女神宓妃**，彼此倾心却人神道殊，终至离别怅惘。文辞华美，想象瑰丽，“翩若惊鸿，婉若游龙”为名句。钟嵘评曹植“骨气奇高，词采华茂”，谢灵运有“才高八斗”之说。**东晋顾恺之据此作《洛神赋图》**，是中国传世名画。","pts":["曹植辞赋代表作，写洛水女神宓妃","人神相恋而殊途，翩若惊鸿","顾恺之据此作《洛神赋图》"],"mem":"曹植“才高八斗”，《洛神赋》就是这八斗才华的结晶。名句“翩若惊鸿，婉若游龙”，画面是洛水上飘来的女神。赋→画：曹植写赋，顾恺之画图，两件事连成线。","mix":"《洛神赋》曾传为《感甄赋》，附会曹植思念甄氏，今多不采信；赋是曹植所作，图是顾恺之所作。","mcq":[{"q":"据曹植《洛神赋》创作《洛神赋图》的画家是","o":["吴道子","阎立本","顾恺之","张择端"],"a":2,"w":"东晋顾恺之《洛神赋图》，今存宋摹本。"}],"rel":[{"t":"曹植","n":"作者"},{"t":"《洛神赋图》","n":"据此创作"},{"t":"顾恺之","n":"绘图者"},{"t":"赋（文体）","n":"抒情小赋"}],"more":"名句：翩若惊鸿，婉若游龙。｜《洛神赋》\n钟嵘评曹植：骨气奇高，词采华茂。","exam":[]},{"id":"a03-015","t":"太康文学：“三张二陆两潘一左”","cid":"03c","p":2,"kind":"合称","alias":["太康文学","三张二陆两潘一左","太康诗风"],"one":"西晋太康年间诗坛：三张、二陆、两潘、一左。","ans":"“三张二陆两潘一左”出自**钟嵘《诗品序》**，指**西晋太康年间（280–289）**的诗人：**三张**（张载、张协、张亢）、**二陆**（陆机、陆云）、**两潘**（潘岳、潘尼）、**一左**（左思）。太康诗风**重辞采、讲对偶**，趋于繁缛华丽。其中陆机、潘岳成就最高，左思的《咏史》诗风力遒劲，《三都赋》使“洛阳纸贵”，潘岳《悼亡诗》写亡妻之痛。","pts":["钟嵘《诗品序》，西晋太康年间","三张、二陆、两潘、一左","重辞采；左思《三都赋》，潘岳《悼亡诗》"],"members":[["三张","张载、张协、张亢"],["二陆","陆机、陆云，陆机作《文赋》"],["两潘","潘岳、潘尼，潘岳作《悼亡诗》"],["一左","左思，《三都赋》《咏史》"]],"mem":"数字就是人数：3+2+2+1=8人。口诀“三张二陆两潘一左”，直接背。再配代表作：陆机《文赋》，潘岳《悼亡》，左思《三都》，各抓一个。","mix":"“三张”指张载、张协、张亢，不含张华、张翰；陆机、陆云兄弟称“二陆”；潘岳、潘尼叔侄称“两潘”。","mcq":[{"q":"“洛阳纸贵”的典故与哪位诗人有关","o":["陆机","潘岳","张协","左思"],"a":3,"w":"左思作《三都赋》，豪贵之家竞相传抄，洛阳纸为之贵。"}],"rel":[{"t":"左思","n":"一左"},{"t":"陆机","n":"二陆之首"},{"t":"钟嵘《诗品》","n":"出处所在"},{"t":"建安文学与三曹","n":"前一时期"}],"more":"洛阳纸贵：左思《三都赋》。\n潘岳《悼亡诗》：怅怳如或存，周遑忡惊惕。\n陆机《文赋》：诗缘情而绮靡。","exam":[]},{"id":"a03-016","t":"正始文学与阮籍《咏怀诗》","cid":"03c","p":3,"kind":"流派","alias":["正始文学","正始之音"],"one":"三国魏正始年间由阮籍、嵇康主导的玄思隐晦托兴诗风流派。","ans":"正始文学指**魏正始年间**以**阮籍、嵇康**为代表的文学流派。受司马氏高压统治，文风由建安慷慨转向**崇尚老庄、旨趣幽深**。代表作**阮籍《咏怀诗》八十二首**采用比兴寄托，辞旨隐微，忧思深广，确立了五言诗**政治抒情与隐晦托兴**的经典范式。","pts":["魏正始年间文学，以阮籍、嵇康为代表","受政局高压与玄风影响，诗风旨深辞隐","阮籍《咏怀诗》八十二首开创政治托兴抒情传统"],"mem":"正始阮嵇老庄风，咏怀八二夜弹琴；辞深意隐避诛戮，五言托兴传千古。","mix":"建安文学主‘建安风骨’，慷慨悲凉；正始文学因司马氏专政，转向‘旨趣幽深、隐晦托兴’；嵇康另有散文名作《与山巨源绝交书》。","mcq":[{"q":"正始文学代表作家阮籍创作的托兴幽微、辞旨深隐的五言政治抒情组诗是","o":["《拟行路难》","《古诗十九首》","《三都赋》","《咏怀诗》"],"a":3,"w":"阮籍作《咏怀诗》八十二首，是正始文学托兴幽微的代表作。"}],"rel":[{"t":"竹林七贤","n":"正始作家所属群体"},{"t":"嵇康","n":"正始文学代表并称"},{"t":"建安文学与三曹","n":"前承建安诗风"}],"more":"代表作家与作品：\n阮籍：《咏怀诗》八十二首（“夜中不能寐，起坐弹鸣琴”）\n嵇康：《与山巨源绝交书》《幽愤诗》","exam":[]},{"id":"a03-017","t":"玄言诗与游仙诗","cid":"03c","p":3,"kind":"流派","alias":["玄言诗","游仙诗"],"one":"魏晋时期受玄道思潮影响兴起的说理玄言诗与寄托超脱的游仙诗派。","ans":"玄言诗与游仙诗是**魏晋受玄学道教影响**的重要诗派。玄言诗在**东晋**极盛，以**孙绰、许询**为代表，重阐老庄义理，钟嵘评其**“理过其辞，淡乎寡味”**；游仙诗借仙游寄托超脱，以**郭璞《游仙诗》**成就最高。两派促成了南朝山水诗的兴起。","pts":["东晋玄言诗推演老庄义理，以孙绰、许询为代表","钟嵘《诗品》讥玄言诗“理过其辞，淡乎寡味”","郭璞《游仙诗》借仙遁世，促成后世山水诗崛起"],"mem":"孙许玄言淡寡味，郭璞游仙寄不平；玄理过词终觉燥，灵运山水代之兴。","mix":"东晋玄言诗特点是‘理过其辞，淡乎寡味’（钟嵘语）；游仙诗代表作是郭璞《游仙诗》十四首；山水诗是玄言诗向山水审美转化的结果。","mcq":[{"q":"南朝文论家钟嵘在《诗品》中评价东晋玄言诗的弊端是","o":["骨气奇高，词采华茂","采缛于旨，辞浮于义","理过其辞，淡乎寡味","文质彬彬，风骨凛然"],"a":2,"w":"钟嵘《诗品》批评东晋玄言诗‘理过其辞，淡乎寡味’。"}],"rel":[{"t":"钟嵘《诗品》","n":"评点玄言诗"},{"t":"谢灵运","n":"山水诗取代玄言诗"},{"t":"竹林七贤","n":"魏晋玄风渊源"}],"more":"郭璞《游仙诗》名句：翡翠戏兰苕，容色更相鲜。绿萝结高林，蒙笼独婵娟。","exam":[]},{"id":"a03-018","t":"陶渊明作品：《归去来兮辞》《桃花源记》《饮酒》","cid":"03c","p":2,"kind":"作品","alias":["《归去来兮辞》","《桃花源记》","《饮酒》","归去来兮辞","桃花源记"],"one":"陶渊明三类代表作：辞《归去来兮辞》、文《桃花源记》、诗《饮酒》。","ans":"陶渊明代表作有三种体裁。**《归去来兮辞》**写于**东晋义熙元年（405）**辞去彭泽令之时，抒写归隐田园的喜悦；**《桃花源记》**是《桃花源诗》的序言，描绘无剥削、无战乱的理想社会；**《饮酒》二十首**以“采菊东篱下，悠然见南山”为名句，寓怀于酒。这些作品开创了**田园诗**，钟嵘称其为**“古今隐逸诗人之宗”**。","pts":["《归去来兮辞》：辞彭泽令，归隐之作","《桃花源记》：理想社会","《饮酒》：采菊东篱下，田园诗"],"mem":"三类三体：归去来兮辞=辞，桃花源记=记(文)，饮酒=诗。“不为五斗米折腰”配《归去来兮辞》，“世外桃源”配《桃花源记》，“采菊东篱”配《饮酒》其五。","mix":"“采菊东篱下，悠然见南山”出自《饮酒》其五，不是《归园田居》；《桃花源记》原是《桃花源诗》序。","mcq":[{"q":"“采菊东篱下，悠然见南山”出自陶渊明的","o":["《饮酒》","《归园田居》","《归去来兮辞》","《桃花源记》"],"a":0,"w":"出自《饮酒二十首》其五。"}],"rel":[{"t":"陶渊明","n":"作者"},{"t":"山水田园诗派","n":"田园诗源头"},{"t":"谢灵运","n":"山水对田园"},{"t":"钟嵘《诗品》","n":"称隐逸之宗"}],"more":"名句：采菊东篱下，悠然见南山。｜《饮酒》其五\n结庐在人境，而无车马喧。｜《饮酒》其五\n归去来兮，田园将芜胡不归。｜《归去来兮辞》\n钟嵘称陶渊明：古今隐逸诗人之宗。","exam":[]},{"id":"a03-019","t":"竟陵八友","cid":"03c","p":3,"kind":"合称","alias":["八友"],"one":"南齐竟陵王萧子良西邸汇聚的八位文士，开创永明体诗歌流派。","ans":"竟陵八友指**南朝齐竟陵王萧子良**西邸八位名士：**萧衍、沈约、谢朓、王融、萧琛、范云、任昉、陆倕**。他们研讨声律，创立**“永明体”新体诗**，主张**声律和谐与辞采并美**。该群体总结四声八病，是古体诗通向唐代近体格律诗的关键枢纽。","pts":["南齐竟陵王萧子良门下八位名士合称","成员含萧衍、沈约、谢朓、王融、任昉等","创立永明体，开创四声八病说，为唐律奠基"],"members":[["萧衍","后代齐建梁，即梁武帝，博学善文"],["沈约","永明体主倡者，倡四声八病，撰《宋书》"],["谢朓","山水诗名家，称“小谢”，作《晚登三山还望京邑》"],["王融","开创永明体声律，辞赋俊美"],["萧琛","工于尺牍表奏，博洽多闻"],["范云","清雅善五言，与沈约友善"],["任昉","以表奏章表见长，与沈约齐名“沈诗任笔”"],["陆倕","工于碑铭制诰，撰《新漏刻铭》"]],"mem":"萧衍沈约小谢融，琛云任陆八友同；西邸研求声律病，永明新体启唐声。","mix":"竟陵八友活动于‘南齐’萧子良门下，萧衍后来成为南朝梁武帝；与明代‘竟陵派’（钟惺、谭元春）无关。","mcq":[{"q":"南齐‘竟陵八友’文人集团中，后来开创南朝梁的开国皇帝是","o":["萧衍","萧道成","萧纲","萧统"],"a":0,"w":"萧衍曾名列竟陵八友，后建立南朝梁，即梁武帝。"}],"rel":[{"t":"谢朓","n":"八友核心诗人"},{"t":"元嘉三大家","n":"南朝诗风承接"},{"t":"“沈宋”与律诗定型","n":"永明体发展为唐律"}],"more":"八友名单：萧衍、沈约、谢朓、王融、萧琛、范云、任昉、陆倕","exam":[]},{"id":"a03-020","t":"南北朝民歌：吴歌西曲与《敕勒歌》","cid":"03c","p":2,"kind":"作品","alias":["吴歌","西曲","《敕勒歌》","《西洲曲》","吴声歌曲","西曲歌"],"one":"南朝民歌（吴歌、西曲）多情歌，北朝民歌刚健，《敕勒歌》为代表。","ans":"南北朝民歌是**乐府民歌的延续**，南北风格不同。**南朝民歌**以**吴声歌曲**（建康一带）和**西曲歌**（长江中游）为主，多写爱情，**清丽婉转**，如《子夜歌》《西洲曲》；**北朝民歌**多写战争、流亡、游牧生活，**刚健豪放**，**《敕勒歌》**的“天苍苍，野茫茫，风吹草低见牛羊”是代表，《木兰诗》也属北朝民歌。它们保存在**《乐府诗集》**中。","pts":["南朝：吴声、西曲，多情歌，清丽","北朝：刚健豪放，《敕勒歌》《木兰诗》","《乐府诗集》收录"],"mem":"南柔北刚：南朝“吴歌西曲”像江南水乡的情歌，北朝像草原上的《敕勒歌》“风吹草低见牛羊”。口诀“南情北刚”，《西洲曲》配南，《木兰诗》《敕勒歌》配北。","mix":"《西洲曲》属南朝，文人化程度较高；《敕勒歌》原为鲜卑语，后译成汉语；《木兰诗》是北朝，不是南朝。","mcq":[{"q":"下列作品属于北朝民歌的是","o":["《子夜歌》","《敕勒歌》","《西洲曲》","《孔雀东南飞》"],"a":1,"w":"《敕勒歌》是北朝民歌；《子夜歌》《西洲曲》是南朝；《孔雀东南飞》是汉乐府。"}],"rel":[{"t":"《木兰诗》","n":"北朝民歌代表"},{"t":"《乐府诗集》","n":"收录总集"},{"t":"乐府与乐府双璧","n":"乐府传统"},{"t":"《玉台新咏》","n":"南朝艳情诗选"}],"more":"名句：天苍苍，野茫茫，风吹草低见牛羊。｜《敕勒歌》\n作品：《子夜歌》《华山畿》《西洲曲》《木兰诗》《敕勒歌》","exam":[]},{"id":"a03-021","t":"江淹与“江郎才尽”","cid":"03c","p":3,"kind":"人物","alias":["江淹","江郎才尽","江文通"],"one":"南朝梁文学家，早年以《恨赋》《别赋》名世，晚年留“江郎才尽”典故。","ans":"江淹（444–505），字文通，**南朝宋齐梁文学家**。他早年精于辞赋，代表作**《别赋》**（“黯然销魂者，唯别而已矣”）与**《恨赋》**写尽哀怨离恨。相传晚年梦郭璞索还五色笔，文思枯竭，留成语**“江郎才尽”**。其赋代表了南朝骈体抒情的高峰。","pts":["南朝文学家，字文通，早年以骈赋名世","代表作《别赋》《恨赋》，抒情清丽","晚年才思退化，留下“江郎才尽”典故"],"mem":"江文通别恨赋销魂，郭璞索还五色笔；晚年无佳作，江郎才尽叹名声。","mix":"江淹代表作为《恨赋》与《别赋》；‘江郎才尽’指才思衰退，典出《南史·江淹传》（梦郭璞索笔或张融索锦）。","mcq":[{"q":"成语‘江郎才尽’中的‘江郎’指的是写有名篇《别赋》《恨赋》的南朝作家","o":["江总","江淹","江斅","江革"],"a":1,"w":"江郎指南朝江淹，早年以辞赋著名，晚年才思减退，留下‘江郎才尽’典故。"}],"rel":[{"t":"鲍照","n":"南朝骈赋先导"},{"t":"庾信","n":"六朝骈赋双璧"},{"t":"徐陵","n":"南朝齐梁文士"}],"more":"代表作：《别赋》《恨赋》《拟咏怀》\n名句：黯然销魂者，唯别而已矣。｜《别赋》","exam":[]},{"id":"a03-022","t":"《与朱元思书》与南朝骈体书信","cid":"03c","p":3,"kind":"作品","alias":["与朱元思书","南朝骈体书信"],"one":"南朝梁吴均所撰写景尺牍名篇，代表南朝山水骈体书札最高成就。","ans":"《与朱元思书》是**南朝梁吴均**创作的骈体写景尺牍。作品描绘富春江富阳至桐庐山水奇貌，名句**“风烟俱净，天山共色”**清拔超俗。它与陶弘景《答谢中书书》、丘迟《与陈伯之书》并为**南朝骈体书信名作**，展示了**骈文描摹自然山水**的极高艺术造诣。","pts":["南朝梁吴均所作骈体写景尺牍","名句“风烟俱净，天山共色”，描摹富春山水","与陶弘景、丘迟书札并为南朝骈体名篇"],"mem":"吴均朱元思风烟净，弘景答谢中书书；丘迟陈伯之草长，南朝骈体写性灵。","mix":"《与朱元思书》是南朝梁吴均所撰；《答谢中书书》是陶弘景所作；丘迟《与陈伯之书》是招抚政论骈文（‘暮春三月，江南草长’）。","mcq":[{"q":"写有名句‘风烟俱净，天山共色。从流飘荡，任意东西’的山水尺牍名篇《与朱元思书》的作者是","o":["陶弘景","丘迟","孔稚珪","吴均"],"a":3,"w":"南朝梁文学家吴均作《与朱元思书》，描绘富春江山水。"}],"rel":[{"t":"谢灵运","n":"山水美学渊源"},{"t":"郦道元","n":"中古山水散文名家"},{"t":"徐庾","n":"南朝骈体文学代表"}],"more":"名篇与名句：\n吴均《与朱元思书》：风烟俱净，天山共色。从流飘荡，任意东西。\n陶弘景《答谢中书书》：山川之美，古来共谈。\n丘迟《与陈伯之书》：暮春三月，江南草长，杂花生树，群莺乱飞。","exam":[]},{"id":"a03-023","t":"钟嵘《诗品》","cid":"03d","p":1,"kind":"作品","alias":["诗品","诗评","钟嵘"],"one":"南朝梁钟嵘撰，评汉至梁五言诗人122人，分上中下三品。","ans":"《诗品》是**南朝梁钟嵘撰写的诗论专著**，是**中国第一部诗论专著**，原名《诗评》。全书评论**汉至梁五言诗人122人**，按**上、中、下三品**分等，并追溯各家源流。钟嵘提倡**“滋味”说**，主张诗要有“指事造形，穷情写物”之味，**反对堆砌用典与过分追求声病**。他评陶渊明为“古今隐逸诗人之宗”，曹植为“建安之杰”。此书对后世诗话影响很大，与《文心雕龙》并称。","pts":["钟嵘撰，第一部诗论专著","评五言诗人122人，分三品","滋味说，反对用典和声病"],"mem":"数字口诀：“一二二”，122人，上中下三品。关键词“滋味”。陶渊明、曹植的评语都要背：陶是“隐逸之宗”，曹植是“建安之杰”。","mix":"《诗品》只评五言诗；《文心雕龙》论文体；《诗品》也有称《诗评》。","mcq":[{"q":"《诗品》的作者是","o":["刘勰","萧统","钟嵘","徐陵"],"a":2,"w":"钟嵘，南朝梁。"},{"q":"《诗品》称陶渊明为","o":["建安之杰","古今隐逸诗人之宗","诗佛","诗圣"],"a":1,"w":"评陶渊明“古今隐逸诗人之宗”。"}],"rel":[{"t":"钟嵘","n":"作者"},{"t":"《文心雕龙》","n":"并称"},{"t":"陶渊明","n":"被评隐逸之宗"},{"t":"曹植","n":"被评建安之杰"},{"t":"《诗艺》","n":"中西诗论对照"}],"more":"上品：古诗、李陵、班婕妤、曹植、刘桢、王粲、阮籍、陆机、潘岳、张协、左思、谢灵运。","exam":[]},{"id":"a03-024","t":"王国维《人间词话》","cid":"03d","p":1,"kind":"作品","alias":["人间词话","境界说"],"one":"王国维词学论著，提出“境界”说，有我之境与无我之境。","ans":"《人间词话》是**近代学者王国维所著的词学评论著作**，1908–1909年发表于《国粹学报》，是**中国古典文论向近代转型的代表作**。核心是**“境界”说**，认为词以境界为上；分**“有我之境”与“无我之境”**，又分**“造境”与“写境”**。书中以三句词比喻**成大事业者的三种境界**：“昨夜西风凋碧树”“衣带渐宽终不悔”“众里寻他千百度”。该书用西方美学观念改造传统词话，影响深远。","pts":["王国维著，1908–1909年发表","境界说，有我无我，造境写境","三种境界"],"mem":"三境界记晏、柳、辛：晏殊“昨夜西风”，柳永“衣带渐宽”，辛弃疾“众里寻他”。有我无我记例子：“泪眼问花花不语”有我；“采菊东篱下”无我。","mix":"《人间词话》论词，严羽《沧浪诗话》论诗；三境界的出处是晏殊、柳永、辛弃疾。","mcq":[{"q":"提出“境界”说的著作是","o":["《文心雕龙》","《沧浪诗话》","《人间词话》","《诗品》"],"a":2,"w":"王国维《人间词话》。"},{"q":"“众里寻他千百度”被王国维用作成大事业的第几种境界","o":["第一种","第二种","第三种","第四种"],"a":2,"w":"第三种，出自辛弃疾《青玉案·元夕》。"}],"rel":[{"t":"王国维","n":"作者"},{"t":"严羽","n":"《沧浪诗话》对照"},{"t":"辛弃疾","n":"第三境界出处"},{"t":"柳永","n":"第二境界出处"},{"t":"《诗学》","n":"中西文论对照"}],"more":"昨夜西风凋碧树，独上高楼，望尽天涯路。｜晏殊\n衣带渐宽终不悔，为伊消得人憔悴。｜柳永\n众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。｜辛弃疾","exam":[]},{"id":"a03-025","t":"诗言志与兴观群怨","cid":"03d","p":2,"kind":"概念","alias":["诗言志","兴观群怨","诗可以兴观群怨"],"one":"诗言志出《尚书·尧典》，兴观群怨出《论语·阳货》，古代文论起点。","ans":"“诗言志”与“兴观群怨”是**中国古代诗论的起点**。**“诗言志”**出自**《尚书·尧典》**，朱自清称之为中国诗论“**开山的纲领**”，强调诗抒写人的志向怀抱。**“兴观群怨”**出自**《论语·阳货》**，孔子说“诗，可以兴，可以观，可以群，可以怨”，指**诗歌具有感发情志、观察得失、交流感情、怨刺时政的作用**。二者奠定了儒家的诗教观念，后来有“诗缘情”“发愤抒情”与之呼应。","pts":["诗言志：《尚书·尧典》，开山的纲领","兴观群怨：《论语·阳货》，孔子","诗的四种功能；儒家诗教起点"],"mem":"兴观群怨四个字对应四个动作：兴=感发，观=观察，群=合群，怨=怨刺。记“言志在书(尚书)，兴观在论(论语)”。","mix":"“诗缘情”出自陆机《文赋》，与“诗言志”并立；“诗言志”出自《尚书》，不是《诗经》。","mcq":[{"q":"“诗言志”最早见于","o":["《论语》","《诗大序》","《文赋》","《尚书·尧典》"],"a":3,"w":"《尚书·尧典》：诗言志，歌永言。"}],"rel":[{"t":"《论语》","n":"兴观群怨出处"},{"t":"《诗经》","n":"诗教对象"},{"t":"陆机《文赋》","n":"诗缘情对举"},{"t":"《诗学》","n":"西方诗论对照"}],"more":"诗言志，歌永言，声依永，律和声。｜《尚书·尧典》\n诗，可以兴，可以观，可以群，可以怨。｜《论语·阳货》\n诗缘情而绮靡。｜陆机《文赋》","exam":[]},{"id":"a03-026","t":"文以明道与文以载道","cid":"03d","p":2,"kind":"概念","alias":["文以明道","文以载道","载道说"],"one":"文以明道出韩愈、柳宗元，文以载道出周敦颐《通书》。","ans":"“文以明道”与“文以载道”是**古代散文的重要理论**。**“文以明道”**由**韩愈、柳宗元**在**古文运动**中倡导，主张文章用来阐明儒家之道，文与道并重；**“文以载道”**是**北宋周敦颐**在**《通书》**中提出的，说“文所以载道也”，把文章看作传道的工具，更偏重“道”。二者体现了**文学与儒家思想的关系**，影响了宋明理学家的文论。","pts":["文以明道：韩愈、柳宗元","文以载道：周敦颐《通书》","文与道关系，古文运动背景"],"mem":"一个“明”(明白)一个“载”(装载)：明道是让文章把道讲明白，载道是文章像车子装着道。人物记“韩柳明，周载”。","mix":"载道说偏重道，轻文；明道说文道并重，不要混淆；韩愈还有“不平则鸣”的文论。","mcq":[{"q":"“文以载道”的提出者是","o":["周敦颐","韩愈","柳宗元","欧阳修"],"a":0,"w":"周敦颐《通书》：文所以载道也。"}],"rel":[{"t":"古文运动","n":"明道的背景"},{"t":"韩愈","n":"倡导者"},{"t":"柳宗元","n":"倡导者"},{"t":"周敦颐","n":"载道说提出者"}],"more":"文所以载道也。｜周敦颐《通书·文辞》","exam":[]},{"id":"a03-027","t":"陆机《文赋》","cid":"03d","p":3,"kind":"作品","alias":["文赋"],"one":"西晋陆机创作的骈赋体文论，中国首篇系统探讨创作过程的专著。","ans":"《文赋》是**西晋陆机**所作骈赋体文论，是**首篇系统论述创作过程的专论**。作品深入剖析艺术构思，描摹“精鹜八极，心游万仞”，提出**“诗缘情而绮靡，赋体物而浏亮”**名论。它开创了古代文学构思论与创作论之先河。","pts":["西晋陆机所撰骈赋，首篇系统文学创作论","论述灵感构思，“精鹜八极，心游万仞”","文体论断“诗缘情而绮靡，赋体物而浏亮”"],"mem":"陆机文赋谈构思，情缘绮靡赋体浏；心游万仞鹜八极，首部创作心理论。","mix":"曹丕《典论·论文》是我国第一部文人专门性文学批评单篇；陆机《文赋》是我国第一篇系统探讨文学创作心理过程的文论（赋体）；刘勰《文心雕龙》是我国第一部文学理论巨著。","mcq":[{"q":"提出‘诗缘情而绮靡，赋体物而浏亮’著名文体风格论断的古代文论著作是","o":["曹丕《典论·论文》","钟嵘《诗品》","刘勰《文心雕龙》","陆机《文赋》"],"a":3,"w":"西晋陆机在《文赋》中提出‘诗缘情而绮靡，赋体物而浏亮’。"}],"rel":[{"t":"陆机","n":"文赋作者"},{"t":"曹丕《典论·论文》","n":"早期文论源流对照"},{"t":"《文心雕龙》","n":"南北朝文论集大成者"}],"more":"名句：\n诗缘情而绮靡，赋体物而浏亮。\n精鹜八极，心游万仞。观古今于须臾，抚四海于一瞬。\n恒患意不称物，文不逮意。","exam":[]},{"id":"a03-028","t":"《二十四诗品》","cid":"03d","p":3,"kind":"作品","alias":["二十四诗品","司空图二十四诗品"],"one":"旧题晚唐司空图撰、以四言韵语论述二十四种诗歌风格的美学名著。","ans":"《二十四诗品》**旧题晚唐司空图撰**（学界有明代伪托争议），是一部诗歌美学专论。全书以**四言韵语**描摹意境，将诗歌艺术风格分为**雄浑、冲淡、高古、自然**等二十四品。作品追求**“不著一字，尽得风流”**与象外之象，深刻启发了明清诗学的神韵派。","pts":["旧题晚唐司空图撰，论述二十四种诗歌美学风格","四言韵语写意，列雄浑、冲淡、高古、自然等品第","追求“不著一字，尽得风流”，深启神韵派"],"mem":"二十四品司空图，四言韵语写风骨；雄浑冲淡自然境，不著一字得风流。","mix":"《二十四诗品》传统题为唐司空图撰，当代考据（陈尚君等）倾向于明代怀悦伪托，考试以通行题名司空图为准；钟嵘《诗品》分三品评诗人，而《二十四诗品》评诗歌美学风格。","mcq":[{"q":"传统题为晚唐司空图所作、以四言韵语论述雄浑、冲淡、自然等二十四种风格的诗论著作是","o":["《六一诗话》","《诗品》","《二十四诗品》","《沧浪诗话》"],"a":2,"w":"《二十四诗品》旧题晚唐司空图撰，以四言韵语系统描绘二十四种诗学品格。"}],"rel":[{"t":"钟嵘《诗品》","n":"古代诗品著作对照"},{"t":"严羽","n":"诗歌妙悟神韵渊源"},{"t":"《文心雕龙》","n":"古代文论体系对照"}],"more":"二十四品目：雄浑、冲淡、纤秾、沉着、高古、典雅、洗炼、劲健、绮丽、自然、含蓄、豪放、精神、缜密、疏野、清奇、委曲、实境、悲慨、形容、超诣、飘逸、旷达、流动。\n名论：不著一字，尽得风流。行神如空，行气如虹。","exam":[]},{"id":"a03-029","t":"欧阳修《六一诗话》","cid":"03d","p":3,"kind":"作品","alias":["六一诗话"],"one":"北宋欧阳修所撰诗评笔记，中国文学史上首部以“诗话”命名的著作。","ans":"《六一诗话》是**北宋欧阳修**所撰诗评随笔，是**首部以“诗话”命名的著作**。作品以条记漫笔品评掌故与诗作工拙，推崇**“状难写之景如在目前，含不尽之意见于言外”**。它开创了随笔式的**“诗话体”**，对后世文学批评影响极深。","pts":["北宋欧阳修晚年所撰，首部以“诗话”命名之作","开创随笔式“诗话体”，品评轶事与工拙","主张“状难写之景如在目前，含不尽之意见于言外”"],"mem":"六一居士开诗话，随笔评诗第一家；难写之景如在目，不尽之意见言外。","mix":"《六一诗话》是‘第一部以诗话命名的著作’，开创诗话体；钟嵘《诗品》是我国‘第一部诗歌品评专著’，分上中下三品，体裁完全不同。","mcq":[{"q":"中国文学史上第一部以‘诗话’命名的诗歌评论专著是","o":["严羽《沧浪诗话》","欧阳修《六一诗话》","钟嵘《诗品》","王国维《人间词话》"],"a":1,"w":"北宋欧阳修作《六一诗话》，开创了中国古典文学批评中的‘诗话’体制。"}],"rel":[{"t":"欧阳修","n":"著作作者"},{"t":"严羽","n":"宋代诗话后继高峰"},{"t":"钟嵘《诗品》","n":"诗论体制对照"}],"more":"名论：状难写之景如在目前，含不尽之意见于言外，然后为至矣。\n影响：开启宋代诗话繁盛之风，后有司空图、严羽、后山等百余种诗话。","exam":[]},{"id":"a03-030","t":"《全唐诗》","cid":"03d","p":2,"kind":"作品","alias":["全唐诗"],"one":"清康熙年间曹寅主持刊刻，收唐五代诗四万八千余首。","ans":"《全唐诗》是**清康熙年间编成的唐代诗歌总集**，由**曹寅**主持刊刻，**彭定求**等人编校，共**九百卷**，收诗**四万八千九百余首**，作者**二千二百余人**，是**唐诗最完备的总集**。它以明代胡震亨《唐音统签》和清初季振宜《唐诗》（又称《全唐诗稿》）为基础，按帝王、后妃、诸王及作者顺序编排，对研究唐诗不可缺少。","pts":["清康熙年间，曹寅主持，彭定求等编校","诗四万八千余首，作者两千二百余人","唐诗最完备总集"],"mem":"数字：4.8万首，2200人，900卷。可与《唐诗三百首》对比：三百首是选本，《全唐诗》是全集。“曹寅(《红楼梦》作者曹雪芹祖父)刊刻”也可作联想。","mix":"《全唐诗》是总集，《唐诗三百首》是清代蘅塘退士的选本；彭定求编校，曹寅刊刻。","mcq":[{"q":"《全唐诗》收诗数量约为","o":["三百余首","四万八千余首","四千八百首","四十八万首"],"a":1,"w":"约四万八千九百余首。"}],"rel":[{"t":"《唐诗三百首》","n":"选本对照"},{"t":"《古文观止》","n":"同代选本"},{"t":"唐朝（唐代）","n":"所收时代"},{"t":"《乐府诗集》","n":"其他诗歌总集"}],"more":"康熙四十四年(1705)曹寅奉敕在扬州刊刻。","exam":[]},{"id":"a03-031","t":"《古文观止》","cid":"03d","p":2,"kind":"作品","alias":["古文观止"],"one":"清吴楚材、吴调侯选编的散文选本，收222篇。","ans":"《古文观止》是**清康熙年间吴楚材、吴调侯叔侄选编的古文选本**，共**十二卷**，收录自**先秦至明代的散文二百二十二篇**，按时代编排。选文有《郑伯克段于鄢》《出师表》《桃花源记》《岳阳楼记》等，**文体多样、篇幅精当**，既选名家名篇，又重文章的思想与文采。它是**流传最广的古代散文普及读本**，影响了几代学子。","pts":["清吴楚材、吴调侯编","先秦至明散文222篇","最流行的古文普及读本"],"mem":"222=“二二二”，对应“二吴”：吴楚材、吴调侯两位吴姓叔侄。“观止”出自《左传》季札观乐，“观止矣”，意思是看到这里就够了，好得无以复加。","mix":"《古文观止》是散文选本，《唐诗三百首》是诗选；《古文观止》选文不含唐以前的诗。","mcq":[{"q":"《古文观止》共收文章","o":["一百一十一篇","三百篇","二百二十二篇","四百篇"],"a":2,"w":"共222篇。"}],"rel":[{"t":"《左传》","n":"所选首篇出处"},{"t":"《唐诗三百首》","n":"诗歌选本对照"},{"t":"《全唐诗》","n":"同代总集"},{"t":"唐宋八大家","n":"选文大宗"}],"more":"“观止”典出《左传》季札观乐：观止矣！若有他乐，吾不敢请已。","exam":[]},{"id":"a03-032","t":"《千家诗》","cid":"03d","p":3,"kind":"作品","alias":["千家诗"],"one":"中国古代著名的蒙学诗歌选本，旧题南宋江湖派诗人刘克庄编选。","ans":"《千家诗》是**古代蒙学诗歌选本**，旧题**南宋刘克庄**选编。全书辑录唐宋名家近体绝句与律诗，按**五绝、七绝、五律、七律**编次，多写四时风物，通俗易诵。它与《三字经》《百家姓》《千字文》并称**“三百千千”**蒙学读物。","pts":["古代经典蒙学诗选，旧题南宋刘克庄编","主收唐宋近体诗，按五绝七绝律诗分卷","通俗易诵，与“三百千”并称“三百千千”"],"mem":"三百千后千家诗，克庄旧题选绝律；四时景物童蒙诵，易记易传发幼蒙。","mix":"《千家诗》旧题宋刘克庄编，专选唐宋近体诗（以绝句律诗为主），定位是启蒙读本；《唐诗三百首》是清代孙洙编，专选唐诗，体例更为严整典雅。","mcq":[{"q":"古代传统蒙学诗选《千家诗》旧题选编者是南宋江湖派著名诗人","o":["刘克庄","戴复古","严羽","姜夔"],"a":0,"w":"《千家诗》旧题南宋刘克庄编选（后世多有增补）。"}],"rel":[{"t":"《唐诗三百首》","n":"启蒙诗学选本对照"},{"t":"《全唐诗》","n":"唐代诗歌文献总集"},{"t":"严羽","n":"南宋同时代诗学人物"}],"more":"名篇举隅：程颢《春日偶成》（云淡风轻近午天）、朱熹《春日》（胜日寻芳泗水滨）、杜牧《清明》（清明时节雨纷纷）","exam":[]},{"id":"a03-033","t":"古体诗与近体诗（格律诗）","cid":"03e","p":1,"kind":"概念","alias":["近体诗","古体诗","格律诗","律诗","绝句"],"one":"近体诗唐代定型，讲平仄对仗押韵，分律诗绝句；古体诗格律自由。","ans":"古体诗与近体诗是**中国古典诗歌的两大体式**。**近体诗又称格律诗，唐代定型**，讲究平仄、对仗和押韵，分**律诗（八句，中间两联对仗）、绝句（四句）和排律**，每类又有五言七言之分。**古体诗**产生较早，句数、平仄、用韵较自由，包括**歌行体和乐府诗**，如李白《蜀道难》、白居易《长恨歌》。“沈宋”对律诗定型有贡献，杜甫的七律成就最高。近体诗奠定了唐诗的基本格局。","pts":["近体诗唐代定型，讲平仄对仗押韵","律诗八句、绝句四句、排律","古体诗自由，含歌行与乐府"],"mem":"数字：律诗八句，绝句四句，律诗“颔联、颈联”对仗（中二联）。口诀“律八绝四排律长”。区分：近体看格律，古体看自由，乐府歌行多属古体。","mix":"唐人的古体诗仍然很多，不是只有近体；“沈宋”（沈佺期、宋之问）是律诗定型的关键人物。","mcq":[{"q":"下列关于近体诗的说法，正确的是","o":["产生于汉代","不讲平仄","绝句共八句","律诗共八句"],"a":3,"w":"律诗八句，中二联对仗；绝句四句。"},{"q":"下列属于古体诗（歌行体）的是","o":["《春望》","《山居秋暝》","《蜀道难》","《静夜思》"],"a":2,"w":"《蜀道难》是李白乐府歌行，其余多为律诗绝句（《春望》五律，《山居秋暝》五律，《静夜思》五绝）。"}],"rel":[{"t":"“沈宋”与律诗定型","n":"律诗定型"},{"t":"杜甫","n":"七律集大成"},{"t":"乐府与乐府双璧","n":"古体来源之一"},{"t":"唐诗分期：初唐、盛唐、中唐、晚唐","n":"唐诗分期"},{"t":"莎士比亚十四行诗","n":"中西格律诗对照"}],"more":"五律、七律、五绝、七绝；排律即长律，十句以上。","exam":[]},{"id":"a03-034","t":"“沈宋”与律诗定型","cid":"03e","p":2,"kind":"合称","alias":["沈宋","沈佺期","宋之问"],"one":"初唐沈佺期、宋之问，完成五言律诗格律的定型。","ans":"“**沈宋**”指**初唐诗人沈佺期与宋之问**，二人活动于武则天至唐中宗时期，同为宫廷诗人，诗风华丽。他们总结前人**永明体**以来的声律经验，讲究**平仄、粘对和对仗**，使**五言律诗的格律最终定型**，也推动七律的成熟，是**近体诗确立**的重要标志。沈佺期有《独不见》，宋之问有《题大庾岭北驿》，二人都曾流放岭南，晚期诗风转向悲凉。","pts":["沈佺期、宋之问，初唐宫廷诗人","总结声律，五言律诗格律定型","近体诗确立的标志"],"members":[["沈佺期","七律《独不见》，曾流放驩州"],["宋之问","《题大庾岭北驿》，曾流放岭南"]],"mem":"逻辑线：南朝沈约讲四声八病（永明体），初唐沈佺期把声律定成律诗，所以一个“沈”开头，一个“沈”收束。口诀：沈约开声律，沈宋定律诗，杜甫写到最高。","mix":"沈宋的“沈”是沈佺期，与南朝沈约不是同一人；初唐四杰推动五律，沈宋使之定型。","mcq":[{"q":"使五言律诗格律最终定型的初唐诗人是","o":["王勃、杨炯","陈子昂、张若虚","沈佺期、宋之问","李白、杜甫"],"a":2,"w":"沈佺期、宋之问合称“沈宋”，是近体诗定型的关键人物。"}],"rel":[{"t":"古体诗与近体诗（格律诗）","n":"律诗定型的结果"},{"t":"初唐四杰","n":"先于沈宋推动五律"},{"t":"陈子昂","n":"同时期反对绮靡诗风"},{"t":"杜甫代表作与“沉郁顿挫”","n":"律诗艺术的高峰"}],"exam":[]},{"id":"a03-035","t":"文章四友","cid":"03e","p":3,"kind":"合称","alias":["初唐文章四友"],"one":"初唐文人李峤、苏味道、崔融、杜审言四人的合称。","ans":"文章四友指**初唐武后时期文人李峤、苏味道、崔融、杜审言**。四人以**五言律诗和应制咏物**见长，苏味道与李峤并称“**苏李**”，杜审言为**杜甫祖父**。四人努力摆脱齐梁绮靡文风，是**齐梁余风向盛唐诗风过渡的重要推手**。","pts":["李峤、苏味道、崔融、杜审言四人","活跃于武后时期，杜审言为杜甫祖父","推进五律与咏物诗，齐梁向盛唐过渡"],"members":[["李峤","擅长咏物诗，前人辑有《李峤杂咏》百首"],["苏味道","与李峤并称“苏李”，留有“模棱两可”典故"],["崔融","善于撰写朝廷制诰与碑铭"],["杜审言","杜甫祖父，排律大家，代表作《和晋陵陆丞早春游望》"]],"mem":"首字串联“**李苏崔杜**”（李峤、苏味道、崔融、杜审言）。关注杜审言是杜甫的祖父，苏味道留有“模棱两可”成语典故。","mix":"杜审言是杜甫的祖父，勿与晚唐“小李杜”的杜牧混淆；李峤与苏味道并称“苏李”，不同于汉代“苏李”（苏武与李陵）。","mcq":[{"q":"初唐“文章四友”中，身为著名诗人杜甫祖父的是","o":["杜审言","李峤","苏味道","崔融"],"a":0,"w":"杜审言是初唐“文章四友”之一，为诗圣杜甫的祖父。"}],"rel":[{"t":"杜甫","n":"杜审言为其祖父"},{"t":"“沈宋”与律诗定型","n":"初唐律诗发展同阶段"},{"t":"初唐四杰","n":"初唐诗坛群体对照"}],"exam":[]},{"id":"a03-036","t":"唐代诗人称号：诗仙、诗圣、诗佛、诗鬼、诗豪、诗魔","cid":"03e","p":1,"kind":"合称","alias":["诗仙诗圣诗佛","诗仙","诗圣","诗佛","诗鬼","诗豪","诗魔","诗囚","诗奴","七绝圣手"],"one":"李白诗仙，杜甫诗圣，王维诗佛，李贺诗鬼，刘禹锡诗豪，白居易诗魔。","ans":"唐代诗人称号是后人对不同风格诗人的雅称：**李白称“诗仙”，杜甫称“诗圣”，王维称“诗佛”，李贺称“诗鬼”，刘禹锡称“诗豪”，白居易称“诗魔”**。此外，**王昌龄称“七绝圣手”，孟郊称“诗囚”，贾岛称“诗奴”**，二人又合称“郊寒岛瘦”。杜诗又被称为“**诗史**”。这些称号分别概括了诗人的风格：李白豪放浪漫，杜甫沉郁现实，王维空灵禅意，李贺奇诡冷艳。","pts":["诗仙李白，诗圣杜甫，诗佛王维","诗鬼李贺，诗豪刘禹锡，诗魔白居易","七绝圣手王昌龄，诗囚孟郊，诗奴贾岛"],"members":[["李白","诗仙"],["杜甫","诗圣，诗史"],["王维","诗佛"],["李贺","诗鬼"],["刘禹锡","诗豪"],["白居易","诗魔"]],"mem":"按朝代顺序记“仙圣佛、鬼豪魔”：盛唐三位（李杜王）仙圣佛；中唐三位（贺禹居）鬼豪魔。画面：李白飘然像仙，杜甫忧民像圣，王维礼佛像佛，李贺幽冷像鬼，刘禹锡昂扬像豪，白居易写诗成痴像魔。","mix":"“诗豪”是刘禹锡，不是李白；“诗魔”白居易，不是李贺；“小李杜”是李商隐、杜牧。","mcq":[{"q":"被称为“诗鬼”的唐代诗人是","o":["李白","李贺","李商隐","杜牧"],"a":1,"w":"李贺，“长吉体”。"},{"q":"被称为“诗豪”的是","o":["白居易","元稹","刘禹锡","韩愈"],"a":2,"w":"刘禹锡，《陋室铭》作者。"}],"rel":[{"t":"李白","n":"诗仙"},{"t":"杜甫","n":"诗圣"},{"t":"王维","n":"诗佛"},{"t":"李贺","n":"诗鬼"},{"t":"刘禹锡","n":"诗豪"},{"t":"白居易","n":"诗魔"}],"more":"七绝圣手王昌龄；郊寒岛瘦指孟郊、贾岛；杜诗称诗史。","exam":[]},{"id":"a03-037","t":"杜甫“三吏”“三别”","cid":"03e","p":2,"kind":"作品","alias":["三吏三别","三吏","三别","新安吏","石壕吏","潼关吏","新婚别","垂老别","无家别"],"one":"杜甫写安史之乱民生疾苦的六首叙事诗。","ans":"“三吏”“三别”是**杜甫**在**安史之乱**中创作的六首叙事诗，作于乾元二年（759）由洛阳返华州途中。**“三吏”为《新安吏》《石壕吏》《潼关吏》，“三别”为《新婚别》《垂老别》《无家别》**，以所见所闻写官吏抓丁、百姓被迫从军、家破人亡的惨状，同时也表现对平叛战争的支持。诗歌以写实见长，真实反映时代，使杜甫的诗被称为“**诗史**”，是**现实主义**诗歌的典范。","pts":["三吏：新安吏、石壕吏、潼关吏","三别：新婚别、垂老别、无家别","安史之乱，现实主义，诗史"],"members":[["新安吏","写新安县征召少年入伍"],["石壕吏","夜宿石壕村，老妇应役"],["潼关吏","写潼关筑城守备"],["新婚别","新娘送新郎出征"],["垂老别","老翁抛家从军"],["无家别","战后归乡者无家可归"]],"mem":"口诀：“吏”记地名，“别”记人。三吏地名：新安、石壕、潼关（一个县，一个村，一个关）；三别人物：新婚、垂老、无家（新郎，老人，归乡人）。顺序按“新、石、潼；婚、老、无”。","mix":"《潼关吏》是诗人向守关小吏问话，对象是官吏；《新婚别》《垂老别》《无家别》则以百姓口吻自述。《兵车行》《丽人行》是天宝年间的作品，写于安史之乱之前，不属于三吏三别。","mcq":[{"q":"下列作品中不属于“三别”的是","o":["《新婚别》","《垂老别》","《无家别》","《石壕吏》"],"a":3,"w":"《石壕吏》属于“三吏”，三别是新婚别、垂老别、无家别。"}],"rel":[{"t":"杜甫","n":"作者"},{"t":"杜甫代表作与“沉郁顿挫”","n":"同属杜甫作品"},{"t":"现实主义","n":"写实诗风的体现"},{"t":"白居易与新乐府运动","n":"继承杜甫写实传统"}],"exam":[]},{"id":"a03-038","t":"饮中八仙","cid":"03e","p":3,"kind":"合称","alias":["醉中八仙","酒中八仙"],"one":"杜甫《饮中八仙歌》所描绘的盛唐李白、贺知章等八位豪饮名士。","ans":"饮中八仙指**杜甫名篇《饮中八仙歌》**所描绘的盛唐八位嗜酒名士，包括**贺知章、李琎、李适之、崔宗之、苏晋、李白、张旭、焦遂**。诗作以歌行体生动展现了李白斗酒诗百篇、张旭狂草挥毫等豪迈群像，**生动体现了盛唐士人狂放不羁的时代气象**。","pts":["杜甫《饮中八仙歌》描写的八位盛唐名士","包括李白、贺知章、草圣张旭等八人","生动体现盛唐士人狂放不羁的风度"],"members":[["贺知章","知章骑马似乘船，白眼望青天"],["李琎","汝阳王，汝阳三斗始朝天"],["李适之","左相，左相日兴费万钱"],["崔宗之","宗之潇洒美少年，举觞白眼望青天"],["苏晋","苏晋长斋绣佛前，醉中往往爱逃禅"],["李白","李白斗酒诗百篇，长安市上酒家眠"],["张旭","张旭三杯草圣传，脱帽露顶王公前"],["焦遂","焦遂五斗方卓然，高谈雄辩惊四筵"]],"mem":"杜甫诗句记忆群像：**李白斗酒**、**张旭脱帽**、**知章乘船**。考点核心是此合称出自**杜甫**笔下的盛唐朋友圈群像诗。","mix":"常考《饮中八仙歌》的作者是杜甫而非李白；饮中八仙名单中没有高适、王维、孟浩然。","mcq":[{"q":"杜甫在《饮中八仙歌》中形容“脱帽露顶王公前，挥毫落纸如云烟”的草圣是","o":["李白","张旭","贺知章","崔宗之"],"a":1,"w":"杜甫诗句描写草圣张旭嗜酒挥毫的狂放情态。"}],"rel":[{"t":"杜甫","n":"《饮中八仙歌》作者"},{"t":"李白","n":"八仙中最著名者"},{"t":"贺知章","n":"八仙之一"},{"t":"张旭、怀素","n":"八仙之一草圣张旭"}],"exam":[]},{"id":"a03-039","t":"盛唐边塞诗四大家","cid":"03e","p":3,"kind":"合称","alias":["边塞四大家"],"one":"盛唐边塞诗派核心代表高适、岑参、王昌龄、李颀四人的合称。","ans":"盛唐边塞诗四大家指**盛唐边塞诗派代表人物高适、岑参、王昌龄、李颀**。高适与岑参并称“**高岑**”，兼具雄壮苍凉与奇丽奔放；王昌龄被称为“**七绝圣手**”；李颀擅长七言歌行。四人多有从军经历，将边塞诗推向**唐代军旅抒情文学的最高峰**。","pts":["高适、岑参、王昌龄、李颀四人","高适岑参并称高岑，王昌龄为七绝圣手","代表盛唐边塞诗派最高成就"],"members":[["高适","《燕歌行》《别董大》，风格雄浑悲壮、质朴苍凉"],["岑参","《白雪歌送武判官归京》，善写奇寒风雪、瑰丽奇谲"],["王昌龄","《出塞》《从军行》，七绝造诣极深，称“七绝圣手”"],["李颀","《古从军行》《听董大弹胡笳声兼语弄寄房给事》，擅七言歌行"]],"mem":"首字口诀“**高岑王李**”（高适、岑参、王昌龄、李颀）。王之涣（黄河远上白云间）和王翰（葡萄美酒夜光杯）虽有边塞名篇，但不在四大家内。","mix":"王之涣、王翰虽作有著名的《凉州词》，但不属于边塞四大家；盛唐边塞派与王孟山水田园派并峙双峰。","mcq":[{"q":"下列盛唐诗人中，不属于“盛唐边塞诗四大家”的是","o":["高适","岑参","王之涣","李颀"],"a":2,"w":"边塞四大家是高适、岑参、王昌龄、李颀；王之涣有边塞名作，但不在其列。"}],"rel":[{"t":"高适","n":"边塞诗领军人物"},{"t":"岑参","n":"与高适并称高岑"},{"t":"王昌龄","n":"七绝圣手"},{"t":"山水田园诗派","n":"盛唐两大并立诗派"}],"exam":[]},{"id":"a03-040","t":"李白代表作","cid":"03e","p":2,"kind":"作品","alias":["蜀道难","将进酒","梦游天姥吟留别","静夜思","早发白帝城","行路难"],"one":"李白代表作：《蜀道难》《将进酒》《梦游天姥吟留别》等。","ans":"李白（701–762）是**盛唐浪漫主义诗人**，号青莲居士，被贺知章称为“**谪仙人**”，后世称“**诗仙**”。他的代表作有乐府歌行《**蜀道难**》《**将进酒**》《**行路难**》，游仙诗《**梦游天姥吟留别**》，以及小诗《**静夜思**》《**早发白帝城**》。诗风想象奇特，语言奔放，气势雄浑，是**盛唐浪漫主义**的最高成就，与杜甫并称“李杜”。","pts":["《蜀道难》《将进酒》《行路难》","《梦游天姥吟留别》《静夜思》《早发白帝城》","谪仙人（贺知章），诗仙，浪漫主义"],"mem":"按题材分三类记：乐府歌行（蜀道难、将进酒、行路难，共同点是“难”和“酒”），游仙诗（梦游天姥），小诗（静夜思、早发白帝城，都是四句）。“谪仙人”的来历是贺知章读《蜀道难》后的惊叹。","mix":"“天生我材必有用”出自《将进酒》；《梦游天姥吟留别》“安能摧眉折腰事权贵”；杜甫《春望》《登高》不是李白作品。","mcq":[{"q":"“朝辞白帝彩云间，千里江陵一日还”出自","o":["杜甫《登高》","王维《送元二使安西》","李白《早发白帝城》","王昌龄《出塞》"],"a":2,"w":"此为李白《早发白帝城》。"}],"rel":[{"t":"李白","n":"作者"},{"t":"杜甫代表作与“沉郁顿挫”","n":"与李白并称“李杜”"},{"t":"浪漫主义","n":"中外浪漫诗人对照"},{"t":"拜伦","n":"中外浪漫主义对照"}],"more":"名句：天生我材必有用，千金散尽还复来。｜《将进酒》\n安能摧眉折腰事权贵，使我不得开心颜。｜《梦游天姥吟留别》\n长风破浪会有时，直挂云帆济沧海。｜《行路难》\n作品：《蜀道难》《将进酒》《行路难》《梦游天姥吟留别》《静夜思》《早发白帝城》","exam":[]},{"id":"a03-041","t":"杜甫代表作与“沉郁顿挫”","cid":"03e","p":2,"kind":"作品","alias":["沉郁顿挫","春望","登高","茅屋为秋风所破歌","兵车行","丽人行"],"one":"杜甫代表作《春望》《登高》《兵车行》等，风格沉郁顿挫。","ans":"杜甫（712–770）是**盛唐诗人**，后世称“**诗圣**”，其诗称“**诗史**”，风格概括为“**沉郁顿挫**”，意为情感深沉郁结，节奏抑扬顿挫。代表作有五律《**春望**》“国破山河在，城春草木深”，七律《**登高**》，被明人誉为“**古今七律第一**”；歌行《**兵车行**》批判开边战争，《**丽人行**》讽刺杨氏兄妹奢华，《**茅屋为秋风所破歌**》“安得广厦千万间，大庇天下寒士俱欢颜”表现忧国忧民。他的诗是**现实主义诗歌的高峰**。","pts":["《春望》《登高》（古今七律第一）","《兵车行》《丽人行》《茅屋为秋风所破歌》","沉郁顿挫，诗史，诗圣"],"mem":"一组分类记：五律《春望》（国破），七律《登高》（秋日，登高），三首歌行（兵车行批战争，丽人行讽权贵，茅屋歌写自己）。“沉郁顿挫”四个字记成“情沉郁，声顿挫”，杜甫自己在《进雕赋表》里这样形容他的文风。","mix":"《登高》“无边落木萧萧下”是杜甫，不是李白；“三吏”“三别”属杜甫的另一组叙事诗；《兵车行》《丽人行》为天宝年间之作，写在安史之乱之前。","mcq":[{"q":"被明代胡应麟誉为“古今七律第一”的杜甫作品是","o":["《春望》","《登高》","《兵车行》","《茅屋为秋风所破歌》"],"a":1,"w":"《登高》是七律，被誉为“古今七律第一”。"}],"rel":[{"t":"杜甫","n":"作者"},{"t":"杜甫“三吏”“三别”","n":"杜甫另一组名作"},{"t":"李白代表作","n":"与杜甫并称“李杜”"},{"t":"李杜；小李杜","n":"合称"}],"more":"名句：国破山河在，城春草木深。｜《春望》\n无边落木萧萧下，不尽长江滚滚来。｜《登高》\n安得广厦千万间，大庇天下寒士俱欢颜。｜《茅屋为秋风所破歌》\n朱门酒肉臭，路有冻死骨。｜《自京赴奉先县咏怀五百字》\n作品：《春望》《登高》《兵车行》《丽人行》《茅屋为秋风所破歌》","exam":[]},{"id":"a03-042","t":"大历十才子","cid":"03f","p":1,"kind":"合称","alias":["大历十才子","大历才子"],"one":"唐代宗大历年间十位诗人，李端、卢纶、钱起等，擅长五言近体。","ans":"大历十才子指**唐代宗大历年间（766–779）活跃于长安的十位诗人**，据《新唐书·卢纶传》为**李端、卢纶、吉中孚、韩翃、钱起、司空曙、苗发、崔峒、耿湋、夏侯审**。他们属**中唐前期诗人群**，承盛唐余绪而气象渐小，多写**五言律诗**，题材以酬赠送别、山水闲咏为主，诗风清丽工稳。钱起“曲终人不见，江上数峰青”、卢纶《塞下曲》、韩翃《寒食》“春城无处不飞花”都是名篇。他们锤炼近体格律，上接王孟，下启中唐诸家，但**多限于应酬，缺少盛唐的雄浑气象**。","pts":["唐代宗大历年间十位诗人","李端、卢纶、钱起、韩翃、司空曙等","五言近体清丽工稳，气象不及盛唐"],"members":[["李端","《听筝》“欲得周郎顾，时时误拂弦”"],["卢纶","《塞下曲》“月黑雁飞高，单于夜遁逃”"],["吉中孚","官至户部侍郎，诗存世不多"],["韩翃","《寒食》“春城无处不飞花”"],["钱起","《省试湘灵鼓瑟》“曲终人不见，江上数峰青”"],["司空曙","《喜外弟卢纶见宿》“雨中黄叶树，灯下白头人”"],["苗发","存诗不多"],["崔峒","诗多送别酬赠"],["耿湋","诗多写乱后羁旅之感"],["夏侯审","存诗不多"]],"mem":"十人分三组记：前四位名气最大，“钱卢李韩”（钱起、卢纶、李端、韩翃）；中间“司空耿湋”（司空曙、耿湋）；其余四位“吉苗崔夏”（吉中孚、苗发、崔峒、夏侯审）。此为自编口诀，顺序不代表地位。年份挂钩：安史之乱 763 年结束，大历（766–779）紧随其后，诗风由盛转衰。","mix":"各书所列人选略有出入，以《新唐书》为通行。大历诗人属中唐前期，不要归入盛唐；与“建安七子”“竹林七贤”等数目合称区分。","mcq":[{"q":"下列诗人中，不属于“大历十才子”的是","o":["卢纶","司空曙","孟郊","韩翃"],"a":2,"w":"孟郊是中唐韩孟诗派诗人，不在十才子之列。"},{"q":"“曲终人不见，江上数峰青”的作者是","o":["韩翃","钱起","李端","卢纶"],"a":1,"w":"出自钱起《省试湘灵鼓瑟》，钱起是大历十才子之一。"}],"rel":[{"t":"唐诗分期：初唐、盛唐、中唐、晚唐","n":"所属时期"},{"t":"韩孟诗派","n":"同为中唐诗派"},{"t":"刘禹锡","n":"同属中唐诗坛"},{"t":"建安七子","n":"数目合称对照"}],"more":"钱起《省试湘灵鼓瑟》：曲终人不见，江上数峰青。\n韩翃《寒食》：春城无处不飞花，寒食东风御柳斜。\n卢纶《塞下曲》：月黑雁飞高，单于夜遁逃。\n李端《听筝》：欲得周郎顾，时时误拂弦。\n司空曙《喜外弟卢纶见宿》：雨中黄叶树，灯下白头人。","exam":[]},{"id":"a03-043","t":"韩孟诗派","cid":"03f","p":2,"kind":"流派","alias":["韩孟","韩愈孟郊诗派"],"one":"中唐以韩愈、孟郊为首的尚奇险诗派，与元白诗派相对。","ans":"韩孟诗派是**中唐以韩愈、孟郊为首的诗歌流派**，成员还有**贾岛、卢仝、李贺、刘叉**等。他们不满大历以来诗风平庸，追求**奇崛险怪、以文为诗**，用字求新求怪，有**苦吟**倾向。韩愈以文为诗，孟郊苦吟寒瘦，贾岛推敲炼字，李贺奇幻瑰丽，各有特色。该流派与**平易通俗的元白诗派**形成对立，共同构成中唐诗坛的两大风格。","pts":["韩愈、孟郊为首，贾岛、李贺等","尚奇险怪僻，以文为诗，苦吟","与平易的元白诗派相对"],"mem":"与元白对举记“险对易”：韩孟险（险怪、苦吟），元白易（平易、通俗）。成员用“孟岛贺”：孟郊、贾岛、李贺，加上卢仝、刘叉，跟着韩愈。","mix":"“韩柳”指古文运动，“韩孟”指诗派；李贺有时被列入韩孟诗派，有时单独称“长吉体”。","mcq":[{"q":"以下属于韩孟诗派的诗人是","o":["白居易","元稹","孟郊","杜牧"],"a":2,"w":"韩孟诗派以韩愈、孟郊为首；白居易、元稹属于元白诗派，杜牧属晚唐。"}],"rel":[{"t":"韩愈","n":"领袖"},{"t":"孟郊","n":"主要成员"},{"t":"贾岛","n":"主要成员"},{"t":"李贺","n":"成员，诗鬼"},{"t":"白居易与新乐府运动","n":"风格相反的另一路"}],"exam":[]},{"id":"a03-044","t":"白居易《长恨歌》《琵琶行》","cid":"03f","p":2,"kind":"作品","alias":["长恨歌","琵琶行","琵琶引"],"one":"白居易两首长篇叙事诗，一写玄宗贵妃，一写江州琵琶女。","ans":"《长恨歌》《琵琶行》是**白居易两首长篇叙事诗**。《**长恨歌**》作于元和元年（806），写**唐玄宗与杨贵妃**的爱情悲剧，“在天愿作比翼鸟，在地愿为连理枝”，同时与陈鸿的《长恨歌传》相配。《**琵琶行**》作于**贬江州司马**期间，写诗人与长安歌女的相遇，“**同是天涯沦落人，相逢何必曾相识**”抒发自身遭贬的失意。两首诗叙事与抒情融合，语言平易，是**唐代长篇歌行的代表**。","pts":["《长恨歌》：玄宗与杨贵妃，陈鸿作传","《琵琶行》：贬江州司马，同是天涯沦落人","长篇叙事诗，叙事抒情结合"],"mem":"一首写帝妃（长恨），一首写自己（琵琶）。“长恨”恨在“此恨绵绵无绝期”，“琵琶行”记“同是天涯沦落人”，一个是爱情之恨，一个是遭贬之感。","mix":"《长恨歌》题材与白朴《梧桐雨》、洪昇《长生殿》相同；《琵琶行》不要与高明《琵琶记》（元末南戏）混淆。","mcq":[{"q":"“同是天涯沦落人，相逢何必曾相识”出自","o":["《长恨歌》","《卖炭翁》","《琵琶行》","《秦妇吟》"],"a":2,"w":"出自白居易《琵琶行》。"}],"rel":[{"t":"白居易","n":"作者"},{"t":"南戏与《琵琶记》","n":"名字相近，易混"},{"t":"《汉宫秋》与《梧桐雨》","n":"《梧桐雨》同写玄宗贵妃"},{"t":"白居易与新乐府运动","n":"同一作者的另一主张"}],"more":"名句：在天愿作比翼鸟，在地愿为连理枝。｜《长恨歌》\n同是天涯沦落人，相逢何必曾相识。｜《琵琶行》\n作品：《长恨歌》《琵琶行》","exam":[]},{"id":"a03-045","t":"柳宗元《永州八记》","cid":"03f","p":2,"kind":"作品","alias":["永州八记","小石潭记","始得西山宴游记"],"one":"柳宗元贬永州时所作八篇山水游记，含《小石潭记》。","ans":"《永州八记》是**柳宗元被贬永州司马期间所作的八篇山水游记**，首篇为《**始得西山宴游记**》，后有《钴鉧潭记》《钴鉧潭西小丘记》《至小丘西小石潭记》（即**《小石潭记》**）、《袁家渴记》《石渠记》《石涧记》《小石城山记》。文章借山水抒发贬谪的**孤愤与幽寂**，写景精细，语言凝练，是**中国山水游记散文的典范**。柳宗元另有《捕蛇者说》《封建论》，也是其散文名作。","pts":["贬永州司马时所作八篇山水游记","首篇《始得西山宴游记》，含《小石潭记》","借景抒贬谪孤愤，山水游记典范"],"mem":"按游览顺序串起来：西山（始得西山宴游记）、钴鉧潭、钴鉧潭西小丘、小石潭、袁家渴、石渠、石涧、小石城山。第一篇“始得西山”和第四篇“小石潭”最常考，其余按“潭、丘、潭、渴、渠、涧、山”走一遍。","mix":"《小石潭记》只是八记之一；《捕蛇者说》《封建论》不在八记之内；柳宗元属于唐宋八大家，欧阳修《醉翁亭记》属于宋人游记。","mcq":[{"q":"下列作品中，不属于“永州八记”的是","o":["《始得西山宴游记》","《小石潭记》","《捕蛇者说》","《小石城山记》"],"a":2,"w":"《捕蛇者说》是柳宗元的另一篇名作，不属于八记。"}],"rel":[{"t":"柳宗元","n":"作者"},{"t":"唐宋八大家","n":"所属"},{"t":"古文运动","n":"柳宗元倡导"},{"t":"韩柳；刘柳；元白；刘白","n":"“韩柳”“刘柳”"}],"exam":[]},{"id":"a03-046","t":"寒山与寒山诗","cid":"03f","p":3,"kind":"人物","alias":["寒山子","寒山体"],"one":"唐代著名诗僧，其诗经加里·斯奈德英译风靡欧美“垮掉的一代”。","ans":"寒山为**唐代诗僧**，隐居天台山，与拾得并称。其诗通俗晓畅，融合**禅意与世俗讽喻**，辑为《寒山子诗集》。20世纪50年代经美国诗人**加里·斯奈德**英译后风靡西方，深刻启发了“**垮掉的一代**”，成为**中国诗歌外译传播的典范**。","pts":["唐代诗僧，诗作通俗晓畅蕴含禅意","加里·斯奈德英译《寒山诗》","深刻影响美国“垮掉的一代”文化运动"],"mem":"跨文化传播记忆链：**寒山（诗僧）→ 加里·斯奈德（英译）→ 垮掉的一代（凯鲁亚克《达摩流浪者》题献）**。","mix":"寒山在中国古代文学史上属于通俗诗僧群体，但在20世纪西方反主流文化中反响巨大；苏州寒山寺亦因寒山曾结庐而得名。","mcq":[{"q":"20世纪50年代将中国唐代诗僧寒山的诗作英译，并在美国“垮掉的一代”中引发广泛反响的诗人是","o":["埃兹拉·庞德","加里·斯奈德","阿瑟·韦利","肯尼斯·雷克斯罗斯"],"a":1,"w":"美国诗人加里·斯奈德（Gary Snyder）英译《寒山诗》，深刻影响垮掉的一代。"}],"rel":[{"t":"垮掉的一代","n":"受寒山诗深刻影响"},{"t":"寒山诗在美国","n":"寒山跨文化传播"},{"t":"张继","n":"《枫桥夜泊》写寒山寺"}],"exam":[]},{"id":"a03-047","t":"唐诗分期：初唐、盛唐、中唐、晚唐","cid":"03f","p":2,"kind":"常识","alias":["四唐","四唐说","初唐盛唐中唐晚唐"],"one":"明代高棅《唐诗品汇》确立“四唐”分期。","ans":"唐诗分期通常采用明代**高棅《唐诗品汇》**确立的**“四唐”**说：**初唐**（约618–712）有初唐四杰、陈子昂、沈宋；**盛唐**（约713–765）为唐诗高峰，有李白、杜甫、王维、孟浩然、高适、岑参、王昌龄；**中唐**（约766–835）安史之乱后，有韩愈、柳宗元、白居易、元稹、刘禹锡、孟郊、贾岛、李贺；**晚唐**（约836–907）有李商隐、杜牧、温庭筠。分期各家略有出入，但以诗人所处时代判断所属时期最稳妥。","pts":["高棅《唐诗品汇》确立四唐","初唐四杰陈子昂，盛唐李杜王孟高岑","中唐韩柳元白刘，晚唐小李杜温"],"mem":"按“人名分段”背：初唐=四杰+陈子昂；盛唐=李杜王孟高岑；中唐=韩柳元白刘郊岛贺；晚唐=小李杜+温。一个分界点：安史之乱（755）之后算中唐。","mix":"盛唐/中唐的界线有开元、天宝、安史之乱、代宗大历多种说法；杜甫跨盛唐与中唐，通常归入盛唐。","mcq":[{"q":"下列诗人中，属于晚唐的是","o":["白居易","孟郊","李商隐","高适"],"a":2,"w":"李商隐、杜牧、温庭筠属晚唐；白居易、孟郊属中唐，高适属盛唐。"}],"rel":[{"t":"《全唐诗》","n":"唐诗总集"},{"t":"《唐诗三百首》","n":"唐诗选本"},{"t":"初唐四杰","n":"初唐代表"},{"t":"李杜；小李杜","n":"盛唐与晚唐的对称"}],"exam":[]},{"id":"a03-048","t":"词牌","cid":"03g","p":1,"kind":"概念","alias":["词调","词牌名"],"one":"词调的名称，规定字数、句数、平仄与韵位，一般与题目、内容无关。","ans":"词牌是**词调的名称**，来自词配乐歌唱时所依的曲调。每个词牌**规定了全词的字数、句数、平仄和韵位**，作者依谱填词，所以叫“填词”。词牌最初多与内容相关，如《渔歌子》咏渔，后来逐渐只是格式名称，**与词的题目、内容一般无关**，题目另标，如《念奴娇·赤壁怀古》中《念奴娇》是词牌，“赤壁怀古”是题目。有的词牌**同调异名**，如《念奴娇》又名《大江东去》《酹江月》。常见词牌有《菩萨蛮》《水调歌头》《满江红》《如梦令》。","pts":["词调名称，规定字数句数平仄韵位","一般与题目内容无关，依谱填词","同调异名：念奴娇又名大江东去、酹江月"],"mem":"词牌像歌曲的“谱名”，题目像歌词的“内容”，《念奴娇·赤壁怀古》就是“曲调·题目”，中间用圆点隔开。名篇配对记：苏轼（念奴娇、水调歌头、江城子、定风波），辛弃疾（永遇乐、青玉案、破阵子、西江月）。","mix":"《念奴娇》是词牌，不是词题，苏轼这首词的题目是“赤壁怀古”；曲牌（如《天净沙》《山坡羊》）属元曲，词牌属宋词，写法相似、所属文体不同。","mcq":[{"q":"苏轼《念奴娇·赤壁怀古》中，“赤壁怀古”是","o":["词牌","题目","别名","词序"],"a":1,"w":"《念奴娇》是词牌，“赤壁怀古”是题目。"},{"q":"下列不属于词牌名的是","o":["《水调歌头》","《菩萨蛮》","《天净沙》","《满江红》"],"a":2,"w":"《天净沙》是元曲的曲牌。"}],"rel":[{"t":"词","n":"词牌所属文体"},{"t":"曲牌与宫调","n":"元曲对应概念"},{"t":"小令、中调、长调与慢词","n":"词的分类"},{"t":"苏轼代表作","n":"常考词牌篇目"},{"t":"莎士比亚十四行诗","n":"固定格律诗体对照"}],"more":"同调异名举例：《念奴娇》又名《大江东去》《酹江月》；《水调歌头》又名《台城游》《元会曲》；《满江红》又名《上江虹》。","exam":[]},{"id":"a03-049","t":"小令、中调、长调与慢词","cid":"03g","p":2,"kind":"概念","alias":["小令","中调","长调","慢词"],"one":"词按字数分小令、中调、长调，柳永大量创作慢词。","ans":"词按字数分为**小令、中调、长调**三类，据清人**毛先舒**的说法：**58字以内为小令，59至90字为中调，91字以上为长调**。**慢词**本指节奏舒缓的长调，**北宋柳永**大量创作慢词，扩大了词的容量，使词能铺叙情景、抒写复杂情感。小令如李煜《虞美人》、晏殊《浣溪沙》，中调如《蝶恋花》，长调如柳永《雨霖铃》、苏轼《念奴娇·赤壁怀古》、辛弃疾《永遇乐》。字数分类是人为划分，并非严格定制。","pts":["58字以内小令，59–90中调，91字以上长调","毛先舒的分法","柳永大量创作慢词"],"mem":"数字口诀“58、59–90、91”：五十八以下小，五九到九十中，九十一起长。慢词的“慢”是节奏慢，与长调大体对应；柳永=慢词大家。","mix":"毛先舒的分法只是通行说，不是唯一标准；小令是否以“令”命名与词牌长短无关。","mcq":[{"q":"按清人毛先舒的分法，91字以上的词称为","o":["小令","中调","长调","慢词"],"a":2,"w":"91字以上为长调，常与慢词相当。"}],"rel":[{"t":"柳永","n":"大量创作慢词"},{"t":"苏轼","n":"以长调抒豪放"},{"t":"二晏","n":"小令高峰"},{"t":"李煜","n":"小令名家"}],"exam":[]},{"id":"a03-050","t":"婉约派与豪放派","cid":"03g","p":1,"kind":"流派","alias":["婉约派","豪放派","婉约词","豪放词"],"one":"宋词两大风格：婉约重柔情与格律，豪放重壮志与旷达；明人张綖首次区分。","ans":"婉约派与豪放派是**宋词的两大风格流派**。**明代张綖在《诗余图谱》中首次以“婉约”“豪放”区分词体**。婉约派内容多写离情别绪、儿女之情，风格含蓄柔美、讲究音律，**代表词人有柳永、秦观、周邦彦、李清照**，李清照被称“婉约词宗”。豪放派内容扩及家国、人生与山河，风格雄放旷达，**由苏轼开创、辛弃疾集大成，合称“苏辛”**。两派并立，使词从“艳科”扩展为能抒写一切情怀的文体，也成为后世评词的基本分类。","pts":["张綖以婉约、豪放区分词风","婉约：柳永、秦观、周邦彦、李清照","豪放：苏轼开创，辛弃疾集大成"],"mem":"婉约四家自编口诀“柳秦周李”（柳永、秦观、周邦彦、李清照）；豪放就记“苏辛”两人。画面对比：十七八岁女郎执红牙板唱“杨柳岸，晓风残月”（婉约），关西大汉执铁板唱“大江东去”（豪放）。","mix":"两派是后人的大致分类，不绝对：苏轼有婉约之作（《江城子·记梦》），辛弃疾《青玉案·元夕》偏婉约。“词别是一家”是李清照，“以诗为词”是苏轼，“以文为词”是辛弃疾。","mcq":[{"q":"最早以“婉约”“豪放”区分词体风格的是","o":["李清照","王国维","张綖","严羽"],"a":2,"w":"明代张綖《诗余图谱》提出词体大略有二：婉约、豪放。"},{"q":"下列词人中，属于豪放派代表的是","o":["秦观","周邦彦","辛弃疾","柳永"],"a":2,"w":"豪放派以苏轼、辛弃疾为代表；其余三位属婉约派。"}],"rel":[{"t":"苏辛","n":"豪放派代表"},{"t":"柳永","n":"婉约派代表"},{"t":"李清照","n":"婉约词宗"},{"t":"秦观、周邦彦","n":"婉约派代表"},{"t":"王孟；高岑","n":"唐诗也有两路对举"}],"exam":[]},{"id":"a03-051","t":"词的起源：敦煌曲子词与李白《菩萨蛮》《忆秦娥》","cid":"03g","p":3,"kind":"常识","alias":["敦煌曲子词","百代词曲之祖"],"one":"词体从民间向文人创作演进的源头，李白二词被称为百代词曲之祖。","ans":"该史实揭示了词体的双重源头。出土的**敦煌曲子词**是**现存最早的民间词遗存**，展现隋唐燕乐风貌；传为李白所作的**《菩萨蛮》与《忆秦娥》**，被尊为“**百代词曲之祖**”。二者共同见证了**词体由民间歌谣向文人雅化创作的过渡与萌发**。","pts":["敦煌曲子词是现存最早民间词总集","传为李白作《菩萨蛮》《忆秦娥》称百代词曲之祖","展现词由民间燕乐向文人雅化过渡"],"mem":"双源头记忆法：民间词看**敦煌曲子词**，文人词看李白两首词为“**百代词曲之祖**”。","mix":"《花间集》是我国现存最早的文人词总集，而敦煌曲子词是更早的民间词遗存；李白是否确为二词作者学界存争议，但考题以“百代词曲之祖”为主要考点。","mcq":[{"q":"南宋黄昇在《唐宋诸贤绝妙词选》中尊为“百代词曲之祖”的文人词作是传为李白所作的","o":["《水调歌头》与《念奴娇》","《虞美人》与《浪淘沙》","《菩萨蛮》与《忆秦娥》","《雨霖铃》与《望海潮》"],"a":2,"w":"传为李白所作的《菩萨蛮》（平林漠漠）与《忆秦娥》（箫声咽）被称为百代词曲之祖。"}],"rel":[{"t":"李白","n":"传为二词作者"},{"t":"《花间集》","n":"最早文人词总集对照"},{"t":"敦煌藏经洞","n":"曲子词出土地"}],"exam":[]},{"id":"a03-052","t":"张先“张三影”","cid":"03g","p":3,"kind":"人物","alias":["张三影","张子野"],"one":"北宋词人张先的美称，因词作中三句含“影”字名句而得名。","ans":"张先（990–1078），字子野，**北宋婉约派词人**。因词中三处“影”字佳句（尤以**《天仙子》“云破月来花弄影”**最著），世称“**张三影**”。其作长于捕捉光影幽微，**上承晏殊、下启柳永与苏轼**，为**北宋词坛过渡的关键人物**。","pts":["北宋词人张先，字子野，美称“张三影”","名句《天仙子》“云破月来花弄影”","北宋词坛上承晏殊、下启柳苏的关键人物"],"mem":"数字绰号对应：**张先＝张三影**。最核心名句是《天仙子》中的“**云破月来花弄影**”。","mix":"“张三影”是北宋词人张先，不是南宋词人张炎；张先擅长慢词小令，是北宋词风过渡的关键纽带。","mcq":[{"q":"北宋词人张先因名句“云破月来花弄影”等三处含“影”字佳句，被时人誉为","o":["张三中","张三绝","张梅子","张三影"],"a":3,"w":"张先字子野，因得意词句多带“影”字，被世人称为“张三影”。"}],"rel":[{"t":"柳永","n":"慢词发展承接"},{"t":"晏殊","n":"北宋前期词人前驱"},{"t":"贺铸","n":"以名句得雅号词人对照"}],"more":"名句：云破月来花弄影。｜《天仙子》\n帘压卷花影。｜《归朝欢》\n堕絮飞无影。｜《剪丹宵》","exam":[]},{"id":"a03-053","t":"李清照代表作与“词别是一家”","cid":"03g","p":2,"kind":"作品","alias":["词别是一家","漱玉词","声声慢","如梦令","醉花阴","一剪梅"],"one":"李清照代表作《声声慢》《如梦令》等，《词论》提出“词别是一家”。","ans":"李清照（1084–约1155）是**南宋婉约派词人**，号易安居士，词集《**漱玉词**》，词风称“**易安体**”。代表作有《**声声慢**》“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”，《**如梦令**》“知否，知否？应是绿肥红瘦”，《**醉花阴**》“人比黄花瘦”，《**一剪梅**》“才下眉头，却上心头”。她在《**词论**》中提出“**词别是一家**”，主张词与诗应有区别，强调协律与典雅，批评柳永、苏轼等人的词作。","pts":["《声声慢》《如梦令》《醉花阴》《一剪梅》","《词论》“词别是一家”","词集《漱玉词》，易安体"],"mem":"三句分别配三首：“绿肥红瘦”配《如梦令》，“人比黄花瘦”配《醉花阴》，“才下眉头，却上心头”配《一剪梅》；《声声慢》开头记“寻寻觅觅”十四个叠字。《词论》记一句话：词要有自己的体，不能当诗写。","mix":"“词别是一家”是李清照《词论》，不是苏轼，也不是王国维；李清照词论批评了苏轼“句读不葺之诗”。","mcq":[{"q":"提出“词别是一家”的是","o":["苏轼","柳永","李清照","周邦彦"],"a":2,"w":"李清照《词论》提出“词别是一家”。"}],"rel":[{"t":"李清照","n":"作者"},{"t":"婉约派与豪放派","n":"婉约代表"},{"t":"柳永","n":"《词论》评论对象"},{"t":"苏轼","n":"《词论》评论对象"}],"more":"名句：寻寻觅觅，冷冷清清，凄凄惨惨戚戚。｜《声声慢》\n知否，知否？应是绿肥红瘦。｜《如梦令》\n莫道不消魂，帘卷西风，人比黄花瘦。｜《醉花阴》\n作品：《声声慢》《如梦令》《醉花阴》《一剪梅》《漱玉词》","exam":[]},{"id":"a03-054","t":"李煜《虞美人》与“千古词帝”","cid":"03g","p":2,"kind":"作品","alias":["虞美人","千古词帝","春花秋月何时了"],"one":"李煜亡国后所作《虞美人》，“问君能有几多愁”，后世称“千古词帝”。","ans":"李煜（937–978）是**南唐后主**，被后世称为“**千古词帝**”。他的《**虞美人**》“春花秋月何时了，往事知多少”作于亡国被俘之后，以“**问君能有几多愁，恰似一江春水向东流**”写亡国之痛，比喻新奇，情感深切。**王国维**评价其词“**眼界始大，感慨遂深**”，使词由“**伶工之词**”变为“**士大夫之词**”。李煜以后期词作成就最高，另有《浪淘沙》《乌夜啼》。","pts":["亡国后所作，“问君能有几多愁”","王国维：眼界始大，感慨遂深","千古词帝，伶工词变士大夫词"],"mem":"一前一后：前期写宫廷享乐，后期写亡国之痛，王国维评他“眼界始大”就是因为前后期落差。《虞美人》与愁绑定：愁多如“一江春水”。","mix":"《虞美人》有“春花秋月何时了”与“问君能有几多愁”两个名句；传说他因此词触怒宋太宗被赐死，属传说性质。","mcq":[{"q":"“问君能有几多愁，恰似一江春水向东流”出自","o":["《虞美人》","《浪淘沙》","《蝶恋花》","《水调歌头》"],"a":0,"w":"李煜《虞美人》。"}],"rel":[{"t":"李煜","n":"作者"},{"t":"南唐二主","n":"李璟、李煜"},{"t":"王国维《人间词话》","n":"“眼界始大”的出处"},{"t":"《人间词话》","n":"评李煜之书"}],"more":"名句：问君能有几多愁，恰似一江春水向东流。｜《虞美人》\n春花秋月何时了，往事知多少。｜《虞美人》\n作品：《虞美人》《浪淘沙》《乌夜啼》","exam":[]},{"id":"a03-055","t":"北宋诗文革新运动","cid":"03h","p":1,"kind":"事件","alias":["诗文革新运动","北宋古文运动","宋代古文运动"],"one":"欧阳修领导的北宋文风改革，继承韩柳古文，反对西昆体与太学体。","ans":"北宋诗文革新运动是**北宋中期以欧阳修为领袖的文学改革运动**，目的是**继承唐代韩愈、柳宗元的古文传统，革除宋初浮艳文风**。宋初杨亿、刘筠等人的西昆体追求辞藻典故，仁宗时太学生又流行险怪奇涩的“太学体”。欧阳修倡导平易自然的文风，**嘉祐二年（1057）知贡举，黜落太学体，录取苏轼、苏辙、曾巩**，并提携王安石、梅尧臣等人。此后三苏、王安石、曾巩继起，**唐宋八大家中宋占六家**，平易流畅的文风成为后世散文的正统。","pts":["欧阳修领导，承韩柳古文传统","反对西昆体、太学体","1057年知贡举取苏轼、苏辙、曾巩"],"mem":"逻辑线：唐代韩柳古文运动→宋初西昆体浮艳回潮→欧阳修“二次革命”。画面：1057 年的那场科举，一榜取到二苏一曾，等于给宋代古文“组队”。","mix":"古文运动（中唐韩愈、柳宗元）与诗文革新运动（北宋欧阳修）前后相承，别混年代；西昆体（杨亿、刘筠、钱惟演）与太学体是被革新的对象。","mcq":[{"q":"北宋诗文革新运动的领袖是","o":["王安石","苏轼","欧阳修","曾巩"],"a":2,"w":"欧阳修领导北宋诗文革新运动。"},{"q":"嘉祐二年欧阳修知贡举时录取的人物不包括","o":["王安石","苏轼","苏辙","曾巩"],"a":0,"w":"王安石是庆历二年进士，不是嘉祐二年。"}],"rel":[{"t":"古文运动","n":"前一阶段"},{"t":"西昆体","n":"被革新的对象"},{"t":"欧阳修","n":"领袖"},{"t":"唐宋八大家","n":"运动的成果"},{"t":"梅尧臣与“苏梅”","n":"诗歌方面的同道"}],"exam":[]},{"id":"a03-056","t":"西昆体","cid":"03h","p":2,"kind":"流派","alias":["西昆酬唱集","西昆派"],"one":"北宋初杨亿编《西昆酬唱集》，宗李商隐，辞藻华丽，是诗文革新的批评对象。","ans":"西昆体是**北宋初年的诗歌流派**，因杨亿编选《**西昆酬唱集**》得名，“西昆”取神话中西昆仑山藏书之府的意思。代表人物是**杨亿、刘筠、钱惟演**，诗风**宗法李商隐**，讲究辞藻华丽、用典繁密、对仗工整，但内容空泛，偏重形式。石介、欧阳修等人批评其浮艳，倡导平实的诗文，西昆体因而成为**北宋诗文革新运动攻击的对象**。","pts":["杨亿编《西昆酬唱集》得名","杨亿、刘筠、钱惟演，宗李商隐","辞藻华丽，是诗文革新的批评对象"],"mem":"逻辑线：宋初承晚唐五代余习→杨亿等人学李商隐的华丽→编成《西昆酬唱集》→欧阳修等倡导平实诗文革新。“西昆”两字是书名，流派因书得名。","mix":"西昆体学的是李商隐（晚唐），江西诗派学的是杜甫；西昆体是被革新的对象，欧阳修是领导革新的人。","mcq":[{"q":"北宋初年宗法李商隐、以《西昆酬唱集》得名的诗歌流派是","o":["江西诗派","西昆体","永嘉四灵","台阁体"],"a":1,"w":"杨亿编《西昆酬唱集》，故称西昆体。"}],"rel":[{"t":"李商隐","n":"他们的宗法对象"},{"t":"北宋诗文革新运动","n":"批评西昆体"},{"t":"欧阳修","n":"革新的领导者"},{"t":"江西诗派“一祖三宗”","n":"宋诗另一重要流派"}],"more":"《西昆酬唱集》由杨亿编，收杨亿、刘筠、钱惟演等人唱和诗。","exam":[]},{"id":"a03-057","t":"梅尧臣与“苏梅”","cid":"03h","p":3,"kind":"合称","alias":["苏梅"],"one":"北宋诗文革新先驱梅尧臣与苏舜钦的并称，梅被誉为宋诗开山祖师。","ans":"“苏梅”指**北宋诗文革新先驱苏舜钦与梅尧臣**。二人力扫西昆浮靡诗风：苏舜钦诗风豪宕，梅尧臣倡“**平淡深远**”重写实。南宋刘克庄尊梅尧臣为**宋诗“开山祖师”**。二人与欧阳修齐心合力，**共同开拓了宋诗崇尚思理与日常的新格局**。","pts":["苏舜钦与梅尧臣并称“苏梅”","梅尧臣倡导平淡深远，尊为宋诗开山祖师","北宋诗文革新先驱，扫除西昆浮靡"],"members":[["苏舜钦","字子美，诗风豪宕雄肆，代表作散文《沧浪亭记》"],["梅尧臣","字圣俞，世称宛陵先生，主平淡深远，被尊为宋诗“开山祖师”"]],"mem":"合称口诀：**“苏梅”破西昆，尧臣开山祖**。记住苏是苏舜钦（杜陵苏学士），梅是梅尧臣（宣城宛陵先生）。","mix":"“苏梅”中的“苏”指苏舜钦而非苏轼；刘克庄尊梅尧臣为宋诗“开山祖师”，体现宋诗由浮艳转入平淡写实与思理。","mcq":[{"q":"南宋刘克庄在《后村诗话》中称誉为宋诗“开山祖师”，并与苏舜钦并称为“苏梅”的诗人是","o":["欧阳修","王安石","梅尧臣","苏轼"],"a":2,"w":"梅尧臣倡导“平淡深远”，被刘克庄誉为宋诗开山祖师。"}],"rel":[{"t":"西昆体","n":"苏梅革新的对立面"},{"t":"欧阳修","n":"革新运动领袖同盟"},{"t":"北宋诗文革新运动","n":"所属文学思潮"}],"exam":[]},{"id":"a03-058","t":"江西诗派“一祖三宗”","cid":"03h","p":1,"kind":"合称","alias":["一祖三宗","江西诗派一祖三宗"],"one":"元代方回提出：江西诗派一祖杜甫，三宗黄庭坚、陈师道、陈与义。","ans":"“一祖三宗”是**元代方回《瀛奎律髓》对江西诗派的追认，尊杜甫为“一祖”，黄庭坚、陈师道、陈与义为“三宗”**。江西诗派得名于北宋末吕本中《江西诗社宗派图》，以黄庭坚为宗主，主张**“点铁成金”“夺胎换骨”**，讲求字字有来历。黄庭坚诗风奇崛瘦硬；陈师道苦吟，学杜甫、黄庭坚；陈与义由北宋入南宋，靖康之乱后诗转沉郁近杜。该说确立了杜甫在宋人诗学中的宗主地位，也体现宋人“学杜”的风气。","pts":["元代方回提出","一祖杜甫","三宗黄庭坚、陈师道、陈与义"],"members":[["杜甫","一祖，宋人学杜的宗主"],["黄庭坚","三宗之首，点铁成金、夺胎换骨"],["陈师道","苦吟，号后山，“闭门觅句陈无己”"],["陈与义","由北宋入南宋，号简斋，诗近杜甫"]],"mem":"“杜是祖，黄为首，二陈跟”。三宗里有两个姓陈：陈师道（后山）在前，陈与义（简斋）在后，都生活在北宋末到南宋初。“一祖”是唐代人，“三宗”都是宋代人。","mix":"吕本中《江西诗社宗派图》列二十五人，并无杜甫，“一祖三宗”是后来方回的追认；“苏黄”指苏轼、黄庭坚，与此不同。","mcq":[{"q":"江西诗派“一祖”指的是","o":["李白","黄庭坚","杜甫","陈师道"],"a":2,"w":"方回尊杜甫为江西诗派一祖。"},{"q":"下列不属于江西诗派“三宗”的是","o":["黄庭坚","陈师道","陈与义","苏轼"],"a":3,"w":"三宗是黄庭坚、陈师道、陈与义。"}],"rel":[{"t":"黄庭坚与江西诗派","n":"诗派宗主"},{"t":"杜甫","n":"“一祖”"},{"t":"永嘉四灵","n":"起而反对"},{"t":"苏黄","n":"与黄庭坚并称的另一说"},{"t":"江湖诗派","n":"南宋后期继起"}],"exam":[]},{"id":"a03-059","t":"苏门六君子","cid":"03h","p":3,"kind":"合称","alias":["苏门六子"],"one":"北宋苏轼门下的六位著名学者文人，即苏门四学士加陈师道、李廌。","ans":"苏门六君子指**北宋推戴苏轼的六位文人学者**，见于李廌《师友谈记》。包括“**苏门四学士**”（**黄庭坚、秦观、晁补之、张耒**）及**陈师道、李廌**。黄庭坚与陈师道后为江西诗派宗祖。六人同声相应，代表了**北宋元祐文坛文学创作的高峰**。","pts":["苏门四学士加陈师道、李廌共六人","称谓见于李廌《师友谈记》","北宋元祐文坛繁荣的核心代表"],"members":[["黄庭坚","字山谷，江西诗派开山之祖，“苏黄”之一"],["秦观","字少游，号淮海居士，北宋婉约词名家"],["晁补之","字无咎，兼擅诗词古文，著《鸡肋集》"],["张耒","字文潜，号柯山，诗风平易自然"],["陈师道","号后山居士，江西诗派“三宗”之一"],["李廌","字方叔，著有记录苏门师友言行的《师友谈记》"]],"mem":"公式记忆：**苏门六君子 ＝ 苏门四学士（黄秦晁张） ＋ 陈师道 ＋ 李廌**。在四学士基础上增加陈、李二人。","mix":"注意“苏门四学士”与“苏门六君子”的区别；陈师道与李廌也是苏轼门下高足，李廌写下了《师友谈记》。","mcq":[{"q":"在“苏门四学士”（黄庭坚、秦观、晁补之、张耒）基础上增加哪两位文人，合称为“苏门六君子”","o":["苏辙、苏洵","欧阳修、曾巩","王安石、司马光","陈师道、李廌"],"a":3,"w":"苏门四学士加上陈师道、李廌，合称为“苏门六君子”。"}],"rel":[{"t":"苏门四学士","n":"四君子基础合称"},{"t":"苏轼","n":"六君子推戴师长"},{"t":"黄庭坚","n":"六君子中声名最著者"},{"t":"秦观","n":"六君子中婉约词名家"}],"exam":[]},{"id":"a03-060","t":"永嘉四灵","cid":"03h","p":1,"kind":"流派","alias":["永嘉四灵","四灵","四灵诗派"],"one":"南宋永嘉四位诗人徐照、徐玑、翁卷、赵师秀，学晚唐贾岛、姚合。","ans":"永嘉四灵是**南宋中后期活跃于浙江永嘉（今温州）的四位诗人：徐照、徐玑、翁卷、赵师秀**，四人字号中都带“灵”字（灵晖、灵渊、灵舒、灵秀），故称。他们**反对江西诗派重学问、好用典的流弊，改学晚唐贾岛、姚合**，主张苦吟，多作五言律诗，写山水田园与闲居生活，诗风清瘦，境界较窄。赵师秀《约客》“黄梅时节家家雨，青草池塘处处蛙”最为传诵。他们得到叶适推重，带动晚唐诗风复兴，并影响后来的江湖诗派。","pts":["徐照、徐玑、翁卷、赵师秀","字号带“灵”，学贾岛、姚合","反江西诗派，五律清瘦"],"members":[["徐照","字灵晖"],["徐玑","字灵渊"],["翁卷","字灵舒"],["赵师秀","字灵秀，《约客》"]],"mem":"口诀“两徐翁赵，晖渊舒秀”。字号对应巧记：徐照↔灵晖（照与晖都是光），翁卷↔灵舒（卷舒相对），徐玑↔灵渊，赵师秀↔灵秀。“四灵学晚唐，江西学杜黄”，两派对立。","mix":"永嘉四灵（诗派）与永嘉学派、事功学派（叶适、陈亮一路的思想学派）不同；四灵学贾岛姚合，江西诗派学杜甫黄庭坚；江湖诗派因陈起刊《江湖集》得名。","mcq":[{"q":"“黄梅时节家家雨，青草池塘处处蛙”的作者是","o":["徐照","徐玑","赵师秀","翁卷"],"a":2,"w":"出自赵师秀《约客》。"},{"q":"永嘉四灵诗歌取法的对象是","o":["李白、杜甫","晚唐贾岛、姚合","黄庭坚、陈师道","陶渊明、谢灵运"],"a":1,"w":"四灵学晚唐贾岛、姚合，反对江西诗派。"}],"rel":[{"t":"江湖诗派","n":"后继诗人群"},{"t":"江西诗派“一祖三宗”","n":"所反对的诗风"},{"t":"贾岛","n":"取法对象"},{"t":"事功学派","n":"叶适所属学派，同出永嘉"},{"t":"中兴四大诗人","n":"南宋另一诗人群"}],"exam":[]},{"id":"a03-061","t":"江湖诗派","cid":"03h","p":2,"kind":"流派","alias":["江湖派","江湖集","江湖诗人"],"one":"南宋后期因书商陈起刊《江湖集》得名，刘克庄、戴复古为代表。","ans":"江湖诗派是**南宋后期的诗歌流派**，因临安书商**陈起**刊刻《江湖集》《江湖后集》等诗集而得名。成员多为不仕或仕途不高的**布衣文人**，**代表人物是刘克庄、戴复古**，另有刘过、敖陶孙等。诗风多近晚唐，部分作品关心时事，语言平易。该派继永嘉四灵之后，进一步冲击江西诗派的影响，是南宋后期诗坛的主要力量。刘克庄兼擅词，属辛派词人。","pts":["书商陈起刊《江湖集》得名","代表刘克庄、戴复古，多为布衣","继永嘉四灵冲击江西诗派"],"mem":"名称线索：书商陈起刊《江湖集》，后人由此称这批人为江湖诗派，“江湖”也指他们多在朝廷之外漂泊。记人名“刘戴”：刘克庄、戴复古；刘克庄诗词两栖。","mix":"永嘉四灵是徐照、徐玑、翁卷、赵师秀，宗晚唐贾岛、姚合；江湖诗派人数更多，两者常连着考。","mcq":[{"q":"南宋后期因书商陈起刊刻《江湖集》而得名的诗派，代表人物是","o":["徐照、翁卷","黄庭坚、陈师道","陈亮、刘过","刘克庄、戴复古"],"a":3,"w":"江湖诗派以刘克庄、戴复古为代表。"}],"rel":[{"t":"永嘉四灵","n":"南宋后期同簇诗派"},{"t":"江西诗派“一祖三宗”","n":"他们冲击的对象"},{"t":"辛派词人","n":"刘克庄兼属辛派"},{"t":"中兴四大诗人","n":"前一代南宋诗人"}],"more":"陈起，临安书商，刊刻《江湖集》。","exam":[]},{"id":"a03-062","t":"辛派词人","cid":"03h","p":2,"kind":"流派","alias":["稼轩派","辛派"],"one":"南宋效法辛弃疾的豪放词人，陈亮、刘过、刘克庄等。","ans":"辛派词人是**南宋效法辛弃疾豪放词风的一批词人**，又称稼轩派。代表人物有**陈亮、刘过、刘克庄**，另有韩元吉、杨炎正等。他们多与辛弃疾有交游唱和，如陈亮与辛弃疾有《贺新郎》唱和，刘过作《沁园春·寄辛承旨》。作品多**抒发抗金复国的壮志与忧愤**，风格慷慨激越，与苏轼开启的豪放词一脉相承，使豪放词成为**南宋词坛的重要一路**。","pts":["效法辛弃疾的南宋豪放词人","陈亮、刘过、刘克庄","抒抗金壮志，承苏轼豪放词"],"members":[["陈亮","号龙川，与辛弃疾有《贺新郎》唱和"],["刘过","号龙洲道人，《沁园春·寄辛承旨》"],["刘克庄","号后村，《沁园春·梦孚若》"]],"mem":"口诀“陈过庄”：陈亮、刘过、刘克庄，围着辛弃疾。三人的共同点是词里都有“抗金”：写的不是闺愁，是国事。","mix":"辛派属豪放，姜夔、吴文英属婉约格律派；刘克庄既是辛派词人，又是江湖诗派代表。","mcq":[{"q":"下列人物中，不属于“辛派词人”的是","o":["陈亮","刘过","刘克庄","姜夔"],"a":3,"w":"姜夔属格律派，词风清空，不属辛派。"}],"rel":[{"t":"辛弃疾","n":"辛派的宗主"},{"t":"苏辛","n":"豪放词的传承"},{"t":"江湖诗派","n":"刘克庄兼属其中"},{"t":"姜夔","n":"同时代格律派对照"}],"more":"陈亮，字同甫，号龙川，永康人。","exam":[]},{"id":"a03-063","t":"吴文英与南宋格律词派","cid":"03h","p":3,"kind":"人物","alias":["吴梦窗","梦窗词"],"one":"南宋格律词派代表词人，号梦窗，张炎评其词如七宝楼台。","ans":"吴文英（约1200–约1260），字次翁，**号梦窗**，**南宋格律词派代表**。其词音律精严，意象繁密。张炎《词源》评其词“**如七宝楼台，眩人眼目，碎拆下来，不成片段**”。著有《梦窗词》，他与姜夔、张炎等共同将**南宋骚雅词风推向极致**。","pts":["南宋格律词派代表词人，号梦窗","张炎评其词“如七宝楼台，眩人眼目”","词风音律精严、意象密集，著《梦窗词》"],"mem":"评价比喻记忆：**吴梦窗＝七宝楼台**（极度华丽密实，拆开零碎），评价者是张炎《词源》。","mix":"张炎在《词源》中以“清空”评姜夔，以“质实”评吴文英，并用“七宝楼台”形象比喻吴词的繁密与碎片化。","mcq":[{"q":"南宋张炎在《词源》中评价哪位词人的词“如七宝楼台，眩人眼目，碎拆下来，不成片段”","o":["吴文英","辛弃疾","姜夔","周邦彦"],"a":0,"w":"张炎《词源》以此评价吴文英（号梦窗）词作意象密实精巧之特征。"}],"rel":[{"t":"姜夔","n":"南宋格律派领军人物"},{"t":"古体诗与近体诗（格律诗）","n":"格律规范对照"},{"t":"辛派词人","n":"南宋豪放词派对立流派"}],"more":"代表作：《风入松·听风听雨过清明》《莺啼序·春晚感怀》","exam":[]},{"id":"a03-064","t":"苏轼代表作","cid":"03h","p":1,"kind":"作品","one":"苏轼词、文、诗、书代表作汇总，《念奴娇》《水调歌头》《赤壁赋》最常考。","ans":"苏轼代表作涵盖词、文、诗与书法。**词**有豪放的**《念奴娇·赤壁怀古》**（“大江东去”）、**《江城子·密州出猎》**，旷达的**《水调歌头·明月几时有》**（中秋怀弟苏辙）、**《定风波·莫听穿林打叶声》**，以及悼亡的《江城子·乙卯正月二十日夜记梦》；**文**有**前后《赤壁赋》**《石钟山记》《记承天寺夜游》；诗有《题西林壁》《饮湖上初晴后雨》；书法**《黄州寒食诗帖》**被誉为“天下第三行书”。这些作品分属词、文、诗、书四类，是苏轼成就全面的代表。","pts":["词：念奴娇、水调歌头、江城子、定风波","文：前后赤壁赋、石钟山记","书法：黄州寒食诗帖，天下第三行书"],"mem":"按贬谪地点串时间线：密州（《江城子·密州出猎》《水调歌头》）→黄州（《念奴娇》《赤壁赋》《定风波》《寒食帖》）。密州写“打猎与中秋”，黄州写“赤壁与风雨”。","mix":"《赤壁赋》写的是黄州赤壁（赤鼻矶），并非三国赤壁之战旧址；“十年生死两茫茫”是《江城子·记梦》（悼亡妻），“老夫聊发少年狂”是《江城子·密州出猎》。","mcq":[{"q":"“但愿人长久，千里共婵娟”出自","o":["《念奴娇·赤壁怀古》","《江城子·密州出猎》","《水调歌头·明月几时有》","《定风波》"],"a":2,"w":"出自苏轼《水调歌头》，中秋怀念弟弟苏辙。"},{"q":"《黄州寒食诗帖》的作者是","o":["黄庭坚","苏轼","米芾","颜真卿"],"a":1,"w":"《黄州寒食诗帖》为苏轼所书，与《兰亭序》《祭侄文稿》并称“天下三大行书”。"}],"rel":[{"t":"苏轼","n":"作者"},{"t":"《黄州寒食诗帖》","n":"书法代表作"},{"t":"天下三大行书","n":"所属称号"},{"t":"苏轼《饮湖上初晴后雨》","n":"同属苏轼名篇"},{"t":"词牌","n":"念奴娇等为词牌"}],"more":"词：《念奴娇·赤壁怀古》《水调歌头·明月几时有》《江城子·密州出猎》《江城子·乙卯正月二十日夜记梦》《定风波·莫听穿林打叶声》\n文：《赤壁赋》《后赤壁赋》《石钟山记》《记承天寺夜游》\n诗：《题西林壁》《饮湖上初晴后雨》《惠崇春江晚景》\n书法：《黄州寒食诗帖》","exam":[],"alias":[]},{"id":"a03-065","t":"辛弃疾代表作","cid":"03h","p":1,"kind":"作品","one":"辛弃疾代表作汇总，《永遇乐》《青玉案》《破阵子》《西江月》，词集《稼轩长短句》。","ans":"辛弃疾代表作多收入词集**《稼轩长短句》**。怀古抒怀有**《永遇乐·京口北固亭怀古》**，借孙权、刘裕与廉颇，抒收复之志与老来无用之愤；军旅壮词有**《破阵子·为陈同甫赋壮词以寄之》**（“醉里挑灯看剑”），寄赠好友陈亮；元夕之作**《青玉案·元夕》**（“众里寻他千百度”）写灯火中的寻觅，偏婉约；田园词有**《西江月·夜行黄沙道中》**（“稻花香里说丰年”）和《清平乐·村居》。他“以文为词”，题材从战场一直写到田园。","pts":["怀古：永遇乐·京口北固亭怀古","军旅：破阵子；婉约：青玉案·元夕","田园：西江月·夜行黄沙道中"],"mem":"三类题材串成“战、情、田”：战（《破阵子》看剑）、情（《青玉案》元夕寻人）、田（《西江月》稻花蛙声），怀古就记《永遇乐》。《破阵子》题目里有“陈同甫”，对应好友陈亮。","mix":"京口北固亭有两首：《永遇乐》（“英雄无觅孙仲谋处”“廉颇老矣，尚能饭否”）与《南乡子》（“生子当如孙仲谋”）；“明月几时有”是苏轼，不是辛弃疾。","mcq":[{"q":"“醉里挑灯看剑，梦回吹角连营”出自","o":["《青玉案·元夕》","《破阵子·为陈同甫赋壮词以寄之》","《西江月》","《永遇乐》"],"a":1,"w":"出自辛弃疾《破阵子·为陈同甫赋壮词以寄之》。"},{"q":"“稻花香里说丰年，听取蛙声一片”的作者是","o":["陆游","范成大","辛弃疾","苏轼"],"a":2,"w":"出自辛弃疾《西江月·夜行黄沙道中》。"}],"rel":[{"t":"辛弃疾","n":"作者"},{"t":"苏辛","n":"与苏轼并称"},{"t":"苏轼代表作","n":"对照篇目"},{"t":"词牌","n":"永遇乐等为词牌"},{"t":"陆游代表作","n":"同怀收复之志"}],"more":"《永遇乐·京口北固亭怀古》《青玉案·元夕》《破阵子·为陈同甫赋壮词以寄之》《西江月·夜行黄沙道中》《丑奴儿·书博山道中壁》《菩萨蛮·书江西造口壁》《南乡子·登京口北固亭有怀》\n词集：《稼轩长短句》","exam":[],"alias":[]},{"id":"a03-066","t":"陆游代表作","cid":"03h","p":2,"kind":"作品","alias":["剑南诗稿","示儿","书愤","游山西村","钗头凤"],"one":"《示儿》《书愤》《游山西村》，词《钗头凤》，诗集《剑南诗稿》九千余首。","ans":"陆游（1125–1210），字务观，号放翁，南宋诗人。其诗集**《剑南诗稿》存诗九千余首**，数量在历代诗人中居前列。代表作《**示儿**》“王师北定中原日，家祭无忘告乃翁”是临终绝笔，《**书愤**》“早岁那知世事艰，中原北望气如山”抒写壮志难酬，《**游山西村**》“山重水复疑无路，柳暗花明又一村”写田园生活。词有《**钗头凤·红酥手**》，悼念与唐琬的爱情，《诉衷情》抒收复之志。","pts":["《剑南诗稿》存诗九千余首","《示儿》《书愤》写爱国，《游山西村》写田园","词《钗头凤》《诉衷情》"],"mem":"三类题材三首诗：爱国《示儿》（死前交代儿子）、壮志《书愤》（中原北望）、田园《游山西村》（柳暗花明）。词记《钗头凤》，是与唐琬的爱情，“红酥手，黄藤酒”。","mix":"“柳暗花明”出自陆游《游山西村》，不是杨万里；《示儿》是陆游绝笔，不是辛弃疾；《剑南诗稿》得名于他入蜀任职的“剑南”。","mcq":[{"q":"“山重水复疑无路，柳暗花明又一村”出自","o":["陆游《游山西村》","杨万里《小池》","范成大《四时田园杂兴》","王安石《泊船瓜洲》"],"a":0,"w":"出自陆游《游山西村》。"}],"rel":[{"t":"陆游","n":"作者"},{"t":"中兴四大诗人","n":"四人之一"},{"t":"杨万里","n":"同属四大诗人"},{"t":"文天祥","n":"同写家国之志"}],"more":"《示儿》：死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。\n《十一月四日风雨大作》：夜阑卧听风吹雨，铁马冰河入梦来。\n《钗头凤》：红酥手，黄藤酒，满城春色宫墙柳。","exam":[]},{"id":"a03-067","t":"宋诗特点：以文字为诗、以议论为诗、以才学为诗","cid":"03h","p":3,"kind":"概念","alias":["宋诗特点","以文字为诗","以议论为诗","以才学为诗"],"one":"严羽《沧浪诗话》概括宋诗重思辨、尚博雅的典型美学风貌。","ans":"该论述出自**南宋严羽《沧浪诗话·诗辨》**，概括了宋诗有别于唐诗重情韵的体貌特征。指宋人喜好**驱遣散文句法（文字）、铺排才学典故（才学）与阐发哲理（议论）**入诗。钱锺书指出宋诗**发展了筋骨思理之美**，与唐诗双峰并峙。","pts":["出自南宋严羽《沧浪诗话·诗辨》","指宋诗重散文句法、博通典故与哲理思辨","钱锺书《宋诗选注》指出其筋骨思理之境"],"mem":"三大特征口诀：**文字、才学、议论**，出自严羽《沧浪诗话》。对比唐诗重“情韵”，宋诗重“理趣思辨”。","mix":"严羽提出此说原带批评意图（认为失却古诗韵味）；钱锺书在《宋诗选注》中从正面肯定了宋诗开掘思理的独特贡献。","mcq":[{"q":"南宋严羽在《沧浪诗话》中用来概括宋诗体貌特征的三句话是","o":["以神韵为诗、以格调为诗、以性灵为诗","以文字为诗、以才学为诗、以议论为诗","以风骨为诗、以兴寄为诗、以声律为诗","以意象为诗、以境界为诗、以辞采为诗"],"a":1,"w":"严羽评宋诗：“近代诸公乃以文字为诗，以才学为诗，以议论为诗。”"}],"rel":[{"t":"严羽","n":"《沧浪诗话》作者"},{"t":"黄庭坚与江西诗派","n":"宋诗才学议论典型代表"},{"t":"钱锺书","n":"《宋诗选注》作者"}],"exam":[]},{"id":"a03-068","t":"范仲淹《岳阳楼记》与“易混作者”","cid":"03h","p":2,"kind":"作品","alias":["岳阳楼记","陋室铭","爱莲说"],"one":"《岳阳楼记》是范仲淹作；《陋室铭》《爱莲说》也常作八大家干扰项。","ans":"《**岳阳楼记**》是**北宋范仲淹**应滕子京之请，于庆历六年（1046）所作的记，文中“**先天下之忧而忧，后天下之乐而乐**”和“**不以物喜，不以己悲**”最有名。它常与**刘禹锡《陋室铭》**（“山不在高，有仙则名”）、**周敦颐《爱莲说》**（“出淤泥而不染”）一起，作为**唐宋八大家的干扰项**出现。三位作者都**不在八大家之列**，八大家只有韩愈、柳宗元、欧阳修、三苏、曾巩、王安石。","pts":["《岳阳楼记》：范仲淹","《陋室铭》刘禹锡，《爱莲说》周敦颐","三人均不在八大家之列"],"mem":"三篇三个人三个态度：范仲淹《岳阳楼记》忧天下，刘禹锡《陋室铭》安贫（“斯是陋室，惟吾德馨”），周敦颐《爱莲说》洁身（“出淤泥而不染”）。八大家口诀“韩柳欧三苏曾王”。","mix":"《陋室铭》作者刘禹锡是唐代“诗豪”，《爱莲说》作者周敦颐是北宋理学家，都不是八大家；韩愈、柳宗元才是唐代入选者。","mcq":[{"q":"下列作家中，属于“唐宋八大家”的是","o":["刘禹锡","周敦颐","范仲淹","曾巩"],"a":3,"w":"曾巩属八大家；其他三人都不在其列。"}],"rel":[{"t":"范仲淹","n":"《岳阳楼记》作者"},{"t":"唐宋八大家","n":"这些作品是其干扰项"},{"t":"刘禹锡","n":"《陋室铭》作者"},{"t":"周敦颐","n":"《爱莲说》作者"}],"more":"八大家：韩愈、柳宗元、欧阳修、苏洵、苏轼、苏辙、曾巩、王安石。","exam":[]},{"id":"a03-069","t":"元杂剧四大悲剧","cid":"03i","p":1,"kind":"合称","alias":["四大悲剧","元杂剧四大悲剧"],"one":"元杂剧四大悲剧：《窦娥冤》《汉宫秋》《梧桐雨》《赵氏孤儿》。","ans":"元杂剧四大悲剧指**关汉卿《窦娥冤》、马致远《汉宫秋》、白朴《梧桐雨》、纪君祥《赵氏孤儿》**。《窦娥冤》写善良寡妇窦娥被诬冤斩，临刑发**血溅白练、六月飞雪、亢旱三年**三桩誓愿；《汉宫秋》写汉元帝被迫送王昭君出塞和亲；《梧桐雨》写唐明皇与杨贵妃的爱情悲剧；《赵氏孤儿》写程婴舍子救孤、复仇雪恨。王国维《宋元戏曲史》称《窦娥冤》《赵氏孤儿》“即列之于世界大悲剧中，亦无愧色”。四剧写政治黑暗与家国命运，代表元杂剧的最高成就。","pts":["窦娥冤、汉宫秋、梧桐雨、赵氏孤儿","关汉卿、马致远、白朴、纪君祥","王国维称前后两剧可入世界大悲剧"],"members":[["《窦娥冤》","关汉卿，窦娥蒙冤，三桩誓愿"],["《汉宫秋》","马致远，汉元帝与王昭君"],["《梧桐雨》","白朴，唐明皇与杨贵妃"],["《赵氏孤儿》","纪君祥，程婴救孤"]],"mem":"四剧对四人：窦（关）、汉（马）、梧（白）、赵（纪）。再记一个“雪秋雨孤”：窦娥冤六月飞雪，汉宫秋，梧桐雨，赵氏孤儿，四个字对应四部戏。","mix":"四大悲剧与四大爱情剧（《西厢记》《拜月亭》《墙头马上》《倩女离魂》）互为干扰项；《墙头马上》《倩女离魂》是爱情剧；《汉宫秋》《梧桐雨》虽写爱情，但结局是悲剧。","mcq":[{"q":"下列剧作中，不属于元杂剧四大悲剧的是","o":["《墙头马上》","《窦娥冤》","《汉宫秋》","《梧桐雨》"],"a":0,"w":"《墙头马上》（白朴）是爱情剧。"},{"q":"《梧桐雨》所写的人物是","o":["汉元帝与王昭君","唐明皇与杨贵妃","张生与崔莺莺","程婴与公孙杵臼"],"a":1,"w":"《梧桐雨》写唐明皇与杨贵妃。"}],"rel":[{"t":"《窦娥冤》","n":"四大悲剧之一"},{"t":"《赵氏孤儿》","n":"四大悲剧之一"},{"t":"《汉宫秋》与《梧桐雨》","n":"四大悲剧之二"},{"t":"元杂剧四大爱情剧","n":"互为干扰项"},{"t":"古希腊三大悲剧家","n":"中西悲剧对照"}],"exam":[]},{"id":"a03-070","t":"元杂剧四大爱情剧","cid":"03i","p":1,"kind":"合称","alias":["四大爱情剧","元杂剧四大爱情剧"],"one":"元杂剧四大爱情剧：《西厢记》《拜月亭》《墙头马上》《倩女离魂》。","ans":"元杂剧四大爱情剧指**王实甫《西厢记》、关汉卿《拜月亭》、白朴《墙头马上》、郑光祖《倩女离魂》**。《西厢记》写张生与崔莺莺；《拜月亭》写书生蒋世隆与尚书之女王瑞兰在战乱中结缘；《墙头马上》写裴少俊与李千金，李千金敢于追求自主婚姻；《倩女离魂》写张倩女魂魄离体追随王文举。四剧的共同主题是**反对门第观念与封建礼教、追求自主婚姻**，其中**《西厢记》成就最高**。四剧与四大悲剧并列为元杂剧的两大题材。","pts":["西厢记、拜月亭、墙头马上、倩女离魂","王实甫、关汉卿、白朴、郑光祖","反礼教，追求自主婚姻"],"members":[["《西厢记》","王实甫，张生与崔莺莺"],["《拜月亭》","关汉卿，蒋世隆与王瑞兰"],["《墙头马上》","白朴，裴少俊与李千金"],["《倩女离魂》","郑光祖，张倩女与王文举"]],"mem":"剧名首字“西拜墙倩”，作者对“王关白郑”。与悲剧互补：悲剧里补位的是纪君祥（《赵氏孤儿》），爱情剧里补位的是王实甫（《西厢记》），马致远只在悲剧里出现。","mix":"《墙头马上》《倩女离魂》是爱情剧，别选入悲剧；关汉卿杂剧《拜月亭》与南戏《拜月亭记》（四大南戏“荆刘拜杀”之一）同题材，注意区分杂剧与南戏。","mcq":[{"q":"下列属于元杂剧四大爱情剧的是","o":["《汉宫秋》","《赵氏孤儿》","《倩女离魂》","《窦娥冤》"],"a":2,"w":"《倩女离魂》（郑光祖）是四大爱情剧之一。"},{"q":"《墙头马上》的作者是","o":["郑光祖","马致远","王实甫","白朴"],"a":3,"w":"《墙头马上》为白朴所作。"}],"rel":[{"t":"《西厢记》","n":"四大爱情剧之首"},{"t":"元杂剧四大悲剧","n":"互为干扰项"},{"t":"郑光祖","n":"《倩女离魂》作者"},{"t":"白朴","n":"《墙头马上》作者"},{"t":"《罗密欧与朱丽叶》","n":"中西爱情剧对照"}],"exam":[]},{"id":"a03-071","t":"《窦娥冤》","cid":"03i","p":1,"kind":"作品","alias":["窦娥冤","感天动地窦娥冤","窦娥"],"one":"关汉卿的元杂剧悲剧，窦娥蒙冤被斩，临刑发三桩誓愿。","ans":"《窦娥冤》全名《感天动地窦娥冤》，是**元代关汉卿创作的杂剧**，列元杂剧四大悲剧之一。剧写**童养媳窦娥早年丧夫，遭流氓张驴儿逼婚，又被诬毒死张父，被昏官桃杌判斩**。窦娥临刑发下三桩誓愿：**血溅白练、六月飞雪、亢旱三年**，后来一一应验，冤案终得昭雪。全剧**揭露元代吏治黑暗、官府昏庸**，塑造了善良而刚烈的妇女形象。唱词“天地也，只合把清浊分辨”控诉天地不公。王国维称其可列入世界大悲剧。","pts":["关汉卿悲剧，窦娥蒙冤被斩","三桩誓愿：血溅白练、六月飞雪、亢旱三年","揭露吏治黑暗，王国维称世界大悲剧"],"mem":"三桩誓愿按“血、雪、旱”记：先是人的血（血溅白练），再是天的雪（六月飞雪），最后是地的旱（亢旱三年），由人到天到地，一层比一层大。作者对应口诀：窦娥冤对关汉卿，“关家窦娥喊冤”。","mix":"三桩誓愿是血溅白练、六月飞雪、亢旱三年；“铜豌豆”是关汉卿的自喻，不是剧名；《窦娥冤》是悲剧，《救风尘》是喜剧；同为四大悲剧的《赵氏孤儿》作者是纪君祥。","mcq":[{"q":"窦娥临刑前发下的誓愿不包括","o":["大水淹城","血溅白练","六月飞雪","亢旱三年"],"a":0,"w":"三桩誓愿是血溅白练、六月飞雪、亢旱三年。"},{"q":"《窦娥冤》的作者是","o":["马致远","关汉卿","白朴","郑光祖"],"a":1,"w":"《窦娥冤》是关汉卿的代表作。"}],"rel":[{"t":"关汉卿","n":"作者"},{"t":"元杂剧四大悲剧","n":"所属合称"},{"t":"关汉卿“铜豌豆”","n":"同一作者的另一常考点"},{"t":"《赵氏孤儿》","n":"同为四大悲剧"},{"t":"古希腊三大悲剧家","n":"中西悲剧对照"}],"more":"天地也，只合把清浊分辨，可怎生糊突了盗跖颜渊。｜《窦娥冤》","exam":[]},{"id":"a03-072","t":"《赵氏孤儿》","cid":"03i","p":1,"kind":"作品","alias":["赵氏孤儿","冤报冤赵氏孤儿","中国孤儿"],"one":"纪君祥的元杂剧，程婴救孤；第一部译成欧洲语言的中国戏剧，伏尔泰据此改编。","ans":"《赵氏孤儿》全名《冤报冤赵氏孤儿》，是**元代纪君祥创作的杂剧**，取材于《史记·赵世家》等记载的晋国赵氏灭门故事，列**元杂剧四大悲剧**之一。剧写**奸臣屠岸贾灭赵氏满门，门客程婴舍子救孤，将赵氏孤儿抚养成人并复仇**，歌颂舍生取义。它是**第一部译成欧洲语言的中国戏剧**：1735年法国传教士马若瑟的译本刊于杜赫德《中华帝国全志》，后伏尔泰据此改编为《中国孤儿》（1755），推动了18世纪欧洲的“中国热”。","pts":["纪君祥杂剧，程婴救孤","四大悲剧之一，歌颂舍生取义","第一部译成欧洲语言的中国戏剧，伏尔泰改编"],"mem":"人物接力记译介线：马若瑟（译）→杜赫德（刊）→伏尔泰（改编），三个人名串成一条中西交流线。剧情口诀：屠岸贾灭门，程婴救孤，公孙杵臼赴死。","mix":"纪君祥不属元曲四大家；《中国孤儿》是伏尔泰的法文改编剧；译者是法国传教士马若瑟，不要与编《华英字典》、译《圣经》的马礼逊混淆。","mcq":[{"q":"第一部被译成欧洲语言的中国戏剧是","o":["《窦娥冤》","《西厢记》","《赵氏孤儿》","《牡丹亭》"],"a":2,"w":"《赵氏孤儿》由马若瑟译成法文，刊于杜赫德《中华帝国全志》。"},{"q":"伏尔泰据《赵氏孤儿》改编的剧本名为","o":["《老实人》","《东方孤儿》","《中国孤儿》","《赵氏复仇》"],"a":2,"w":"伏尔泰改编为《中国孤儿》。"}],"rel":[{"t":"元杂剧四大悲剧","n":"所属合称"},{"t":"纪君祥","n":"作者"},{"t":"伏尔泰","n":"改编者"},{"t":"明清来华耶稣会士","n":"译介背景"},{"t":"启蒙运动","n":"欧洲接受的思想背景"}],"more":"王国维《宋元戏曲史》：即列之于世界大悲剧中，亦无愧色。","exam":[]},{"id":"a03-073","t":"《汉宫秋》与《梧桐雨》","cid":"03i","p":2,"kind":"作品","alias":["汉宫秋","梧桐雨","破幽梦孤雁汉宫秋","唐明皇秋夜梧桐雨"],"one":"马致远《汉宫秋》写汉元帝与王昭君，白朴《梧桐雨》写唐明皇与杨贵妃。","ans":"《汉宫秋》与《梧桐雨》是**元杂剧中两部写帝王爱情的悲剧**，均为四折一楔子。**马致远《汉宫秋》**写**汉元帝与王昭君**，毛延寿陷害，昭君被迫出塞和亲，在汉番边界投江，元帝闻孤雁哀鸣而悲。**白朴《梧桐雨》**取材于白居易《长恨歌》“秋雨梧桐叶落时”，写**唐明皇与杨贵妃**，马嵬坡赐死后，明皇秋夜听雨怀念贵妃。二者常与《窦娥冤》《赵氏孤儿》并称元杂剧四大悲剧。","pts":["《汉宫秋》马致远：元帝与昭君","《梧桐雨》白朴：明皇与贵妃","均为帝王爱情悲剧，常列四大悲剧"],"mem":"配对口诀：马汉白唐（马致远—汉元帝，白朴—唐明皇）。画面：汉宫是“秋”（孤雁），唐宫是“雨”（梧桐），一个听雁，一个听雨。","mix":"洪昇《长生殿》写同一对唐明皇与杨贵妃，但结局团圆，是清代传奇；《梧桐雨》是元代杂剧，结局悲。","mcq":[{"q":"白朴《梧桐雨》写的是","o":["汉元帝与王昭君","唐明皇与杨贵妃","张生与崔莺莺","杜丽娘与柳梦梅"],"a":1,"w":"《梧桐雨》写唐明皇与杨贵妃。"}],"rel":[{"t":"马致远","n":"《汉宫秋》作者"},{"t":"白朴","n":"《梧桐雨》作者"},{"t":"元杂剧四大悲剧","n":"并列于四大悲剧"},{"t":"《长生殿》","n":"同写明皇贵妃，清代传奇"}],"more":"《梧桐雨》典出白居易《长恨歌》：春风桃李花开日，秋雨梧桐叶落时。","exam":[]},{"id":"a03-074","t":"曲牌与宫调","cid":"03i","p":1,"kind":"概念","alias":["曲牌","宫调"],"one":"曲牌是曲调名称，宫调标在曲牌前表示调式，如“越调·天净沙”“南吕·一枝花”。","ans":"曲牌是**元曲曲调的名称**，规定每支曲子的句数、字数、平仄与用韵，如**【天净沙】【山坡羊】【一枝花】**，作者依牌填曲；曲牌与题目要分开，如《天净沙·秋思》中“天净沙”是曲牌，“秋思”是题目。宫调是**曲牌所属的音乐调式系统**，标在曲牌之前，如**“越调·天净沙”“中吕·山坡羊”“南吕·一枝花”**，表示该曲牌用何种调式演唱。同一宫调的若干曲牌可连成套数。辨清宫调、曲牌与题目，是读懂元曲作品全称的关键，如张养浩《中吕·山坡羊·潼关怀古》由宫调、曲牌、题目三部分组成。","pts":["曲牌=曲调名，规定字数句式平仄","宫调=曲牌所属调式，标于曲牌前","全称=宫调·曲牌·题目"],"mem":"三层结构像“省·市·街”：宫调（大类）→曲牌（曲目）→题目（内容）。公式“宫·牌·题”，例：中吕（宫）·山坡羊（牌）·潼关怀古（题）。","mix":"词牌属宋词，曲牌属元曲，名称有的重合，写法不同；《一枝花》是曲牌，《不伏老》才是题目；南吕、越调、中吕是宫调，不是曲牌。","mcq":[{"q":"“中吕·山坡羊·潼关怀古”中，“山坡羊”是","o":["宫调","曲牌","题目","作者号"],"a":1,"w":"中吕是宫调，山坡羊是曲牌，潼关怀古是题目。"},{"q":"《南吕·一枝花·不伏老》中，“南吕”属于","o":["曲牌","题目","宫调","词牌"],"a":2,"w":"南吕是宫调。"}],"rel":[{"t":"词牌","n":"词的对应概念"},{"t":"散曲","n":"曲牌用于散曲"},{"t":"马致远《天净沙·秋思》","n":"天净沙为曲牌"},{"t":"关汉卿“铜豌豆”","n":"南吕·一枝花"},{"t":"张养浩","n":"《山坡羊·潼关怀古》作者"}],"more":"曲牌举例：【天净沙】【山坡羊】【一枝花】【沉醉东风】【折桂令】。","exam":[]},{"id":"a03-075","t":"“乔张”：乔吉与张可久","cid":"03i","p":3,"kind":"合称","alias":["乔张"],"one":"元代后期散曲两大领军人物乔吉与张可久的合称。","ans":"“乔张”指**元代后期散曲双璧乔吉与张可久**。二人追求**清丽雅正、声律严密**，代表了散曲走向文人雅化的转变。乔吉提出文章乐府须具“**凤头、猪肚、豹尾**”；张可久专力作曲，存作数量居元人之冠。二人并驾齐驱，**代表了元代散曲后期的最高成就**。","pts":["元代后期散曲两大家乔吉与张可久","风格清丽雅正，标志散曲走向文人雅化","乔吉提出“凤头、猪肚、豹尾”之法"],"members":[["乔吉","字梦符，散曲清丽，提出作乐府法须有“凤头、猪肚、豹尾”"],["张可久","号小山，专力散曲，存作八百余首居元人之冠，风格典雅工整"]],"mem":"文论口诀：**乔吉谈结构（凤头猪肚豹尾），张可久专作曲（小山存作最多）**。二人并称“乔张”，代表元代散曲后期雅派。","mix":"元代前期散曲以关汉卿、马致远为代表（通俗生动、豪放辛辣），后期以乔吉、张可久为代表（清丽典雅、字斟句酌）。","mcq":[{"q":"在散曲理论中提出作乐府须具备“凤头、猪肚、豹尾”的元代后期作家是","o":["张可久","乔吉","马致远","张养浩"],"a":1,"w":"乔吉提出“凤头（起要美丽）、猪肚（中要浩荡）、豹尾（结要响亮）”之法。"}],"rel":[{"t":"散曲","n":"所属文学体裁"},{"t":"马致远","n":"前期散曲名家对照"},{"t":"元杂剧与元曲四大家","n":"元曲整体脉络"}],"exam":[]},{"id":"a03-076","t":"睢景臣《高祖还乡》","cid":"03i","p":3,"kind":"作品","alias":["高祖还乡","般涉调·哨遍·高祖还乡"],"one":"元代睢景臣所作散曲套数，以乡民视角讽刺汉高祖刘邦。","ans":"《高祖还乡》是**元代散曲家睢景臣**的套数代表作，曲牌为**《般涉调·哨遍》**。作品打破封建帝王神圣威严，巧妙借**同乡村民视角**，将衣锦还乡的汉高祖刘邦彻底还原为乡里无赖“刘三”。全曲极尽夸张谐谑，是**元代散曲叙事讽刺艺术的巅峰之作**。","pts":["元代睢景臣作散曲套数《般涉调·哨遍》","借乡民第一人称盲点视角，称刘邦为刘三","讽刺剥除帝王伪装，散曲谐谑名篇"],"mem":"讽刺艺术记忆：**睢景臣写高祖还乡＝村民眼中的“刘三”**。曲牌《般涉调·哨遍》，以村汉无知视角产生绝妙讽刺效果。","mix":"《高祖还乡》是散曲套数而非元杂剧折子戏；曲中直接以“刘三”解构帝王威仪，展现元代散曲平民化批判色彩。","mcq":[{"q":"元代散曲套数《般涉调·哨遍·高祖还乡》打破帝王神话、借乡民口吻讽刺汉高祖刘邦，其作者是","o":["马致远","张养浩","睢景臣","乔吉"],"a":2,"w":"《高祖还乡》是睢景臣的散曲套数名篇。"}],"rel":[{"t":"睢景臣","n":"作品作者"},{"t":"散曲","n":"作品所属文学体裁"},{"t":"张养浩","n":"同时代散曲名家"}],"more":"名句：你改得这般疾，教保官认不得，俺只道刘三，谁想是刘邦。｜《高祖还乡》","exam":[]},{"id":"a03-077","t":"王国维《宋元戏曲史》","cid":"03i","p":2,"kind":"作品","alias":["宋元戏曲史","宋元戏曲考"],"one":"第一部中国戏曲史专著，提出“一代有一代之文学”，推重元曲。","ans":"《宋元戏曲史》是**王国维**所著的**第一部系统研究中国戏曲史的专著**，约1913年写成，原名《宋元戏曲考》，后由商务印书馆出版时改今名。书中提出“**一代有一代之文学**”，认为楚之骚、汉之赋、唐之诗、宋之词、元之曲各代表一个时代，以**元曲为元代文学的代表**，推崇元杂剧的“自然”；评关汉卿“一空倚傍，自铸伟词”，称《窦娥冤》《赵氏孤儿》可列入世界大悲剧。","pts":["王国维著，第一部中国戏曲史专著","一代有一代之文学","推崇元曲，评关汉卿"],"mem":"一句话：从“楚骚、汉赋、唐诗、宋词、元曲”一线排下去，这条线就是王国维提出的。再记一个对应：王国维管“戏曲史”，鲁迅管“小说史”（《中国小说史略》）。","mix":"《人间词话》也是王国维所作，讲的是词与境界；“一代有一代之文学”出在《宋元戏曲史》，常与胡适的文学进化论混。","mcq":[{"q":"提出“一代有一代之文学”并推崇元曲的著作是","o":["《宋元戏曲史》","《中国小说史略》","《人间词话》","《文心雕龙》"],"a":0,"w":"王国维《宋元戏曲史》（原《宋元戏曲考》）。"}],"rel":[{"t":"王国维","n":"作者"},{"t":"王国维《人间词话》","n":"同作者，词学"},{"t":"《中国小说史略》","n":"鲁迅，小说史对照"},{"t":"关汉卿","n":"书中盛赞对象"}],"more":"一代有一代之文学：楚之骚，汉之赋，六代之骈语，唐之诗，宋之词，元之曲。｜《宋元戏曲考》序","exam":[]},{"id":"a03-078","t":"周德清《中原音韵》与钟嗣成《录鬼簿》","cid":"03i","p":3,"kind":"作品","alias":["中原音韵与录鬼簿"],"one":"元代曲学奠基之作，分别确立了北曲曲韵标准与元曲作家作品谱系。","ans":"二书为**元代戏曲曲学领域的两部开山专著**。周德清**《中原音韵》**是**第一部北曲音韵专著**，以北方中原语音为准，首创“平分阴阳、入派三声”；钟嗣成**《录鬼簿》**是**最早为戏曲作家立传著录的著作**。二者共同推动了**元曲的规范化与古典曲学建立**。","pts":["周德清《中原音韵》为第一部北曲曲韵专著","首创“平分阴阳、入派三声”规律","钟嗣成《录鬼簿》为最早戏曲家传记与著录"],"mem":"功能对应法：**周德清管曲韵**（《中原音韵》立北曲声律标准）；**钟嗣成管曲家史料**（《录鬼簿》记作家作品）。","mix":"《中原音韵》首创“入派三声”（北曲无入声，分入平上去三声）；《录鬼簿》的“鬼”指已故戏曲家，非鬼怪迷信。","mcq":[{"q":"我国古代第一部北曲音韵专著，总结了“平分阴阳、入派三声”规律的著作是","o":["《切韵》","《广韵》","《录鬼簿》","《中原音韵》"],"a":3,"w":"元代周德清作《中原音韵》，为我国第一部北曲曲韵专著。"}],"rel":[{"t":"元杂剧与元曲四大家","n":"记述元杂剧作家背景"},{"t":"关汉卿","n":"《录鬼簿》首列作家"},{"t":"王国维《宋元戏曲史》","n":"戏曲史考据源头文献"}],"exam":[]},{"id":"a03-079","t":"明清传奇","cid":"03j","p":1,"kind":"概念","alias":["传奇","明清传奇"],"one":"由南戏发展而来的长篇戏曲，一本数十出，多用昆腔；代表《牡丹亭》《长生殿》《桃花扇》。","ans":"明清传奇指**由南戏发展而来的长篇戏曲**，与唐代传奇小说同名而不同类。体制上**一本通常数十出，不限折数，各脚色都可歌唱**，以南曲为主，明中叶以后多用**昆腔**演唱。魏良辅改革昆山腔，梁辰鱼《浣纱记》使昆腔登上传奇舞台。代表作有**汤显祖《牡丹亭》、洪昇《长生殿》、孔尚任《桃花扇》**，高明《琵琶记》是南戏向传奇过渡的源头。传奇是明清戏曲的主要样式，篇幅远长于元杂剧。","pts":["南戏发展而来，长篇，数十出","不限主唱，多用昆腔","牡丹亭、长生殿、桃花扇"],"mem":"对比口诀“杂剧四折一人唱，传奇数十众人唱”。三部代表按时间记：明（牡丹亭）→清初（长生殿 1688、桃花扇 1699），“一明二清”。","mix":"唐传奇是文言短篇小说，明清传奇是戏曲；元杂剧一本四折，明清传奇数十出；《西厢记》是元杂剧，《琵琶记》是南戏。","mcq":[{"q":"关于明清传奇，下列说法正确的是","o":["一本四折、一人主唱","是唐代文言小说","主要用北曲演唱","由南戏发展而来，一本数十出"],"a":3,"w":"明清传奇由南戏发展而来，一本数十出，多用昆腔。"},{"q":"下列作品属于明清传奇的是","o":["《西厢记》","《窦娥冤》","《桃花扇》","《汉宫秋》"],"a":2,"w":"《桃花扇》是清初传奇，其余三部是元杂剧。"}],"rel":[{"t":"南戏与《琵琶记》","n":"前身"},{"t":"昆曲","n":"主要声腔"},{"t":"汤显祖与“临川四梦”","n":"明代高峰"},{"t":"“南洪北孔”","n":"清初高峰"},{"t":"元杂剧与元曲四大家","n":"体制对照"}],"more":"魏良辅：改革昆山腔。梁辰鱼《浣纱记》：第一部用昆腔演唱的传奇。","exam":[]},{"id":"a03-080","t":"《牡丹亭》","cid":"03j","p":1,"kind":"作品","alias":["牡丹亭","牡丹亭还魂记","还魂记","杜丽娘"],"one":"汤显祖1598年作传奇，杜丽娘与柳梦梅因梦生情、死而复生，“情不知所起，一往而深”。","ans":"《牡丹亭》全名《牡丹亭还魂记》，是**明代汤显祖创作的传奇**，成于**万历二十六年（1598）**，是“临川四梦”（玉茗堂四梦）中最著名的一部，另三部为《紫钗记》《南柯记》《邯郸记》。剧写**南安太守之女杜丽娘游园惊梦，梦中与书生柳梦梅相爱，伤情而死，后魂魄与柳梦梅相会，起死回生并终成眷属**，题词“情不知所起，一往而深”点明主题。全剧以**“情”对抗“理”**，批判程朱理学对人性的压抑，是明传奇的高峰，常与《西厢记》并称，对《红楼梦》等也有影响。","pts":["明代汤显祖传奇，1598年","杜丽娘与柳梦梅，因梦生情、死而复生","以情抗理，临川四梦中最著名"],"mem":"情节链“园、梦、死、魂、生”：游园→惊梦→伤情而死→魂游相会→还魂成亲。年份挂钩：1598 年成书，2026 年是汤显祖逝世 410 周年（1616 年去世）。","mix":"《牡丹亭》又名《还魂记》；“原来姹紫嫣红开遍”是《惊梦》唱词；《西厢记》（元杂剧，王实甫）写张生与崔莺莺；《长生殿》《桃花扇》都在清代。","mcq":[{"q":"“情不知所起，一往而深”出自","o":["《西厢记》","《长生殿》","《牡丹亭》","《邯郸记》"],"a":2,"w":"出自汤显祖《牡丹亭》题词。"},{"q":"《牡丹亭》的男女主人公是","o":["张生与崔莺莺","杜丽娘与柳梦梅","侯方域与李香君","唐明皇与杨贵妃"],"a":1,"w":"《牡丹亭》写杜丽娘与柳梦梅。"}],"rel":[{"t":"汤显祖与“临川四梦”","n":"作者与四梦"},{"t":"汤显祖与莎士比亚同年逝世","n":"2026年410周年"},{"t":"吴江派与临川派（汤沈之争）","n":"文学论争"},{"t":"《西厢记》","n":"常并称的爱情戏"},{"t":"《罗密欧与朱丽叶》","n":"中西爱情剧对照"}],"more":"情不知所起，一往而深。生者可以死，死可以生。｜《牡丹亭》题词\n原来姹紫嫣红开遍，似这般都付与断井颓垣。｜《惊梦》","exam":[]},{"id":"a03-081","t":"《长生殿》","cid":"03j","p":2,"kind":"作品","alias":["长生殿","洪昇长生殿"],"one":"洪昇作，写唐明皇与杨贵妃，1688年定稿，“南洪北孔”之一。","ans":"《长生殿》是**清代洪昇所作传奇**，**1688年定稿**，前后三易其稿，共五十出。全剧写**唐明皇与杨贵妃**的爱情：前半写二人恩爱与马嵬坡之变，杨妃被赐死；后半写明皇思念，最终二人在月宫重圆，结局团圆。题材取自白居易《长恨歌》，剧名出自“七月七日长生殿，夜半无人私语时”。它与孔尚任《桃花扇》并称“**南洪北孔**”，是**清初传奇的代表**。","pts":["洪昇作，清代传奇，1688年定稿","写唐明皇与杨贵妃，结局团圆","与《桃花扇》并称南洪北孔"],"mem":"年份配对：1688《长生殿》、1699《桃花扇》，相差十一年，“洪在前，孔在后”，与“南洪北孔”顺序一致。题材记“长恨歌→长生殿”：都有“长”字。","mix":"《梧桐雨》（元，白朴）也写明皇贵妃，是杂剧，结局悲；《长生殿》是清代传奇，结局团圆。洪昇是南方钱塘人，所以是“南洪”。","mcq":[{"q":"清代洪昇的传奇《长生殿》写的是","o":["侯方域与李香君","唐明皇与杨贵妃","杜丽娘与柳梦梅","张生与崔莺莺"],"a":1,"w":"《长生殿》写唐明皇与杨贵妃，取材于《长恨歌》。"}],"rel":[{"t":"洪昇","n":"作者"},{"t":"《桃花扇》","n":"南洪北孔的另一部"},{"t":"“南洪北孔”","n":"合称"},{"t":"《汉宫秋》与《梧桐雨》","n":"同写帝妃，元杂剧"}],"more":"七月七日长生殿，夜半无人私语时。｜白居易《长恨歌》（剧名出处）","exam":[]},{"id":"a03-082","t":"《桃花扇》","cid":"03j","p":2,"kind":"作品","alias":["桃花扇","孔尚任桃花扇"],"one":"孔尚任作，侯方域与李香君，“借离合之情，写兴亡之感”，1699年定稿。","ans":"《桃花扇》是**清代孔尚任所作传奇**，**1699年定稿**。全剧以**复社文人侯方域与秦淮名妓李香君**的爱情为线索，写南明弘光朝廷的覆灭，作者自称“**借离合之情，写兴亡之感**”。李香君血溅诗扇，被点染成桃花，故名《桃花扇》；结局侯李二人在栖霞山被道士点醒，双双入道，没有团圆。它是**清代历史剧的代表**，与洪昇《长生殿》并称“**南洪北孔**”。","pts":["孔尚任作，1699年定稿","侯方域与李香君，写南明兴亡","借离合之情，写兴亡之感"],"mem":"一个画面：李香君头撞柱，血溅在诗扇上，杨龙友添几笔成桃花，这一幅图就是剧名。口诀：“侯李离合”写爱情，“南明兴亡”写国事。","mix":"《牡丹亭》是明代汤显祖，写杜丽娘与柳梦梅；《长生殿》是明皇贵妃，团圆；《桃花扇》是悲剧，侯李入道。孔尚任是孔子后裔，山东曲阜人，是“北孔”。","mcq":[{"q":"“借离合之情，写兴亡之感”是哪部作品的创作主旨","o":["《长生殿》","《牡丹亭》","《西厢记》","《桃花扇》"],"a":3,"w":"孔尚任《桃花扇》自述其旨为“借离合之情，写兴亡之感”。"}],"rel":[{"t":"孔尚任","n":"作者"},{"t":"《长生殿》","n":"南洪北孔的另一部"},{"t":"“南洪北孔”","n":"合称"},{"t":"《牡丹亭》","n":"明代传奇高峰对照"}],"more":"借离合之情，写兴亡之感。｜《桃花扇》","exam":[]},{"id":"a03-083","t":"汤显祖与莎士比亚同年逝世","cid":"03j","p":2,"kind":"时事","alias":["汤莎","东方的莎士比亚","1616年逝世"],"one":"汤显祖、莎士比亚、塞万提斯同卒于1616年，2026年为410周年。","ans":"汤显祖（1550–1616）与莎士比亚（1564–1616）**同卒于1616年**，西班牙作家塞万提斯也在同年去世。汤显祖是**明代戏曲家**，“临川四梦”作者，代表作《牡丹亭》，被称为“**东方的莎士比亚**”；莎士比亚是**英国文艺复兴时期剧作家**，有《哈姆雷特》《罗密欧与朱丽叶》。二人因同年辞世、同为戏剧大家，常被作中西戏剧比较，**2026年是二人逝世410周年**。","pts":["汤显祖与莎士比亚同卒于1616年","塞万提斯同年去世","2026年为逝世410周年"],"mem":"三个人记“一六一六，三人同行”：汤显祖（中国）、莎士比亚（英国）、塞万提斯（西班牙），各占东西方戏剧小说一端。2026−1616＝410，周年数好算。","mix":"汤显祖1550年生，莎士比亚1564年生，汤年长14岁；《牡丹亭》约1598年，《罗密欧与朱丽叶》约1595年，两剧都是爱情题材，常被对举。","mcq":[{"q":"与莎士比亚同于1616年去世的作家是","o":["关汉卿","塞万提斯","但丁","乔叟"],"a":1,"w":"塞万提斯和莎士比亚、汤显祖同于1616年去世。"}],"rel":[{"t":"汤显祖","n":"中方主角"},{"t":"莎士比亚","n":"英方主角"},{"t":"塞万提斯","n":"同年去世"},{"t":"《牡丹亭》","n":"与《罗密欧与朱丽叶》常对举"}],"more":"2016年是汤显祖、莎士比亚逝世400周年；2026年是410周年。","exam":[]},{"id":"a03-084","t":"吴江派与临川派（汤沈之争）","cid":"03j","p":3,"kind":"流派","alias":["汤沈之争","临川派与吴江派"],"one":"明代万历年间沈璟吴江派与汤显祖临川派关于戏剧格律与才情的论争。","ans":"汤沈之争指**明末传奇戏曲吴江派与临川派的理论分野**。沈璟领衔的**吴江派**主张“**恪守曲律、以字就律**”，注重舞台合律；汤显祖领衔的**临川派**强调“**因情成梦、重意趣才情**”，重案注文学。两派之争深刻探讨了**戏曲文学性与场上表演性的辩证关系**。","pts":["明代后期吴江派沈璟与临川派汤显祖之争","吴江派重格律规范场上演唱，临川派重才情意趣","深刻探讨戏曲案头文学性与舞台场上性关系"],"mem":"核心对立公式：**沈璟（吴江派）重曲律** vs **汤显祖（临川派）倡才情**。汤显祖名言“不妨拗折天下人齿”体现不为声律牺牲才情。","mix":"沈璟吴江派重在“场上表演与协律”，汤显祖临川派重在“案头文学与情志”；清初李渔则融合了二者之长。","mcq":[{"q":"明代后期戏曲界围绕“案头文学才情”与“场上音律格律”展开的“汤沈之争”，其两位领袖是","o":["汤显祖与沈璟","汤显祖与沈德潜","汤显祖与李渔","沈璟与孔尚任"],"a":0,"w":"临川派汤显祖（主才情）与吴江派沈璟（主格律规范）展开“汤沈之争”。"}],"rel":[{"t":"汤显祖","n":"临川派领袖"},{"t":"《牡丹亭》","n":"临川派代表作"},{"t":"汤显祖与“临川四梦”","n":"临川派核心名作"}],"exam":[]},{"id":"a03-085","t":"台阁体","cid":"03j","p":2,"kind":"流派","alias":["三杨","台阁派"],"one":"明初“三杨”杨士奇、杨荣、杨溥，诗文雍容典雅，歌功颂德。","ans":"台阁体是**明初永乐至成化年间的诗文风格**，因代表人物多居台阁（内阁）高位而得名。代表为“**三杨**”：**杨士奇、杨荣、杨溥**，三人先后任大学士，诗文**雍容典雅、平正**，多为应制、颂圣、酬应之作，**内容空洞，歌功颂德**。因作者位高权重，台阁体盛行数十年，末流千篇一律，成为**前七子倡导“文必秦汉，诗必盛唐”复古主张的反对对象**。","pts":["三杨：杨士奇、杨荣、杨溥","雍容典雅，歌功颂德","遭前七子复古派反对"],"members":[["杨士奇","号西杨"],["杨荣","号东杨"],["杨溥","号南杨"]],"mem":"“三杨”按字：士奇、荣、溥，顺序“西东南”：杨士奇西杨，杨荣东杨，杨溥南杨。逻辑线：台阁体空洞→前七子提“文必秦汉”→公安派提“独抒性灵”，明代诗文一路反着来。","mix":"台阁体的“台阁”指内阁，不是“台湾”；它被前七子取代，而前七子又被唐宋派、公安派批评，要分清先后。","mcq":[{"q":"明代前期，以杨士奇、杨荣、杨溥为代表的诗文流派是","o":["唐宋派","台阁体","公安派","竟陵派"],"a":1,"w":"三杨为台阁体代表。"}],"rel":[{"t":"前七子","n":"反对台阁体的复古派"},{"t":"后七子","n":"继前七子的复古派"},{"t":"唐宋派","n":"反对复古的散文流派"},{"t":"公安派与竟陵派","n":"明代后期流派"}],"more":"明代诗文流派先后：台阁体、前后七子、唐宋派、公安派、竟陵派。","exam":[]},{"id":"a03-086","t":"茶陵诗派","cid":"03j","p":3,"kind":"流派","alias":["茶陵派"],"one":"明代中期以李东阳为首的诗歌流派，为前后七子复古运动的先导。","ans":"茶陵诗派是**明代中期出现的诗歌流派**，以内阁大学士**李东阳**（茶陵人）为领袖。针对台阁体板滞庸靡文风，主张**宗法汉魏杜甫、讲求法度音调与声律**。诗风典雅深沉，纠正了馆阁浮泛之弊，成为**明代“前后七子”复古诗风的直接先导**。","pts":["明代中期诗歌流派，以李东阳为首","主张宗法汉魏杜甫，讲求声律法度","纠正台阁体板滞，为前后七子复古先导"],"mem":"流派演变链条：**台阁体（颂赞板滞）→ 茶陵诗派（李东阳法杜纠弊）→ 前后七子（文必秦汉、诗必盛唐）**。","mix":"茶陵诗派以李东阳为首，虽然开前后七子复古先河，但主张博采汉魏盛唐、注重声律，不同于前七子的生硬模拟。","mcq":[{"q":"明代成化、弘治年间力图纠正台阁体卑靡板滞之风，并成为“前七子”复古运动先导的诗派是","o":["唐宋派","茶陵诗派","公安派","竟陵派"],"a":1,"w":"以李东阳为首的茶陵诗派提倡宗法汉魏杜甫，是前后七子复古的先导。"}],"rel":[{"t":"台阁体","n":"茶陵派力矫之流派"},{"t":"前七子","n":"受茶陵派启发的复古流派"},{"t":"后七子","n":"明代复古派后继"}],"exam":[]},{"id":"a03-087","t":"前七子","cid":"03j","p":1,"kind":"合称","alias":["前七子"],"one":"明弘治、正德年间复古派，李梦阳、何景明等七人，“文必秦汉，诗必盛唐”。","ans":"前七子是**明代弘治、正德年间的文学流派，成员有李梦阳、何景明、徐祯卿、边贡、康海、王九思、王廷相**，以李梦阳、何景明为首。他们针对台阁体的平庸委靡与茶陵诗派，**倡导文学复古，主张“文必秦汉，诗必盛唐”**，强调学习秦汉古文与盛唐诗歌的格调。这一主张打破了台阁体长期笼罩的局面，开创明代诗文复古的潮流，但过分强调模拟，陷入摹拟剽窃的弊端，后来受到唐宋派与公安派批评。嘉靖年间李攀龙、王世贞等继起，称后七子。","pts":["弘治、正德年间，李梦阳、何景明等七人","文必秦汉，诗必盛唐","反台阁体，后陷模拟"],"members":[["李梦阳","领袖，“文必秦汉，诗必盛唐”"],["何景明","与李梦阳并称，后与之有论争"],["徐祯卿","吴中人，早年有“吴中四才子”之名"],["边贡","济南历下人"],["康海","陕西武功人"],["王九思","陕西鄠县人，擅散曲"],["王廷相","河南仪封人"]],"mem":"口诀“李何徐边，康王王”：李梦阳、何景明、徐祯卿、边贡、康海、王九思、王廷相，取每人首字。口号对应：文→秦汉，诗→盛唐。区分前后：前李何，后李王（李攀龙、王世贞）。","mix":"前七子（弘治、正德）与后七子（嘉靖、隆庆）同主复古，别混；两者与“建安七子”“竹林七贤”是不同的七人组合；公安派反对他们的拟古。","mcq":[{"q":"“文必秦汉，诗必盛唐”是哪一派的主张","o":["公安派","前七子","唐宋派","竟陵派"],"a":1,"w":"这是以李梦阳为首的前七子的复古口号，后七子沿用。"},{"q":"下列人物中，属于前七子的是","o":["李攀龙","王世贞","何景明","谢榛"],"a":2,"w":"何景明属前七子；其余三位属后七子。"}],"rel":[{"t":"后七子","n":"继起的复古派"},{"t":"台阁体","n":"所反对的文风"},{"t":"茶陵诗派","n":"同时所针对的诗派"},{"t":"唐宋派","n":"起而反对其拟古"},{"t":"公安派与竟陵派","n":"晚明反复古"}],"exam":[]},{"id":"a03-088","t":"后七子","cid":"03j","p":1,"kind":"合称","alias":["后七子"],"one":"明嘉靖、隆庆年间复古派，李攀龙、王世贞等七人，延续前七子的复古主张。","ans":"后七子是**明代嘉靖、隆庆年间的文学流派，成员有李攀龙、王世贞、谢榛、宗臣、梁有誉、徐中行、吴国伦**，先后以李攀龙、王世贞为领袖。他们**继承前七子的复古主张，重申“文必秦汉，诗必盛唐”**，对抗当时的唐宋派，并强调诗的格调法度。谢榛后因与李攀龙意见不合被排挤出社，李攀龙去世后王世贞主持文坛二十年，所著《艺苑卮言》是重要诗论。后七子使复古风气盛行一时，但拟古倾向也引起公安派等反对，成为晚明文学革新的对立面。","pts":["嘉靖、隆庆年间，李攀龙、王世贞等七人","继续主张文必秦汉、诗必盛唐","王世贞《艺苑卮言》；被公安派反对"],"members":[["李攀龙","领袖之一，济南历城人"],["王世贞","后期领袖，《艺苑卮言》"],["谢榛","布衣诗人，后被排挤出社"],["宗臣","《报刘一丈书》"],["梁有誉","广东顺德人"],["徐中行","浙江长兴人"],["吴国伦","湖北兴国人"]],"mem":"口诀“李王谢宗，梁徐吴”：李攀龙、王世贞、谢榛、宗臣、梁有誉、徐中行、吴国伦。前后七子对照：“前李何，后李王”，前面领袖李梦阳、何景明，后面领袖李攀龙、王世贞。","mix":"前后七子都主复古，别与唐宋派（归有光、茅坤、唐顺之）、公安派（三袁）混；谢榛是后七子初期成员，后被排挤出社；宗臣以《报刘一丈书》著称。","mcq":[{"q":"后七子的领袖人物是","o":["李梦阳、何景明","钟惺、谭元春","袁宏道、袁中道","李攀龙、王世贞"],"a":3,"w":"后七子以李攀龙、王世贞为领袖。"},{"q":"下列人物中，不属于后七子的是","o":["康海","谢榛","宗臣","徐中行"],"a":0,"w":"康海属前七子。"}],"rel":[{"t":"前七子","n":"前一阶段复古派"},{"t":"唐宋派","n":"同时期对立派别"},{"t":"公安派与竟陵派","n":"起而反对复古"},{"t":"袁宏道","n":"公安派领袖"},{"t":"台阁体","n":"前七子所反对的前代文风"}],"exam":[]},{"id":"a03-089","t":"唐宋派","cid":"03j","p":2,"kind":"流派","alias":["唐宋派"],"one":"王慎中、唐顺之、茅坤、归有光，反对前后七子；茅坤编《唐宋八大家文钞》。","ans":"唐宋派是**明嘉靖年间的散文流派**，代表人物为**王慎中、唐顺之、茅坤、归有光**。他们反对前后七子“文必秦汉”的拟古主张，**提倡学习唐宋古文**，强调文章要抒写胸臆、有“本色”。茅坤编**《唐宋八大家文钞》**，使“**唐宋八大家**”之称广泛流行；归有光的散文《项脊轩志》《先妣事略》以朴素的家常叙事见长，是**明代散文成就较高的作家**。","pts":["王慎中、唐顺之、茅坤、归有光","反对前后七子，提倡学唐宋文","茅坤《唐宋八大家文钞》使八大家之称流行"],"members":[["王慎中","唐宋派代表"],["唐顺之","主张“本色”"],["茅坤","编《唐宋八大家文钞》"],["归有光","《项脊轩志》《先妣事略》"]],"mem":"名称来源线：茅坤编《唐宋八大家文钞》→“唐宋八大家”流行→主张学唐宋文的一派叫“唐宋派”。人名首字“王唐茅归”，归有光最著名，抓《项脊轩志》。","mix":"“唐宋八大家”一词由茅坤文钞推广，并非唐宋时期就有；唐宋派反对前后七子，公安派又反对一切复古。","mcq":[{"q":"编有《唐宋八大家文钞》、使“八大家”之称广泛流行的是","o":["唐顺之","归有光","茅坤","王慎中"],"a":2,"w":"茅坤编《唐宋八大家文钞》。"}],"rel":[{"t":"唐宋八大家","n":"名称由其推广"},{"t":"归有光","n":"代表作家"},{"t":"前七子","n":"他们反对的复古派"},{"t":"后七子","n":"他们反对的复古派"}],"more":"归有光：《项脊轩志》《先妣事略》。","exam":[]},{"id":"a03-090","t":"晚明小品文","cid":"03j","p":3,"kind":"概念","alias":["晚明小品"],"one":"明代后期兴起的抒情写景散文体裁，以袁宏道、张岱等为代表。","ans":"晚明小品文是**明代后期繁荣的散文体裁**。受阳明心学及公安派“独抒性灵”思潮启发，以**袁宏道、张岱**为代表。文风短小精巧，多记日常琐事与山水清赏。张岱**《陶庵梦忆》**集其大成，**展现了晚明士人的雅致情趣与故国挽歌**。","pts":["明代后期抒情写景散文体裁","受心学与公安派“独抒性灵”影响","以袁宏道、张岱为代表，名作《陶庵梦忆》"],"mem":"核心作家挂钩：**晚明小品＝袁宏道（公安派先驱）＋ 张岱（陶庵梦忆集大成）**。代表篇目《湖心亭看雪》《西湖梦寻》。","mix":"晚明小品文反对前后七子的拟古文风；张岱作品成书于明亡之后，虽为小品但寄寓深切故国之思，非单纯轻浮享乐之作。","mcq":[{"q":"明代后期晚明小品文的集大成者，著有《陶庵梦忆》《西湖梦寻》及散文名篇《湖心亭看雪》的是","o":["归有光","李贽","张岱","袁宏道"],"a":2,"w":"张岱是晚明小品文代表文人，著有《陶庵梦忆》《西湖梦寻》。"}],"rel":[{"t":"张岱","n":"晚明小品集大成者"},{"t":"袁宏道","n":"倡“独抒性灵”代表"},{"t":"公安派与竟陵派","n":"晚明文论背景流派"}],"more":"代表篇目：张岱《湖心亭看雪》、袁宏道《满井游记》","exam":[]},{"id":"a03-091","t":"明初诗文三大家","cid":"03j","p":3,"kind":"合称","alias":["明初三大家"],"one":"明代开国时期三位文坛领军人物宋濂、刘基、高启的并称。","ans":"明初诗文三大家指**明代开国文坛领军人物宋濂、刘基、高启**。宋濂被誉为“**开国文臣之首**”，古文平正醇正；刘基兼备谋略文采，作寓言集《郁离子》；高启被推为“**明初诗人之冠**”。三人扫除元末靡靡之风，**奠定了明代开国文学质实健朗的风骨**。","pts":["明初文人宋濂、刘基、高启三人合称","宋濂为开国文臣之首，刘基作《郁离子》","高启为明初诗人之冠，奠定开国文学典范"],"members":[["宋濂","字景濂，朱元璋誉为“开国文臣之首”，代表作散文《送东阳马生序》"],["刘基","字伯温，开国名勋，散文雄浑，著有讽喻散文集《郁离子》"],["高启","字季迪，号青丘子，诗作宏富才高，被誉为“明初诗人之冠”"]],"mem":"称号定位法：**文臣之首宋濂、开国奇士刘基（伯温）、诗人之冠高启**。三人并立于明初洪武时期。","mix":"“明初诗文三大家”是宋濂、刘基、高启；而“明代唐宋派”是归有光、唐顺之、茅坤等；高启后因诗获罪被朱元璋腰斩。","mcq":[{"q":"“明初诗文三大家”中，被明太祖朱元璋誉为“开国文臣之首”，并作有名篇《送东阳马生序》的是","o":["宋濂","刘基","高启","方孝孺"],"a":0,"w":"宋濂被朱元璋誉为“开国文臣之首”，代表作有《送东阳马生序》。"}],"rel":[{"t":"宋濂","n":"三大家之一"},{"t":"宋濂《送东阳马生序》","n":"宋濂代表散文"},{"t":"台阁体","n":"明初文学其后流派"}],"exam":[]},{"id":"a03-092","t":"江左三大家","cid":"03j","p":3,"kind":"合称","alias":["江左三大家","钱吴龚"],"one":"明末清初活跃于江南诗坛的三大领袖钱谦益、吴伟业、龚鼎孳的并称。","ans":"江左三大家指**明末清初江南文坛领袖钱谦益、吴伟业、龚鼎孳**。三人经历鼎革之变，诗中多寄托身世遗恨与故国沧桑。钱谦益雄踞虞山诗派盟主；吴伟业以叙事名篇《圆圆曲》开创“**梅村体**”；龚鼎孳富于才华。三人代表了**清初诗歌创作的最高成就**。","pts":["明末清初钱谦益、吴伟业、龚鼎孳三人","诗中寄寓明清易代身世沧桑与故国遗恨","钱谦益文坛盟主，吴伟业作《圆圆曲》开梅村体"],"members":[["钱谦益","号牧斋，世称虞山先生，清初文坛盟主，著《初学集》《有学集》"],["吴伟业","号梅村，长于七言叙事长诗，以《圆圆曲》开创“梅村体”"],["龚鼎孳","号芝麓，合肥人，兼工五言律诗与词，著《定山堂集》"]],"mem":"姓氏口诀：**钱吴龚（江左三大家）**。钱是钱谦益，吴是吴伟业（梅村体《圆圆曲》），龚是龚鼎孳。江左即江东江南地区。","mix":"江左三大家均由明入清出仕，后世列为“贰臣”，诗中充满亡国悔恨之情；勿与清中期的“乾隆三大家”（袁枚、蒋士铨、赵翼）混淆。","mcq":[{"q":"明末清初“江左三大家”中，创作叙事长诗《圆圆曲》并开创“梅村体”诗风的诗人是","o":["钱谦益","吴伟业","龚鼎孳","王士禛"],"a":1,"w":"吴伟业号梅村，长于七言叙事歌行，开创“梅村体”，代表作《圆圆曲》。"}],"rel":[{"t":"明末清初三大思想家","n":"同时代思想界对照"},{"t":"清初四僧","n":"同时代艺术界群体"},{"t":"纳兰性德","n":"清初著名词人对照"}],"exam":[]},{"id":"a03-093","t":"清词三大家与清代词派","cid":"03j","p":2,"kind":"合称","alias":["清词三大家","阳羡词派","浙西词派","常州词派","清词中兴"],"one":"纳兰性德、陈维崧、朱彝尊；陈开阳羡派，朱开浙西派，张惠言开常州派。","ans":"清词三大家通行指**纳兰性德、陈维崧、朱彝尊**，是清词中兴的代表。陈维崧是**阳羡词派**领袖，词风豪放，近辛弃疾；朱彝尊是**浙西词派**领袖，宗南宋姜夔、张炎，主清空醇雅，编有《词综》；纳兰性德不属词派，以自然真切的小令著称。清代中叶**张惠言**创**常州词派**，提倡比兴寄托，后经周济发展，影响晚清词坛。","pts":["纳兰性德、陈维崧、朱彝尊","阳羡派（陈）、浙西派（朱）","张惠言开常州词派"],"members":[["纳兰性德","《饮水词》，自然真切"],["陈维崧","阳羡词派领袖，近辛弃疾"],["朱彝尊","浙西词派领袖，宗姜夔、张炎"]],"mem":"口诀“纳陈朱”，三派配三地：陈维崧—阳羡（江苏宜兴）、朱彝尊—浙西（浙江）、张惠言—常州（江苏）。风格配人：陈像辛（豪放），朱像姜（清空），张讲比兴（寄托）。","mix":"清词三大家有不同说法，另有以王士禛代纳兰性德之说；常州词派开创者是张惠言，周济只是后继者，不是开创者。","mcq":[{"q":"开创浙西词派、主张清空醇雅的清代词人是","o":["陈维崧","纳兰性德","张惠言","朱彝尊"],"a":3,"w":"朱彝尊是浙西词派开创者；陈维崧是阳羡派，张惠言是常州派。"}],"rel":[{"t":"纳兰性德","n":"三大家之一"},{"t":"姜夔","n":"浙西派宗法对象"},{"t":"辛弃疾","n":"阳羡派宗法对象"},{"t":"婉约派与豪放派","n":"风格对照"}],"more":"陈维崧《湖海楼词》；朱彝尊《曝书亭集》《词综》；张惠言《词选》。","exam":[]},{"id":"a03-094","t":"清代四大诗说：神韵、格调、性灵、肌理","cid":"03j","p":2,"kind":"合称","alias":["神韵说","格调说","性灵说","肌理说","清代四大诗说"],"one":"王士禛神韵、沈德潜格调、袁枚性灵、翁方纲肌理。","ans":"清代四大诗说指**王士禛“神韵说”、沈德潜“格调说”、袁枚“性灵说”、翁方纲“肌理说”**。神韵说主张诗要清远空灵、含蓄蕴藉；格调说重诗的格律声调，宗盛唐，编《唐诗别裁集》；**性灵说**主张抒写真性情，反对复古模拟，袁枚著《**随园诗话**》；肌理说主张以学问为诗，重考据义理与文理。四说中以性灵说最富革新精神。","pts":["神韵（王士禛）、格调（沈德潜）","性灵（袁枚，《随园诗话》）、肌理（翁方纲）","性灵说反复古，最富革新"],"members":[["王士禛","神韵说，清远空灵"],["沈德潜","格调说，宗盛唐"],["袁枚","性灵说，《随园诗话》"],["翁方纲","肌理说，以学问为诗"]],"mem":"顺序口诀“神格灵肌”，对应人名“王沈袁翁”。画面：王士禛的诗像烟雨山水（神韵），沈德潜的诗像整齐仪仗（格调），袁枚的诗像孩子说话（性灵），翁方纲的诗像书卷考据（肌理）。","mix":"明代公安派也讲“性灵”，但清代性灵说属于袁枚；“神韵”一词可追溯到严羽、司空图，王士禛是集中提倡者。","mcq":[{"q":"清代主张“性灵说”、著有《随园诗话》的诗人是","o":["王士禛","沈德潜","翁方纲","袁枚"],"a":3,"w":"袁枚倡性灵说，著《随园诗话》。"}],"rel":[{"t":"袁枚","n":"性灵说代表"},{"t":"严羽","n":"神韵说的前驱"},{"t":"公安派与竟陵派","n":"明代也讲性灵"},{"t":"《人间词话》","n":"王国维的“境界说”对照"}],"more":"袁枚《随园诗话》；沈德潜《唐诗别裁集》《古诗源》；王士禛《渔洋精华录》；翁方纲《石洲诗话》。","exam":[]},{"id":"a03-095","t":"乾隆三大家","cid":"03j","p":3,"kind":"合称","alias":["乾隆三大家","袁蒋赵"],"one":"清代乾隆年间著名诗人袁枚、蒋士铨、赵翼三人的合称。","ans":"乾隆三大家指**清代乾隆朝诗人袁枚、蒋士铨、赵翼**。三人力矫格调派泥古之风，主张**独抒性灵、表达真性情**。袁枚力倡“**性灵说**”；蒋士铨诗剧兼长；赵翼作《论诗》留有名句“**江山代有才人出，各领风骚数百年**”。三人**代表了乾隆诗坛的高峰**。","pts":["清代乾隆朝袁枚、蒋士铨、赵翼三人","反对拟古，主张独抒性灵与真实才情","袁枚倡性灵说，赵翼作“江山代有才人出”"],"members":[["袁枚","号简斋，随园先生，力倡“性灵说”，著《随园诗话》"],["蒋士铨","字心馀，号清容，诗剧兼擅，著有《忠雅堂集》"],["赵翼","号瓯北，史学家与诗人，作名篇《论诗五首》，著《廿二史札记》"]],"mem":"合称口诀：**乾隆三大家，袁蒋赵性灵发**。袁枚随园诗话，赵翼“江山代有才人出”，蒋士铨诗剧俱佳。","mix":"清初为“江左三大家”（钱吴龚），清中为“乾隆三大家”（袁蒋赵）；赵翼不仅是诗人，也是清代乾嘉史学名家（著《廿二史札记》）。","mcq":[{"q":"传诵名句“江山代有才人出，各领风骚数百年”出自“乾隆三大家”中哪位诗人的《论诗五首》","o":["袁枚","蒋士铨","赵翼","沈德潜"],"a":2,"w":"清代赵翼（号瓯北）在《论诗五首·其二》中写下该千古名句。"}],"rel":[{"t":"袁枚","n":"三大家之首"},{"t":"清代四大诗说：神韵、格调、性灵、肌理","n":"包含袁枚性灵说"},{"t":"桐城派","n":"同时代清代散文流派"}],"more":"名句：李杜诗篇万口传，至今已觉不新鲜。江山代有才人出，各领风骚数百年。｜《论诗五首·其二》","exam":[]},{"id":"a03-096","t":"桐城派“义法”与“义理、考据、辞章”","cid":"03j","p":2,"kind":"概念","alias":["义法","义理考据辞章","义理、考据、辞章"],"one":"方苞倡“义法”（言有物、言有序）；姚鼐倡义理、考据、辞章统一。","ans":"这是**桐城派的核心文论**。**方苞**提出“**义法**”：“义”指文章的内容，要“**言有物**”，“法”指文章的形式，要“**言有序**”，要求内容充实、条理分明、语言雅洁。**姚鼐**在此基础上主张“**义理、考据、辞章**”三者统一：义理指儒家思想，考据指学问考证，辞章指文章写作，并编**《古文辞类纂》**作为范本。这套主张使桐城派成为清代最有影响的散文流派。","pts":["方苞“义法”：言有物、言有序","姚鼐：义理、考据、辞章统一","姚鼐编《古文辞类纂》"],"mem":"方苞两个“有”：“言有物”（内容，义），“言有序”（形式，法）。姚鼐三件事：“义理”是思想，“考据”是学问，“辞章”是文采，三者缺一不可，可记“思想、学问、文采”。","mix":"“义法”是方苞，不是姚鼐；“义理、考据、辞章”是姚鼐，不是方苞。桐城三祖里刘大櫆重“神气音节”。","mcq":[{"q":"桐城派中提出“义理、考据、辞章”三者统一的是","o":["方苞","刘大櫆","姚鼐","曾国藩"],"a":2,"w":"姚鼐主张义理、考据、辞章三者统一。"}],"rel":[{"t":"桐城派","n":"所属流派"},{"t":"方苞","n":"提出义法"},{"t":"姚鼐","n":"提出三者统一"},{"t":"桐城三祖","n":"三位代表"}],"more":"姚鼐《古文辞类纂》选战国至清代的古文，分十三类。","exam":[]},{"id":"d03-001","t":"建安风骨","cid":"03c","p":1,"kind":"概念","alias":["汉魏风骨","建安风力"],"one":"汉末建安诗文慷慨悲凉、刚健爽朗的艺术风格，以三曹、建安七子为代表。","ans":"建安风骨指**东汉末建安时期（196–220）诗文慷慨悲凉、刚健有力的美学风格**，又称“汉魏风骨”“建安风力”。它由**“三曹”**（曹操、曹丕、曹植）、**“建安七子”**（孔融、王粲、刘桢等）及蔡琰开创。汉末战乱与建功之志交织，作品直面现实、情真气盛，**曹植**五言诗成就最高。南朝**刘勰**《文心雕龙》赞其“志深而笔长，梗概而多气”，**钟嵘**《诗品》称“建安风力”；初唐**陈子昂**倡“汉魏风骨”革诗风，确立后世古典诗歌审美标尺。","pts":["东汉末建安时期慷慨悲凉、刚健有力的诗文风格","以三曹、建安七子及蔡琰为代表，曹植成就最高","刘勰、钟嵘推崇，陈子昂借以革新唐诗"],"mem":"三层画面记风骨：**乱世战火+英雄豪情=慷慨悲凉**；代表人物“三曹七子一蔡琰”；后世点赞三人组：**刘勰**（梗概多气）、**钟嵘**（建安风力）、**陈子昂**（汉魏风骨）。","mix":"“建安”是汉献帝年号（196–220），属东汉末年而非三国曹魏时期；“风骨”作为理论术语由刘勰《文心雕龙·风骨》系统阐发，“汉魏风骨”口号由初唐陈子昂提出。","mcq":[{"q":"在《文心雕龙·时序》中以“志深而笔长，故梗概而多气”评价建安文学的批评家是","o":["刘勰","钟嵘","严羽","陆机"],"a":0,"w":"南朝刘勰在《文心雕龙·时序》中概括建安文学“慷慨以任气”“梗概而多气”。"},{"q":"初唐高举“汉魏风骨”旗帜、力扫齐梁绮靡余风的诗人是","o":["王勃","陈子昂","张若虚","沈佺期"],"a":1,"w":"陈子昂在《与东方左史虬修竹篇序》中批评齐梁诗风，呼吁恢复“汉魏风骨”。"}],"rel":[{"t":"建安文学与三曹","n":"建安风骨的核心开创者"},{"t":"建安七子","n":"建安风骨代表群体"},{"t":"刘勰","n":"《文心雕龙》系统阐发风骨"},{"t":"钟嵘《诗品》","n":"盛赞“建安风力”"},{"t":"陈子昂","n":"初唐倡“汉魏风骨”革诗风"}],"more":"名句：观其时文，雅好慷慨，良由世积乱离，风衰俗怨，并志深而笔长，故梗概而多气也。｜刘勰《文心雕龙·时序》\n蓬莱文章建安骨，中间小谢又清发。｜李白《宣州谢朓楼饯别校书叔云》","exam":[]},{"id":"d03-002","t":"宋末三杰","cid":"03h","p":3,"kind":"合称","alias":["亡宋三杰","南宋三忠"],"one":"文天祥、陆秀夫、张世杰，南宋末年抗元殉国的三位忠义重臣。","ans":"宋末三杰指**南宋末年抗元殉国的文天祥、陆秀夫、张世杰**。1279年**崖山海战**败北，**陆秀夫**背幼帝赵昺投海，**张世杰**突围溺亡，南宋亡；**文天祥**被俘不屈，作《过零丁洋》《正气歌》，1283年在大都就义，三人成为士人气节典范。","pts":["文天祥、陆秀夫、张世杰","1279年崖山之战陆、张殉国，1283年文天祥就义"],"members":[["文天祥","南宋宰相，作《过零丁洋》《正气歌》，1283年大都就义"],["陆秀夫","南宋左丞相，1279年崖山战败负幼帝赵昺投海"],["张世杰","南宋抗元主将，1279年崖山突围遇飓风溺亡"]],"mem":"口诀**“文陆张”**，配结局画面：**陆**秀夫背帝投海，**张**世杰飓风沉船，**文**天祥铁窗写《正气歌》后从容就义。","mix":"莫与“汉初三杰”（张良、萧何、韩信）或“中兴四将”（岳飞、韩世忠、张俊、刘光世）混淆；文天祥1278年已被俘，并非在崖山战死，而是在1283年于元大都就义。","mcq":[{"q":"1279年崖山海战失败后，背负南宋幼帝赵昺投海殉国的大臣是","o":["文天祥","张世杰","陆秀夫","岳飞"],"a":2,"w":"宋末三杰中，陆秀夫在崖山负幼帝赵昺投海，张世杰突围遇风溺死，文天祥于大都就义。"}],"rel":[{"t":"文天祥","n":"宋末三杰之一"},{"t":"辛弃疾","n":"同具南宋爱国抗敌精神"},{"t":"陆游","n":"南宋爱国诗坛前辈"},{"t":"成吉思汗与忽必烈","n":"忽必烈建元灭南宋"}],"more":"名句：人生自古谁无死？留取丹心照汗青。｜文天祥《过零丁洋》","exam":[]},{"id":"d03-003","t":"陈维崧与朱彝尊","cid":"03j","p":3,"kind":"人物","alias":["朱陈","陈迦陵","朱竹垞"],"one":"清初词坛双璧，合称“朱陈”，分别开创阳羡词派与浙西词派。","ans":"陈维崧与朱彝尊是**清初词坛两大宗师**，合称**“朱陈”**，共启清词中兴。**陈维崧**（1625–1682）宜兴人，创**阳羡词派**，宗苏辛豪放，著《湖海楼词》；**朱彝尊**（1629–1709）秀水人，创**浙西词派**，宗姜张醇雅，编《词综》。","pts":["清初词人合称“朱陈”，共启清词中兴","陈维崧阳羡派宗苏辛，朱彝尊浙西派宗姜张"],"mem":"两字对应口诀：**陈阳苏（豪）、朱浙姜（雅）**。陈维崧在江苏宜兴（阳羡）写豪放，朱彝尊在浙江秀水（浙西）编《词综》讲醇雅。","mix":"莫与清代“清词三大家”（纳兰性德、陈维崧、朱彝尊）和后起“常州词派”（张惠言、周济）混淆；陈维崧以填词量宏富著称，朱彝尊则以编选历代词总集《词综》影响深远。","mcq":[{"q":"清初词坛“朱陈”并称中，朱彝尊开创的词派及其尊崇的宋词典范是","o":["阳羡词派，宗苏轼、辛弃疾","常州词派，宗周邦彦、吴文英","花间词派，宗温庭筠、韦庄","浙西词派，宗姜夔、张炎"],"a":3,"w":"朱彝尊创浙西词派，主醇雅清空，宗南宋姜夔、张炎；陈维崧创阳羡词派，宗苏辛。"}],"rel":[{"t":"清词三大家与清代词派","n":"与纳兰性德并称清词三大家"},{"t":"纳兰性德","n":"同期清初婉约名家"},{"t":"苏轼","n":"阳羡词派所宗豪放典范"},{"t":"姜夔","n":"浙西词派所宗醇雅典范"}],"exam":[]},{"id":"d03-004","t":"《陌上桑》","cid":"03b","p":2,"kind":"作品","alias":["艳歌罗敷行","日出东南隅行","陌上桑"],"one":"汉乐府叙事民歌名篇，写邯郸采桑女秦罗敷机智拒斥使君调戏。","ans":"《陌上桑》又名**《艳歌罗敷行》《日出东南隅行》**，是**汉乐府民歌**五言叙事名篇，收入宋代郭茂倩**《乐府诗集·相和歌辞》**。全诗三章：首章以**“行者见罗敷，下担捋髭须”**侧面烘托采桑女**秦罗敷**之美；次章写其严词斥责使君调戏；末章借盛夸夫婿显赫机智脱身。作品塑造了不畏权贵的民间女性形象，奠定五言叙事诗典范。","pts":["汉乐府五言叙事名篇，收入《乐府诗集》","侧面烘托秦罗敷美貌，写其智拒使君调戏","塑造不畏权贵的民间女性形象"],"mem":"三幕剧画面记全诗：第一幕**夸美**（看客捋胡子忘锄地）→第二幕**拒官**（使君自有妇，罗敷自有夫）→第三幕**夸夫**（东方千余骑，夫婿居上头）。","mix":"莫与“乐府双璧”混淆：乐府双璧指汉乐府《孔雀东南飞》与北朝民歌《木兰诗》，不包括《陌上桑》；《陌上桑》写秦罗敷，《羽林郎》写胡姬反抗霍家奴，题材相近易混。","mcq":[{"q":"名句“行者见罗敷，下担捋髭须。少年见罗敷，脱帽著帩头”出自汉乐府","o":["《陌上桑》","《羽林郎》","《孔雀东南飞》","《上邪》"],"a":0,"w":"该句出自《陌上桑》首章，以旁人失态的侧面描写烘托秦罗敷之美。"}],"rel":[{"t":"汉乐府名篇","n":"汉乐府叙事代表作"},{"t":"乐府与乐府双璧","n":"与乐府双璧区分记忆"},{"t":"《乐府诗集》","n":"收入《相和歌辞》"},{"t":"《孔雀东南飞》","n":"同为汉代五言叙事诗"},{"t":"《木兰诗》","n":"古代民间女性形象对照"}],"more":"名句：行者见罗敷，下担捋髭须。少年见罗敷，脱帽著帩头。｜《陌上桑》\n使君一何愚！使君自有妇，罗敷自有夫。｜《陌上桑》","exam":[]},{"id":"d03-005","t":"诗缘情","cid":"03d","p":3,"kind":"概念","alias":["诗缘情而绮靡"],"one":"西晋陆机《文赋》提出的诗学命题，与“诗言志”相对，突出诗歌抒情本质。","ans":"诗缘情是**西晋陆机《文赋》提出的核心诗学命题**，原文为**“诗缘情而绮靡，赋体物而浏亮”**。它与《尚书》**“诗言志”**政教传统相对，肯定诗歌源于情感抒发与文辞华美，标志着**魏晋文学自觉**的审美转向。","pts":["西晋陆机《文赋》提出“诗缘情而绮靡”","与“诗言志”相对，标志魏晋文学自觉"],"mem":"对比两句定坐标：先秦《尚书》讲**诗言志**（政治抱负），西晋陆机讲**诗缘情**（个人情感+文辞绮靡），刚好对应魏晋“文学自觉”。","mix":"提出者是西晋陆机（《文赋》），不是东晋陶渊明，也不是南朝刘勰（《文心雕龙》）或钟嵘（《诗品》）；原文后半句“赋体物而浏亮”讲的是赋的特征。","mcq":[{"q":"中国古代文论中，“诗缘情而绮靡，赋体物而浏亮”的提出者及出处是","o":["曹丕《典论·论文》","陆机《文赋》","刘勰《文心雕龙》","钟嵘《诗品》"],"a":1,"w":"西晋陆机在《文赋》中首次提出“诗缘情而绮靡”，突出诗歌抒情与文辞之美。"}],"rel":[{"t":"陆机《文赋》","n":"命题直接出处"},{"t":"陆机","n":"命题提出者"},{"t":"诗言志与兴观群怨","n":"与“诗言志”相对举"},{"t":"《文心雕龙》","n":"南朝文论的继承发展"}],"exam":[]}],"tables":[{"name":"元曲四大家（关马郑白）与相关作家","note":"","rows":[["作家","杂剧代表作","记忆点","交大考过"],["关汉卿","《窦娥冤》《救风尘》《拜月亭》《单刀会》","元杂剧奠基人；套数《南吕·一枝花·不伏老》自称“铜豌豆”","2026选择"],["马致远","《汉宫秋》（王昭君故事）","号东篱，“曲状元”；小令《天净沙·秋思》“秋思之祖”","2020、2024选择"],["白朴","《梧桐雨》（唐明皇、杨贵妃）《墙头马上》","号兰谷","2021选择"],["郑光祖","《倩女离魂》（张倩女魂随王文举）","字德辉","2022选择"],["王实甫","《西厢记》（张生、崔莺莺）","不在四大家之列，常作干扰项",""],["纪君祥","《赵氏孤儿》（程婴救孤）","18世纪经马若瑟译成法文，伏尔泰改编为《中国孤儿》",""]]},{"name":"唐宋诗人词人称号","note":"","rows":[["称号或诗体","人物","代表作"],["诗仙","李白（盛唐，号青莲居士）","《蜀道难》《将进酒》《梦游天姥吟留别》"],["诗圣，其诗称“诗史”","杜甫（字子美，号少陵野老）","“三吏”“三别”、《春望》《登高》"],["诗佛","王维（字摩诘）","《使至塞上》《山居秋暝》；“诗中有画”"],["诗鬼，“长吉体”","李贺（字长吉，中唐）","《雁门太守行》《李凭箜篌引》"],["诗豪","刘禹锡","《陋室铭》《酬乐天扬州初逢席上见赠》"],["诗魔","白居易（号香山居士）","《长恨歌》《琵琶行》，倡导新乐府运动"],["七绝圣手","王昌龄","《出塞》“秦时明月汉时关”"],["郊寒岛瘦","孟郊、贾岛（苦吟诗人）","孟郊《游子吟》，贾岛“推敲”"],["小李杜","李商隐、杜牧（晚唐）","李商隐《锦瑟》无题诗；杜牧《阿房宫赋》《清明》"],["花间鼻祖，“温韦”","温庭筠、韦庄","温庭筠《菩萨蛮·小山重叠金明灭》"],["千古词帝","李煜（南唐后主）","《虞美人》“春花秋月何时了”"],["婉约词宗，易安体","李清照","《声声慢》《如梦令》，词集《漱玉词》"],["词中之龙","辛弃疾（号稼轩）","《永遇乐·京口北固亭怀古》《青玉案·元夕》"]]},{"name":"唐宋八大家","note":"易混：范仲淹《岳阳楼记》、刘禹锡《陋室铭》、周敦颐《爱莲说》作者都不在八大家之列。“三苏”指苏洵、苏轼、苏辙父子。","rows":[["人物","时代","代表散文"],["韩愈","唐","《师说》《马说》《进学解》"],["柳宗元","唐","《永州八记》（含《小石潭记》）《捕蛇者说》《封建论》"],["欧阳修","北宋","《醉翁亭记》《秋声赋》《朋党论》"],["苏洵","北宋","《六国论》"],["苏轼","北宋","《赤壁赋》《后赤壁赋》《石钟山记》"],["苏辙","北宋","《黄州快哉亭记》"],["王安石","北宋","《游褒禅山记》《答司马谏议书》"],["曾巩","北宋","《墨池记》"]]}]});